/* 2026.09 证券从业 LC 终极押题 · 6 套（自动生成，仅供内部学习） */
var PREDICT_202609 = [{"id":"law1","subject":"law","name":"法律法规 · 押题卷一","stats":{"单选":30,"多选":50,"判断":30,"案例":10},"questions":[{"id":"law1-0","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"单选","q":"发行股票后溢价收入是公司的（）。","options":["法定公积金","任意公积金","资本公积金","营业收入"],"answer":"C","explain":"C 选项正确，公司以超过股票票面金额的发行价格发行股份所得的溢价款、发行无面额股所得股款未计入注册资本的金额以及国务院财政部门规定列入资本公积金的其他项目，应当列为公司资本公积金。故本题选C 选项。【温馨提示】公司分配当年税后利润时，应当提取利润的10%列入公司法定公积金。公司从税后利润中提取法定公积金后，经股东会决议，还可以从税后利润中提取任意公积金。营业收入是公司在日常经营活动中形成的经济利益总流入。发行股票属于筹资活动，而非经营活动，其溢价收入不属于营业收入。"},{"id":"law1-1","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"单选","q":"根据《合伙企业法》，下列关于合伙企业债务承担的说法，错误的是（）。","options":["合伙企业依法被宣告破产的，普通合伙人对合伙企业债务仍应承担无限连带责任","合伙企业不能清偿到期债务的，债权人可以依法向人民法院提出破产清算申请","合伙企业注销后，原普通合伙人对合伙企业存续期间的债务仍应承担无限连带责任","合伙企业不能清偿到期债务的，债权人可以要求有限合伙人清偿"],"answer":"D","explain":"A 选项正确，合伙企业依法被宣告破产的，普通合伙人对合伙企业债务仍应承担无限连带责任。B 选项正确、D 选项错误，合伙企业不能清偿到期债务的，债权人可以依法向人民法院提出破产清算申请，也可以要求普通合伙人清偿（并非\"有限合伙人\"）。C 选项正确，合伙企业注销后，原普通合伙人对合伙企业存续期间的债务仍应承担无限连带责任。故本题选D 选项。"},{"id":"law1-2","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"单选","q":"根据《合伙企业法》，下列关于有限合伙企业事务执行的说法，错误的是（）。","options":["有限合伙企业由普通合伙人执行合伙事务","有限合伙企业仅剩有限合伙人的，应当解散","有限合伙人不执行合伙事务，不得对外代表有限合伙企业","有限合伙企业仅剩普通合伙人的，应当解散"],"answer":"D","explain":"有限合伙企业由普通合伙人执行合伙事务（A 选项正确）。有限合伙人不执行合伙事务，不得对外代表有限合伙企业（C 选项正确）。有限合伙企业仅剩有限合伙人的，应当解散（B 选项正确）；有限合伙企业仅剩普通合伙人的，转为普通合伙企业（D 选项错误）。故本题选D 选项。"},{"id":"law1-3","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"单选","q":"根据《上海证券交易所科创板股票交易特别规定》，关于投资者参与科创板股票交易需满足的适当性条件，下列说法正确的是（）。","options":["机构投资者申请权限开通前 20 个交易日证券账户及资金账户内的资产日均不低于人民币50 万元，或者参与证券交易24 个月以上","机构投资者申请权限开通前 20 个交易日证券账户及资金账户内的资产日均不低于人民币50 万元，并且参与证券交易24 个月以上","个人投资者申请权限开通前 20 个交易日证券账户及资金账户内的资产日均不低于人民币50 万元（不包括该投资者通过融资融券融入的资金和证券），或者参与证券交易 24 个月以上","个人投资者申请权限开通前 20 个交易日证券账户及资金账户内的资产日均不低于人民币50 万元（不包括该投资者通过融资融券融入的资金和证券），并且参与证券交易 24 个月以上"],"answer":"D","explain":"投资者参与科创板股票交易的具体条件：（1）个人投资者（而非机构投资者）申请权限开通前 20 个交易日证券账户及资金账户内的资产日均不低于人民币 50 万元（不包括该投资者通过融资融券融入的资金和证券），并且（而非或者）参与证券交易24 个月以上（A、B、C 选项错误，D 选项正确）。（2）符合法律法规及上交所规定的机构投资者，可直接申请开通科创板股票交易权限。（3）投资者仅需向其委托的证券公司申请，在已有沪市 A 股证券账户上开通科创板股票交易权限即可，无须在中国结算开立新的证券账户。故本题选D 选项。"},{"id":"law1-4","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"单选","q":"根据《证券法》，下列关于上市公司收购方式的说法，错误的是（）。","options":["收购要约约定的收购期限不得少于30 日，并不得超过 60 日","上市公司发行不同种类股份的，收购人可以针对不同种类股份提出不同的收购条件","在收购要约确定的承诺期限内，收购人不得变更其收购要约","采取协议收购方式的，协议双方可以临时委托证券登记结算机构保管协议转让的股票，并将资金存放于指定的银行"],"answer":"C","explain":"C 选项错误，在收购要约确定的承诺期限内，收购人不得撤销其收购要约。收购人需要变更收购要约的（并非\"不得变更\"），应当及时公告，载明具体变更事项。故本题选C 选项。"},{"id":"law1-5","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"单选","q":"根据《证券法》有关规定，证券公司在承销期结束时，将未售出的证券全部退还给发行人的承销方式是（）。","options":["自行销售","代销","余额包销","全额包销"],"answer":"B","explain":"B 选项正确，证券代销是指证券公司代发行人发售证券，在承销期结束时，将未售出的证券全部退还给发行人的承销方式。故本题选B 选项。"},{"id":"law1-6","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"单选","q":"根据《证券公司风险处置条例》，相关机构或人员存在以下（）情形的，应禁止参与处置证券公司风险工作。","options":["内部控制存在一定瑕疵","因违规行为受到纪律处分未逾3 年","因严重违法行为受到行政处罚已逾3 年","涉嫌犯罪正在被立案侦查、起诉"],"answer":"D","explain":"有下列情形之一的机构或者人员，禁止参与处置证券公司风险工作：（1）曾受过刑事处罚或者涉嫌犯罪正在被立案侦查、起诉（D 选项正确）；（2）涉嫌严重违法正在被行政管理部门立案稽查或者曾因严重违法行为受到行政处罚未逾 3年（B、C 选项错误）；（3）仍处于证券市场禁入期；（4）内部控制薄弱、存在重大风险隐患（A 选项错误）；（5）与被处置证券公司处置事项有利害关系；（6）国务院证券监督管理机构认定不宜参与处置证券公司风险工作的其他情形。故本题选D 选项。"},{"id":"law1-7","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"单选","q":"根据《证券期货经营机构及其工作人员廉洁从业规定》，下列关于证券期货经营机构工作人员违反廉洁从业规定的说法，错误的是（）。","options":["曾任证券期货经营机构合规风控职务的人员违反廉洁从业规定的，应当从重处理","直接、间接或者唆使、协助他人向监管人员输送利益的，应当从重处理","违反廉洁从业规定，事后及时向中国证券业协会报告，或者积极配合调查的，依法免予从轻处理","曾为公职人员特别是监管人员违反廉洁从业规定的，应当从重处理"],"answer":"C","explain":"C 选项错误，证券期货经营机构工作人员违反《廉洁规定》，事后及时向中国证监会（而非中国证券业协会）报告，或者积极配合调查的，依法免于追究责任或者从轻、减轻处理。故本题选C 选项。【温馨提示】证券期货经营机构及其工作人员违反《廉洁规定》，有下列情形之一的，中国证监会应当从重处理：（1）直接、间接或者唆使、协助他人向监管人员输送利益；（2）连续或者多次违反本规定；（3）涉及金额较大或者涉及人员较多；（4）产生恶劣社会影响；（5）曾为公职人员特别是监管人员，以及曾任证券期货经营机构合规风控职务的人员违反本规定；（6）中国证监会认定应当从重处理的其他情形。"},{"id":"law1-8","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"单选","q":"根据《证券期货经营机构及其工作人员廉洁从业规定》《证券经营机构及其工作人员廉洁从业实施细则》，以下关于廉洁从业风险报告的说法，正确的是（）。","options":["证券期货经营机构应于每年 4 月 30 日、8 月 30 日前，向中国证监会有关派出机构报送年度廉洁从业管理报告、半年度廉洁从业管理报告","证券期货经营机构及其工作人员发现监管人员存在应当回避的情形而未进行回避、利用职务之便索取或者收受不正当利益等违反廉洁规定行为的，应当在五个工作日内，向中国证监会有关派出机构报告","证券期货经营机构在内部检查中，发现存在违反《证券期货经营机构及其工作人员廉洁从业规定》行为的，且进行内部追责的，应当在十个工作日内，向中国证券业协会报告","证券期货经营机构或者其工作人员因违反廉洁从业相关规定被纪检监察部门、司法机关立案调查或者被采取纪律处分、行政处罚、刑事处罚等措施的，应当在五个工作日内，向中国证券业协会报告"],"answer":"B","explain":"证券期货经营机构应当于每年 4 月 30 日前，向中国证监会有关派出机构报送上年度廉洁从业管理情况报告（A 选项错误，并未提及应当报送半年度报告）。有下列情形之一的，证券期货经营机构应当在 5 个工作日内（C 选项错误，并非\"十个工作日内\"），向中国证监会有关派出机构报告（D 选项错误，并非\"中国证券业协会\"）：（1）证券期货经营机构在内部检查中，发现存在违反规定行为的；（2）证券期货经营机构及其工作人员发现监管人员存在应当回避的情形而未进行回避、利用职务之便索取或者收受不正当利益等违反廉洁规定行为的（B 选项正确）；（3）证券期货经营机构及其工作人员发现其股东、客户等相关方以不正当手段干扰监管工作的；（4）证券期货经营机构或者其工作人员因违反廉洁从业规定被纪检监察部门、司法机关立案调查或者被采取纪律处分、行政处罚、刑事处罚等措施的。故本题选B 选项。"},{"id":"law1-9","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"单选","q":"根据《证券行业诚信准则》，下列选项中，属于证券公司及其工作人员应当遵守的勤勉尽责要求的是（）。","options":["自觉学习了解并遵守相关法律法规、监管规定、自律规则、业务规范和内部规章制度","尊重同行，公平竞争，禁止商业贿赂，自觉维护市场竞争秩序，坚决反对不正当竞争的行为","对自己的专业能力有充分认识，不承诺力不能及或不能如期完成的业务，不推诿应承担的责任","不利用虚假和误导性信息进行宣传，不编造传播虚假和误导性信息"],"answer":"C","explain":"A 选项错误，属于合法合规的要求。B 选项错误，属于公平竞争的要求。C 选项正确，属于勤勉尽责的要求。D 选项错误，属于言行一致的要求。故本题选C 选项。【温馨提示】机构及其工作人员应当自觉遵守以下勤勉尽责要求：（1）恪守职业操守，忠实勤勉，履行对投资者及其他利益相关方的责任和义务；（2）持续学习，不断提升专业能力，保证服务质量；（3）专业审慎，尽到合理专业的注意义务，履职尽责；（4）对自己的专业能力有充分认识，不承诺力不能及或不能如期完成的业务，不推诿应承担的责任；（5）实事求是，独立、审慎、客观、公正开展业务，不受其他单位和个人的非法干预和影响；（6）按规定做好相关工作底稿档案的记录、归集和保存管理。"},{"id":"law1-10","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"单选","q":"公司分配当年税后利润时，应当提取利润的 10%列入公司法定公积金。公司法定公积金累计额为公司注册资本的（）以上的，可以不再提取。","options":["20%","30%","50%","60%"],"answer":"C","explain":"C 选项正确，公司分配当年税后利润时，应当提取利润的 10%列入公司法定公积金。公司法定公积金累计额为公司注册资本的50%以上的，可以不再提取。故本题选C 选项。"},{"id":"law1-11","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"单选","q":"股份有限公司的发起人不得超过（）。","options":["50 人","30 人","200 人","100 人"],"answer":"C","explain":"C 选项正确，发起人符合法定人数。设立股份有限公司，应当有 1 人以上 200 人以下为发起人，其中应当有半数以上的发起人在中华人民共和国境内有住所。故本题选C 选项。"},{"id":"law1-12","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"单选","q":"股票期权经过（）交付权利金后，可以决定是否在约定期间内是否行使权利。","options":["双方","买方","卖方","中间交易方"],"answer":"B","explain":"A 选项错误，期权交易中仅买方支付权利金，卖方收取权利金，不存在\"双方均支付\"的情形。B 选项正确，股票期权买方有权决定在合约规定期间内是否行权。股票期权买方提出行权时，股票期权卖方应当按照有关规定履行相应义务。C 选项错误，卖方的义务是\"收取权利金后，在买方行权时必须履约\"，并非支付权利金。D 选项错误，中间交易方仅提供交易平台或经纪服务，不参与权利金的支付或收取。故本题选B 选项。"},{"id":"law1-13","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"单选","q":"甲乙丙合伙设立企业，甲乙是普通合伙人，丙是有限合伙人，问（）要符合私募基金管理人的要求监管。","options":["甲和乙","甲","甲乙丙","乙"],"answer":"A","explain":"私募基金管理人应由依法设立的公司或者合伙企业担任，以合伙企业形式设立的私募基金，资产由普通合伙人管理的，普通合伙人视同私募基金管理人进行规范。A 选项正确，甲和乙是普通合伙人，要符合私募基金管理人的要求监管。故本题选A 选项。"},{"id":"law1-14","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"单选","q":"开放式基金的基金份额在基金存续期间，基金份额持有人（）。","options":["可在任何时间申请赎回","可以在基金合同约定的时间和场所申请赎回","可以在任何场所申请赎回","不得申请赎回"],"answer":"B","explain":"B 选项正确，开放式基金的基金份额可以在基金合同约定的时间和场所进行申购或者赎回，导致开放式基金的规模一直处于增加或减少的变动之中。故本题选B 选项。"},{"id":"law1-15","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"单选","q":"上市公司年度报告应当在每个会计年度结束之日起（）前披露。","options":["1 月31 日","3 月31 日","4 月30 日","6 月30 日"],"answer":"C","explain":"上市公司、公司债券上市交易的公司、股票在国务院批准的其他全国性证券交易场所交易的公司，应当按照以下规定报送和公告：（1）在每一会计年度结束之日起 4 个月内，报送并公告年度报告，其中的年度财务会计报告应当经符合《证券法》规定的会计师事务所审计（C 选项正确，会计年度于 12 月 31 日结束，四个月后的截止日期即为次年4 月30 日）；（2）在每一会计年度的上半年结束之日起2 个月内，报送并公告中期报告。故本题选C 选项。"},{"id":"law1-16","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"单选","q":"同一投资者最多可以有（）个同名资金账户。","options":["3","2","1","5"],"answer":"D","explain":"D 选项正确，同一客户最多开立 5 个同名资金账户，每个资金账户分别对应一个存管银行，客户的每个资金账户与对应存管银行账户之间，保持一一对应的第三方存管关系。故本题选D 选项。"},{"id":"law1-17","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"单选","q":"为加强对证券公司客户资产的保护，下列不符合《证券公司监督管理条例》规定的是（）。","options":["证券公司可以将客户的交易结算资金放在指定的商业银行金融机构","为保护客户权益，证券公司的资产应与客户资产相互独立","证券公司可以将客户资产用于向他人提供融资或者担保","在符合一定条件下的情况下，证券公司可以对客户交易结算资金进行单方面的处理"],"answer":"C","explain":"根据《证券公司监督管理条例》第六十一条的规定，证券公司不得以证券经纪客户或者证券资产管理客户的资产向他人提供融资或者担保（C 选项符合题意，并非\"可以\"）。任何单位或者个人不得强令、指使、协助、接受证券公司以其证券经纪客户或者证券资产管理客户的资产提供融资或者担保。故本题选C 选项。"},{"id":"law1-18","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"单选","q":"下列不属于证券公司代销金融产品应当遵循的原则是（）。","options":["公开","公平","平等","诚实信用"],"answer":"A","explain":"证券公司代销金融产品应遵循平等（C 选项不符合题意）、自愿、公平（B 选项不符合题意）、诚实信用（D 选项不符合题意）和适当性原则，避免利益冲突，不得损害客户合法权益。故本题选A 选项。"},{"id":"law1-19","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"单选","q":"下列不属于证券公司风险控制指标的是（）。","options":["净资产","风险覆盖率","资本杠杆率","净资本"],"answer":"A","explain":"为了建立以净资本和流动性为核心的风险控制指标体系，加强证券公司风险监管，督促证券公司加强内部控制、提升风险管理水平、防范风险，证券公司应当计算净资本（A 选项符合题意，并非\"净资产\"；D 选项不符合题意）、风险覆盖率（B 选项不符合题意）、资本杠杆率（C 选项不符合题意）、流动性覆盖率、净稳定资金率等各项风险控制指标。故本题选A 选项。"},{"id":"law1-20","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"单选","q":"下列不属于证券公司及相关从业人员从事私募资产管理业务的禁止行为的是（）。","options":["投资决策出现严重失误导致产品净值大幅度回撤","为规避监管的证券期货业务活动提供交易便利","以获取佣金为目的，使用资产管理计划财产进行不必要的交易","间接向投资者返还管理费"],"answer":"A","explain":"证券公司及相关从业人员从事私募资产管理业务，不得有下列行为：（1）为违法或者规避监管的证券期货业务活动提供交易便利（B 选项不符合题意）。（2）直接或间接向投资者返还管理费（D 选项不符合题意）。（3）以获取佣金或者其他不当利益为目的，使用资产管理计划财产进行不必要的交易（ C 选项不符合题意）。A 选项符合题意，属于业务上的失误。故本题选A 选项。【温馨提示】证券公司及相关从业人员从事私募资产管理业务，不得有的行为，还包括：（1）利用资产管理计划从事内幕交易、操纵市场或者其他不正当、违法的证券期货业务活动。（2）泄露因职务便利获取的未公开信息、利用该信息从事或者明示、暗示他人从事相关交易活动。（3）从事非公平交易、利益输送等损害投资者合法权益的行为。（4）利用资产管理计划进行商业贿赂。（5）侵占、挪用资产管理计划财产。（6）利用资产管理计划或者职务便利为投资者以外的第三方谋取不正当利益。（7）法律、行政法规和中国证监会规定禁止的其他行为。"},{"id":"law1-21","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"单选","q":"下列不属于证券自营业务禁止性行为的是（）。","options":["违反规定委托他人代为买卖证券","将自营业务与经纪业务混合操作","将自营账户借给他人使用","通过专用自营席位进行证券交易"],"answer":"D","explain":"证券自营业务的禁止性行为包括：①内幕交易；②操纵市场；③假借他人名义或者个人名义进行自营业务；④违反规定委托他人代为买卖证券（A 选项不符合题意）；⑤违反规定购买本证券公司控股股东或者与本证券公司有其他重大利害关系的发行人发行的证券；⑥将自营账户借给他人使用（C 选项不符合题意）；⑦将自营业务与经纪业务混合操作（B 选项不符合题意）；⑧法律、行政法规或中国证监会禁止的其他行为。D 选项符合题意，属于证券自营业务的具体操作要求。故本题选D 选项。"},{"id":"law1-22","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"单选","q":"下列关于分类监管制度对证券公司正向激励作用的说法，错误的是（）。","options":["提升风险控制能力","培育核心竞争力","便于证券公司广告宣传","加强合规管理"],"answer":"C","explain":"证券公司分类监管制度是证券行业的一项基础性制度，对促进证券公司加强合规管理（D 选项正确）、提升风险控制能力（A 选项正确）、培育核心竞争力（B 选项正确），发挥了正向激励作用。C 选项错误，证券公司不得将分类评估结果用于广告、宣传、营销等商业目的。故本题选C 选项。"},{"id":"law1-23","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"单选","q":"下列属于证券公司全体工作人员应履行的合规管理职责的是（）。","options":["评估合规管理有效性","组织制定公司规章制度，并监督其实施","在业务开展过程中主动识别和防范业务合规风险","建立与合规负责人的直接沟通机制"],"answer":"C","explain":"C 选项正确，全体工作人员履行的合规管理职责包括：在业务开展过程中主动识别和防范业务合规风险。A、D 选项错误，属于董事会的合规管理职责。B 选项错误，属于经营管理主要负责人的职责。故本题选C 选项。【温馨提示】全体工作人员履行下列合规管理职责：（1）主动了解、掌握和遵守相关法律、法规和准则；（2）积极参加公司安排的合规培训和合规宣导活动；（3）根据公司要求，签署并信守相关合规承诺；（4）在执业过程中充分关注执业行为的合法合规性；（5）在业务开展过程中主动识别和防范业务合规风险；（6）发现违法违规行为或者合规风险隐患时，应当主动按照公司规定及时报告；（7）出现合规风险事项时，积极配合公司调查，并接受公司问责，落实整改要求。"},{"id":"law1-24","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"单选","q":"以公司是否有（）可分为国有独资企业、国有控股企业、国有参股企业、非国有公司等。","options":["股东人数和股份流动性","相互之间的组织关系","公司注册地","国有资本及其所占比重"],"answer":"D","explain":"公司可依照不同的分类标准作不同的分类。A 选项错误，依股东人数和股份流动性等，可分为有限责任公司和股份有限公司。B 选项错误，依相互之间的组织关系，可分为母公司与子公司、总公司与分公司、企业集团与成员企业等。C 选项错误，依公司注册地，可分为中国公司和外国公司；依股份公司之股份是否在证券交易所挂牌交易，可分为上市公司和非上市公司。D 选项正确，依公司是否有国有资本及其所占比重，可分为国有独资公司、国有控股公司、国有参股公司、非国有公司等。故本题选D 选项。"},{"id":"law1-25","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"单选","q":"有权决定国有独资公司合并分立的是（）。","options":["股东会","董事会","国有资产监督管理机构","监事会"],"answer":"C","explain":"C 选项正确，国务院或者地方人民政府可以授权国有资产监督管理机构或者其他部门、机构代表本级人民政府对国家出资公司履行出资人职责。国有独资公司的合并、分立、解散、申请破产，增加或者减少注册资本，分配利润，应当由履行出资人职责的机构决定。故本题选C 选项。"},{"id":"law1-26","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"单选","q":"有限责任公司的设立方式是（）。","options":["发起设立","募集设立","公开募集","内部募集"],"answer":"A","explain":"A 选项正确，发起设立适用于有限责任公司和股份有限公司。故本题选A 选项。【温馨提示】公司的设立方式有两种，即发起设立和募集设立。发起设立，是指由发起人认购设立公司时应发行的全部股份而设立公司。发起设立适用于有限责任公司和股份有限公司。募集设立，是指由发起人认购设立公司时应发行股份的一部分，其余股份向特定对象募集或者向社会公开募集而设立公司。募集设立只适用于股份有限公司。"},{"id":"law1-27","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"单选","q":"证券的发行、交易活动，必须遵循的原则是（）。","options":["公开、平等、公正","公开、公平、平等","开放、公平、公正","公平、公开、公正"],"answer":"D","explain":"D 选项正确，证券的发行、交易活动，必须遵循公开、公平、公正\"三公\"原则。故本题选D 选项。"},{"id":"law1-28","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"单选","q":"证券公司持续合规状况的评价依据之一为（）采取的刑事处罚措施。","options":["中国证监会","司法机关","中国证监会及其派出机构","中国人民银行"],"answer":"B","explain":"B 选项正确，证券公司持续合规状况主要根据司法机关采取的刑事处罚措施、中国证监会及其派出机构采取的行政处罚措施、行政监管措施及证券期货行业自律组织纪律处分、自律管理措施等情况进行评价。故本题选B 选项。"},{"id":"law1-29","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"单选","q":"证券公司进行柜台交易，其（）应当通过中国证券业协会组织的专业评价。","options":["柜台交易管理制度和重大事项报告","实施方案和重大事项报告","柜台交易管理制度和实施方案","实施方案和定期报告"],"answer":"C","explain":"证券公司进行柜台交易，应当报中国证券业协会备案，其柜台交易管理制度和实施方案应当通过中国证券业协会组织的专业评价（C 选项正确）。故本题选C 选项。"},{"id":"law1-30","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"证券公司进行柜台交易，向投资者收取履约保证金的，应当在双方约定的金融机构开立（）存放，不得违约动用。","options":["存款账户","专门账户","产品账户","信用账户"],"answer":"B","explain":"B 选项正确，证券公司进行柜台交易，与投资者约定抵押、质押等财产担保的，应当依法办理担保设定手续；向投资者收取履约保证金的，应当在双方约定的金融机构开立专门账户存放，不得违约动用。A 选项错误，存款账户未体现\"专户专用\"的要求，可能导致资金混同。C 选项错误，产品账户适用于私募产品的交易登记。D 选项错误，信用账户属于融资融券业务的担保账户。故本题选B 选项。"},{"id":"law1-31","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"证券公司无法以合理成本及时获得充足资金，以偿付到期债务、履行其他支付义务和满足正常业务开展的资金需求的风险是（）。","options":["流动性风险","操作风险","声誉风险","信用风险"],"answer":"A","explain":"A 选项符合题意，流动性风险，是指证券公司无法以合理成本及时获得充足资金，以偿付到期债务、履行其他支付义务和满足正常业务开展的资金需求的风险。故本题选A 选项。【温馨提示】（1）操作风险是指由不完善或有问题的内部程序、人员、信息技术系统，以及外部事件造成损失的风险。（2）声誉风险是指由于证券经营机构行为或外部事件及其工作人员违反廉洁规定、职业道德、业务规范、行规行约等相关行为，导致投资者、发行人、监管机构、自律组织、社会公众、媒体等对证券公司形成负面评价，从而损害其品牌价值，不利其正常经营，甚至影响到市场稳定和社会稳定的风险。（3）信用风险指因融资方、交易对手或发行人等违约导致损失的风险。"},{"id":"law1-32","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"证券公司向普通投资者销售产品前，应当告知的信息不包括（）。","options":["可能直接导致本金亏损的事项","限制销售对象权利行使期限或者可解除合同期限等全部限制内容","可能直接导致超过原始本金损失的事项","就产品收益提供的确定性判断"],"answer":"D","explain":"经营机构向普通投资者销售产品或者提供服务前，应当告知下列信息：（1）可能直接导致本金亏损的事项（A 选项不符合题意）；（2）可能直接导致超过原始本金损失的事项（C 选项不符合题意）；（3）因经营机构的业务或者财产状况变化，可能导致本金或者原始本金亏损的事项；（4）因经营机构的业务或者财产状况变化，影响客户判断的重要事由；（5）限制销售对象权利行使期限或者可解除合同期限等全部限制内容（ B 选项不符合题意）；（6）投资者适当性匹配意见。D 选项符合题意，经营机构在销售产品或者提供服务的过程中禁止向投资者就不确定事项提供确定性的判断，或者告知投资者有可能使其误认为具有确定性的意见。故本题选D 选项。"},{"id":"law1-33","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"证券公司应当采取有效措施，确保在柜台市场交易的私募产品持有人数量符合相关规定，其中，非公开募集基金的合格投资者累计不得超过（）人。","options":["150","100","300","200"],"answer":"D","explain":"D 选项正确，非公开募集基金应当向合格投资者募集，合格投资者累计不得超过 200 人。故本题选D 选项。"},{"id":"law1-34","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"证券公司应当在全公司推行的风险文化是（）。","options":["积极","保守","激进","稳健"],"answer":"D","explain":"D 选项正确，证券公司应当在全公司推行稳健的风险文化，形成与本公司相适应的风险管理理念、价值准则、职业操守，建立培训、宣导和监督机制并纳入考核体系。故本题选D 选项。"},{"id":"law1-35","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"证券公司应当自资产管理计划终止之日起（）个工作日内报告中国证券投资基金业协会。","options":["1","3","4","5"],"answer":"D","explain":"D 选项正确，证券公司应当自资产管理计划终止之日起 5 个工作日内报告中国证券投资基金业协会。故本题选D 选项。"},{"id":"law1-36","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"证券公司证券自营业务投资运作的最高管理机构是（），负责确定具体的资产配置策略、投资事项和投资品种等。","options":["股东会","自营业务部门","董事会","投资决策机构"],"answer":"D","explain":"D 选项正确，投资决策机构是自营业务投资运作的最高管理机构，负责确定具体的资产配置策略、投资事项和投资品种等。故本题选D 选项。【温馨提示】股东会是公司的权力机构。董事会是自营业务的最高决策机构，在严格遵守监管法规中关于自营业务规模等风险控制指标规定基础上，根据公司资产、负债、损益和资本充足等情况确定自营业务规模、可承受的风险限额等，并以董事会决议的形式进行落实，自营业务具体投资运作管理由董事会授权公司投资决策机构决定。自营业务部门为自营业务的执行机构，应在投资决策机构作出的决策范围内，根据授权负责具体投资项目的决策和执行工作。"},{"id":"law1-37","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"证券公司中应对违反职责范围内的内部控制要求所导致的风险和损失承担首要责任的是（）。","options":["直接从事业务经营活动的相关人员","董事会","经理层","合规部门"],"answer":"A","explain":"A 选项正确，直接从事业务经营活动的业务部门和分支机构的相关人员有义务向证券公司报告内部控制的缺陷，并及时加以纠正。相关人员应对违反职责范围内的内部控制导致的风险和损失承担首要责任。故本题选A 选项。"},{"id":"law1-38","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"证券金融公司向证券公司转融通的期限不得超过（）个月。","options":["12","6","3","9"],"answer":"B","explain":"B 选项正确，证券金融公司向证券公司转融通的期限不得超过6 个月。故本题选B 选项。"},{"id":"law1-39","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"中国证监会对违反《证券公司融资融券业务管理办法》的证券公司可采取的监管措施不包括（）。","options":["撤销业务许可","暂停部分业务","暂停全部业务","追究刑事责任"],"answer":"D","explain":"证券公司或其分支机构违反《证券公司融资融券业务管理办法》，中国证监会或者其派出机构可采取责令改正、监管谈话、出具警示函、责令公开说明、责令参加培训、责令定期报告、暂不受理与行政许可有关的文件、暂停部分或者全部业务（ B、C 选项不符合题意）、撤销业务许可（A 选项不符合题意）等相关监管措施。D 选项符合题意，属于涉嫌犯罪的情况下依法移送司法机关处理。故本题选D 选项。"},{"id":"law1-40","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"法律关系由（）要素构成。","options":["法律关系行为","法律关系客体","法律关系主体","法律关系内容"],"answer":"BCD","explain":"法律关系由主体（C 选项正确）、客体（B 选项正确）与内容（D 选项正确）三个要素构成。A 选项错误，行为属于客体中的一类对象。故本题选BCD 选项。【温馨提示】法律关系的三要素包括：（1）法律关系主体，是指在法律关系中享有权利和承担义务的人：自然人、组织和国家；（2）法律关系客体是法律关系主体的权利和义务所指向的对象：物、人身、人格、精神成果、行为；（3）法律关系的内容是指法律关系中的权利和义务。"},{"id":"law1-41","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"根据《发布证券研究报告暂行规定》，证券公司证券投资咨询机构发布的证券研究报告，应当载明事项有（）。","options":["证券研究报告采用的信息和资料来源","使用证券研究报告的风险提示","证券公司、证券投资咨询机构名称","收费标准和支付方式"],"answer":"ABC","explain":"经营机构发布的证券研究报告，应当载明下列事项：（1）\"证券研究报告\"字样；（2）经营机构名称（C 选项正确）；（3）具备证券投资咨询业务资格的说明；（4）证券分析师姓名及其登记编码；（5）发布证券研究报告的时间；（6）证券研究报告采用的信息和资料来源（A 选项正确）；（7）使用证券研究报告的风险提示（B 选项正确）。故本题选ABC 选项。"},{"id":"law1-42","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"根据《证券发行与承销管理办法》证券发行与承销信息披露的有关规定，首次公开发行股票的发行人和主承销商应当在发行和承销过程中公开披露信息的具体内容包括（）。","options":["招股意向书刊登首日在发行公告中披露包括发行定价方式、程序、股票配售原则等信息","在发行结果公告中披露获配投资者名称以及每个获配投资者的报价、申购数量等信息","网上申购前披露每位网下投资者的详细报价情况","采用询价方式且存在规定情形之一的，应当在网上申购前发布投资风险特别公告，详细说明定价合理性，提示投资者注意投资风险"],"answer":"ABCD","explain":"A 选项正确，招股意向书刊登首日，应当在发行公告中披露发行定价方式、定价程序、参与网下询价投资者条件、证券配售原则、配售方式、有效报价的确定方式、中止发行安排、发行时间安排和路演推介相关安排等信息。B 选项正确，在发行结果公告中披露获配投资者名称以及每个获配投资者的报价、申购数量和获配数量等，并明确说明自主配售的结果是否符合事先公布的配售原则。C 选项正确，网上申购前，应当披露每位网下投资者的详细报价情况，包括投资者名称、申购价格及对应的拟申购数量。D 选项正确，采用询价方式且存在规定情形之一的，应当在网上申购前发布投资风险特别公告，详细说明定价合理性，提示投资者注意投资风险。故本题选ABCD 选项。"},{"id":"law1-43","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"根据《证券法》，证券的发行、交易活动必须遵守法律、行政法规；禁止行为有（）。","options":["欺诈","内幕交易","获取利益","操纵证券市场"],"answer":"ABD","explain":"A、B、D 选项正确，证券的发行、交易活动，必须遵守法律、行政法规；禁止欺诈、内幕交易和操纵证券市场的行为。C 选项错误，证券参与方的目的是盈利，合法合规地通过证券交易获取利益并不违法。故本题选择ABD 选项。"},{"id":"law1-44","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"根据《证券法》，证券服务机构未勤勉尽责，所制作、出具的文件有虚假记载、误导性陈述或者重大遗漏的，可以采取的措施包括（）。","options":["责令改正","没收业务收入","暂停或者禁止从事证券服务业务","对直接负责的主管人员给予警告，并处以五十万元以上五百万元以下的罚款"],"answer":"ABC","explain":"证券服务机构违反《证券法》第一百六十三条的规定，未勤勉尽责，所制作、出具的文件有虚假记载、误导性陈述或者重大遗漏的，责令改正（ A 选项正确），没收业务收入（ B 选项正确），并处以业务收入 1 倍以上 10 倍以下的罚款，没有业务收入或者业务收入不足 50 万元的，处以 50 万元以上 500 万元以下的罚款；情节严重的，并处暂停或者禁止从事证券服务业务（C选项正确）。对直接负责的主管人员和其他直接责任人员给予警告，并处以 20 万元以上 200 万元以下的罚款（D 选项错误，并非\"五十万元以上五百万元以下\"）。故本题选ABC 选项。"},{"id":"law1-45","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"根据《证券公司代销金融产品管理规定》，下列做法错误的有（）。","options":["甲证券公司营业部员工张某向投资者宣传某股票型基金稳赚不赔","乙证券公司营业部员工王某与客户约定某基金亏损由王某承担","丙证券公司营业部销售基金赠送大米","丁证券公司营业部员工李某销售戊基金公司的基金后，收取戊基金公司奖励的购物卡"],"answer":"ABCD","explain":"根据《证券公司代销金融产品管理规定》，证券公司及其从事金融产品代销业务的人员在代销金融产品过程中不得有下列行为：（1）采取夸大宣传、虚假宣传等方式误导客户购买金融产品（A 选项错误）；（2）采取抽奖、回扣、赠送实物等方式诱导客户购买金融产品（C 选项错误）；（3）与客户分享投资收益、分担投资损失（B 选项错误）；（4）使用除证券公司客户交易结算资金专用存款账户外的其他账户，代委托人接收客户购买金融产品的资金；（5）证券公司从事代销金融产品活动的人员不得接受委托人给予的财物或其他利益（ D 选项错误）；（6）其他可能损害客户合法权益的行为。故本题选ABCD 选项。"},{"id":"law1-46","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"根据《证券公司为期货公司提供中间介绍业务试行办法》，证券公司受期货公司委托从事介绍业务，应当提供的服务有（）。","options":["提供期货交易设施","提供期货行情信息","代期货公司收取期货保证金","协助办理开户手续"],"answer":"ABD","explain":"根据《证券公司为期货公司提供中间介绍业务试行办法》第九条的规定，证券公司受期货公司委托从事介绍业务，应当提供下列服务：（1）协助办理开户手续（D 选项正确）；（2）提供期货行情信息、交易设施（A、B 选项正确）；（3）中国证监会规定的其他服务。C 选项错误，证券公司不得代理客户进行期货交易、结算或者交割，不得代期货公司、客户收付期货保证金，不得利用证券资金账户为客户存取、划转期货保证金。故本题选ABD 选项。"},{"id":"law1-47","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"根据《证券公司信用风险管理指引》，下列关于证券公司信用风险管理的说法，正确的有（）。","options":["证券公司相关业务部门是信用风险管理的一线主体","证券公司董事会应承担信用风险管理的监督责任","证券公司应建立有效的信用风险管理组织架构","证券公司应建立健全有效的考核及问责机制"],"answer":"ACD","explain":"B 选项错误，证券公司监事会（或行使监事会职权的监事或董事会设置的由董事组成的审计委员会）承担全面风险管理的监督责任。因此，监事会承担信用风险管理的监督责任（并非董事会）。故本题选ACD 选项。"},{"id":"law1-48","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"根据《证券基金经营机构信息技术管理办法》，下列关于证券公司经营数据和客户信息保护的说法正确的有（）。","options":["证券公司应当记录经营数据和客户信息的使用情况，并持续监督信息技术服务机构等相关方落实保密协议的情况","证券公司发现信息技术服务机构等相关方违规存储或者使用自身经营数据和客户信息的，应当责令其立即改正并销毁已获取的经营数据和客户信息","信息技术服务机构等相关方拒绝配合整改的，证券公司应当立即停止与其合作，并采取措施维护自身及客户的合法权益","证券公司在收集使用客户信息之前，可以不用公开收集、使用的规则和目的，但应当征得客户同意"],"answer":"ABC","explain":"D 选项错误，在收集使用客户信息之前，证券公司应当公开收集、使用的规则和目的（并非 \"可以不用\"），并征得客户同意。故本题选ABC 选项。"},{"id":"law1-49","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"根据《证券基金经营机构信息技术管理办法》，下列关于证券公司委托信息技术服务机构提供产品或服务的说法，正确的有（）。","options":["证券公司可以委托信息技术服务机构提供产品或服务，但其依法应当承担的责任不因委托而免除或减轻","除法律法规及中国证监会另有规定外，可以将重要信息系统的运维、日常安全管理交由信息技术服务机构独立实施","证券公司应当清晰、准确、完整地掌握重要信息系统的技术架构、业务逻辑和操作流程等内容","证券公司应确保重要信息系统运行始终处于自身控制范围"],"answer":"ACD","explain":"A 选项正确，证券公司借助信息技术手段从事证券基金业务活动的，可以委托信息技术服务机构提供产品或服务，但证券公司依法应当承担的责任不因委托而免除或减轻。B 选项错误，除法律法规及中国证监会另有规定外，不得将重要信息系统的运维、日常安全管理交由信息技术服务机构独立实施。C、D 选项正确，证券公司应当清晰、准确、完整地掌握重要信息系统的技术架构、业务逻辑和操作流程等内容，确保重要信息系统运行始终处于自身控制范围。故本题选ACD 选项。"},{"id":"law1-50","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"根据《证券投资顾问业务暂行规定》，证券公司、证券投资咨询机构向客户提供证券投资顾问服务，应当告知客户的基本信息包括（）。","options":["证券投资顾问不得代客户作出投资决策","证券投资顾问的姓名及其登记编码","证券投资顾问服务的内容和方式","投资决策由客户作出，投资风险与客户共担"],"answer":"ABC","explain":"证券公司、证券投资咨询机构向客户提供证券投资顾问服务，应当告知客户下列基本信息：（1）公司名称、地址、联系方式、投诉电话、证券投资咨询业务资格等。（2）证券投资顾问的姓名及其登记编码（B 选项符合题意）。（3）证券投资顾问服务的内容和方式（C 选项符合题意）。（4）投资决策由客户作出，投资风险由客户承担（D 选项不符合题意，并非\"共担\"）。（5）证券投资顾问不得代客户作出投资决策（A 选项符合题意）。故本题选ABC 选项。"},{"id":"law1-51","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"根据《中华人民共和国期货和衍生品法》，下列关于期货结算与交割的说法，正确的有（）。","options":["期货交易实行当日无负债结算制度","在期货交易场所规定的时间，期货结算机构应当在当日按照结算价对结算参与人进行结算","交易者在交割过程中违约的，期货结算机构有权对交易者的标准仓单等合约标的物权利凭证进行处置","结算参与人收取的权利金，在期货保证金存管机构专户存放"],"answer":"ABD","explain":"A、B 选项正确，期货交易实行当日无负债结算制度。在期货交易场所规定的时间，期货结算机构应当在当日按照结算价对结算参与人进行结算。C 选项错误，交易者在交割过程中违约的，结算参与人（并非期货结算机构）有权对交易者的标准仓单等合约标的物权利凭证进行处置。D 选项正确，期货结算机构、结算参与人收取的保证金、权利金等，应当与其自有资金分开，按照国务院期货监督管理机构的规定，在期货保证金存管机构专户存放，分别管理，禁止违规挪用。故本题选ABD 选项。"},{"id":"law1-52","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"根据公司经营原则，公司从事经营活动，应当遵守（）。","options":["商业道德","法律","社会公德","行政法规"],"answer":"ABCD","explain":"公司从事经营活动，应当遵守法律法规（ B、D 选项正确），遵守社会公德、商业道德（ A、C选项正确），诚实守信，接受政府和社会公众的监督；应当充分考虑公司职工、消费者等利益相关者的利益以及生态环境保护等社会公共利益，承担社会责任。故本题选ABCD 选项。"},{"id":"law1-53","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"公司合并可以采取（）的形式。","options":["完全合并","吸收合并","部分合并","新设合并"],"answer":"BD","explain":"B、D 选项正确，公司合并可以采取吸收合并或者新设合并。故本题选BD 选项。"},{"id":"law1-54","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"公司在企业信息系统平台公示的内容包括（）。","options":["出资时间","出资方式","认缴出资","实缴出资"],"answer":"ABCD","explain":"公司应通过企业信用信息公示系统及时公示其股东认缴和实缴出资（ C、D 选项符合题意）、出资时间（A 选项符合题意）、出资方式（B 选项符合题意）等情况。故本题选ABCD 选项。"},{"id":"law1-55","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"公司章程对（）具有约束力。","options":["公司","股东","董事","高级管理人员"],"answer":"ABCD","explain":"公司章程（也称\"公司的宪法\"），是指由公司权力机构依据规定程序制定的，规范股东出资及相关关系、公司组织机构设置、公司经营准则等公司营运基本规则，内部成员权利义务相关事项的法定文件，具有特定的法律地位。公司章程对公司（A 选项正确）、股东（B 选项正确）、董事（C 选项正确）、监事、高级管理人员（D 选项正确）具有约束力。故本题选ABCD 选项。"},{"id":"law1-56","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"股份有限公司章程上应当载明的事项有（）。","options":["发起人的名字","股份总数","公司的注册资本","公司经营范围"],"answer":"ABCD","explain":"股份有限公司章程应当载明下列事项：（1）公司经营范围（D 选项正确）；（2）公司注册资本、已发行的股份数和设立时发行的股份数，面额股的每股金额（B、C 选项正确）；（3）发起人的姓名或者名称、认购的股份数、出资方式（A 选项正确）。故本题选ABCD 选项。【温馨提示】股份有限公司章程应当载明的事项还有：（1）公司名称和住所；（2）公司设立方式；（3）每一类别股的股份数及其权利和义务（发行类别股的）；（4）董事会的组成、职权和议事规则；（5）公司法定代表人的产生、变更办法；（6）监事会的组成、职权和议事规则；（7）公司利润分配办法；（8）公司的解散事由与清算办法；（9）公司的通知和公告办法；（10）股东会认为需要规定的其他事项。"},{"id":"law1-57","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"关于证券公司风险控制指标标准，下列表述正确的是（）。","options":["风险覆盖率不低于100%","流动性覆盖率不低于100%","净稳定资金率不低于100%","资本杠杆率不低于100%"],"answer":"ABC","explain":"证券公司必须持续符合下列风险控制指标标准：（1）风险覆盖率不得低于100%（A 选项正确）；（2）资本杠杆率不得低于8%（D 选项错误，并非\"100%\"）；（3）流动性覆盖率不得低于100%（B 选项正确）；（4）净稳定资金率不得低于100%（C 选项正确）。故本题选ABC 选项。"},{"id":"law1-58","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"关于证券公司在销售产品或者提供服务过程中的责任，下列说法正确的有（）。","options":["将适当的产品或者服务销售或者提供给适合的投资者","全面了解投资者情况，深入调查分析产品或者服务信息","勤勉尽责，审慎履职","对违法违规行为承担法律责任"],"answer":"ABCD","explain":"经营机构在向投资者销售证券期货产品或者提供证券期货服务的过程中，应当遵守法律法规及其他有关规定，勤勉尽责，审慎履职（C 选项正确），全面了解投资者情况，深入调查分析产品或者服务信息（B 选项正确），科学有效评估，充分揭示风险，基于投资者的不同风险承受能力以及产品或者服务的不同风险等级等因素，提出明确的适当性匹配意见，将适当的产品或者服务销售或者提供给适合的投资者，并对违法违规行为承担法律责任（A、D 选项正确）。故本题选择ABCD 选项。"},{"id":"law1-59","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"关于证券金融公司开展转融通业务的证券来源，说法正确的有（）。","options":["证券金融公司通过证券交易所的业务平台融入的证券","证券金融公司直接使用证券公司客户的证券","证券金融公司通过转融通担保证券账户持有的证券","证券金融公司自有证券"],"answer":"AD","explain":"证券金融公司开展转融通业务，可以使用下列资金和证券：（1）自有资金和证券（D 选项正确）；（2）通过证券交易所的业务平台融入的资金和证券（A 选项正确）；（3）通过证券金融公司的业务平台融入的资金；（4）依法筹集的其他资金和证券。B 选项错误，证券金融公司直接使用证券公司客户的证券是严格禁止行为。C 选项错误，证券金融公司通过转融通担保证券账户持有的证券不计入其自有证券。故本题选AD 选项。"},{"id":"law1-60","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"合伙企业的特征是（）。","options":["共同转让","共同出资","共担风险","共享收益"],"answer":"BCD","explain":"合伙企业，是指由自然人、法人和其他组织依照《合伙企业法》订立合伙协议，共同出资（ B选项正确），共担风险（C 选项正确），共享收益（D 选项正确），对合伙企业债务承担责任的经营性组织。A 选项错误，\"共同转让\"不是合伙企业的特征，合伙人转让其在合伙企业中的财产份额，需遵守法律和合伙协议的规定。故本题选BCD 选项。"},{"id":"law1-61","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"进行融资融券业务时需要用到的账户有（）。","options":["融券专用证券账户","融资专用资金账户","客户信用证券账户","客户信用资金账户"],"answer":"ABCD","explain":"证券公司经营融资融券业务，应当以自己的名义，在证券登记结算机构分别开立融券专用证券账户（A 选项正确）、客户信用交易担保证券账户、信用交易证券交收账户和信用交易资金交收账户。证券公司经营融资融券业务，应当以自己的名义，在商业银行分别开立融资专用资金账户（ B选项正确）和客户信用交易担保资金账户。客户通过证券公司开展融资融券业务，应当在证券公司开立实名信用资金台账和信用证券账户（C 选项正确），在指定的商业银行开立实名信用资金账户（D 选项正确）。故本题选ABCD 选项。"},{"id":"law1-62","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"声誉风险应遵循的原则包括（）。","options":["全程全员原则","预防第一原则","审慎管理原则","快速响应原则"],"answer":"ABCD","explain":"声誉风险管理应遵循全程全员原则（A 选项符合题意）、预防第一原则（B 选项符合题意）、审慎管理原则（C 选项符合题意）、快速响应原则（D 选项符合题意）。故本题选ABCD 选项。"},{"id":"law1-63","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"下列各项中，属于证券市场行业自律规则的有（）。","options":["中国银行业协会制定的自律规则","中国证券业协会制定的自律规则","证券交易所制定的自律规则","中国证券登记结算有限责任公司制定的自律规则"],"answer":"BCD","explain":"证券市场的行业自律规则等包括以下几类：（1）证券交易场所制定的自律规则（C 选项符合题意）；（2）中国证券业协会制定的自律规则（B 选项符合题意）；（3）中国证券登记结算有限责任公司（简称 \"中国结算\"）制定的自律规则（ D 选项符合题意）。故本题选BCD 选项。"},{"id":"law1-64","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"下列关于公司的财务会计制度的说法，正确的有（）。","options":["公司违反规定向股东分配利润的，股东应当将违反规定分配的利润退还公司","公司除法定的会计账簿外，不得另立会计账簿","公司持有的本公司股份可分配利润","公司的公积金可用于弥补公司的亏损、扩大公司生产经营或者转为增加公司资本，资本公积金不得用于弥补公司的亏损"],"answer":"AB","explain":"A 选项正确，公司违反规定向股东分配利润的，股东应当将违反规定分配的利润退还公司。B 选项正确，公司除法定的会计账簿外，不得另立会计账簿。对公司资金，不得以任何个人名义开立账户存储。C 选项错误，公司持有的本公司股份不得分配利润。D 选项错误，公司的公积金用于弥补公司的亏损、扩大公司生产经营或者转为增加公司注册资本。公积金弥补公司亏损，应当先使用任意公积金和法定公积金；仍不能弥补的，可以按照规定使用资本公积金。因此资本公积金可以用于弥补公司的亏损。故本题选AB 选项。"},{"id":"law1-65","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"下列关于股份有限公司董事任免的说法，正确的有（）。","options":["董事会中的职工代表由公司职工通过职工代表大会、职工大会或者其他形式民主选举产生","非职工代表董事由股东会选举","董事任期由公司章程规定，但每届任期不得超过6 年","董事任期届满，连选可以连任"],"answer":"ABD","explain":"C 选项错误，董事任期由公司章程规定，但每届任期不得超过3 年（并非\"6 年\"）。故本题选ABD 选项。"},{"id":"law1-66","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"下列关于基金财产债权债务独立性的说法，正确的有（）。","options":["非因基金财产本身承担的债务，不得对基金财产强制执行","基金财产的债权不得与基金管理人固有财产的债务相抵销","不同基金财产的债权债务，可以相互抵销","基金财产的债权与基金管理人的固有财产严格区分"],"answer":"ABD","explain":"A 选项正确，基金财产的债务由基金财产本身承担，基金份额持有人以其出资为限对基金财产的债务承担责任。但基金合同依照《证券投资基金法》另有约定的，从其约定。非因基金财产本身承担的债务，不得对基金财产强制执行。B 选项正确，基金财产的债权，不得与基金管理人、基金托管人固有财产的债务相抵销。C 选项错误，不同基金财产的债权债务，不得相互抵销。D 选项正确，基金财产独立于基金管理人、基金托管人的固有财产。基金管理人、基金托管人不得将基金财产归入其固有财产。故本题选ABD 选项。"},{"id":"law1-67","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"下列关于欺诈发行证券罪的说法中，正确的有（）。","options":["必须具有数额巨大、后果严重或者其他严重情节才构成犯罪","若单位构成犯罪的，仅对单位判处罚金","欺诈发行的方式包括在发行文件中隐瞒重要事实或者编造重大虚假内容","犯罪主体只能为个人"],"answer":"AC","explain":"欺诈发行证券罪的客观方面：（1）行为人必须实施在招股说明书、认股书、公司、企业债券募集办法等发行文件中隐瞒重要事实或者编造重大虚假内容的行为（C 选项正确）。（2）行为人必须实施了发行证券的行为。如果行为人仅是制作了虚假的招股说明书、认股书、公司、企业债券募集办法等发行文件，而未实施发行证券的行为，不构成本罪。必须是既制作了虚假的上述文件，且已经发行证券的才构成本罪。（3）行为人制作虚假的招股说明书、认股书、公司、企业债券募集办法等发行文件发行证券的行为，必须达到一定的严重程度，即达到\"数额巨大、后果严重或者有其他严重情节的\"，才构成犯罪（A 选项正确）。B 选项错误，单位犯前述罪的，对单位判处非法募集资金金额 20%以上 1 倍以下罚金，并对其直接负责的主管人员和其他直接责任人员，依照《刑法》第一百六十条第一款的规定处罚（并非\"仅对单位判处罚金\"）。D 选项错误，欺诈发行证券罪的主体主要是单位（并非\"只能为个人\"）。自然人在一定条件下也能成为犯罪的主体。故本题选AC 选项。"},{"id":"law1-68","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"下列关于证券公司从事私募资产管理业务的投资经理应具备的条件，正确的是（）。","options":["最近三年未被监管机构采取重大行政监管措施","依法取得基金从业资格","具备良好的诚信记录","具有三年以上投资管理、投资研究、投资咨询等相关业务经验"],"answer":"ABCD","explain":"根据《证券期货经营机构私募资产管理业务管理办法》《证券期货经营机构投资管理人员注册登记规则》，私募资产管理业务投资经理应当依法取得基金从业资格（B 选项正确），具有 3年以上投资管理、投资研究、投资咨询等相关业务经验（D 选项正确），具备良好的诚信记录和职业操守（C 选项正确），且最近3 年未被监管机构采取重大行政监管措施（A 选项正确）、行政处罚，符合法律法规规定的其他条件。故本题选ABCD 选项。"},{"id":"law1-69","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"证券公司、证券投资咨询机构或者其他财务顾问机构存在下列（）情形时，不得担任上市公司独立财务顾问。","options":["持有或者通过协议、其他安排与他人共同持有上市公司股份达到 2%","上市公司持有或者通过协议、其他安排与他人共同持有财务顾问的股份达到 2%","财务顾问的监事在上市公司任职","最近1 年财务顾问为上市公司提供过融资服务"],"answer":"CD","explain":"存在下列情形之一的，不得担任独立财务顾问：（1）持有或者通过协议、其他安排与他人共同持有上市公司股份达到或者超过 5%（A 选项错误），或者选派代表担任上市公司董事；（2）上市公司持有或者通过协议、其他安排与他人共同持有财务顾问的股份达到或者超过 5%（B 选项错误），或者选派代表担任财务顾问的董事；（3）最近 2 年财务顾问与上市公司存在资产委托管理关系、相互提供担保，或者最近一年财务顾问为上市公司提供融资服务（D 选项正确）；（4）财务顾问的董事、监事、高级管理人员、财务顾问主办人或者其直系亲属有在上市公司任职等影响公正履行职责的情形（C 选项正确）；（5）在并购重组中为上市公司的交易对方提供财务顾问服务；（6）与上市公司存在利害关系、可能影响财务顾问及其财务顾问主办人独立性的其他情形。故本题选CD 选项。"},{"id":"law1-70","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"证券公司从事私募资产管理业务，其资产管理计划财产的独立性体现在（）。","options":["独立于证券公司的固有财产","独立于托管人的固有财产","独立于托管人托管的其他财产","独立于证券公司管理的其他财产"],"answer":"ABCD","explain":"资产管理计划财产独立于证券公司和托管人的固有财产（ A、B 选项正确），并独立于证券公司管理的和托管人托管的其他财产（ C、D 选项正确）。证券公司、托管人不得将资产管理计划财产归入其固有财产。故本题选ABCD 选项。"},{"id":"law1-71","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"证券公司防范敏感信息的不当流动和使用，可以在公开侧业务之间或保密侧业务之间采取的措施包括（）。","options":["信息隔离","限制名单","观察名单","跨墙"],"answer":"ABCD","explain":"证券公司可以根据公司实际需要，在公开侧业务之间或保密侧业务之间采取信息隔离（A 选项符合题意）、跨墙（D 选项符合题意）、观察名单（C 选项符合题意）、限制名单（B 选项符合题意）等措施，防范敏感信息的不当流动和使用。故本题选ABCD 选项。"},{"id":"law1-72","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"证券公司风险控制指标无法达标，严重危害证券市场秩序、损害投资者利益的，中国证监会可以区别情形对其采取的措施有（）。","options":["责令停业整顿","指定其他机构托管、接管","撤销经营证券业务许可","撤销"],"answer":"ABCD","explain":"证券公司风险控制指标无法达标，严重危害证券市场秩序、损害投资者利益的，中国证监会可以区别情形，对其采取下列措施：（1）责令停业整顿（A 选项正确）；（2）指定其他机构托管、接管（B 选项正确）；（3）撤销经营证券业务许可（C 选项正确）；（4）撤销（D 选项正确）。故本题选ABCD 选项。"},{"id":"law1-73","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"证券公司进行柜台交易，应当与特定对手方或投资者签订柜台交易合同，合同的方式可以有（）。","options":["书面","电子","口头","电话"],"answer":"AB","explain":"证券公司进行柜台交易，应当与特定交易对手方或投资者以书面或电子方式签订柜台交易合同（A、B 选项正确），约定双方的权利义务。不得以口头、电话这种方式（C、D 选项错误）。故本题选AB 选项。"},{"id":"law1-74","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"证券公司开展证券经纪业务中，禁止的行为包括（）。","options":["拒绝客户全权委托代理其买卖证券","将客户的资金账户、证券账户提供给他人使用","在经纪业务营销活动中委托不具有受托资格的单位进行客户招揽","对客户买卖证券承诺收益或赔偿"],"answer":"BCD","explain":"A 选项不符合题意，是可以做的行为。证券公司及其从业人员不得接受投资者的全权委托代理。B、C、D 选项符合题意，是禁止的行为。故本题选BCD 选项。【温馨提示】证券公司从事证券经纪业务，不得有下列行为：（1）诱导无投资意愿或者不具备相应风险承受能力的投资者开立账户、参与证券交易活动；（2）提供、传播虚假或者误导投资者的信息；（3）直接或者变相向投资者返还佣金、赠送礼品礼券或者提供其他非证券业务性质的服务；（4）采用诋毁其他证券公司等不正当竞争方式招揽投资者；（5）对投资者证券买卖的收益或者赔偿证券买卖的损失作出承诺；（6）与投资者约定分享投资收益或者分担投资损失；（7）违规委托证券经纪人以外的个人或者机构进行投资者招揽、服务活动；（8）损害投资者合法权益或者扰乱市场秩序的其他行为。"},{"id":"law1-75","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"证券公司可以通过（）开展客户招揽与服务活动。","options":["基金公司","公司员工","委托经纪人","委托其它机构"],"answer":"BC","explain":"A 选项错误，基金公司是独立的资产管理机构。证券公司不能直接通过基金公司为自己招揽客户或提供服务。目前在我国证券经纪业务营销渠道包括证券公司内部营销员工进行客户招揽和客户服务（B 选项正确），也可由证券公司委托经纪人开展（C 选项正确），但证券公司不得违反规定委托其他单位或者个人进行客户招揽、客户服务、产品销售活动（D 选项错误）。故本题选BC 选项。"},{"id":"law1-76","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"证券公司每年在规定时间内应报送柜台市场业务年度报告，下列关于报告内容的说法，正确的有（）。","options":["投资者适当性管理","登记结算","风险及合规管理","交易情况"],"answer":"ABCD","explain":"证券公司应于每月结束后 5 个工作日内按要求向中国证券业协会报送柜台交易月度报表；每年结束后在规定时间报送柜台市场业务年度报告，内容包括但不限于：柜台市场业务总体情况、交易（D 选项正确）、登记结算（B 选项正确）、投资者适当性管理（A 选项正确）、风险及合规管理（C 选项正确）等。故本题选ABCD 选项。"},{"id":"law1-77","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"证券公司应当在全公司推行稳健的风险文化，形成与本公司相适应的（）。","options":["风险管理理念","价值准则","监督机制","职业操守"],"answer":"ABCD","explain":"证券公司应当在全公司推行稳健的风险文化，形成与本公司相适应的风险管理理念（A 选项正确）、价值准则（B 选项正确）、职业操守（D 选项正确），建立培训、宣导和监督机制（C 选项正确）并纳入考核体系。故本题选ABCD 选项。"},{"id":"law1-78","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"证券投资顾问应当遵循诚实信用原则、勤勉、审慎地为客户提供证券投资顾问服务。证券投资顾问不得从事的活动有（）。","options":["以任何方式向客户承诺或保证投资收益","以个人名义向客户收取证券投资顾问服务费用","向他人泄露客户的投资决策计划信息","通过网络等公众媒体作出买入具体证券的投资建议"],"answer":"ABCD","explain":"证券投资顾问不得从事下列活动：（1）以任何方式向客户承诺或保证投资收益（A 选项正确）；（2）对服务能力和过往业绩进行虚假、不实、误导性的营销宣传；（3）向他人泄露客户的投资决策计划信息（C 选项正确）；（4）以个人名义向客户收取证券投资顾问服务费用（B 选项正确）；（5）通过广播、电视、网络、报刊等公众媒体作出买入、卖出或者持有具体证券的投资建议（D 选项正确）。故本题选ABCD 选项。"},{"id":"law1-79","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"资产管理计划的投资者主要的义务包括（）。","options":["认真阅读并遵守资产管理合同，保证投资资金的来源及用途合法","认真阅读并签署风险揭示书","在持有的资产管理计划份额内承担资产管理计划亏损或者终止的有限责任","取得分配清算后的剩余资产管理计划财产"],"answer":"ABC","explain":"资产管理计划的投资者主要应履行的义务包括：（1）认真阅读并遵守资产管理合同，保证投资资金的来源及用途合法（A 选项符合题意）；（2）认真阅读并签署风险揭示书（B 选项符合题意）；（3）对于单一资产管理计划，按照资产管理合同的约定，将参与资金交付管理人和托管人（如有）分别进行投资管理和资产托管，以参与资金为限，承担资产管理计划亏损或者终止的有限责任，对于集合资产管理计划，在持有的资产管理计划份额范围内，承担资产管理计划亏损或者终止的有限责任（C 选项符合题意）。D 选项不符合题意，属于资产管理计划的投资者主要享有的权利，并非\"义务\"。故本题选ABC 选项。【温馨提示】资产管理计划的投资者主要应履行的义务还包括：（1）接受合格投资者认定程序，如实填写风险识别能力和风险承担能力问卷，如实提供资金来源、金融资产、收入及负债情况，并对其真实性、准确性和完整性负责，签署合格投资者相关文件；（2）除公募资产管理产品外，以合伙企业、契约等非法人形式直接或者间接投资于资产管理计划的，应当向管理人充分披露实际投资者和最终资金来源；（3）按照规定向管理人或者资产管理计划销售机构提供信息资料以及身份证明文件，配合管理人或者其销售机构完成投资者适当性管理、非居民金融账户涉税信息尽职调查、反洗钱等监管规定的工作；（4）按照资产管理合同约定支付资产管理计划份额的参与款项，承担资产管理合同约定的管理费、业绩报酬（如有）、托管费（如有）、审计费（如有）、税费等合理费用；（5）不得违反资产管理合同的约定干涉管理人的投资行为；（6）不得从事任何有损资产管理计划及其投资者、管理人管理的其他资产以及托管人（如有）托管的其他资产合法权益的活动；（7）不得利用资产管理计划相关信息进行内幕交易或者其他不当、违法的证券期货业务活动；（8）保守商业秘密，不得泄露资产管理计划的投资计划、投资意向、投资信息等，依法依规提供信息的除外。"},{"id":"law1-80","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"判断","q":"按照《证券公司内部控制指引》的要求，证券公司内部控制的组织结构要求设立严密有效的三道业务防线，其中，第二道防线是建立重要一线岗位双人、双职、双责为基础的防线。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。证券公司应建立重要一线岗位双人、双职、双责为基础的\"第一道防线\"，并加强对单人单岗业务的监控。题干中的表述应为第一道防线，而非第二道防线。故本题表述错误。【温馨提示】证券公司应建立清晰合理的组织结构，依据所处环境和自身经营特点设立严密有效的三道业务监控防线：（1）建立重要一线岗位双人、双职、双责为基础的 \"第一道防线\"，并加强对单人单岗业务的监控。与资金、有价证券、重要空白凭证、业务合同、印章等直接接触的岗位和涉及信息系统安全的岗位，应当实行双人负责制。（2）建立相关部门、相关岗位之间相互制衡、监督的 \"第二道防线\"。不同部门应有明确的职责分工不相容职务应适当分离。（3）建立独立的监督检查部门对各项业务、各部门、各分支机构、各岗位全面实施监控、检查和反馈的\"第三道防线\"。"},{"id":"law1-81","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"判断","q":"操纵证券、期货市场罪的客观方面包括在自己实际控制的账户之间进行大量证券交易，造成股票价格上升后卖出获利。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。操纵证券、期货市场罪，是指有下列情形，操纵证券、期货市场，影响证券、期货交易价格或者证券、期货交易量：在自己实际控制的账户之间进行证券交易，或者以自己为交易对象，自买自卖期货合约的。操纵证券、期货市场罪的客观方面表现为利用其资金、信息等优势或者滥用职权操纵市场、制造市场假象，影响证券、期货交易价格或者证券、期货交易量，情节严重的行为。故本题表述正确。【温馨提示】操纵证券、期货市场罪，是指有下列情形之一，操纵证券、期货市场，影响证券、期货交易价格或者证券、期货交易量：（1）单独或者合谋，集中资金优势、持股或者持仓优势或者利用信息优势联合或者连续买卖；（2）与他人串通，以事先约定的时间、价格和方式相互进行证券、期货交易；（3）在自己实际控制的账户之间进行证券交易，或者以自己为交易对象，自买自卖期货合约的；（4）不以成交为目的，频繁或者大量申报买入、卖出证券、期货合约并撤销申报；（5）利用虚假或者不确定的重大信息，诱导投资者进行证券、期货交易；（6）对证券、证券发行人、期货交易标的公开作出评价、预测或者投资建议，同时进行反向证券交易或者相关期货交易；（7）以其他方法操纵证券、期货市场的。"},{"id":"law1-82","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"判断","q":"发行人向不特定对象发行证券的，应当聘请承销团承销，承销团成员由主承销商和参与承销的证券公司组成。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。向不特定对象发行证券聘请承销团承销的，承销团应当由主承销和参与承销的证券公司组成。但法律并未规定所有向不特定对象发行的证券都必须采用承销团方式，发行人也可以选择单一证券公司承销。故本题表述错误。"},{"id":"law1-83","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"判断","q":"反洗钱是指为了预防通过各种方式掩饰、隐瞒毒品犯罪、黑社会性质的组织犯罪、恐怖活动犯罪、走私犯罪、贪污贿赂犯罪、破坏金融管理秩序犯罪、金融诈骗犯罪和其他犯罪所得及其收益的来源和性质的洗钱活动，依照《反洗钱法》等法律法规采取相关措施的行为。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。反洗钱是指为了预防通过各种方式掩饰、隐瞒毒品犯罪、黑社会性质的组织犯罪、恐怖活动犯罪、走私犯罪、贪污贿赂犯罪、破坏金融管理秩序犯罪、金融诈骗犯罪和其他犯罪所得及其收益的来源和性质的洗钱活动，依照《反洗钱法》等法律法规采取相关措施的行为。故本题表述正确。"},{"id":"law1-84","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"判断","q":"非法吸收或者变相吸收公众存款，扰乱金融秩序，对象达到 200 人以上的，方可予以立案追诉。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。非法吸收或者变相吸收公众存款，扰乱金融秩序，对象达到 150 人以上的，方可予以立案追诉（并非200 人以上）。故本题表述错误。"},{"id":"law1-85","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"判断","q":"根据《证券法》，收购人未按照规定履行上市公司收购的公告、发出收购要约义务的，责令改正，给予警告，并处罚款十万元以上三十万元以下。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。收购人未按照《证券法》的规定履行上市公司收购的公告、发出收购要约义务的，责令改正，给予警告，并处以50 万元以上500 万元以下的罚款（并非\"十万元以上三十万元以下\"）。故本题表述错误。"},{"id":"law1-86","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"判断","q":"根据《证券公司董事、监事、高级管理人员及从业人员管理规则》，总公司从事业务管理工作的其他董事、上海分公司投资顾问、营业厅经理，都属于证券从业人员。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。从业人员是指在证券基金经营机构从事证券基金业务和相关管理工作的人员，包括从事证券经纪、证券投资咨询、与证券交易及证券投资活动有关的财务顾问、证券承销与保荐、证券融资融券、证券自营、证券做市交易、证券资产管理等业务和相关管理工作的人员。证券公司董事长、从事业务管理工作的其他董事和监事、高级管理人员、分支机构负责人均为从业人员。故本题表述正确。"},{"id":"law1-87","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"判断","q":"根据《证券公司及基金管理公司子公司资产证券化业务管理规定》，资产证券化业务的基础资产应当权属明确，是可以产生独立、可预测的现金流的特定财产，财产权利不得作为基础资产。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。基础资产，是指符合法律法规规定，权属明确，可以产生独立、可预测的现金流且可特定化的财产权利或者财产。故本题表述错误。"},{"id":"law1-88","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"判断","q":"根据《证券公司治理准则》，证券公司应当向社会公众披露本公司未经审计的年度财务报告及其他信息，并保证披露信息的真实、准确、完整。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。履行公司财务报告披露义务。证券公司应当按照规定向社会公众披露本公司经审计的年度财务报告及其他信息（并非\"未经审计\"），并保证披露信息真实、准确、完整。故本题表述错误。"},{"id":"law1-89","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"判断","q":"根据期货衍生品法，期货交易实行保证金制度，以有价证券作为保证金。可以依法通过质押等具有履约保障功能的方式进行。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。保证金的形式包括现金，国债、股票、基金份额、标准仓单等流动性强的有价证券，以及国务院期货监督管理机构规定的其他财产。以有价证券等作为保证金的，可以依法通过质押等具有履约保障功能的方式进行。故本题表述正确。"},{"id":"law1-90","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"判断","q":"公开募集基金的基金管理人，由依法设立的公司和合伙企业担任。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。公开募集基金的基金管理人，由基金管理公司或者经国务院证券监督管理机构按照规定核准的其他机构担任。非公开募集基金的基金管理人，由依法设立的公司或者合伙企业担任（并非公开募集基金的基金管理人）。故本题表述错误。"},{"id":"law1-91","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"判断","q":"公司除法定的会计账簿外，可以另立会计账簿。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。公司除法定的会计账簿外，不得另立会计账簿（并非可以）。对公司资金，不得以任何个人名义开立账户存储。故本题表述错误。"},{"id":"law1-92","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"判断","q":"股份有限公司的设立，可以采取发起设立或募集设立的方式。以募集设立方式设立股份有限公司的，发起人认购的股份不得少于公司股份总数的25%。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。公司的设立方式有两种，即发起设立和募集设立。募集设立只适用于股份有限公司。其中，发起人认购的股份不得少于公司章程规定的公司设立时应发行股份总数的35%（并非\"25%\"），但是法律、行政法规另有规定的，从其规定。故本题表述错误。"},{"id":"law1-93","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"判断","q":"股票发行采用代销方式，代销期限届满，向投资者出售的股票数量未达到拟公开发行股票数量50%的，为发行失败。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。股票发行采用代销方式，代销期限届满，向投资者出售的股票数量未达到拟公开发行股票数量70%的（并非\"50%\"），为发行失败。故本题表述错误。"},{"id":"law1-94","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"判断","q":"股票期权实行当日无负债结算制度。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。股票期权交易实行当日无负债结算制度。证券登记结算机构应当在当日及时将结算结果通知结算参与人，结算参与人据此对投资者进行结算，并应当将结算结果按照与投资者约定的方式及时通知投资者。投资者应当及时查询并妥善处理自己的交易持仓。故本题表述正确。"},{"id":"law1-95","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"判断","q":"基金销售机构不得采取抽奖、回扣等方式销售基金。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。基金销售机构及其从业人员从事基金销售业务，不得采取抽奖、回扣或者送实物、保险、基金份额等方式销售基金。故本题表述正确。"},{"id":"law1-96","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"判断","q":"科创板首次公开发行股票上市前 5 个交易日不设涨跌幅限制，上市 5 个交易日后涨跌幅限制比例为20%。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。考虑到科创企业具有投入大、迭代快等特点，在总结现有股票交易涨跌幅制度实施中的利弊得失基础上，将科创板股票的涨跌幅限制放宽至 20%。为尽快形成合理价格，新股上市后的前 5个交易日不设涨跌幅限制。故本题表述正确。"},{"id":"law1-97","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"判断","q":"内核部门是风险管控的第一道防线。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。证券公司应当构建清晰、合理的投资银行类业务内部控制组织架构，建立分工合理、权责明确、相互制衡、有效监督的三道内部控制防线：（1）项目组、业务部门为内部控制的\"第一道防线\"；（2）质量控制为内部控制的\"第二道防线\"；（3）内核、合规、风险管理等部门或机构为内部控制的\"第三道防线\"。故本题表述错误。"},{"id":"law1-98","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"判断","q":"普通合伙企业中，若合伙协议未约定或约定不明的事项，应按照全体合伙人一人一票、经超过半数合伙人同意的方式表决。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。普通合伙人对合伙企业有关事项作出决议，按照合伙协议约定的表决办法办理。合伙协议未约定或者约定不明确的，实行合伙人一人一票并经全体合伙人过半数通过的表决办法。故本题表述正确。"},{"id":"law1-99","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"判断","q":"普通投资者在信息告知、风险警示、适当性匹配等方面享有特别保护。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。根据《证券期货投资者适当性管理办法》的规定，投资者分为普通投资者与专业投资者。普通投资者在信息告知、风险警示、适当性匹配等方面享有特别保护。故本题表述正确。"},{"id":"law1-100","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"判断","q":"上市公司在一年内担保金额超过公司资产总额 30%的，应当由股东会做出决议，经出席会议的股东半数人数同意通过。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。上市公司在 1 年内向他人提供担保的金额超过公司资产总额 30%的，应当由股东会作出决议，并经出席会议的股东所持表决权的2/3 以上通过（并非\"半数\"）。故本题表述错误。"},{"id":"law1-101","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"判断","q":"我国证券市场法律法规体系的主要层级包括法律、行政法规、部门规章、规范性文件和行业自律规则。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。我国证券市场法律法规体系的主要层级包括五级：法律、行政法规、部门规章、规范性文件、行业自律规则。故本题表述正确。"},{"id":"law1-102","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"判断","q":"证券从业人员不得为牟取佣金收入，诱使客户进行不必要的证券买卖。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。从业人员禁止行为包括：（1）直接或者以化名、借他人名义持有、买卖股票或者其他具有股权性质的证券，收受他人赠送的股票或者其他具有股权性质的证券；（2）利用因职务便利获取的内幕信息以外的其他未公开的信息；（3）私下接受客户委托买卖证券；（4）在证券交易活动中作出虚假陈述或信息误导；（5）违背客户的委托为其买卖证券；（6）不在规定时间内向客户提供交易的确认文件；（7）未经客户的委托，擅自为客户买卖证券，或者假借客户的名义买卖证券；（8）为牟取佣金收入，诱使客户进行不必要的证券买卖；（9）其他违背客户真实意思表示，损害客户利益的行为。故本题表述正确。"},{"id":"law1-103","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"判断","q":"证券发行上市保荐业务中，保荐人出具有重大遗漏的保荐书，处罚措施中包括：责令改正，给予警告，没收业务收入，并处以业务收入1 倍以上10 倍以下罚款。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。保荐人出具有虚假记载、误导性陈述或者重大遗漏的保荐书，或者不履行其他法定职责的，责令改正，给予警告，没收业务收入，并处以业务收入1 倍以上10 倍以下的罚款。故本题表述正确。"},{"id":"law1-104","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"判断","q":"证券公司分类监管评级中，D 级是正常经营机构中的最低级别。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。中国证监会根据证券公司评价计分的高低，将证券公司分为 A（AAA、AA、A）、B（BBB、BB、B）、C（CCC、CC、C）、D、E 五大类 11 个级别。其中，C 级是正常经营状态的最低等级（并非\"D 级\"）。故本题表述错误。"},{"id":"law1-105","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"判断","q":"证券公司开展股票质押式回购业务，资金融出方可以是证券公司，也可以是证券公司管理的公开募集或非公开募集集合资产管理计划、单一资产管理计划。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。公募基金与证券公司集合资管计划是不同产品，不能作为股票质押回购的融出方。不存在\"公开募集集合资管计划\"。故本题表述错误。"},{"id":"law1-106","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"判断","q":"证券公司可以根据合同约定，为另类子公司的合规管理、风险控制、人力资源管理、产品销售等方面提供支持和服务。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。证券公司可以根据合同约定或内控制度规定，为另类子公司的合规管理、风险管理、稽核审计、人力资源管理、财务管理、信息技术、研究和运营等方面提供支持和服务。故本题表述正确。"},{"id":"law1-107","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"判断","q":"证券公司应当建立健全投资者回访制度，为回访提供充分的人力与物质保障，不得委托第三方实施回访。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。证券公司应当建立健全投资者回访制度，持续了解投资者状况，及时发现并纠正不规范行为。证券公司应当为回访提供充分的人力和物质保障，保证必要的回访比例。证券公司可以委托第三方专业机构实施回访（并非\"不得委托\"），但法律责任仍由证券公司承担。故本题表述错误。"},{"id":"law1-108","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"判断","q":"证券公司应至少每半年对流动性风险限额进行一次评估，必要时进行调整。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。证券公司应至少每年对流动性风险限额进行一次评估，必要时进行调整。故本题表述错误。"},{"id":"law1-109","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"判断","q":"证券市场当事人具有不平等地位，在自愿、有偿、诚实信用的原则下进行交易活动。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。证券发行、交易活动的当事人具有平等（并非不平等）的法律地位，应当遵守自愿、有偿、诚实信用的原则。故本题表述错误。"},{"id":"law1-110","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"案例","q":"【资料】张某在某基金销售公司担任销售部经理，同时又在 A 证券公司担任证券经纪人。\n为拓展业务，张某将 A 证券公司开户二维码转发其基金销售公司六名下属，委托他们协助其招\n揽 A 证券公司客户，对开户成功客户张某会长期推荐\"；黑马\"；股票，并承诺年化投资收益可\n以达到10%。 \n假设上述案例所述情形均发生在现行相关法律法规生效时间之后，且不考虑各备选项之间的相\n关影响，请根据上述背景信息回答以下问题。\n\n【问题】下列关于A 证券公司经纪人张某存在违规行为的说法，错误的是（）。","options":["张某存在\"自营或者为他人经营与所任证券公司同类或者存在利益冲突业务\"的行为","张某存在\"向客户违规承诺收益或者承担损失\"的行为","张某存在\"泄露因职务便利获取的未公开信息\"的行为","张某存在\"超出法规规定和证券公司授权的范围从事业务\"的行为"],"answer":"C","explain":"A 选项正确，\"张某在某基金销售公司担任销售部经理，同时又在 A 证券公司担任证券经纪人\"，从业人员不得自营或者为他人经营与所在证券公司同类或者存在利益冲突的业务。B 选项正确，\"张某承诺年化投资收益可以达到 10%\"，从业人员不得向客户违规承诺收益、承诺承担损失。C 选项错误，题干未提及未公开信息、泄露信息的内容。未公开信息交易是指利用因职务便利获取的内幕信息以外的其他未公开的信息，如机构持仓、交易动向、投资决策等。黑马股票只是经纪人随口忽悠、拍胸脯推荐、吹牛说会涨，并未说明其推荐依据是 \"因职务便利获取的未公开信息\"。因此不存在\"泄露因职务便利获取的未公开信息\"的行为。D 选项正确，证券经纪人不能委托他人招揽客户、不能私下推荐股票、不能承诺收益，超出了证券公司的授权范围和法规规定的范围，属于违规行为。故本题选C 选项。"},{"id":"law1-111","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"案例","q":"【资料】张某在某基金销售公司担任销售部经理，同时又在 A 证券公司担任证券经纪人。\n为拓展业务，张某将 A 证券公司开户二维码转发其基金销售公司六名下属，委托他们协助其招\n揽 A 证券公司客户，对开户成功客户张某会长期推荐\"；黑马\"；股票，并承诺年化投资收益可\n以达到10%。 \n假设上述案例所述情形均发生在现行相关法律法规生效时间之后，且不考虑各备选项之间的相\n关影响，请根据上述背景信息回答以下问题。\n\n【问题】A 证券公司的下列情况中符合《证券经纪人管理暂行规定》的是（）。","options":["A 证券公司建立健全证券经纪人管理制度，采取有效措施，对证券经纪人及其执业行为实施集中统一管理","A 证券公司应当对证券经纪人进行不少于40 个小时的执业前培训，其中法律法规和职业道德的培训时间不少于20 个小时","A 证券公司负责电话回访的人员从事客户招揽和客户服务活动","A 证券公司对证券经纪人所招揽和服务客户的账户进行有效监控，并规定出现异常情况的，记录存档并在3 个工作日内查明原因"],"answer":"A","explain":"A 选项正确，证券公司应当建立健全证券经纪人管理制度，采取有效措施，对证券经纪人及其执业行为实施集中统一管理，保障证券经纪人具备基本的职业道德和业务素质，防止证券经纪人在执业过程中从事违法违规或者超越代理权限、损害客户合法权益的行为。B 选项错误，证券公司应当对证券经纪人进行不少于 60 个小时的执业前培训（并非\"40 个小时\"），其中法律法规和职业道德的培训时间不少于20 个小时。C 选项错误，负责电话回访的人员不得从事客户招揽和客户服务活动。D 选项错误，证券公司应当对证券经纪人所招揽和服务客户的账户进行有效监控，发现异常情况的，应立即查明原因并按照规定处理。没有\"3 个工作日内\"这一具体时限。故本题选A 选项。"},{"id":"law1-112","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"案例","q":"【资料】某公司董事长张某、财务总监王某为使公司上市，组织单位工作人员通过使用自\n制的银行单据等方式，虚增当期利润总额达 50%，并在上市申请文件的定期财务报告和招股说\n明书中均载入上述内容。该公司上市后，张某和王某继续使用相同手段，连续三年均虚增当期\n营业收入总额40%以上，并在年报中使用上述虚增经营数据，给公众投资者造成重大损失。 \n请根据上述背景信息回答以下问题。\n\n【问题】依据张某和王某在上市申请文件和招股说明书中使用虚构财务数据的行为，可能触犯的罪名是（）。","options":["提供虚假证明文件、出具证明文件重大失实罪","欺诈发行证券罪","操纵证券、期货市场罪","非法吸收公众存款罪"],"answer":"B","explain":"B 选项正确，欺诈发行证券的定义是指发行人不符合发行条件，以欺骗手段骗取发行注册的行为。如果情节严重构成犯罪的，以欺诈发行证券罪定罪处罚。欺诈发行证券罪的客观方面表现为：①行为人必须实施在招股说明书、认股书、公司、企业债券募集办法等发行文件中隐瞒重要事实或者编造重大虚假内容的行为。②行为人必须实施了发行证券的行为。如果行为人仅是制作了虚假的招股说明书、认股书、公司、企业债券募集办法等发行文件，而未实施发行证券的行为，不构成本罪。必须是既制作了虚假的上述文件，且已经发行证券的才构成本罪。③行为人制作虚假的招股说明书、认股书、公司、企业债券募集办法等发行文件发行证券的行为，必须达到一定的严重程度，即达到\"数额巨大、后果严重或者有其他严重情节的\"，才构成犯罪。张某和王某满足上述条件。故本题选B 选项。"},{"id":"law1-113","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"案例","q":"【资料】某公司董事长张某、财务总监王某为使公司上市，组织单位工作人员通过使用自\n制的银行单据等方式，虚增当期利润总额达 50%，并在上市申请文件的定期财务报告和招股说\n明书中均载入上述内容。该公司上市后，张某和王某继续使用相同手段，连续三年均虚增当期\n营业收入总额40%以上，并在年报中使用上述虚增经营数据，给公众投资者造成重大损失。 \n请根据上述背景信息回答以下问题。\n\n【问题】下列关于张某和王某就虚构上市公司财务数据并在年报中进行披露的行为应承担的法律责任的说法，错误的有（）。","options":["可能触犯违规披露、不披露重要信息罪","可能触犯背信运用受托财产罪","可能触犯提供虚假证明文件、出具证明文件重大失实罪","若王某不配合监管机关调查且伪造证据，应予从重处罚"],"answer":"BC","explain":"A 选项正确，违规披露、不披露重要信息罪，是指依法负有信息披露义务的公司、企业向股东和社会公众提供虚假的或者隐瞒重要事实的财务会计报告，或者对依法应当披露的其他重要信息不按照规定披露，严重损害股东或者其他人利益，或有其他严重情节的行为。B 选项错误，背信运用受托财产，是指商业银行、证券交易所、期货交易所、证券公司、期货经纪公司、保险公司或者其他金融机构，违背受托义务，擅自运用客户资金或者其他委托、信托的财产，情节严重的行为。C 选项错误，提供虚假证明文件、出具证明文件重大失实的犯罪主体主要指承担资产评估、验资、验证、会计、审计、法律服务、保荐、安全评价、环境影响评价、环境监测等职责的中介组织的人员。张某、王某是公司内部人员，不构成此罪。D 选项正确，不配合证券监管机构监管，或者拒绝、阻碍证券监管机构及其工作人员执法，甚至以暴力、威胁及其他手段干扰执法，应当从重处罚；在信息披露违法案件中变造、隐瞒、毁灭证据，或者提供伪证，妨碍调查，应当从重处罚。故本题选BC 选项。"},{"id":"law1-114","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"案例","q":"【资料】甲证券公司为了扩大公司规模，提高自己在市场上的竞争力，经过董事会同意，\n拟向中国证监会申请为期货公司提供中间介绍业务的资格。 \n请根据上述背景信息回答以下问题。\n\n【问题】如果甲证券公司的申请获得了中国证监会的批准，甲可以接受（）的委托从事中间介绍业务。","options":["与甲证券公司长期具有贸易往来的期货公司","甲证券公司全资拥有的期货公司","与甲证券公司属于同一机构控制的期货公司","甲证券公司控股的期货公司"],"answer":"BCD","explain":"证券公司只能接受其全资拥有或者控股的（ B、D 选项正确），或者被同一机构控制的期货公司的委托从事介绍业务（C 选项正确），不能接受其他期货公司的委托从事介绍业务（A 选项错误）。故本题选BCD 选项。"},{"id":"law1-115","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"案例","q":"【资料】甲证券公司为了扩大公司规模，提高自己在市场上的竞争力，经过董事会同意，\n拟向中国证监会申请为期货公司提供中间介绍业务的资格。 \n请根据上述背景信息回答以下问题。\n\n【问题】甲证券公司受期货公司委托从事介绍业务，不得从事（）。","options":["提供期货行情信息、交易设施","代理客户进行期货交易","代期货公司、客户收付期货保证金","利用证券资金账户为客户存取、划转期货保证金"],"answer":"BCD","explain":"证券公司受期货公司委托从事介绍业务，应当提供下列服务：①协助办理开户手续；②提供期货行情信息、交易设施（A 选项错误）；③中国证监会规定的其他服务。证券公司不得代理客户进行期货交易、结算或者交割（B 选项正确），不得代期货公司、客户收付期货保证金（C 选项正确），不得利用证券资金账户为客户存取、划转期货保证金（D 选项正确）。故本题选BCD 选项。"},{"id":"law1-116","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"案例","q":"【资料】甲证券公司为了扩大公司规模，提高自己在市场上的竞争力，经过董事会同意，\n拟向中国证监会申请为期货公司提供中间介绍业务的资格。 \n请根据上述背景信息回答以下问题。\n\n【问题】甲证券公司从事介绍业务，应当与期货公司签订书面委托协议，委托协议应当载明（）。","options":["客户投诉的接待处理方式","介绍业务的范围","报酬支付及相关费用的分担方式","介绍业务对接规则"],"answer":"ABCD","explain":"证券公司从事介绍业务，应当与期货公司签订书面委托协议。委托协议应当载明下列事项：①介绍业务的范围（B 选项正确）；②执行期货保证金安全存管制度的措施；③介绍业务对接规则（D 选项正确）；④客户投诉的接待处理方式（A 选项正确）；⑤报酬支付及相关费用的分担方式（C 选项正确）；⑥违约责任；⑦中国证监会规定的其他事项。故本题选ABCD 选项。"},{"id":"law1-117","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"案例","q":"【资料】客户王某在甲证券公司某营业部开立有经纪业务账户，因其账户证券交易存在异\n常被证券公司使用的反洗钱系统预警。甲证券公司营业部的业务人员和合规人员共同分析、识\n别后，结合客户尽职调查的结果，怀疑客户王某用于进行证券交易的资金与其担任法定代表人\n的公司违规经营外汇业务相关。甲证券公司立即向中国反洗钱监测分析中心提交了可疑交易报\n告，同时向其营业部所在地的中国人民银行某中心支行提交了重点可疑交易报告，并将客户的\n洗钱风险等级调至最高，对客户采取了冻结账户等措施。 \n请根据上述背景信息回答以下问题。\n\n【问题】下列关于大额交易和可疑交易的表述，说法正确的是（）。","options":["既属于大额交易又属于可疑交易的交易，证券公司应当提交综合报告","证券公司与客户进行金融交易并通过银行账户划转款项的，由银行机构按照规定提交大额交易报告","可疑报告与所涉资金金额或者资产价值大小有关","证券公司在报送可疑交易报告后，应当根据中国证监会的相关规定采取适当的后续风险控制措施"],"answer":"B","explain":"A 选项错误，对于既属于大额交易又属于可疑交易的交易，证券公司应当分别提交大额交易报告和可疑交易报告。B 选项正确，证券公司与客户进行金融交易并通过银行账户划转款项的，由银行机构按照规定提交大额交易报告。C 选项错误，证券公司发现或者有合理理由怀疑客户、客户的资金或者其他资产、客户的交易或者试图进行的交易与洗钱、恐怖融资等犯罪活动相关的，不论所涉资金金额或者资产价值大小，应当向中国反洗钱监测分析中心提交可疑交易报告。D 选项错误，证券公司在报送可疑交易报告后，应当根据中国人民银行的相关规定采取适当的后续风险控制措施。故本题选B 选项。"},{"id":"law1-118","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"案例","q":"【资料】客户王某在甲证券公司某营业部开立有经纪业务账户，因其账户证券交易存在异\n常被证券公司使用的反洗钱系统预警。甲证券公司营业部的业务人员和合规人员共同分析、识\n别后，结合客户尽职调查的结果，怀疑客户王某用于进行证券交易的资金与其担任法定代表人\n的公司违规经营外汇业务相关。甲证券公司立即向中国反洗钱监测分析中心提交了可疑交易报\n告，同时向其营业部所在地的中国人民银行某中心支行提交了重点可疑交易报告，并将客户的\n洗钱风险等级调至最高，对客户采取了冻结账户等措施。 \n请根据上述背景信息回答以下问题。\n\n【问题】存在（）的情形，证券公司应当向中国反洗钱监测分析中心提交可疑交易报告。","options":["明显涉嫌洗钱、恐怖融资等犯罪活动","交易数额巨大","严重危害国家安全","影响社会稳定"],"answer":"ACD","explain":"当可疑交易符合下列情形之一的，证券公司应当在向中国反洗钱监测分析中心提交可疑交易报告的同时，以电子形式或书面形式向所在地中国人民银行或者其分支机构报告，并配合反洗钱调查：①明显涉嫌洗钱、恐怖融资等犯罪活动的（A 选项正确）；②严重危害国家安全或者影响社会稳定的（C、D 选项正确）；③其他情节严重或者情况紧急的情形。B 选项错误，是触发大额交易报告的条件，而非可疑交易报告的决定性条件。故本题选ACD 选项。"},{"id":"law1-119","subject":"law","source":"2026.09 LC终极押题 · 押题卷一","type":"案例","q":"【资料】客户王某在甲证券公司某营业部开立有经纪业务账户，因其账户证券交易存在异\n常被证券公司使用的反洗钱系统预警。甲证券公司营业部的业务人员和合规人员共同分析、识\n别后，结合客户尽职调查的结果，怀疑客户王某用于进行证券交易的资金与其担任法定代表人\n的公司违规经营外汇业务相关。甲证券公司立即向中国反洗钱监测分析中心提交了可疑交易报\n告，同时向其营业部所在地的中国人民银行某中心支行提交了重点可疑交易报告，并将客户的\n洗钱风险等级调至最高，对客户采取了冻结账户等措施。 \n请根据上述背景信息回答以下问题。\n\n【问题】证券公司应当在向中国反洗钱监测分析中心提交可疑交易报告的同时，以（）向所在地中国人民银行或者其分支机构报告，并配合反洗钱调查。","options":["电子形式或口头形式","口头形式或其他形式","书面形式或其他形式","书面形式或电子形式"],"answer":"D","explain":"D 选项正确，证券公司应当在向中国反洗钱监测分析中心提交可疑交易报告的同时，以电子形式或书面形式向所在地中国人民银行或者其分支机构报告，并配合反洗钱调查。故本题选D 选项。"}]},{"id":"law2","subject":"law","name":"法律法规 · 押题卷二","stats":{"单选":30,"多选":50,"判断":30,"案例":10},"questions":[{"id":"law2-0","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"单选","q":"按照《证券业从业人员执业行为准则》及相关规则的规定，一般证券从业人员应接受协会和所在机构组织的后续职业培训，且每年的培训不少于（）。","options":["20 学时","15 学时","10 学时","5 学时"],"answer":"B","explain":"B 选项正确，从业人员自首次执业登记日的下一年起，每个自然年为一个培训周期。证券公司应当要求其从业人员在每个培训周期内完成一定时间的业务培训，建议不少于 15 学时，每学时为45 分钟。故本题选B 选项。"},{"id":"law2-1","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"单选","q":"对于流动性风险限额的评估（）。","options":["每半年一次","每三年一次","每两年一次","每一年一次"],"answer":"D","explain":"D 选项正确，证券公司应至少每年对流动性风险限额进行一次评估，必要时进行调整。故本题选D 选项。"},{"id":"law2-2","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"单选","q":"根据《公司法》，关于有限责任公司股东会职权的说法，错误的是（）。","options":["对发行公司债券作出决议","制定公司的基本管理制度","审议批准公司的利润分配方案和弥补亏损方案","审议批准董事会的报告"],"answer":"B","explain":"有限责任公司股东会由全体股东组成。股东会是公司的权力机构，依法行使职权。股东会行使下列法定职权：（1）对发行公司债券作出决议（A 选项正确）；（2）审议批准公司的利润分配方案和弥补亏损方案（C 选项正确）；（3）审议批准董事会的报告（D 选项正确）。B 选项错误，制定公司的基本管理制度属于董事会的职责。故本题选B 选项。【温馨提示】股东会行使的法定职权还包括：（1）选举和更换董事、监事，决定有关董事、监事的报酬事项；（2）审议批准监事会的报告；（3）对公司增加或者减少注册资本作出决议；（4）对公司合并、分立、解散、清算或者变更公司形式作出决议；（5）修改公司章程；（6）公司章程规定的其他职权。"},{"id":"law2-3","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"单选","q":"根据《公司法》，上市公司董事和高级管理人员在任职期间每年转让的股份不得超过其所持本公司股份总数的（）。","options":["15%","10%","20%","25%"],"answer":"D","explain":"D 选项正确，公司董事、监事、高级管理人员应当向公司申报所持有的本公司的股份及其变动情况，在就任时确定的任职期间每年转让的股份不得超过其所持有本公司股份总数的 25%。故本题选D 选项。"},{"id":"law2-4","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"单选","q":"根据《合伙企业法》，下列关于合伙企业应当解散的情形，说法错误的是（）。","options":["三分之二以上合伙人决定解散","合伙协议约定的解散事由出现","合伙人已不具备法定人数满三十天","合伙期限届满，合伙人决定不再经营"],"answer":"A","explain":"合伙企业有下列情形之一的，应当解散：（1）合伙期限届满，合伙人决定不再经营（D 选项正确）；（2）合伙协议约定的解散事由出现（B 选项正确）；（3）全体合伙人决定解散（A 选项错误，并非三分之二）；（4）合伙人已不具备法定人数满30 天（C 选项正确）；（5）合伙协议约定的合伙目的已经实现或者无法实现；（6）依法被吊销营业执照、责令关闭或者被撤销；（7）法律、行政法规规定的其他原因。故本题选A 选项。"},{"id":"law2-5","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"单选","q":"根据《证券公司风险控制指标管理办法》，证券公司应建立以（）和流动性为核心的风险控制指标体系。","options":["净资本","净资产","总负债","净利润"],"answer":"A","explain":"A 选项正确，为了建立以净资本和流动性为核心的风险控制指标体系，加强证券公司风险监管，督促证券公司加强内部控制、提升风险管理水平、防范风险，证券公司应当计算净资本、风险覆盖率、资本杠杆率、流动性覆盖率、净稳定资金率等各项风险控制指标。故本题选A 选项。"},{"id":"law2-6","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"单选","q":"根据《证券公司和证券投资基金管理公司合规管理办法》，证券公司合规管理基本制度应当经（）审议通过后实施。","options":["股东会","董事会","风险控制委员会","经营管理层"],"answer":"B","explain":"证券公司应当制定合规管理的基本制度，经董事会审议通过后实施（B 选项正确）。合规管理的基本制度应当明确合规管理的目标、基本原则、机构设置及其职责、履职保障、合规考核、违法违规行为及合规风险隐患的报告、处理和责任追究等内容。故本题选B 选项。"},{"id":"law2-7","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"单选","q":"根据《证券公司另类投资子公司管理规范》规定，下列关于另类投资子公司下设机构的说法，正确的是（）。","options":["可以下设全资子公司","可以下设控股子公司","不得下设任何机构","可以下设参股子公司"],"answer":"C","explain":"C 选项正确，证券公司应当突出主业，充分考虑自身发展需要、财务实力和管理能力，审慎设立另类子公司。另类子公司不得再下设任何机构。故本题选C 选项。"},{"id":"law2-8","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"单选","q":"根据《证券公司证券自营业务指引》，关于自营业务资金出入的相关规定，下列行为正确的是（）。","options":["以个人名义从自营账户调出资金","以公司名义从自营账户提取现金","以个人名义调入资金","以公司名义调入资金"],"answer":"D","explain":"自营业务资金的出入必须以公司名义进行（D 选项正确），禁止以个人名义从自营账户中调入调出资金（A、C 选项错误），禁止从自营账户中提取现金（B 选项错误）。故本题选D 选项。"},{"id":"law2-9","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"单选","q":"根据《证券基金经营机构董事、监事、高级管理人员及从业人员监督管理办法》，证券从业人员的以下行为，不违反从业人员履职限制及禁止行为的是（）。","options":["泄露因职务便利获取的未公开信息","接受他人赠送的股票","买卖上市公司发行的可转换公司债券","公平进行业务竞争"],"answer":"D","explain":"根据《证券基金经营机构董事、监事、高级管理人员及从业人员监督管理办法》，从业人员不得从事下列行为：（1）不正当交易或者利益输送（B 选项不符合题意）；（2）泄露因职务便利获取的未公开信息、利用该信息从事或者明示、暗示他人从事相关的交易活动（A 选项不符合题意）；（3）违反法律法规和中国证监会的规定，从事证券、基金和未上市企业股权投资（ C 选项不符合题意）。D 选项符合题意，公平进行业务竞争不违反从业人员的履职限制及禁止行为。故本题选D 选项。【温馨提示】根据《证券基金经营机构董事、监事、高级管理人员及从业人员监督管理办法》，从业人员不得从事的行为还有：（1）利用职务之便为本人或者他人牟取不正当利益；（2）与其履行职责存在利益冲突的活动；（3）挪用或者侵占公司、客户资产或者基金财产；（4）私下接受客户委托从事证券基金投资；（5）向客户违规承诺收益或者承担损失；（6）违规向客户提供资金、证券或者违规为客户融资提供中介、担保或者其他便利；（7）滥用职权、玩忽职守，不按照规定履行职责；（8）法律法规和中国证监会规定禁止的其他行为。"},{"id":"law2-10","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"单选","q":"根据《证券期货经营机构私募资产管理业务管理办法》证券期货经营机构被宣告破产且在六个月内没有新的管理人承接的，证券期货经营机构设立的资产管理计划应当（）。","options":["终止","展期","中止","破产清算"],"answer":"A","explain":"有下列情形的，资产管理计划应当终止：证券公司被依法撤销资产管理业务资格或者依法解散、被撤销、被宣告破产，且在6 个月内没有新的管理人承接（A 选项正确）。故本题选A 选项。【温馨提示】资产管理计划应当终止的情形还包括：（1）资产管理计划存续期届满且不展期。（2）托管人被依法撤销基金托管资格或者依法解散、被撤销、被宣告破产，且在 6 个月内没有新的托管人承接。（3）经全体投资者、证券公司和托管人协商一致决定终止的。（4）发生资产管理合同约定的应当终止的情形。（5）集合资产管理计划存续期间，持续5 个工作日投资者少于 2 人。（6）法律、行政法规及中国证监会规定的其他情形。"},{"id":"law2-11","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"单选","q":"根据《证券市场资信评级业务管理办法》，证券评级机构评级委员会委员及评级从业人员在开展证券评级业务期间，下列关于证券资信评级业务人员的回避情形，错误的是（）。","options":["本人、直系亲属持有受评级机构或者受评级证券发行人的股份达到 5%以上","本人、直系亲属为受评级机构或者受评级证券发行人的普通员工","本人、直系亲属持有受评级证券或者受评级机构发行的证券金额超过 50 万元","本人、直系亲属担任受评级机构或者受评级证券发行人聘任的会计师事务所、律师事务所、财务顾问等证券服务机构的负责人或者项目签字人"],"answer":"B","explain":"证券评级机构应当建立回避制度。证券评级机构评级委员会委员及评级从业人员在开展证券评级业务期间有下列情形之一的，应当回避：（1）本人、直系亲属持有评级委托方、受评级机构或者受评级证券发行人的股份达到 5%以上，或者是受评级机构、受评级证券发行人的实际控制人（A 选项正确）；（2）本人、直系亲属担任评级委托方、受评级机构或者受评级证券发行人的董事、监事和高级管理人员；（3）本人、直系亲属担任评级委托方、受评级机构或者受评级证券发行人聘任的会计师事务所、律师事务所、财务顾问等证券服务机构的负责人或者项目签字人（D 选项正确）；（4）本人、直系亲属持有评级委托方、受评级证券或者受评级机构发行的证券金额超过 50 万元，或者与评级委托方、受评级机构、受评级证券发行人发生累计超过50 万元的交易（C 选项正确）；（5）中国证监会认定的足以影响独立、客观、公正、审慎性原则的其他情形。B 选项错误，不包括普通员工。故本题选B 选项。"},{"id":"law2-12","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"单选","q":"根据《证券投资顾问业务暂行规定》，以下不属于证券投资顾问从业的禁止性行为的是（）。","options":["向客户说明与其投资建议不一致的观点","以个人名义向客户收取证券投资顾问服务费用","向客户承诺或者保证投资收益","代客户作出投资决策"],"answer":"A","explain":"证券投资顾问不得从事下列活动：（1）以任何方式向客户承诺或者保证投资收益（C 选项不符合题意）；（2）对服务能力和过往业绩进行虚假、不实、误导性的营销宣传；（3）向他人泄露客户的投资决策计划信息；（4）以个人名义向客户收取证券投资顾问服务费用（B 选项不符合题意）；（5）通过广播、电视、网络、报刊等公众媒体作出买入、卖出或者持有具体证券的投资建议。D 选项不符合题意，证券投资顾问不得代客户作出投资决策。故本题选A 选项。"},{"id":"law2-13","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"单选","q":"根据资产支持证券信息披露的规定，管理人、托管人应当在每年（）之前向资产支持证券合格投资者披露上年度资产管理报告、年度托管报告。","options":["1 月31 日","3 月31 日","4 月30 日","6 月30 日"],"answer":"C","explain":"C 选项正确，管理人、托管人应当在每年4 月30 日之前向资产支持证券合格投资者披露上年度资产管理报告、年度托管报告。故本题选C 选项。"},{"id":"law2-14","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"单选","q":"公司应当自作出合并决议之日起（）日内通知债权人，并于30 日内在报纸上公告。","options":["15","10","20","30"],"answer":"B","explain":"B 选项正确，公司合并，应当由合并各方签订合并协议，并编制资产负债表及财产清单。公司应当自作出合并决议之日起 10 日内通知债权人，并于 30 日内在报纸上或者国家企业信用信息公示系统公告。故本题选B 选项。"},{"id":"law2-15","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"单选","q":"股份有限公司以超过股票票面金额的发行价格发行股份所得的溢价款应当列为公司的（）。","options":["资本公积金","任意公积金","股本溢价","法定公积金"],"answer":"A","explain":"A 选项正确，公司以超过股票票面金额的发行价格发行股份所得的溢价款、发行无面额股所得股款未计入注册资本的金额以及国务院财政部门规定列入资本公积金的其他项目，应当列为公司资本公积金。故本题选A 选项。【温馨提示】公司分配当年税后利润时，应当提取利润的10%列入公司法定公积金。公司从税后利润中提取法定公积金后，经股东会决议，还可以从税后利润中提取任意公积金。股本溢价是资本公积金下的明细科目（资本公积金包含股本溢价、其他资本公积等），题目问的是整体归属，而非具体明细，法规题目要遵从法律原文表述。"},{"id":"law2-16","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"单选","q":"关于诱骗投资者买卖证券、期货合约罪的犯罪构成，以下说法错误的是（）。","options":["主体包含证券公司、期货公司从业人员，不包含证券期货监督管理部门的工作人员","主观方面为故意","侵犯的客体是证券、期货市场的正常交易管理秩序和证券、期货投资人的合法利益","客观要件包含行为人故意提供虚假信息诱骗投资者买卖证券，造成严重后果的行为"],"answer":"A","explain":"诱骗投资者买卖证券、期货合约罪犯罪的主体是特殊主体，主要包括两个方面：（1）证券交易所、期货交易所、证券公司、期货经纪公司的从业人员；（2）证券业协会、期货业协会或者证券期货监督管理部门的工作人员（A 选项错误）。故本题选A 选项。"},{"id":"law2-17","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"单选","q":"关于证券金融公司开展转融通业务的资金来源的说法，错误的是（）。","options":["证券金融公司通过证券交易所的业务平台融入的资金","证券金融公司不得使用向股东借入次级债融入的资金","证券金融公司自有资金","证券金融公司通过自己的业务平台融入的资金"],"answer":"B","explain":"证券金融公司开展转融通业务，可以使用下列资金和证券：（1）自有资金和证券（C 选项正确）；（2）通过证券交易所的业务平台融入的资金和证券（A 选项正确）；（3）通过证券金融公司的业务平台融入的资金（D 选项正确）；（4）依法筹集的其他资金和证券。B 选项错误，证券金融公司可以向股东或其他符合条件的机构投资者借入次级债，作为其资金来源之一。故本题选B 选项。"},{"id":"law2-18","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"单选","q":"甲与乙串通，以事先约定的时间、价格和方式相互进行证券交易，影响证券交易价格，获得巨大非法收益，则甲与乙的行为构成（）罪。","options":["内幕交易","利用未公开信息交易","操纵证券市场","背信运用受托财产"],"answer":"C","explain":"操纵证券、期货市场罪，是指有下列情形的，操纵证券、期货市场，影响证券、期货交易价格或者证券、期货交易量：与他人串通，以事先约定的时间、价格和方式相互进行证券、期货交易（C 选项正确）。故本题选C 选项。【温馨提示】操纵证券、期货市场罪，是指有下列情形之一，操纵证券、期货市场，影响证券、期货交易价格或者证券、期货交易量：（1）单独或者合谋，集中资金优势、持股或者持仓优势或者利用信息优势联合或者连续买卖；（2）与他人串通，以事先约定的时间、价格和方式相互进行证券、期货交易；（3）在自己实际控制的账户之间进行证券交易，或者以自己为交易对象，自买自卖期货合约的；（4）不以成交为目的，频繁或者大量申报买入、卖出证券、期货合约并撤销申报；（5）利用虚假或者不确定的重大信息，诱导投资者进行证券、期货交易；（6）对证券、证券发行人、期货交易标的公开作出评价、预测或者投资建议，同时进行反向证券交易或者相关期货交易；（7）以其他方法操纵证券、期货市场的。"},{"id":"law2-19","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"单选","q":"甲证券营业部客服人员李某向张某销售某集合资产管理计划，李某向普通投资者张某进行了背景调查，并告知了适当性匹配意见及相关警示内容，并提供了书面文件。下列关于了解投资者信息的说法，错误的是（）。","options":["李某向张某销售产品，应当了解张某的诚信记录","李某向张某提供服务，应当了解张某的直系亲属信息","李某向张某提供服务，应当了解张某的投资经验","李某向张某提供服务，应当了解张某的风险偏好及可承受的损失"],"answer":"B","explain":"根据《证券期货投资者适当性管理办法》的要求，经营机构向投资者销售产品或者提供服务时，应当了解投资者的下列信息：（1）自然人的姓名、住址、职业、年龄、联系方式，法人或者其他组织的名称、注册地址、办公地址、性质、资质及经营范围等基本信息（B 选项错误，并非\"直系亲属\"）；（2）投资相关的学习、工作经历及投资经验（C 选项正确）；（3）风险偏好及可承受的损失（D 选项正确）；（4）诚信记录（A 选项正确）。故本题选B 选项。【温馨提示】经营机构向投资者销售产品或者提供服务时，还应当了解投资者的下列信息：（1）收入来源和数额、资产、债务等财务状况；（2）投资期限、品种、期望收益等投资目标；（3）实际控制投资者的自然人和交易的实际受益人；（4）法律法规、自律规则规定的投资者准入要求相关信息；（5）其他必要信息。"},{"id":"law2-20","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"单选","q":"期货交易实行（）结算制度。","options":["次日负债","当日负债","当日无负债","次日无负债"],"answer":"C","explain":"C 选项正确，期货交易实行当日无负债结算制度。故本题选C 选项。"},{"id":"law2-21","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"单选","q":"投资者融券卖出时，私募证券投资基金的融券保证金比例不得低于（）。","options":["50%","70%","90%","120%"],"answer":"D","explain":"投资者融券卖出时，融券保证金比例不得低于 100%，其中私募证券投资基金的融券保证金比例不得低于120%（D 选项正确）。故本题选D 选项。"},{"id":"law2-22","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"单选","q":"我国有限责任公司股东不得超过（）人。","options":["50","100","150","200"],"answer":"A","explain":"A 选项正确，有限责任公司由1 个以上 50 个以下股东出资设立。故本题选A 选项。"},{"id":"law2-23","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"单选","q":"下列法律法规及主要部门规章、规范性文件中，不属于证券公司发行与承销业务适用的是（）。","options":["《企业债券管理条例》","《证券发行与承销管理办法》","《上市公司收购管理办法》","《公司法》"],"answer":"C","explain":"证券公司发行与承销业务的主要法律、行政法规包括《公司法》（D 选项不符合题意）《证券法》《证券公司监督管理条例》《企业债券管理条例》（A 选项不符合题意）等。证券发行承销的主要部门规章、规范性文件及业务规则主要包括《证券发行与承销管理办法》（B 选项不符合题意）《上海证券交易所首次公开发行证券发行与承销业务实施细则》《深圳证券交易所首次公开发行证券发行与承销业务实施细则》《上海证券交易所上市公司证券发行与承销业务实施细则》《深圳证券交易所上市公司证券发行与承销业务实施细则》《北京证券交易所证券发行与承销管理细则》《首次公开发行证券承销业务规则》等。C 选项符合题意，《上市公司收购管理办法》属于与证券交易、证券投资活动有关的财务顾问的业务的规章制度。故本题选C 选项。"},{"id":"law2-24","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"单选","q":"下列关于非公开基金投资范围的说法中，错误的是（）。","options":["非公开募集基金可以买卖股指期货","非公开募集基金可以买卖基金份额","非公开募集基金可以买卖股权","非公开募集基金可以买卖基金合同约定以外的投资标的"],"answer":"D","explain":"非公开募集基金财产的投资包括买卖股票、股权（C 选项正确）、债券、期货（A 选项正确）、期权、基金份额（B 选项正确）及投资合同约定的其他投资标的（D 选项错误）。故本题选D 选项。"},{"id":"law2-25","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"单选","q":"下列关于合伙企业的清算的说法，错误的是（）。","options":["合伙企业解散，应当由清算人进行清算。清算人由全体合伙人担任","经全体合伙人过半数同意，可以自合伙企业解散事由出现后 15 日内指定 1 个或者数个合伙人，或者委托第三人，担任清算人","合伙企业财产在支付清算费用和职工工资、社会保险费用、法定补偿金以及缴纳所欠税款、清偿债务后的剩余财产，依照普通合伙企业利润分配、亏损分担规则进行分配","清算结束，清算人应当编制清算报告，经 2/3 合伙人签名、盖章后，在 15 日内向企业登记机关报送清算报告，申请办理合伙企业注销登记"],"answer":"D","explain":"A 选项正确，合伙企业解散，应当由清算人进行清算。清算人由全体合伙人担任。B 选项正确，经全体合伙人过半数同意，可以自合伙企业解散事由出现后15 日内指定1 个或者数个合伙人，或者委托第三人，担任清算人。C 选项正确，合伙企业财产在支付清算费用和职工工资、社会保险费用、法定补偿金以及缴纳所欠税款、清偿债务后的剩余财产，依照普通合伙企业利润分配、亏损分担规则进行分配。D 选项错误，清算结束，清算人应当编制清算报告，经全体合伙人签名、盖章后（并非 2/3 合伙人），在15 日内向企业登记机关报送清算报告，申请办理合伙企业注销登记。故本题选D 选项。"},{"id":"law2-26","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"单选","q":"下列关于净资本的说法，正确的是（）。","options":["计算核心净资本时，不需要计提资产减值准备","净资本和净资产的概念相同","净资本由核心净资本和附属净资本构成","核心净资本由净资本和附属净资本构成"],"answer":"C","explain":"A 选项错误，证券公司计算核心净资本时，应当按照规定对有关项目充分计提资产减值准备。B 选项错误，净资本和净资产是两个概念。净资产指公司总资产减去总负债后的所有者权益账面价值。净资本指在净资产的基础上，根据各项资产的风险程度和负债的流动性进行风险调整后，得出的用于衡量证券公司资本充足和流动性状况的监管指标。C 选项正确、D 选项错误，证券公司净资本由核心净资本和附属净资本构成。故本题选C 选项。"},{"id":"law2-27","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"单选","q":"下列关于证券投资咨询机构及其执业人员向社会公众开展证券投资咨询业务活动的说法，错误的是（）。","options":["证券投资咨询从业人员向公众提供证券投资咨询服务时，需先行取得所在机构的认可","证券公司财务顾问专业人员在离开原岗位后的 6 个月内不得从事面向公众开展的投资咨询业务","证券投资咨询机构可参加媒体等机构举办的模拟证券投资大赛的节目，但证券投资咨询人员除外","经证监会核准的公开发行证券的企业的承销商及其所属的证券投资咨询机构，不得在公众传播媒体上刊登其为客户撰写的投资价值分析报告"],"answer":"C","explain":"C 选项错误，证券投资咨询机构及其从业人员不得参加（并非\"可参加\"）媒体等机构举办的荐股\"擂台赛\"、模拟证券投资大赛或类似的栏目或节目。故本题选C 选项。"},{"id":"law2-28","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"单选","q":"下列关于资产管理产品的说法，错误的是（）。","options":["资产管理产品按投资性质不同可分为三类，即固定收益类产品、权益类产品、期货和衍生品类产品","固定收益类产品投资于债权类资产比例不低于80%","权益类产品投资于股权类资产比例不低于80%","期货和衍生品的持仓合约价值的比例不低于资产管理计划总资产的 80%"],"answer":"A","explain":"A 选项错误，资产管理产品按照投资性质不同，分为固定收益类产品、权益类产品、期货和衍生品类产品和混合类产品。故本题选A 选项。"},{"id":"law2-29","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"单选","q":"下列有关证券公司证券自营业务禁止性行为的说法，错误的是（）。","options":["证券自营业务不得违反规定委托他人代为买卖证券","证券公司不得利用本公司投资银行业务内幕信息从事证券交易活动","证券自营业务不得违反规定购买本证券公司控股股东发行的证券","证券公司可以将自营业务与经纪业务混合操作"],"answer":"D","explain":"证券自营业务的禁止性行为：（1）禁止内幕交易。证券公司从事证券自营业务时，严禁以获取利益或者减少损失为目的，利用证券交易内幕信息的知情人和非法获取内幕信息的人利用内幕信息从事证券交易活动（ B选项正确）。（2）禁止操纵市场。（3）其他禁止的行为。包括：①违反规定委托他人代为买卖证券（A 选项正确）；②违反规定购买本证券公司控股股东或者与本证券公司有其他重大利害关系的发行人发行的证券（C 选项正确）；③将自营业务与经纪业务混合操作（D 选项错误）。故本题选D 选项。【温馨提示】证券自营业务其他禁止的行为包括：（1）假借他人名义或者个人名义进行自营业务；（2）违反规定委托他人代为买卖证券；（3）违反规定购买本证券公司控股股东或者与本证券公司有其他重大利害关系的发行人发行的证券；（4）将自营账户借给他人使用；（5）将自营业务与经纪业务混合操作；（6）法律、行政法规或中国证监会禁止的其他行为。"},{"id":"law2-30","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"以下关于信息安全的说法，错误的是（）。","options":["证券公司已经或可能掌握内幕信息的，应当将内幕信息所涉公司或证券列入限制名单","与公司工作人员签署保密文件，要求工作人员对工作中获取的敏感信息严格保密","加强对涉及敏感信息的信息系统、通信及办公自动化等信息设施、设备的管理，保障敏感信息安全","对可能知悉敏感信息的工作人员使用公司的信息系统或配发的设备形成的电子邮件、即时通信信息和其他通信信息进行监测"],"answer":"A","explain":"A 选项错误，证券公司已经或者可能掌握内幕信息的，应当将内幕信息所涉公司或者证券列入观察名单（并非\"限制名单\"）。故本题选A 选项。"},{"id":"law2-31","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"以下可能不属于专业投资者的是（）。","options":["金融资产300 万的个人投资者","商业银行","保险公司","私募基金管理者"],"answer":"A","explain":"（1）第一类专业投资者具体包括：经有关金融监管部门批准设立的金融机构，包括证券公司、期货公司、基金管理公司及其子公司、商业银行（B 选项不符合题意）、保险公司（C 选项不符合题意）、信托公司、财务公司等；经行业协会备案或者登记的证券公司子公司、期货公司子公司、私募基金管理人（D 选项不符合题意）。（2）第二类专业投资者包括：同时符合下列条件的自然人：①金融资产不低于500 万元（A 选项符合题意），或者最近3 年个人年均收入不低于50 万元；②具有 2 年以上证券、基金、期货、黄金、外汇等投资经历，或者具有 2 年以上金融产品设计、投资、风险管理及相关工作经历，或者属于前述第一类专业投资者中的第 1 部分的金融机构的高级管理人员、获得职业资格认证的从事金融相关业务的注册会计师和律师。故本题选A 选项。【温馨提示】（1）第一类专业投资者具体还包括：①上述机构面向投资者发行的理财产品，包括但不限于证券公司资产管理产品、基金管理公司及其子公司产品、期货公司资产管理产品、银行理财产品、保险产品、信托产品、经行业协会备案的私募基金。②社会保障基金、企业年金等养老基金，慈善基金等社会公益基金，合格境外机构投资者，人民币合格境外机构投资者。（2）第二类专业投资者还包括：同时符合下列条件的法人或者其他组织：①最近1 年末净资产不低于2000 万元；②最近1 年末金融资产不低于1000 万元；③具有2 年以上证券、基金、期货、黄金、外汇等投资经历。"},{"id":"law2-32","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"以下属于证监会等监管机构制定证券经纪业务相关监管政策、实施监督管理的重要法规依据的是（）。","options":["《证券登记结算管理办法》","《信托法》","《公司法》","《证券公司监督管理条例》"],"answer":"D","explain":"D 选项正确，《证券法》《证券公司监督管理条例》是中国证监会等监管机构制定证券经纪业务相关监管政策、实施监督管理的重要法律依据。故本题选D 选项。"},{"id":"law2-33","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"由于股票期权交易实行（）制度，证券登记结算机构应当在当日及时将结算结果通知结算参与人，结算参与人据此对投资者进行结算，并应当将结算结果按照与投资者约定的方式及时通知投资者。","options":["当日无负债结算","保证金","强制平仓","套期保值"],"answer":"A","explain":"A 选项正确，股票期权交易实行当日无负债结算制度。证券登记结算机构应当在当日及时将结算结果通知结算参与人，结算参与人据此对投资者进行结算，并应当将结算结果按照与投资者约定的方式及时通知投资者。B 选项错误，保证金用于结算和履约保障。期货交易实行保证金制度，期货结算机构向结算参与人收取保证金，结算参与人向交易者收取保证金。C 选项错误，强制平仓制度是指当投资者（如期货、融资融券、外汇保证金交易等）的保证金账户资金不足以维持持仓风险时，交易所或券商（经纪商）强制卖出（平仓）其部分或全部持仓，以控制风险、防止损失进一步扩大的制度。D 选项错误，套期保值是指交易者为管理因其资产、负债等价值变化产生的风险而达成与上述资产、负债等基本吻合的期货交易和衍生品交易的活动。故本题选A 选项。"},{"id":"law2-34","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"债券交易人员薪酬与激励合计超过人民币（）万元的，超过部分应按照等分原则递延发放，周期不少于2 年。","options":["50","100","200","500"],"answer":"B","explain":"B 选项正确，债券交易人员薪酬与激励合计超过人民币 100 万元的，超过部分应按照等分原则递延发放，周期不少于2 年。故本题选B 选项。"},{"id":"law2-35","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"证券公司从事证券自营业务，可以依据（）的附件《证券公司证券自营投资品种清单》买卖其中所列的证券。","options":["《证券公司证券自营业务指引》","《证券公司内部控制指引》","《证券公司风险控制指标管理办法》","《关于证券公司证券自营业务投资范围及有关事项的规定》"],"answer":"D","explain":"D 选项正确，根据《关于证券公司证券自营业务投资范围及有关事项的规定》，证券公司从事证券自营业务，可以买卖此规定附件《证券公司证券自营投资品种清单》所列证券。故本题选D 选项。"},{"id":"law2-36","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"证券公司派内部单位工作人员，借调至贫困山区参与扶贫项目，参与扶贫攻坚，体现了其（）。","options":["承担社会责任","遵守法律法规","接受政府和公众的监督","遵守社会公德"],"answer":"A","explain":"A 选项正确，证券公司派员参与扶贫攻坚，属于积极响应国家脱贫攻坚战略，主动投入资源助力社会发展，是典型的社会责任体现。故本题选A 选项。【温馨提示】公司从事经营活动，应当遵守法律法规，遵守社会公德、商业道德，诚实守信，接受政府和社会公众的监督；应当充分考虑公司职工、消费者等利益相关者的利益以及生态环境保护等社会公共利益，承担社会责任。"},{"id":"law2-37","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"证券公司应当于每年（）前，完成对上一年网络和信息安全工作的专项评估，编制网络和信息安全管理年报，报送中国证监会及其派出机构。","options":["8 月31 日","12 月31 日","4 月30 日","6 月30 日"],"answer":"C","explain":"C 选项正确，证券公司应当于每年 4 月 30 日前，完成对上一年网络和信息安全工作的专项评估，编制网络和信息安全管理年报，报送中国证监会及其派出机构。故本题选C 选项。"},{"id":"law2-38","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"中国证监会等监管机构制定证券公司信用业务相关监管政策、实施监督管理的法律依据是（）。","options":["《中国证券登记结算有限责任公司证券出借及转融通登记结算业务规则（试行）》","《转融通业务监督管理试行办法》","《证券公司融资融券业务管理办法》","《证券法》和《证券公司监督管理条例》"],"answer":"D","explain":"A 选项错误，是中国结算制定的自律规则，不属于监管机构制定政策、实施监督管理的法律依据。B、C 选项错误，是中国证监会制定的部门规章，属于具体的监管政策文件，而非其制定这些政策、实施监管的法律依据。D 选项正确，《证券法》和《证券公司监督管理条例》是中国证监会等监管机构制定信用业务相关监管政策、实施监督管理的重要法律依据。故本题选D 选项。"},{"id":"law2-39","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"中国证监会根据证券公司评价计分的高低，将证券公司分为五大类十一个级别，其中（）是正常经营状态的最低等级。","options":["D 级","B 级","E 级","C 级"],"answer":"D","explain":"中国证监会根据证券公司评价计分的高低，将证券公司分为 A（AAA、AA、A）、B（BBB、BB、B）、C（CCC、CC、C）、D、E 五大类十一个级别。其中，C 级是正常经营状态的最低等级（D 选项正确）。故本题选D 选项。【温馨提示】（1）A 类公司风险管理能力在行业内最高，能较好地控制新业务、新产品方面的风险；（2）B 类公司风险管理能力在行业内较高，在市场变化中能较好地控制业务扩张的风险；（3）C 类公司风险管理能力与其现有业务相匹配；（4）D 类公司风险管理能力弱，潜在风险可能超过公司可承受范围；（5）E 类公司潜在风险已经变为现实风险，已被采取风险处置措施。"},{"id":"law2-40","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"（）不属于法律法规调整的关系。","options":["代理关系","委托关系","恋爱关系","朋友关系"],"answer":"CD","explain":"C、D 选项正确，没有相应的法律规范，就不会产生相应的法律关系，但并不是所有的社会关系均受到法律规范的调整，有些社会关系，如恋爱关系、朋友关系或社会团体内部成员之间的关系，一般不存在相应的法律规定，不受法律规范调整，因此不产生法律关系，也不存在合法或非法的评价。A 选项错误，代理关系是指代理人在代理权限范围内，以被代理人（本人）的名义与第三人实施民事法律行为，其法律后果直接由被代理人承担的一种法律关系。属于法律法规调整的关系。B 选项错误，委托关系是指一方（委托人）将事务交由另一方（受托人）处理，受托人以委托人的名义或自己的名义实施行为，双方基于信任形成的权利义务关系。属于法律法规调整的关系。故本题选CD 选项。"},{"id":"law2-41","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"不具备证券自营业务资格的证券公司，其自有资金能够从事（）。","options":["不以对冲风险为目的的金融衍生产品交易","以对冲风险为目的的金融衍生产品交易","以套期保值为目的的股票期权交易","公开发行并上市的股票交易"],"answer":"BC","explain":"A 选项错误、B 选项正确，具备证券自营业务资格的证券公司可以从事金融衍生产品交易，不具备证券自营业务资格的证券公司只能以对冲风险为目的，从事金融衍生产品交易。C 选项正确、D 选项错误，证券公司以自有资金参与股票期权交易试点的，应当具备证券自营业务资格。不具备证券自营业务资格的证券公司，其自有资金只能以套期保值为目的，参与股票期权交易。故本题选BC 选项。"},{"id":"law2-42","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"从事私募基金业务活动，应当遵循（）的原则。","options":["自愿","平等","诚信","公平"],"answer":"ACD","explain":"从事私募基金业务活动，应当遵循自愿、公平、诚信原则（A、C、D 选项正确），保护投资者合法权益，不得违反法律、行政法规和国家政策，不得违背公序良俗，不得损害国家利益、社会公共利益和他人合法权益。故本题选ACD 选项。"},{"id":"law2-43","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"根据《非上市公众公司监督管理办法》，对挂牌公司进行持续监管，防范风险，维护证券市场秩序的监管主体包括（）。","options":["国务院有关部门","商业银行","地方人民政府","中国证监会"],"answer":"ACD","explain":"中国证监会会同国务院有关部门（A、D 选项正确）、地方人民政府（C 选项正确），依照法律法规和国务院有关规定，各司其职，分工协作，对挂牌公司进行持续监管，防范风险，维护证券市场秩序。B 选项错误，商业银行是金融机构，不具备对非上市公众公司进行证券市场监管的法定职责。故本题选ACD 选项。"},{"id":"law2-44","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"根据《关于规范债券市场参与者债券交易业务的通知》，债券交易包括（）等符合规定的债券交易业务。","options":["现券买卖","债券回购","债券远期","债券借贷"],"answer":"ABCD","explain":"债券交易包括现券买卖（A 选项符合题意）、债券回购（B 选项符合题意）、债券远期（C 选项符合题意）、债券借贷（D 选项符合题意）等符合规定的债券交易业务。故本题选ABCD 选项。"},{"id":"law2-45","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"根据《金融机构洗钱和恐怖融资风险评估及客户分类管理指引》，下列关于证券公司开展洗钱风险评估及客户分类管理的说法，错误的有（）。","options":["证券公司应对客户参与不同的业务进行不同的风险等级划分，同一客户在证券公司不应有唯一的风险等级","对高风险客户应采取强化的客户尽职调查及其他风险控制措施","对于首次建立业务关系的客户，无论风险等级高低，证券公司在初次确定其风险等级后的三年内至少应进行一次复核","对于已确立过风险等级的客户，证券公司不得再根据其风险程度设置相应的重新审核期限"],"answer":"AD","explain":"A 选项错误，对于新建立业务关系的客户，证券公司应在建立业务关系后的10 个工作日内，按照收集信息、筛选分析信息、初评和复评的流程，划分其风险等级，同一客户在证券公司应有唯一的风险等级。B 选项正确，证券公司应在客户风险等级划分的基础上，采取相应的客户尽职调查及其他风险管控措施。对于风险等级较高的客户，证券公司应当根据风险情形采取相匹配的一种或者多种强化尽职调查措施。C 选项正确、D 选项错误，对于已确立过风险等级的客户，证券公司应根据其风险程度设置相应的重新审核期限，实现对风险的动态追踪。原则上，风险等级最高的客户的审核期限不得超过半年，低一等级客户的审核期限不得超出上一级客户审核期限时长的两倍。对于首次建立业务关系的客户，无论其风险等级高低，证券公司在初次确定其风险等级后的 3 年内至少应进行一次复核。故本题选AD 选项。"},{"id":"law2-46","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"根据《期货和衍生品法》，下列关于期货交易所职责的说法正确的有（）。","options":["按照章程和业务规则对会员进行自律管理","开展交易者教育和市场培育工作","设计合约品种，安排合约品种上市","直接或者间接参与期货交易"],"answer":"ABC","explain":"期货交易所的职责：（1）提供交易的场所、设施和服务；（2）设计期货合约、标准化期权合约品种，安排期货合约、标准化期权合约品种上市（ C 选项正确）；（3）对期货交易进行实时监控和风险监测；（4）依照章程和业务规则对会员、交易者、期货服务机构等进行自律管理（A 选项正确）；（5）开展交易者教育和市场培育工作（B 选项正确）；（6）国务院期货监督管理机构规定的其他职责。D 选项错误，期货交易场所不得直接或者间接参与期货交易。故本题选ABC 选项。"},{"id":"law2-47","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"根据《区域性股权市场自律管理与服务规范（试行）》，应当遵守证券行业自律管理的主体包括（）。","options":["区域性股权市场运营机构","区域性股权市场运营机构从业人员","参与区域性股权市场的证券公司","参与区域性股权市场的证券公司从业人员"],"answer":"ABCD","explain":"区域性股权市场运营机构（A、B 选项符合题意）、证券公司及其从业人员（C、D 选项符合题意）应当配合中国证券业协会对落实《规范》及相关自律要求情况的监督检查。故本题选ABCD 选项。"},{"id":"law2-48","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"根据《私募投资基金监督管理暂行办法》，私募基金管理人不得实施的行为有（）。","options":["从事损害基金财产的投资活动","公平地对待其管理的基金财产","玩忽职守，不按规定履行职责","挪用基金财产"],"answer":"ACD","explain":"私募基金管理人及其从业人员从事私募基金业务，不得有以下行为：（1）将其固有财产或者他人财产混同于基金财产从事投资活动；（2）不公平地对待其管理的不同基金财产；（3）利用基金财产或者职务之便，为本人或者投资者以外的人牟取利益，进行利益输送；（4）侵占、挪用基金财产（D 选项正确）；（5）泄露因职务便利获取的未公开信息，利用该信息从事或者明示、暗示他人从事相关的交易活动；（6）从事损害基金财产和投资者利益的投资活动（A 选项正确）；（7）玩忽职守，不按照规定履行职责（C 选项正确）；（8）从事内幕交易、操纵交易价格及其他不正当交易活动。故本题选ACD 选项。"},{"id":"law2-49","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"根据《刑法》，下列关于违规披露、不披露重要信息罪构成要件的说法，正确的有（）。","options":["本罪侵犯的客体是国家有关公司、企业的财会报告及其他重要信息的管理秩序和股东、社会公众和其他利害关系人的合法权益","本罪在客观方面表现为向股东和社会公众提供虚假的或者隐瞒重要事实的财务会计报告等，严重损害股东或者其他人利益的行为","本罪主观方面既可以是故意，也可以是过失","本罪的主体是特殊主体，即依法负有信息披露义务的公司、企业及相关责任人员"],"answer":"ABD","explain":"A 选项正确，本罪侵犯的客体是国家有关公司、企业的财会报告及其他重要信息的管理秩序和股东、社会公众和其他利害关系人的合法权益。B 选项正确，本罪在客观方面表现为向股东和社会公众提供虚假的或者隐瞒重要事实的财务会计报告等，严重损害股东或者其他人利益的行为。C 选项错误，本罪犯罪主观方面只能由故意构成，过失不构成本罪。D 选项正确，本罪的犯罪主体为特殊主体，即依法负有信息披露义务的公司、企业及相关责任人员。故本题选ABD 选项。"},{"id":"law2-50","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"根据《证券法》，下列关于证券公司承销证券的说法，正确的有（）。","options":["证券公司承销证券，发现公开发行募集文件有虚假记载、误导性陈述或者重大遗漏的，不得进行销售活动","证券公司承销证券，不得进行虚假的或者误导投资者的广告宣传","证券公司承销证券，发现公开发行募集文件有虚假记载、误导性陈述或者重大遗漏，已经销售的，必须立即停止销售活动，并采取纠正措施","证券公司承销证券，不得以不正当竞争手段招揽承销业务"],"answer":"ABCD","explain":"证券公司承销证券，应当对公开发行募集文件的真实性、准确性、完整性进行核查。发现有虚假记载、误导性陈述或者重大遗漏的，不得进行销售活动（A 选项正确）；已经销售的，必须立即停止销售活动，并采取纠正措施（C 选项正确）。证券公司承销证券，不得有下列行为：（1）进行虚假的或者误导投资者的广告宣传或者其他宣传推介活动（B 选项正确）；（2）以不正当竞争手段招揽承销业务（D 选项正确）；（3）其他违反证券承销业务规定的行为。故本题选ABCD 选项。"},{"id":"law2-51","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"根据《证券公司风险处置条例》下列关于国务院证券监督管理机构在处置证券公司风险工作中应履行的职责，正确的有（）。","options":["及时向国家审计机关通报涉嫌证券违规的情况，移送违规的案件","派驻风险处置现场工作组，对被处置证券公司、托管组、接管组、行政清理组、管理人以及参与风险处置的其他机构和人员进行监督和指导","协调证券交易所、证券登记结算机构、证券投资者保护基金管理机构，保障被处置证券公司证券经纪业务正常进行","向有关地方人民政府通报证券公司风险状况以及影响社会稳定的情况"],"answer":"BCD","explain":"A 选项错误，及时向公安机关（并非\"国家审计机关\"）等通报涉嫌刑事犯罪的情况，按照有关规定移送涉嫌犯罪的案件。故本题选BCD 选项。【温馨提示】国务院证券监督管理机构在处置证券公司风险工作中，履行下列职责：（1）制订证券公司风险处置方案并组织实施；（2）派驻风险处置现场工作组，对被处置证券公司、托管组、接管组、行政清理组、管理人以及参与风险处置的其他机构和人员进行监督和指导；（3）协调证券交易所、证券登记结算机构、证券投资者保护基金管理机构，保障被处置证券公司证券经纪业务正常进行；（4）对证券公司的违法行为立案稽查并予以处罚；（5）及时向公安机关等通报涉嫌刑事犯罪的情况，按照有关规定移送涉嫌犯罪的案件；（6）向有关地方人民政府通报证券公司风险状况以及影响社会稳定的情况；（7）法律、行政法规要求履行的其他职责。"},{"id":"law2-52","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"根据《证券公司风险控制指标管理办法》，净资本指标不符合规定标准时，证券公司应当向（）报告。","options":["公司全体董事","中国证券业协会","中国证监会派出机构","公司全体股东"],"answer":"ACD","explain":"净资本指标与上月相比发生 20%以上不利变化或不符合规定标准时，证券公司应当在 5 个工作日内向公司全体董事报告（A 选项正确），10 个工作日内向公司全体股东报告（D 选项正确）。证券公司的净资本等风险控制指标达到预警标准或者不符合规定标准的，应当分别在该情形发生之日起 3 个、1 个工作日内，向中国证监会及其派出机构报告（C 选项正确），说明基本情况、问题成因以及解决问题的具体措施和期限。故本题选ACD 选项。"},{"id":"law2-53","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"根据《证券公司流动性风险管理指引》，下列关于证券公司流动性风险限额的说法，正确的有（）。","options":["证券公司应当对流动性风险限额的执行情况进行监控","证券公司应当根据其业务规模、性质、复杂程度、流动性风险偏好和外部市场发展变化、监管要求等情况设定流动性风险限额","证券公司流动性风险限额一经设定，不得调整","证券公司应至少每年对流动性风险限额进行一次评估"],"answer":"ABD","explain":"证券公司应对流动性风险实施限额管理，根据其业务规模、性质、复杂程度、流动性风险偏好和外部市场发展变化、监管要求等情况，设定流动性风险限额并对其执行情况进行监控（A，B选项正确）。证券公司应至少每年对流动性风险限额进行一次评估，必要时进行调整（C 选项错误，并非不得调整；D 选项正确）。故本题选ABD 选项。"},{"id":"law2-54","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"根据《证券公司流动性风险管理指引》，证券公司流动性风险管理的目标是建立健全流动性风险管理体系，对流动性风险采取（）等措施，以有效管控流动性风险。","options":["识别和计量","报告","监测","控制"],"answer":"ACD","explain":"证券公司流动性风险管理的目标，是建立健全流动性风险管理体系，对流动性风险实施有效识别、计量（A 选项正确）、监测（C 选项正确）和控制（D 选项正确），确保其流动性需求能够及时以合理成本得到满足。故本题选ACD 选项。"},{"id":"law2-55","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"根据《证券公司信用风险管理指引》，下列属于证券公司信用风险的有（）。","options":["因财务顾问违约导致损失的风险","因发行人违约导致损失的风险","因融资方违约导致损失的风险","因交易对手违约导致损失的风险"],"answer":"BCD","explain":"A 选项不符合题意，通常属于操作风险的范畴。操作风险是指由不完善或有问题的内部程序、人员、信息技术系统，以及外部事件造成损失的风险。信用风险指因融资方（C 选项符合题意）、交易对手（D 选项符合题意）或发行人（B 选项符合题意）等违约导致损失的风险。故本题选BCD 选项。"},{"id":"law2-56","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"根据《证券基金经营机构信息技术管理办法》，下列关于证券公司信息系统安全的说法，正确的有（）。","options":["证券公司应当结合公司发展战略、市场交易规模等因素定期对重要信息系统开展压力测试和评估分析，确保其容量满足业务开展需要","证券公司应当确保重要信息系统具备可审计功能，并可以根据监管部门的要求转换、提供数据","证券公司应当建立健全信息系统安全监测机制，设定监测指标并持续监测重要信息系统的运行状况","证券公司重要信息系统计划停止使用的，可不用开展技术和业务影响评估"],"answer":"ABC","explain":"A 选项正确，证券公司应当结合公司发展战略、市场交易规模等因素定期对重要信息系统开展压力测试和评估分析，确保其容量满足业务开展需要。B 选项正确，证券公司应当确保重要信息系统具备可审计功能，并可以根据监管部门的要求转换、提供数据。C 选项正确，证券公司应当建立健全信息系统安全监测机制，设定监测指标并持续监测重要信息系统的运行状况。证券公司应当指定专人跟踪监测发现的异常情形，及时处置并定期开展评估分析。D 选项错误，证券公司重要信息系统计划停止使用的，应当开展（并非\"可不用开展\"）技术和业务影响评估，制定完整的系统停用和数据迁移保管方案，并组织必要的评审及停用后的安全检查。故本题选ABC 选项。"},{"id":"law2-57","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"根据合伙人对合伙企业债务承担责任的不同，合伙企业可分为（）。","options":["有限合伙企业","普通合伙企业","个人合伙企业","合资合伙企业"],"answer":"AB","explain":"根据合伙人对合伙企业债务承担责任的不同，合伙企业可分为普通合伙企业（B 选项正确）和有限合伙企业（A 选项正确）。故本题选AB 选项。"},{"id":"law2-58","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"股份有限公司董事，监事，高级管理人员持有本公司股票转让方式正确的有（）。","options":["在任职期间每年转让的股份不得超过其所持有本公司股份总数的 25%","在离职后一年内不得转让","上市交易之日起一年内不得转让","上市交易之日起半年内不得转让"],"answer":"AC","explain":"公司董事、监事、高级管理人员应当向公司申报所持有的本公司的股份及其变动情况，在就任时确定的任职期间每年转让的股份不得超过其所持有本公司股份总数的 25%（A 选项正确）；所持本公司股份自公司股票上市交易之日起1 年内不得转让（C 选项正确、D 选项错误）。上述人员离职后半年内，不得转让其所持有的本公司股份（B 选项错误）。故本题选AC 选项。"},{"id":"law2-59","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"甲证券公司不得为（）开立信用业务账户。","options":["未按照要求提供有关情况的张某","从事证券交易时间不足半年，缺乏风险承担能力的李某","最近20 个交易日日均证券类资产低于50 万元或者有重大违约记录的王某","最近20 个交易日日均证券类资产高于50 万元的赵某"],"answer":"ABC","explain":"证券公司不得为客户开立信用业务账户的情形：（1）未按照要求提供有关情况（A 选项正确）。（2）从事证券交易时间不足半年，缺乏风险承担能力（B 选项正确）。（3）最近20 个交易日日均证券类资产低于50 万元或者有重大违约记录的客户（C 选项正确、D 选项错误）。（4）本公司的股东（不包括仅持有上市证券公司5%以下流通股份的股东）、关联人。故本题选ABC 选项。"},{"id":"law2-60","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"某证券公司的下列实践中，能够反映证券行业文化建设基本要求中 \"牢记社会责任，展现良好形象\"的有（）。","options":["将对口帮扶地区的农副产品引入工会慰问品采购名单并鼓励会员优先选","多措并举增加注册资本并积极推动上市","建立各业务条线负责人必须出席的定期合规展业交流机制","积极参与证券行业支持民营企业发展系列资管计划（纾困基金）的设立"],"answer":"AD","explain":"牢记社会责任，展现良好形象。要求坚持义利兼顾，正道直行，发挥专业特长，加强经济形势分析研究，合力维护市场健康舆论生态，助力国家精准扶贫和乡村振兴，积极参与社会公益事业（A、D 选项符合题意），与经济社会共生共荣、融合发展。B 选项不符合题意，增加注册资本和推动上市属于证券公司自身资本运作和经营发展策略，核心目的是增强资本实力、拓展业务规模，属于商业行为范畴。该行为未直接体现\"社会责任\"或\"良好形象\"。C 选项不符合题意，合规展业交流机制属于公司内部治理和合规管理范畴，目的是确保业务开展符合法律法规要求，属于行业文化中\"坚持依法合规，筑牢发展基础\"的要求，而非社会责任。故本题选AD 选项。"},{"id":"law2-61","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"普通投资者应至少在（）享有特别保护。","options":["信息告知","风险警示","适当性匹配","保证本金"],"answer":"ABC","explain":"根据《证券期货投资者适当性管理办法》的规定，投资者分为普通投资者与专业投资者。普通投资者在信息告知（A 选项正确）、风险警示（B 选项正确）、适当性匹配（C 选项正确）等方面享有特别保护。D 选项错误，\"保证本金\"属于禁止行为。故本题选ABC 选项。"},{"id":"law2-62","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"下列关于非公开募集基金的募集与宣传推介的说法，正确的有（）。","options":["不得通过讲座、报告会、分析会等方式向其现有投资者宣传推介","不得通过报刊、电台、电视台等公众传播媒体向不特定对象宣传推介","不得在互联网上向不特定对象宣传推介","不得向合格投资者之外的单位和个人募集资金"],"answer":"BCD","explain":"A 选项错误，现有投资者属于合格投资者，可以通过讲座、报告会、分析会等方式向其宣传推介。B、C 选项正确，私募基金应非公开募集，不得通过报刊、电台、电视台、互联网等大众传播媒介，电话、短信、即时通信工具、电子邮件、传单，或者讲座、报告会、分析会等方式向不特定对象宣传推介。D 选项正确，非公开募集基金不得向合格投资者之外的单位和个人募集资金。故本题选BCD 选项。【温馨提示】私募基金还不得以虚假、片面、夸大等方式宣传推介；不得以私募基金托管人名义宣传推介；不得向投资者承诺投资本金不受损失或者承诺最低收益。私募基金管理人应当自行募集资金，不得委托他人募集资金，但国务院证券监督管理机构另有规定的除外。"},{"id":"law2-63","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"下列关于股份有限公司监事会的表述正确的有（）。","options":["监事会设主席一人，并应当设副主席","监事会主席由全体监事过半数选举产生","董事、高级管理人员不得兼任监事","监事会成员不得少于三人"],"answer":"BCD","explain":"股份有限公司设监事会，《公司法》第一百二十一条第一款、第一百三十三条另有规定的除外。A 选项错误，监事会设主席1 人，可以设副主席（并非应当）。B 选项正确，监事会主席和副主席由全体监事过半数选举产生。C 选项正确，董事、高级管理人员不得兼任监事。D 选项正确，监事会成员为3 人以上。故本题选BCD 选项。【温馨提示】监事会成员应当包括股东代表和适当比例的公司职工代表，其中职工代表的比例不得低于 1/3，具体比例由公司章程规定。监事会中的职工代表由公司职工通过职工代表大会、职工大会或者其他形式民主选举产生。"},{"id":"law2-64","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"下列关于有限责任公司股权转让的规定，说法正确的有（）。","options":["股东之间可以相互转让股权","股东向股东以外的人转让股权，其他股东自接到书面通知之日起满 30 日未答复的，视为放弃优先购买权","未经其他股东同意的，股东不得转让股权","股东向股东以外的人转让股权，口头书面通知其他股东即可，无需书面通知"],"answer":"AB","explain":"A 选项正确，有限责任公司的股东之间可以相互转让其全部或者部分股权。B 选项正确、D 选项错误，股东向股东以外的人转让股权，应当将股权转让的数量、价格、支付方式和期限等事项书面通知其他股东，其他股东在同等条件下有优先购买权。股东自接到书面通知之日起满30 日未答复的，视为放弃优先购买权。C 选项错误，说法过于绝对，对内转让无需其他股东同意，对外转让需要书面通知。故本题选AB 选项。"},{"id":"law2-65","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"下列关于证券公司对敏感信息采取保密措施的说法，正确的有（）。","options":["与证券公司工作人员签署保密文件，要求工作人员对工作中获取的敏感信息严格保密","对可能知悉敏感信息的工作人员使用的公司及个人各类信息系统或设备形成的电子邮件、即时通信信息和其他通讯信息进行监测","建立内幕信息知情人管理制度","加强对涉及敏感信息的信息系统、通信及办公自动化等信息设施、设备的管理，保障敏感信息安全"],"answer":"ACD","explain":"（1）与公司工作人员签署保密文件，要求工作人员对工作中获取的敏感信息严格保密（ A 选项正确）；（2）加强对涉及敏感信息的信息系统、通信及办公自动化等信息设施、设备的管理，保障敏感信息安全（D 选项正确）；（3）对可能知悉敏感信息的工作人员使用公司（并不包括个人）的信息系统或配发的设备形成的电子邮件、即时通信信息和其他通信信息进行监测（B 选项错误）；（4）建立内幕信息知情人管理制度（C 选项正确）。故本题选ACD 选项。"},{"id":"law2-66","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"下列关于证券公司合规管理的说法，错误的有（）。","options":["证券公司首次开展行业已有可借鉴先例的业务，不需要进行新产品、新业务的评估与决策","经过合规负责人审核的材料，其他相关高级管理人员不需再对其中的内容负责","合规负责人发现公司存在合规风险隐患的，应依照公司章程及时向董事会、经营管理主要负责人报告，提出处理意见，并督促整改","合规负责人直接向总经理办公会负责"],"answer":"ABD","explain":"A 选项错误，证券公司应当建立新产品、新业务评估与决策机制，合规负责人和合规部门应当对新产品、新业务发表合规审查意见，证券公司在进行相关决策时，应当充分考虑和采纳合规审查意见。B 选项错误，中国证监会及其派出机构、自律组织要求对证券公司报送的申请材料或报告进行合规审查的，合规负责人应当审查，并在该申请材料或报告上签署合规审查意见。其他相关高级管理人员等应当对申请材料或报告中基本事实和业务数据的真实性、准确性及完整性负责。C 选项正确，合规负责人发现证券公司存在违法违规行为或合规风险隐患的，应当依照公司章程规定及时向董事会、经营管理主要负责人报告，提出处理意见，并督促整改。D 选项错误，合规负责人是高级管理人员，直接向董事会负责。故本题选ABD 选项。"},{"id":"law2-67","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"下列关于子公司法律地位的说法，正确的有（）。","options":["子公司具有独立的法人资格","子公司从事经营活动的民事责任由其母公司承担","子公司不具有法人资格","子公司依法独立承担民事责任"],"answer":"AD","explain":"子公司具有法人资格（A 选项正确、C 选项错误），依法独立承担民事责任（B 选项错误、D 选项正确）。故本题选AD 选项。【温馨提示】分公司不具有法人资格，其民事责任由公司承担。"},{"id":"law2-68","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"下列规章及规范性文件涉及上市公司收购以及上市公司重大资产重组的有（）。","options":["《科创板上市公司重大资产重组特别规定》","《上市公司并购重组财务顾问业务管理办法》","《证券投资顾问业务暂行规定》","《上市公司重大资产重组管理办法》"],"answer":"ABD","explain":"C 选项错误，是与证券投资咨询业务相关的法律法规、自律规则。故本题选ABD 选项。"},{"id":"law2-69","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"下列属于期货交易制度的有（）。","options":["账户实名制","当日无负债结算制度","保证金制度","持仓限额制度"],"answer":"ABCD","explain":"期货交易的基本制度包括：（1）账户实名制（A 选项符合题意）；（2）保证金制度（C 选项符合题意）；（3）持仓限额制度（D 选项符合题意）；（4）实际控制关系报备制度；（5）程序化交易报备制度。期货交易实行当日无负债结算制度（B 选项符合题意）。故本题选ABCD 选项。"},{"id":"law2-70","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"下列行为不属于资产管理业务禁止行为的有（）。","options":["为规避监管的期货业务提供交易便利","投资决策错误导致资产管理计划业绩回报处于同类产品末端","系统故障导致交易无法达成，造成资产管理计划财产受损","向投资者返还管理费"],"answer":"BC","explain":"证券公司、托管人、投资顾问及相关从业人员从事私募资产管理业务，不得有下列行为：（1）为违法或者规避监管的证券期货业务活动提供交易便利（A 选项不符合题意）；（2）直接或者间接向投资者返还管理费（D 选项不符合题意）。B 选项符合题意，是资产管理业务中可能发生的正常商业风险，不属于禁止行为。C 选项符合题意，属于技术风险或操作风险事件，不属于禁止行为。故本题选BC 选项。【温馨提示】证券公司、托管人、投资顾问及相关从业人员从事私募资产管理业务，不得有下列行为：（1）利用资产管理计划从事内幕交易、操纵市场或者其他不正当、违法的证券期货业务活动；（2）泄露因职务便利获取的未公开信息、利用该信息从事或者明示、暗示他人从事相关交易活动；（3）利用资产管理计划，通过直接投资、投资其他资产管理产品或者与他人进行交叉融资安排等方式，违规为本机构及其控股股东、实际控制人或者其他关联方提供融资；（4）为本人或他人违规持有金融机构股权提供便利；（5）从事非公平交易、利益输送等损害投资者合法权益的行为；（6）利用资产管理计划进行商业贿赂；（7）侵占、挪用资产管理计划财产；（8）利用资产管理计划或者职务便利为投资者以外的第三方谋取不正当利益；（9）以获取佣金或者其他不当利益为目的，使用资产管理计划财产进行不必要的交易；（10）法律、行政法规和中国证监会规定禁止的其他行为。"},{"id":"law2-71","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"证券公司承销证券，同发行人签订的证券代销协议必备的条款包括（）。","options":["代销证券的发行价格","代销的期限及起止日期","代销证券的种类、数量","代销证券的金额"],"answer":"ABCD","explain":"证券公司承销证券，应当同发行人签订代销或者包销协议，载明下列事项：（1）当事人的名称、住所及法定代表人姓名。（2）代销、包销证券的种类、数量、金额及发行价格（A、C、D 选项正确）。（3）代销、包销的期限及起止日期（B 选项正确）。（4）代销、包销的付款方式及日期。（5）代销、包销的费用和结算办法。（6）违约责任。（7）国务院证券监督管理机构规定的其他事项。故本题选ABCD 选项。"},{"id":"law2-72","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"证券公司风险管理部门具备 3 年以上的有关领域工作经历的人员占公司总部员工比例应不低于2%，不包括（）。","options":["金融","法律","证券","新闻"],"answer":"BD","explain":"证券公司风险管理部门具备3 年以上的证券（C 选项不符合题意）、金融（A 选项不符合题意）、会计、信息技术等有关领域工作经历的人员占公司总部员工比例应不低于 2%。故本题选BD 选项。"},{"id":"law2-73","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"证券公司净资本或者其他风险控制指标不符合规定标准的，中国证监会派出机构应当责令公司限期改正。整改期内，中国证监会及其派出机构应当区别情形，可以对证券公司采取的措施有（）。","options":["限制转让财产或在财产上设定其他权利","限制薪酬发放","限制分配红利","停止批准新业务"],"answer":"ACD","explain":"整改期内，中国证监会及其派出机构应当区别情形，对证券公司采取下列措施：（1）停止批准新业务（D 选项正确）；（2）停止批准增设、收购营业性分支机构；（3）限制分配红利（C 选项正确）；（4）限制转让财产或在财产上设定其他权利（A 选项正确）。B 选项错误，综上所述，\"限制薪酬发放\"不是整改期内，中国证监会及其派出机构应当区别情形，可以对证券公司采取的措施。故本题选ACD 选项。"},{"id":"law2-74","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"证券公司开展中间介绍业务，有下列（）行为的，按照《期货交易管理条例》相关规定进行处罚。","options":["未将财务、人员、经营场所与期货公司分开隔离","未将介绍业务与其他经营业务分开或者有效隔离","未按规定审查客户的开户资料和身份真实性","未经许可擅自开展介绍业务"],"answer":"ABCD","explain":"证券公司有下列行为之一的，按照《期货交易管理条例》第七十条进行处罚：（1）未经许可擅自开展介绍业务（D 选项正确）；（2）未按规定审查客户的开户资料和身份真实性（C 选项正确）；（3）未将介绍业务与其他经营业务分开或者有效隔离（B 选项正确）；（4）未将财务、人员、经营场所与期货公司分开隔离（A 选项正确）。故本题选ABCD 选项。【温馨提示】证券公司有下列行为之一的，按照《期货交易管理条例》第七十条进行处罚，还包括：（1）对客户未充分揭示期货交易风险，进行虚假宣传，误导客户；（2）代理客户进行期货交易、结算或者交割；（3）收付、存取或者划转期货保证金；（4）为客户从事期货交易提供融资或者担保；（5）代客户下达交易指令；（6）利用客户的交易编码、资金账号或者期货结算账户进行期货交易；（7）拒绝、阻碍中国证监会及其派出机构依法履行职责。"},{"id":"law2-75","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"证券公司内部控制应当遵循的原则包括（）。","options":["健全","合理","制衡","独立"],"answer":"ABCD","explain":"证券公司内部控制应当遵循以下原则，确保内部控制有效：健全（A 选项符合题意）、合理（B选项符合题意）、制衡（C 选项符合题意）、独立（D 选项符合题意）。故本题选ABCD 选项。"},{"id":"law2-76","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"证券公司融资融券的业务决策机构主要负责（）。","options":["保证金收取和交易执行等业务操作","确定对单一客户和单一证券的授信额度","决定与融资融券业务有关的部门设置","确定融资融券的期限和利率费率"],"answer":"BD","explain":"业务决策机构由有关高级管理人员及部门负责人组成，负责制定融资融券业务操作流程，选择可从事融资融券业务的分支机构，确定对单一客户和单一证券的授信额度（B 选项正确）、融资融券的期限和利率（费率）（D 选项正确）、保证金比例和最低维持担保比例、可充抵保证金的证券种类及折算率、客户可融资买入和融券卖出的证券种类。分支机构在公司总部的集中监控下，按照公司的统一规定和决定，具体负责客户征信、签约、开户、保证金收取和交易执行等业务操作（A 选项错误）。董事会负责制定融资融券业务的基本管理制度，决定与融资融券业务有关的部门设置（C 选项错误）及各部门职责，确定融资融券业务的总规模。故本题选BD 选项。"},{"id":"law2-77","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"证券期货经营机构违反适当性管理规定，有下列（）情形的，给予警告，并处以 3 万元以下罚款；对直接负责的主管人员和其他直接责任人员，给予警告，并处以 3 万元以下罚款。","options":["未按规定对普通投资者进行细化分类和管理的","未按规定进行投资者类别转化的","未建立或者更新投资者评估数据库的","未按规定了解所销售产品或者所提供服务信息或者履行分级义务的"],"answer":"ABCD","explain":"经营机构有下列情形之一的，给予警告，并处以 3 万元以下罚款；对直接负责的主管人员和其他直接责任人员，给予警告，并处以3 万元以下罚款：①未按规定对普通投资者进行细化分类和管理的（A 选项正确）；②未按规定进行投资者类别转化的（B 选项正确）；③未建立或者更新投资者评估数据库的（C 选项正确）；④未按规定了解所销售产品或者所提供服务信息或者履行分级义务的（D 选项正确）；⑤未按规定划分产品或者服务风险等级的；⑥未按规定录音录像或者采取配套留痕安排的；⑦未按规定制定或者落实适当性内部管理制度和相关制度机制的；⑧未按规定开展适当性自查的；⑨未按规定妥善保存相关信息资料的故本题选ABCD 选项。"},{"id":"law2-78","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"证券投资顾问业务和发布证券研究报告的区别包括以下（）方面。","options":["立场不同","服务对象不同","市场影响有所不同","服务方式和服务内容不同"],"answer":"ABCD","explain":"证券投资顾问业务和发布证券研究报告的区别：（1）立场不同（A 选项符合题意）；（2）服务方式和内容不同（D 选项符合题意）；（3）服务对象有所不同（B 选项符合题意）；（4）市场影响有所不同（C 选项符合题意）。故本题选ABCD 选项。"},{"id":"law2-79","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"证券投资咨询业务的基本形式包括（）。","options":["证券投资顾问","委托理财","发布证券研究报告","销售基金"],"answer":"AC","explain":"证券投资顾问业务和发布证券研究报告是证券投资咨询业务的两种基本形式（ A、C 选项符合题意）。故本题选AC 选项。"},{"id":"law2-80","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"判断","q":"《证券法》适用于在中华人民共和国境内的股票、公司债券、存托凭证、证券投资基金和国务院依法认定的其他证券的发行和交易。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。证券投资基金的发行主要由《中华人民共和国证券投资基金法》进行规范。【温馨提示】《证券法》的适用范围包括以下四类：一是在中华人民共和国境内，股票、公司债券、存托凭证和国务院依法认定的其他证券的发行和交易；二是政府债券、证券投资基金份额的上市交易；三是资产支持证券、资产管理产品发行、交易的管理办法，由国务院依照《证券法》的原则规定；四是在中华人民共和国境外的证券发行和交易活动，扰乱中华人民共和国境内市场秩序，损害境内投资者合法权益的，依照《证券法》有关规定处理并追究法律责任。"},{"id":"law2-81","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"判断","q":"除公募资产管理产品外，投资者以合伙企业、契约等非法人形式直接或者间接投资于证券公司资产管理计划的，应向管理人充分披露实际投资者和最终资金来源。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。除公募资产管理产品外，以合伙企业、契约等非法人形式直接或者间接投资于资产管理计划的，应当向管理人充分披露实际投资者和最终资金来源。"},{"id":"law2-82","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"判断","q":"对证券行业高级管理人员的岗前培训时间和其他从业人员一致。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。培训学时根据相关人员执业情况、专业能力水平评价情况、处罚处分措施情况、诚信情况、其他执业声誉情况及为行业发展、履行社会责任作出贡献情况等实行差异化管理（并非\"一致\"）。"},{"id":"law2-83","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"判断","q":"法律主体主要包括自然人、组织和国家三类。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。法律主体主要包括自然人、组织和国家三类，其中，可以成为法律主体的自然人包括我国公民以及在我国境内的外国人和无国籍人。"},{"id":"law2-84","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"判断","q":"根据《证券公司风险处置条例》，证券公司风险控制指标不符合有关规定，在规定期限内未能完成整改的，中国证券业协会可以责令证券公司停止部分或者全部业务进行整顿。停业整顿的期限不超过3 个月。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。证券公司风险控制指标不符合有关规定，在规定期限内未能完成整改的，国务院证券监督管理机构（而非中国证券业协会）可以责令证券公司停止部分或者全部业务进行整顿。停业整顿的期限不超过3 个月。"},{"id":"law2-85","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"判断","q":"根据《证券公司风险管理条例》，证券公司风险控制指数不达标的，中国证券业协会责令整改，逾期不改，证券公司停办全部业务或部分业务，停办最长不超三个月。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。证券公司净资本或者其他风险控制指标不符合规定标准的，派出机构应当责令公司限期改正（并非\"中国证券业协会\"）。证券公司未按期完成整改的，自整改期限到期的次日起，派出机构应当区别情形，对其采取下列措施：（1）限制业务活动；（2）责令暂停部分业务（并非\"全部业务\"，并未规定暂停期限）；（3）限制向董事、监事、高级管理人员支付报酬、提供福利；（4）责令更换董事、监事、高级管理人员或者限制其权利；（5）责令负有责任的股东转让股权，限制负有责任的股东行使股东权利；（6）认定负有责任的董事、监事、高级管理人员为不适当人选；（7）中国证监会及其派出机构认为有必要采取的其他措施。"},{"id":"law2-86","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"判断","q":"根据《证券公司风险控制指标管理办法》，证券公司应当建立动态的风险控制指标监控和资本补足机制，确保净资本等各项风险控制指标在每个季末都符合规定标准。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。证券公司建立动态的风险控制指标监控和资本补足机制，确保净资本等各项风险控制指标在任一时点都符合规定标准（并非\"每个季末\"）。"},{"id":"law2-87","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"判断","q":"根据《证券公司和证券投资基金管理公司合规管理办法》，证券公司的合规是指证券公司及其工作人员的经营管理和执业行为符合法律、法规、规章及规范性文件、行业规范和自律规则、公司内部规章制度，以及行业普遍遵守的职业道德和行为准则。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。根据《证券公司和证券投资基金管理公司合规管理办法》第二条的规定，证券公司的合规是指证券公司及其工作人员的经营管理和执业行为符合法律、法规、规章及规范性文件、行业规范和自律规则、公司内部规章制度以及行业普遍遵守的职业道德和行为准则。"},{"id":"law2-88","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"判断","q":"公开发行的证券，可以在证券交易所、国务院批准的其他全国性证券交易场所、按照国务院规定设立的区域性股权市场转让。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。非公开发行的证券（并非\"公开发行\"），可以在证券交易所、国务院批准的其他全国性证券交易场所、按照国务院规定设立的区域性股权市场转让。"},{"id":"law2-89","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"判断","q":"合规管理人员工作称职的，其年度薪酬收入总额原则上不低于所在机构同等条件（同岗位类型、同职级、同考核结果）人员的平均水平。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。合规负责人工作称职的，其年度薪酬收入总额在公司高级管理人员年度薪酬收入总额中的排名应当不低于中位数。其他合规管理人员工作称职的，其年度薪酬收入总额应当不低于公司同级别人员的平均水平。"},{"id":"law2-90","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"判断","q":"合伙人企业中，有限合伙企业只存在普通合伙人，该公司应该被注销。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。有限合伙企业仅剩普通合伙人的，转为普通合伙企业（并非注销）。"},{"id":"law2-91","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"判断","q":"经营证券承销与保荐、证券融资融券、证券做市交易、证券自营、其他证券业务之一的，注册资本最低限额为1 亿元。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。经营证券承销与保荐、证券融资融券、证券做市交易、证券自营、其他证券业务之一的，注册资本最低限额为人民币1 亿元。【温馨提示】证券公司经营证券经纪，证券投资咨询，与证券交易、证券投资活动有关的财务顾问业务的，注册资本最低限额为人民币5000 万元；经营证券承销与保荐、证券融资融券、证券做市交易、证券自营、其他证券业务中两项以上的，注册资本最低限额为人民币5 亿元。"},{"id":"law2-92","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"判断","q":"全面风险管理包含了：\"全员\"、对\"全部风险\"进行管理、开展风险管理的\"全部活动\"、对风险进行\"全程管理\"四部分含义。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。全面风险管理，是指证券公司董事会、经理层以及全体员工共同参与，对公司经营中的流动性风险、市场风险、信用风险、操作风险、声誉风险等各类风险，进行准确识别、审慎评估、动态监控、及时报告、妥善应对及全程管理。"},{"id":"law2-93","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"判断","q":"声誉风险不包括战略风险和法律风险。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。声誉风险是指由于证券经营机构行为或外部事件，及其工作人员违反廉洁规定、职业道德、业务规范、行规行约等相关行为，导致投资者、发行人、监管机构、自律组织、社会公众、媒体等对证券公司形成负面评价，从而损害其品牌价值，不利其正常经营，甚至影响到市场稳定和社会稳定的风险。声誉风险、战略风险、法律风险是并列的风险类型。声誉风险不包括战略风险和法律风险，它们之间是\"可能相互引发，但本质不同\"的关系。"},{"id":"law2-94","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"判断","q":"王某在 2020 年 3 月因证券违法行为受到过行政处罚，2022 年 9 月其参与内幕交易获利 30万元，其行为应予立案追诉。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。内幕交易获利或者避免损失数额在 25 万元以上，并且在 2 年内因证券、期货违法行为受过行政处罚的（2020 年3 月至 2022 年9 月已经超出 2 年的限制），应予立案追诉。"},{"id":"law2-95","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"判断","q":"为加强融资融券业务集中统一管理，证券公司分管融资融券业务的高级管理人员应该兼管风险监控部门。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。负责风险监控和业务稽核的部门和岗位应当独立于其他部门和岗位，分管融资融券业务的高级管理人员不得兼管风险监控部门和业务稽核部门（并非应该兼管）。"},{"id":"law2-96","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"判断","q":"我国的金融市场世界排名第一，保险市场也名列世界前茅，我国是金融强国。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。我国虽然已是金融大国，银行体量、外汇储备等指标位居世界第一，债市、股市规模位居世界第二，保险规模也名列前茅，但总体上大而不强。建设金融强国需要长期努力，久久为功（即还未成为金融强国）。"},{"id":"law2-97","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"判断","q":"向投资者销售或者提供\"荐股软件\"，并直接或者间接获取经济利益的，属于从事证券公司中间介绍业务，应当经中国证监会许可，取得相关业务资格。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。向投资者销售或者提供\"荐股软件\"，并直接或者间接获取经济利益的，属于从事证券投资咨询业务（并非中间介绍业务），应当经中国证监会许可，符合证券投资咨询业务条件。"},{"id":"law2-98","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"判断","q":"有限责任公司只能募集设立。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。有限责任公司只能采取发起设立的方式，由全体股东出资设立（并非募集设立）。募集设立只适用于股份有限公司。【温馨提示】公司的设立方式有两种，即发起设立和募集设立。发起设立，是指由发起人认购设立公司时应发行的全部股份而设立公司。发起设立适用于有限责任公司和股份有限公司。募集设立，是指由发起人认购设立公司时应发行股份的一部分，其余股份向特定对象募集或者向社会公开募集而设立公司。"},{"id":"law2-99","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"判断","q":"在上交所开展的股票质押式回购业务融入方违约处置完成后，证券公司向中国证券业协会、证券交易所、中国结算提交违约处置结果报告。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。违约处置完成后，证券公司向交易所、中国结算和中国证券投资者保护基金有限责任公司提交违约处置结果报告（并非\"中国证券业协会\"）。"},{"id":"law2-100","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"判断","q":"在营业场所内办理普通投资者转化为专业投资者应全程录音录像。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。在普通投资者申请转为专业投资者，向普通投资者销售高风险产品或者提供相关服务，经营机构主动调整投资者分类、产品或者服务分级、适当性匹配意见及向普通投资者履行信息告知义务这四种情形下，经营机构应：（1）通过营业网点向普通投资者进行告知、警示的，应当全过程录音或者录像；（2）通过互联网等非现场方式进行的，应当完善配套留痕安排，由普通投资者通过符合法律、行政法规要求的电子方式进行确认。"},{"id":"law2-101","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"判断","q":"在证券公司从事基金产品销售需要具有基金从业资格证。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。未经注册，任何单位或者个人不得从事基金销售业务。基金销售机构应当强化人员资质管理，确保基金销售人员具有基金从业资格。"},{"id":"law2-102","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"判断","q":"证券包销包括证券公司将发行人的证券按照协议全部购入的承销方式或者在承销期结束时将售后剩余证券全部自行购入的承销方式。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。证券包销，是指证券公司将发行人的证券按照协议全部购入，或者在承销期结束时将售后剩余证券全部自行购入的承销方式。"},{"id":"law2-103","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"判断","q":"证券公司代销证券期限最长不得超过60 日。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。证券的代销、包销期限最长不得超过90 日（并非\"60 日\"）。"},{"id":"law2-104","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"判断","q":"证券公司分类监管评价设定正常经营的证券公司基准分为90 分。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。证券公司分类评价首先设定正常经营的证券公司基准分为100 分（并非90 分）。"},{"id":"law2-105","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"判断","q":"证券公司及其境内分支机构可以经营未经批准的业务。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。根据《证券公司监督管理条例》第二十六条的规定，证券公司及其境内分支机构经营的业务应当经国务院证券监督管理机构批准，不得经营未经批准的业务。"},{"id":"law2-106","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"判断","q":"证券公司借助信息技术手段从事证券基金业务活动，应当在依法合规、有效防范风险的前提下进行。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。证券公司借助信息技术手段从事证券基金业务活动，应当保障充足的信息技术投入，在依法合规、有效防范风险的前提下，充分利用现代信息技术手段完善客户服务体系、改进业务运营模式、提升内部管理水平、增强合规风控能力，持续强化现代信息技术对证券基金业务活动的支撑作用。"},{"id":"law2-107","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"判断","q":"证券公司应当设专职部门或者岗位，处理客户投诉。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。根据《证券公司监督管理条例》第八十四条的规定，证券公司未按照规定建立并有效执行信息查询制度或未按照规定指定专门部门处理客户投诉的，责令改正，给予警告，没收违法所得，并处以违法所得1 倍以上 5 倍以下的罚款。"},{"id":"law2-108","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"判断","q":"证券投资咨询人员只需专科学历即可执业登记。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。证券投资咨询人员必须具备下列条件：（1）具有中华人民共和国国籍；（2）具有完全民事行为能力；（3）品行良好、正直诚实，具有良好的职业道德；（4）未受过刑事处罚或者与证券业务有关的严重行政处罚；（5）具有大学本科以上学历（并非专科）；（6）具有从事证券业务两年以上的经历；（7）具备从事业务所需的相应专业能力，符合相关从业条件；（8）中国证监会规定的其他条件。"},{"id":"law2-109","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"判断","q":"中国证监会、国务院其他主管部门等其他省部级以上单位作出的表彰、奖励应当记入中国证监会建立的全国统一的证券期货市场诚信档案数据库。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。中国证监会、国务院其他主管部门等其他省部级及以上单位和证券期货交易场所、证券期货市场行业协会、证券登记结算机构等全国性证券期货市场行业组织作出的表彰、奖励、评比，以及信用评级机构、诚信评估机构作出的信用评级、诚信评估，记入诚信档案。"},{"id":"law2-110","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"案例","q":"【资料】2021 年底，国内甲证券公司担任乙股份公司的保荐机构，甲证券公司按照协议全\n部购入乙公司将要发行的全部股票，然后分销给其他投资者。甲证券公司承担销售和价格的全\n部风险，甲证券公司本次承销活动非常顺利，在短时间内将所承销股票全部售出。此后，甲证\n券公司以自有资金在证券市场上对乙公司的股票进行买卖，并赚取了买卖差价。 \n请根据上述背景信息回答以下问题。\n\n【问题】甲证券公司在承销证券时，应对公开发行募集文件的（）进行核查。","options":["真实性","合理性","准确性","完整性"],"answer":"ACD","explain":"B 选项错误，A、C、D 选项正确，证券公司承销证券，应当对公开发行募集文件的真实性、准确性、完整性进行核查。发现有虚假记载、误导性陈述或者重大遗漏的，不得进行销售活动。已经销售的，必须立即停止销售活动，并采取纠正措施。故本题选ACD 选项。"},{"id":"law2-111","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"案例","q":"【资料】2021 年底，国内甲证券公司担任乙股份公司的保荐机构，甲证券公司按照协议全\n部购入乙公司将要发行的全部股票，然后分销给其他投资者。甲证券公司承担销售和价格的全\n部风险，甲证券公司本次承销活动非常顺利，在短时间内将所承销股票全部售出。此后，甲证\n券公司以自有资金在证券市场上对乙公司的股票进行买卖，并赚取了买卖差价。 \n请根据上述背景信息回答以下问题。\n\n【问题】甲证券公司以自有资金在证券市场上对乙公司的股票进行买卖，并赚取了买卖差价，证券公司在承销证券要求包括（）。","options":["注册资本不低于1 亿元人民币","注册资本不低于5 亿元人民币","净资本不低于2 亿元人民币","净资本不低于5000 万元人民币"],"answer":"BC","explain":"经营证券承销与保荐、证券融资融券、证券做市交易、证券自营、其他证券业务中两项以上的，注册资本最低限额为人民币5 亿元。经营证券承销与保荐、证券自营、证券资产管理、其他证券业务中两项及两项以上的，其净资本不得低于人民币2 亿元。B、C 选项符合题意，本题中甲证券公司以自有资金在证券市场上对乙公司的股票进行买卖，并赚取了买卖差价，属于证券自营业务，同时甲证券公司经营证券承销业务，属于经营证券承销和自营业务两种。故本题选BC 选项。"},{"id":"law2-112","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"案例","q":"【资料】唐某为 A 证券公司营业部总经理，负责营业部全面工作。孙某为 A 证券公司营业\n部客户经理，负责开发及维护客户。201x 年 3 月至 201x 年 8 月，唐某、孙某擅自运用客户沙\n某的证券账户进行交易，造成沙某证券账户亏损人民币 1080 万元，为 A 证券公司赚取交易手\n续费 121 万元。法院经审理认为，唐某、孙某未征得沙某同意，利用掌握的交易密码自行操作\n沙某证券账户，属于擅自运用客户资金的行为。唐某、孙某为 A 证券公司员工，其违法行为收\n取的手续费亦归A 证券公司所有，A 证券公司构成单位犯罪。\n\n【问题】A 证券公司违背受托义务，擅自运用客户资金，情节特别严重，其行为侵犯了国家的金融管理秩序和客户的合法权益，构成（）。","options":["非法吸收公众存款罪","集资诈骗罪","背信运用受托财产罪","利用未公开信息交易罪"],"answer":"C","explain":"C 选项正确，背信运用受托财产，是指商业银行、证券交易所、期货交易所、证券公司、期货经纪公司、保险公司或者其他金融机构，违背受托义务，擅自运用客户资金或者其他委托、信托的财产，情节严重的行为。故本题选C 选项。"},{"id":"law2-113","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"案例","q":"【资料】唐某为 A 证券公司营业部总经理，负责营业部全面工作。孙某为 A 证券公司营业\n部客户经理，负责开发及维护客户。201x 年 3 月至 201x 年 8 月，唐某、孙某擅自运用客户沙\n某的证券账户进行交易，造成沙某证券账户亏损人民币 1080 万元，为 A 证券公司赚取交易手\n续费 121 万元。法院经审理认为，唐某、孙某未征得沙某同意，利用掌握的交易密码自行操作\n沙某证券账户，属于擅自运用客户资金的行为。唐某、孙某为 A 证券公司员工，其违法行为收\n取的手续费亦归A 证券公司所有，A 证券公司构成单位犯罪。\n\n【问题】唐某作为营业部直接负责的主管人员，孙某作为该营业部其他责任人员，依法均应予惩处，下列刑罚中，说法正确的有（）。","options":["唐某，判处有期徒刑3 年 6 个月，并处罚金人民币 20 万元","孙某，判处有期徒刑3 年，并处罚金 5 万元","唐某，判处有期徒刑2 年 6 个月，并处罚金人民币 20 万元","孙某，判处有期徒刑3 年，并处罚金 3 万元"],"answer":"AB","explain":"商业银行、证券交易所、期货交易所、证券公司、期货经纪公司、保险公司或者其他金融机构，违背受托义务，擅自运用客户资金或者其他委托、信托的财产，情节特别严重的，对其直接负责的主管人员和其他直接责任人员处 3 年以上（含 3 年）10 年以下有期徒刑（C 选项错误），并处5 万元以上（含 5 万元）50 万元以下罚金（D 选项错误）。故本题选AB 选项。"},{"id":"law2-114","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"案例","q":"【资料】甲公司成立于 2010 年 9 月 10 日发起人李某认购公司股份 200 万股，为公司的小\n股东。2017 年 12 月 15 日公司向社会公开发行 A 股 10000 万股，2018 年 1 月 5 日公司股票在\n证券交易所上市交易。陈某于 2011 年 1 月 10 日至 2019 年 5 月 10 日期间任甲公司副董事长、\n董事，2019 年 5 月 11 日正式离职。截至 2019 年 6 月，陈某个人直接持有甲公司股票 3444000\n股。陈某实际控制的乙公司持有丙公司23.26%的股份，丙公司持有甲公司股票2091000 股。 \n根据该案例，回答以下问题。\n\n【问题】下列关于公司上市后李某在公司成立时认购的股份转让的说法，正确的是（）。","options":["2018 年1 月5 日后方可以转让","2019 年1 月5 日后方可以转让","2019 年12 月15 日后方可以转让","2018 年9 月10 日后方可以转让"],"answer":"B","explain":"B 选项正确，公司公开发行股份前已发行的股份，自公司股票在证券交易所上市交易之日起一年内不得转让。故本题选B 选项。"},{"id":"law2-115","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"案例","q":"【资料】甲公司成立于 2010 年 9 月 10 日发起人李某认购公司股份 200 万股，为公司的小\n股东。2017 年 12 月 15 日公司向社会公开发行 A 股 10000 万股，2018 年 1 月 5 日公司股票在\n证券交易所上市交易。陈某于 2011 年 1 月 10 日至 2019 年 5 月 10 日期间任甲公司副董事长、\n董事，2019 年 5 月 11 日正式离职。截至 2019 年 6 月，陈某个人直接持有甲公司股票 3444000\n股。陈某实际控制的乙公司持有丙公司23.26%的股份，丙公司持有甲公司股票2091000 股。 \n根据该案例，回答以下问题。\n\n【问题】根据《公司法》，下列有关股份有限公司董事在就任时确定的任职期间转让所持有的本公司股份的表述，正确的有（）。","options":["每年转让的股份不得超过其所持股份总数的5%","每年转让的股份不得超过其所持股份总数的25%","所持股份自公司上市之日起12 个月内不得转让","所持股份自公司上市之日起36 个月内不得转让"],"answer":"BC","explain":"发起人持有的本公司股份，自公司成立之日起一年内不得转让。公司公开发行股份前已发行的股份，自公司股票在证券交易所上市交易之日起一年内不得转让。公司董事、监事、高级管理人员应当向公司申报所持有的本公司的股份及其变动情况，在就任时确定的任职期间每年转让的股份不得超过其所持有本公司股份总数的25%（A 选项错误、B 选项正确）；所持本公司股份自公司股票上市交易之日起一年内不得转让（C 选项正确、D 选项错误）。上述人员离职后半年内，不得转让其所持有的本公司股份。公司章程可以对公司董事、监事、高级管理人员转让其所持有的本公司股份作出其他限制性规定。故本题选BC 选项。"},{"id":"law2-116","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"案例","q":"【资料】甲公司成立于 2010 年 9 月 10 日发起人李某认购公司股份 200 万股，为公司的小\n股东。2017 年 12 月 15 日公司向社会公开发行 A 股 10000 万股，2018 年 1 月 5 日公司股票在\n证券交易所上市交易。陈某于 2011 年 1 月 10 日至 2019 年 5 月 10 日期间任甲公司副董事长、\n董事，2019 年 5 月 11 日正式离职。截至 2019 年 6 月，陈某个人直接持有甲公司股票 3444000\n股。陈某实际控制的乙公司持有丙公司23.26%的股份，丙公司持有甲公司股票2091000 股。 \n根据该案例，回答以下问题。\n\n【问题】下列有关股份有限公司股份转让的规定，错误的是（）。","options":["记名股票，由股东以背书方式或者法律、行政法规规定的其他方式转让","无记名股票，由股东将该股票交付给受让人后即可","股份在法律、行政法规规定的限制转让期限内出质的，质权人在限制转让期限内行使质权","公司董事、监事、高级管理人员离职后半年内，不得转让其所持有的本公司股份"],"answer":"C","explain":"C 选项错误，股份在法律、行政法规规定的限制转让期限内出质的，质权人不得在限制转让期限内行使质权。故本题选C 选项。"},{"id":"law2-117","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"案例","q":"【资料】张某担任甲证券公司私募资产管理业务投资经理。2022 年 6 月 1 日，张某从甲证\n券公司离任，拟入职乙证券公司担任私募资产管理业务投资经理，从事投资业务。 \n请根据上述背景信息回答以下问题。\n\n【问题】张某作为私募资产管理业务的投资经理，应当具备（）。","options":["从事证券业务所需的专业能力","2 年以上投资管理、投资研究、投资咨询等相关业务经验","良好的诚信记录和职业操守","法律法规规定的其他条件"],"answer":"ACD","explain":"私募资产管理业务投资经理应当依法取得基金从业资格（A 选项正确），具有 3 年以上投资管理、投资研究、投资咨询等相关业务经验（B 选项错误，并非\"2 年以上\"），具备良好的诚信记录和职业操守（C 选项正确），且最近 3 年未被监管机构采取重大行政监管措施、行政处罚，符合法律法规规定的其他条件（D 选项正确）。故本题选ACD 选项。"},{"id":"law2-118","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"案例","q":"【资料】张某担任甲证券公司私募资产管理业务投资经理。2022 年 6 月 1 日，张某从甲证\n券公司离任，拟入职乙证券公司担任私募资产管理业务投资经理，从事投资业务。 \n请根据上述背景信息回答以下问题。\n\n【问题】关于张某的离任审查，下列说法正确的有（）。","options":["张某离任时，甲证券公司应当立即对其进行离任审查","张某在2022 年12 月 1 日方可在乙证券公司担任私募资产管理业务投资经理","甲证券公司应当自张某离任之日起3 个月内形成离任审查报告，以存档备查","甲证券公司应当自张某离任之日起 30 个工作日内将审查报告报送中国证监会相关派出机构和证券投资基金业协会"],"answer":"AB","explain":"私募资产管理业务投资经理离任的，证券期货经营机构应当立即对其进行离任审查（A 选项正确），并自离任之日起30 个工作日内将审查报告报送中国证监会相关派出机构（D 选项错误）。投资经理离任的，证券基金经营机构应当对其进行离任审查，并自离任之日起 2 个月内形成离任审查报告，以存档备查（C 选项错误）。证券基金经营机构不得聘用从其他证券基金经营机构离任未满 6 个月的投资经理，从事投资、研究、交易等相关业务（B 选项正确，2022 年 6 月1 日至 2022 年12 月1 日已满 6 个月）。故本题选AB 选项。"},{"id":"law2-119","subject":"law","source":"2026.09 LC终极押题 · 押题卷二","type":"案例","q":"【资料】张某担任甲证券公司私募资产管理业务投资经理。2022 年 6 月 1 日，张某从甲证\n券公司离任，拟入职乙证券公司担任私募资产管理业务投资经理，从事投资业务。 \n请根据上述背景信息回答以下问题。\n\n【问题】甲、乙证券公司应当针对私募资产管理业务的主要业务人员和相关管理人员建立收入递延支付机制，递延支付年限原则上不少于（）年。","options":["1","2","3","4"],"answer":"C","explain":"C 选项正确，证券期货经营机构应当针对私募资产管理业务的主要业务人员和相关管理人员建立收入递延支付机制，合理确定收入递延支付标准、递延支付年限和比例。递延支付年限原则上不少于3 年，递延支付的收入金额原则上不少于 40%。故本题选C 选项。"}]},{"id":"basics1","subject":"basics","name":"金融基础 · 押题卷一","stats":{"单选":30,"多选":50,"判断":30,"案例":10},"questions":[{"id":"basics1-0","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"单选","q":"1992年以前，我国对银行业、证券业、保险业、信托业实行集中统一监管的机构是（）。","options":["财政部","国务院金融稳定委员会","中国人民银行","国家发改委"],"answer":"C","explain":"C选项正确，1984年，中国人民银行开始专门行使中央银行职能，负责对银行业、证券业、保险业、信托业实行集中统一监管。故本题选C选项。"},{"id":"basics1-1","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"单选","q":"ⅠOSCO（国际证监会组织）不包含下列（）监管目标。","options":["保护投资者","保证市场公平透明","消除市场波动","减少系统性风险"],"answer":"C","explain":"国际证监会组织于1998年制定的《证券监管目标和原则》公布了证券监管的三个目标：一是保护投资者利益（A选项不符合题意）；二是保证证券市场的公平、效率和透明（B选项不符合题意）；三是降低系统性风险（D选项不符合题意）。故本题选C选项。"},{"id":"basics1-2","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"单选","q":"从基金财产中列支的费用不包括（）。","options":["基金托管人的托管费","基金的证券交易费用","基金转换费","基金管理人的管理费"],"answer":"C","explain":"在基金运作过程中涉及的费用可以分为两大类：一类是基金销售过程中发生的由基金投资者承担的费用，主要包括申购费（认购费）、赎回费及基金转换费等（C选项符合题意）。另一类是基金管理过程中发生的费用，主要包括基金管理费（D选项不符合题意）、基金托管费（A选项不符合题意）、销售服务费、证券交易费（B选项不符合题意）、持有人大会费用、会计师费和律师费、信息披露费等，这些费用由基金资产承担。故本题选C选项。"},{"id":"basics1-3","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"单选","q":"地方政府债券包括一般债券和（）。","options":["公益债权","专项债券","短期债券","中期债券"],"answer":"B","explain":"B选项正确，地方政府债券按资金用途和偿还资金来源不同，通常可以分为一般债券（普通债券）和专项债券（收入债券）。故本题选B选项。【温馨提示】（1）根据我国财政部《地方政府一般债券发行管理暂行办法》，地方政府一般债券是指省、自治区、直辖市政府（含经省级政府批准自办债券发行的计划单列市政府）为没有收益的公益性项目发行的、约定一定期限内主要以一般公共预算收入还本付息的政府债券。（2）地方政府专项债券是指省、自治区、直辖市政府（含经省级政府批准自办债券发行的计划单列市政府）为有一定收益的公益性项目发行的、约定一定期限内以公益性项目对应的政府性基金或专项收入还本付息的政府债券。"},{"id":"basics1-4","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"单选","q":"非累积优先股票的特点是股息分派以（）为界，当年结清。","options":["每个经营周期","每个营业年度","每个产业周期","每个生产周期"],"answer":"B","explain":"根据公司因当年可分配利润不足而未向优先股股东足额派发股息，差额部分是否累积到下一会计年度，可分为累积优先股和非累积优先股。非累积优先股则是指公司不足以支付优先股的全部股息时，对所欠股息部分，优先股股东不能要求公司在以后年度补发（B选项正确）。故本题选B选项。【温馨提示】累积优先股是指公司在某一时期所获盈利不足，导致当年可分配利润不足以支付优先股股息时，则将应付股息累积到次年或以后某一年盈利时，在普通股的股息发放之前，连同本年优先股股息一并发放。"},{"id":"basics1-5","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"单选","q":"根据《证券法》，持有上市公司（）以上有表决权股份的股东可以作为征集人代为出席股东大会，并代为行使提案权、表决权等股东权利。","options":["0.1%","1%","0.3%","0.5%"],"answer":"B","explain":"新《证券法》设置了\"投资者保护\"专章，建立上市公司股东权利代为行使征集制度，明确上市公司董事会、独立董事、持有1%（B选项正确）以上有表决权股份的股东或者投资者保护机构可以作为征集人代为出席股东大会，并代为行使提案权、表决权等股东权利。故本题选B选项。"},{"id":"basics1-6","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"单选","q":"根据商业银行的业务分类，下列不属于商业银行表外业务中担保承诺类业务的是（）。","options":["信用证","投资业务","保函","银行承兑汇票"],"answer":"B","explain":"担保承诺类业务，包括担保类、承诺类等按照约定承担偿还责任的业务。（1）担保类业务是指商业银行对第三方承担偿还责任的业务，包括但不限于银行承兑汇票（D选项不符合题意）、保函（C选项不符合题意）、信用证（A选项不符合题意）、信用风险仍在银行的销售与购买协议等。（2）承诺类业务是指商业银行在未来某一日期按照事先约定的条件向客户提供约定的信用业务，包括但不限于贷款承诺等。B选项符合题意，投资业务属于商业银行的资产业务。故本题选B选项。"},{"id":"basics1-7","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"单选","q":"国际债券以（）作为计量货币。","options":["外国货币","本国货币或外国货币","本国货币","通用货币"],"answer":"D","explain":"国际债券在国际市场上发行，因此，其计价货币往往是国际通用货币（D选项正确），一般以美元、英镑、欧元、日元和瑞士法郎为主。故本题选D选项。"},{"id":"basics1-8","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"单选","q":"基金一般都是按照（）的时间间隔对基金资产进行估值。","options":["不确定","固定","管理人随时确定","托管人随时确定"],"answer":"B","explain":"B选项正确，基金一般都按照固定的时间间隔对基金资产进行估值，通常相关法规会规定一个最小的估值频率。故本题选B选项。"},{"id":"basics1-9","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"单选","q":"交易双方在场外市场上通过协商，按约定价格在约定的未来日期买卖某种标的金融资产的合约称为（）。","options":["互换合约","远期合约","期货合约","期权合约"],"answer":"B","explain":"A选项错误，金融互换是指两个或两个以上的当事人按共同商定的条件，在约定的时间内定期交换现金流的金融交易。B选项正确，金融远期合约是指交易双方在场外市场上通过协商，按约定价格（称为\"远期价格\"）在约定的未来日期（交割日）买卖某种标的金融资产（或金融变量）的合约。C选项错误，金融期货是指交易双方在集中的交易场所以公开竞价方式进行的标准化金融期货合约的交易。D选项错误，金融期权是指合约买方向卖方支付一定费用（称为期权费或期权价格），在约定日期内（或约定日期）享有按事先确定的价格向合约卖方买卖某种金融工具的权利的契约。故本题选B选项。"},{"id":"basics1-10","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"单选","q":"买卖双方签订了一份合约，该合约规定买方在交付了一笔费用后，即取得在合约规定的到期日或到期日以前按协定价买入或卖出一定数量相关股票的权利。这种合约称为（）合约。","options":["货币期权","互换期权","利率期权","股票期权"],"answer":"D","explain":"D选项正确，单只股票期权（简称\"股票期权\"）指买方在交付了期权费后，即取得在合约规定的到期日或到期日以前按协定价格买入或卖出一定数量相关股票的权利。故本题选D选项。"},{"id":"basics1-11","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"单选","q":"某投资者投资项目，该项目五年后，将一次性获得一万元收入假定投资者希望的年利率为5%，那么按单利计算，投资的现值为（）。","options":["8000元","7500元","10000元","12500元"],"answer":"A","explain":"A选项正确，PV=FV/（1+i×n）=10000/（1+5%×5）=8000元。故本题选A选项。"},{"id":"basics1-12","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"单选","q":"某外商独资私募证券基金管理机构拟在中国境内开展私募证券基金管理业务，其需要满足的条件不包括（）。","options":["该机构为在中国境外设立的公司","该机构的境外股东为所在国家金融监管当局（已与中国证监会签订证券监管合作谅解备忘录）批准的金融机构","应当在中国证券投资基金业协会登记为私募证券基金管理人","该机构及其境外股东最近3年没有受到监管机构和司法机构的重大处罚"],"answer":"A","explain":"经中国证监会同意，外商独资和合资私募证券基金管理机构在中国境内开展私募证券基金管理业务，应当在中国证券投资基金业协会登记为私募证券基金管理人（C选项不符合题意），并应当符合以下条件：（1）该私募证券基金管理机构为在中国境内设立的公司（A选项符合题意）；（2）该私募证券基金管理机构的境外股东为所在国家或者地区金融监管当局批准或者许可的金融机构，且境外股东所在国家或者地区的证券监管机构已与中国证监会或者中国证监会认可的其他机构签订证券监管合作谅解备忘录（B选项不符合题意）；（3）该私募证券基金管理机构及其境外股东最近3年没有受到监管机构和司法机构的重大处罚（D选项不符合题意）；（4）有境外实际控制人的私募证券基金管理机构，该境外实际控制人也应当符合上述第（2）和第（3）项条件。故本题选A选项。"},{"id":"basics1-13","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"单选","q":"目前，证券业传统业务面临激烈的（）竞争，金融业对外开放和金融混业经营趋势进一步加剧了证券行业竞争。","options":["全球化","异质化","多样化","同质化"],"answer":"D","explain":"D选项正确，目前，证券业传统业务面临激烈的同质化竞争，金融业对外开放和金融混业经营趋势进一步加剧了证券行业竞争。故本题选D选项。"},{"id":"basics1-14","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"单选","q":"双方约定在未来某一时刻按照现在确定的价格买卖标的证券的行为称为（）。","options":["远期交易","现券交易","回购交易","即期交易"],"answer":"A","explain":"A选项符合题意，远期交易是双方约定在未来某一时刻（或时间段内）按照现在确定的价格买卖标的债券的行为。B、D选项不符合题意，现券交易，也称为债券的即期交易，是指证券买卖双方在成交后就办理交收手续，买入者付出资金并得到证券，卖出者交付证券并得到资金，也就是所谓二级市场的债券交易。C选项不符合题意，回购交易，是指债券买卖双方（资金融入方和资金融出方）在成交的同时，约定于未来某一时间以某一约定价格双方再进行反向交易的行为。故本题选A选项。"},{"id":"basics1-15","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"单选","q":"投资者在证券交易所买卖证券，是通过委托（）来进行的。","options":["证券经纪商","中国证券业协会","中国证券登记结算有限责任公司上海分公司或深圳分公司","上海证券交易所或深圳证券交易所"],"answer":"A","explain":"A选项正确，投资者在证券交易所买卖证券，是通过委托证券经纪商来进行的，此时，投资者是证券经纪商的客户。客户在办理委托买卖证券时，需要向证券经纪商下达委托指令。故本题选A选项。"},{"id":"basics1-16","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"单选","q":"我国的证券登记结算制度实行证券（）。","options":["代持制","实名制","代理制","经纪制"],"answer":"B","explain":"B选项正确，我国的证券登记结算制度实行证券实名制。投资者开立证券账户应当向证券登记结算机构提出申请，投资者申请开立证券账户应当保证其提交的开户资料真实、准确、完整，投资者不得将本人的证券账户提供给他人使用。故本题选B选项。"},{"id":"basics1-17","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"单选","q":"下列不属于北交所上市公司向特定对象发行股票的禁止情形的是（）。","options":["上市公司擅自改变募集资金用途，未作纠正也未经股东大会认可","上市公司实际控制人因涉嫌侵占财产正被司法机关立案侦查，尚未有明确结论意见","上市公司最近半年内存在重大信息披露违法行为","上市公司实际控制人被列入失信被执行人名单但目前情形已经消除"],"answer":"D","explain":"北交所上市公司存在下列情形之一的，不得向特定对象发行股票：（1）上市公司或其控股股东、实际控制人最近三年内存在贪污、贿赂、侵占财产、挪用财产或者破坏社会主义市场经济秩序的刑事犯罪，存在欺诈发行、重大信息披露违法（C选项不符合题意）或者其他涉及国家安全、公共安全、生态安全、生产安全、公众健康安全等领域的重大违法行为；（2）上市公司或其控股股东、实际控制人，现任董事、监事、高级管理人员最近一年内受到中国证监会行政处罚、北交所公开谴责；或因涉嫌犯罪正被司法机关立案侦查或者涉嫌违法违规正被中国证监会立案调查，尚未有明确结论意见（B选项不符合题意）；（3）擅自改变募集资金用途，未作纠正或者未经股东大会认可（A选项不符合题意）；（4）上市公司或其控股股东、实际控制人被列入失信被执行人名单且情形尚未消除（D选项符合题意）；（5）上市公司利益严重受损的其他情形。故本题选D选项。"},{"id":"basics1-18","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"单选","q":"下列不属于金融机构类投资者的是（）。","options":["银行业金融机构","保险经营机构","证券经营机构","全国社会保障基金"],"answer":"D","explain":"金融机构类投资者，是指进行证券投资、从事金融资产交易的金融机构，包括证券经营机构（C选项不符合题意）、银行业金融机构（A 选项不符合题意）、保险经营机构（B选项不符合题意）、基金公司以及其他金融机构。D选项符合题意，属于基金类投资者。故本题选D选项。"},{"id":"basics1-19","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"单选","q":"下列不属于其他存款吸收机构的是（）。","options":["信用合作社","投资银行","抵押贷款银行","证券交易商"],"answer":"D","explain":"其他存款吸收机构包括储蓄银行、开发银行、信用合作社（A选项不符合题意）、投资银行（B选项不符合题意）、抵押贷款银行（C选项不符合题意）以及建房互助协会、吸收存款的小额贷款机构。其他金融公司主要是那些从事金融中介或者与金融中介关系紧密的辅助性金融业务，但没有被列入存款吸收机构的公司，包括保险公司、养老基金、证券交易商（D选项符合题意）、投资基金、财务公司、租赁公司以及金融辅助经济机构等。故本题选D选项。"},{"id":"basics1-20","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"单选","q":"下列关于ABS产品的说法，错误的是（）。","options":["狭义的ABS主要以某一类同质资产为标的资产","ABS产品可以分为狭义的ABS和担保债务凭证 CDO","担保债务凭证的基础资产是一系列的债务工具","期限在一年以下的资产支持商业票据属于担保债务凭证CDO的基础资产"],"answer":"D","explain":"ABS产品的分类更为繁杂，大致可以分为狭义的ABS和担保债务凭证（CDO）两类（B选项正确）。（1）狭义的ABS主要是基于某一类同质资产，如汽车贷款、信用卡贷款、学生贷款、设备租赁等为标的资产的证券化产品（A选项正确），也有期限在1年以下的资产支持商业票据（D选项错误）。（2）担保债务凭证对应的基础资产则是一系列的债务工具（C选项正确），如高息债券、新兴市场企业债或国家债券、银行贷款，甚至传统的MBS等证券化产品。故本题选D选项。"},{"id":"basics1-21","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"单选","q":"下列关于地方政府债券的说法，错误的是（）。","options":["由地方政府发行并负责偿还的债券","简称地方债券","发行主体是地方政府","筹集资金不能用于弥补地方财政资金的不足"],"answer":"D","explain":"地方政府债券简称\"地方债券\"，也可以称地方公债或地方债，是地方政府根据本地区经济发展和资金需求状况，以承担还本付息责任为前提，向社会筹集资金的债务凭证。筹集的资金一般用于弥补地方财政资金的不足（D选项错误），或者兴建地方大型项目。故本题选D选项。"},{"id":"basics1-22","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"单选","q":"下列关于风险与金融产品的说法，错误的是（）。","options":["金融产品具有风险性","\"无风险收益率\"仅是理论上的一种设定","金融产品定价仅考虑收益","风险溢价是对投资者承担风险的补偿"],"answer":"C","explain":"任何金融产品都具有风险性（A选项正确）。作为市场基准的所谓的\"无风险收益率\"仅仅是理论上的一种设定（B选项正确）。任何产品同时也具有收益性，构成对投资者承担风险的补偿，这种收益通常称为风险溢价（D选项正确）。任何金融产品都服从这种风险和收益的二元结构。这是金融产品的重要特征之一。C选项错误，金融产品定价，需要综合考虑收益、风险、流动性等因素，不是仅考虑收益。故本题选C选项。"},{"id":"basics1-23","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"单选","q":"下列关于金融市场功能的说法，错误的是（）。","options":["金融市场的首要功能是风险管理","金融市场提供流动性指其为金融资产交易变现或赎回提供渠道和机制","金融市场中供求双方的相互作用决定了交易资产的价格","在金融交易中，花费一定的时间来定位交易对手一般视为隐性成本"],"answer":"A","explain":"A选项错误，金融市场的首要功能是资金融通（并非风险管理）。B选项正确，金融市场的一个重要功能就是提供流动性，即金融资产交易变现或赎回的渠道和机制。C选项正确，金融市场中供求双方的相互作用决定了交易资产的价格，价格反过来又为潜在的市场参与者提供了信号，引导资金在不同的金融资产之间进行配置，达成供需平衡，这也称为价格发现过程。D选项正确，搜寻成本有显性成本与隐性成本，比如花钱做广告寻求金融资产的买方与卖方为显性成本，而花费一定的时间来定位交易对手则为隐性成本。故本题选A选项。"},{"id":"basics1-24","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"单选","q":"下列关于融资融券交易的说法，错误的是（）。","options":["融资交易是一种杠杆交易，能放大投资者的盈利或者亏损，参与融资融券交易要求投资者有较强的证券研究能力和风险承受能力","融资交易是指投资者向证券公司缴纳一定的保证金，融入一定数量的资金买入股票的交易行为","融资融券交易又被称为信用交易，分为融资交易和融券交易","融资交易中投资者向证券公司提交的保证金必须是现金"],"answer":"D","explain":"A选项正确，融资交易是一种杠杆交易，能放大投资者的盈利或者亏损，参与融资融券交易要求投资者有较强的证券研究能力和风险承受能力。B选项正确，融资交易是指投资者向证券公司缴纳一定的保证金，融入一定数量的资金买入股票的交易行为。C选项正确，融资融券交易，又称为信用交易，分为融资交易和融券交易。D选项错误，投资者向证券公司提交的保证金可以是现金或者可充抵保证金的证券。故本题选D选项。"},{"id":"basics1-25","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"单选","q":"下列关于申请募集基金时基金招募说明书和投资者适当性管理制度的说法，错误的是（）。","options":["有明确的对基金投资者的定位、识别和评估的方法","有符合投资者特征的投资者适当性管理制度","招募说明书要真实、准确、完整地披露投资者作出投资决策所需要的重要信息","招募说明书语言要详尽，不需要简明，但要易懂、实用，符合投资者的理解能力"],"answer":"D","explain":"招募说明书真实、准确、完整地披露了投资者作出投资决策所需的重要信息（C选项正确），不存在虚假记载、误导性陈述或者重大遗漏，语言简明、易懂、实用，符合投资者的理解能力（D选项错误）；有符合基金特征的投资者适当性管理制度（B选项正确），有明确的投资者定位、识别和评估等落实投资者适当性安排的方法（A选项正确），有清晰的风险警示内容等。故本题选D选项。"},{"id":"basics1-26","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"单选","q":"下列关于我国基金资产估值原则的说法错误的是（）。","options":["有充分证据表明估值日或最近交易日的报价不能真实反映公允价值的，应对报价进行调整，确定公允价值","估值日无报价且最近交易日后未发生影响公允价值计量的重大事件的，应采用最近交易日的报价确定公允价值","采用估值技术确定公允价值时，应优先使用不可观察输入值","对不存在活跃市场的投资品种，应采取在当前情况下适用并且可利用数据和其他信息支持的估值技术确定公允价值"],"answer":"C","explain":"C选项错误，采用估值技术确定公允价值时，应优先使用可观察输入值，只有在无法取得相关资产或负债可观察输入值或取得不切实可行的情况下，才可以使用不可观察输入值。故本题选C选项。"},{"id":"basics1-27","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"单选","q":"下列关于证券公司的说法，错误的是（）。","options":["世界各国对证券公司的划分和称呼不尽相同，美国的通俗称谓是\"投资银行\"，英国则称为\"商人银行\"","证券公司是证券市场证券和资金的主要提供者","在我国，设立证券公司必须经国务院证券监督管理机构审查批准","证券公司可以通过资产管理方式，为投资者提供证券及其他金融产品的投资管理服务"],"answer":"B","explain":"B选项错误，证券公司是证券市场的主要中介机构，是证券市场投融资服务的提供者，为证券发行人和投资者（证券和资金的主要提供者）提供专业化的中介服务。A选项正确，世界各国对证券公司的划分和称呼不尽相同，美国的通俗称谓是\"投资银行\"，英国则称为\"商人银行\"。C选项正确，在我国，设立证券公司必须经国务院证券监督管理机构审查批准。D选项正确，证券公司通过资产管理方式，为投资者提供证券及其他金融产品的投资管理服务等。故本题选B选项。"},{"id":"basics1-28","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"单选","q":"下列关于证券公司声誉风险管理的说法，正确的是（）。","options":["公司有董事会秘书，可不设新闻发言人","公司声誉风险只能由风险管理部门牵头","公司办公室主任不能担任新闻发言人","公司可有多名新闻发言人，但其中至少一人为高管"],"answer":"D","explain":"D选项正确，《证券公司声誉风险管理指引》要求证券公司应设置新闻发言人。新闻发言人可由一人或多人担任，其中至少一名为公司高级管理人员。故本题选D选项。"},{"id":"basics1-29","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"单选","q":"行权价格可以取基础资产在一段时间内的平均值的期权，称之为（）。","options":["平均期权","任选期权","障碍期权","百慕大期权"],"answer":"A","explain":"奇异型期权通常在期权性质、基础资产以及期权有效期等内容上与标准化的交易所交易期权存在差异，种类庞杂，较为流行的就有数十种之多。例如，有的期权合约具有两种基础资产，可以择优执行其中一种（任选期权）（B选项错误）；有的可以在规定的一系列时点行权（百慕大期权）（D选项错误）；有的对行权设置一定条件（障碍期权）（C选项错误）；有的行权价格可以取基础资产在一段时间内的平均值（平均期权）（A选项正确）等。故本题选A选项。"},{"id":"basics1-30","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"在公募REITs的运营管理方面，（）应当主动履行基础设施项目运营管理职责，通过设立专门子公司或者委托运营管理机构负责基础设施项目运营管理。","options":["基金管理人","项目公司","财务顾问","原始权益人"],"answer":"A","explain":"A选项正确，基金管理人应当主动履行基础设施项目运营管理职责，通过设立专门子公司或者委托运营管理机构负责基础设施项目运营管理。故本题选A选项。"},{"id":"basics1-31","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"在基金募集期间募集的资金应当（），在基金募集行为结束前，任何人不得动用。","options":["存入专门账户","存入管理人账户","存入托管人账户","存入第三方账户"],"answer":"A","explain":"A选项正确，在基金募集期间募集的资金应当存入专门账户，在基金募集行为结束前，任何人不得动用。故本题选A选项。"},{"id":"basics1-32","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"在债券评级中，证券评级机构应当在受评证券存续期内每年至少出具一次（）。","options":["评级等级跟踪报告","实地调研跟踪报告","定期跟踪评级报告","临时跟踪评级报告"],"answer":"C","explain":"证券评级机构应当在受评证券存续期内每年至少出具一次定期跟踪评级报告（C选项正确），且在受评级证券或其发行人年度报告披露后3 个月内披露。故本题选C选项。"},{"id":"basics1-33","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"在长期实践探索的基础上，对证券公司实施有效监管的基础性制度已经基本形成。其中，基础性制度不包括（）。","options":["证券公司业务许可制度","以风险资本为核心的风险监控和预警制度","客户交易结算资金第三方存管制度","信息报送和披露制度"],"answer":"B","explain":"证券公司的监管制度：（1）业务许可制度（A选项不符合题意）；（2）以诚信与资质为标准的市场准入制度；（3）分类监管制度；（4）以净资本和流动性为核心的风险监控和预警制度（B选项符合题意）；（5）合规管理制度；（6）客户交易结算资金第三方存管制度（C选项不符合题意）；（7）信息报送与披露制度（D选项不符合题意）。故本题选B选项。"},{"id":"basics1-34","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"证券公司对于风险超限额的处置，应当由（）负责组织落实，并对超限额处置的实际效果定期进行返回检验。","options":["高级管理人员","董事会","监事会","风险管理部门"],"answer":"D","explain":"D选项正确，对于超限额的处置，应由风险管理部门负责组织落实，并对超限额处置的实际效果要定期进行返回检验。故本题选D选项。【温馨提示】风险管理部门发现风险指标超限额的，应当与业务部门、分支机构、子公司及时沟通，了解情况和原因，督促业务部门、分支机构、子公司采取措施在规定时间内结合业务特点，制定超限额后的风险缓释措施，并及时向首席风险官报告。对因违规超限额造成的损失进行责任认定；对超限额处置的实际效果要定期进行返回检验。"},{"id":"basics1-35","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"证券公司为客户办理证券和资金的清算与交收的时间为（）。","options":["每个工作日结束后","每个自然日结束后","每个指定日结束后","每个交易日结束后"],"answer":"D","explain":"每日交易结束后（D选项正确），证券公司要为客户办理证券和资金的清算与交收。目前，我国证券市场采用的是法人结算模式。法人结算是指由证券公司以法人名义在证券登记结算机构开立证券交收账户和资金交收账户，其接受客户委托代理的证券交易的清算交收均通过此账户办理。故本题选D选项。"},{"id":"basics1-36","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"直接融资的特点之一是（）。","options":["融资的主动权主要掌握在金融中介机构手中","融资者有相对较强的自主性","融资信誉的差异性相对较小","融资的相对集中性"],"answer":"B","explain":"直接融资的特点有：直接性、分散性（D选项错误）、融资的信誉有较大的差异性（C选项错误）、部分融资的不可逆性、融资者有相对较强的自主性（B选项正确）。A选项错误，属于间接融资的特点。故本题选B选项。"},{"id":"basics1-37","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"主板市场对发行人的稳定性、股本大小、盈利水平、最低市值等方面的要求标准较高，上市企业多为（）。","options":["创业型企业","大型成熟企业","创新型企业","成长型企业"],"answer":"B","explain":"主板市场对发行人的营业期限、股本大小、盈利水平、最低市值等方面的要求标准较高，上市企业多为大型成熟企业（B选项正确），具有较大的资本规模以及稳定的盈利能力。故本题选B选项。"},{"id":"basics1-38","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"主要的商品期货种类不包括（）。","options":["能源化工期货","外汇期货","金属期货","农产品期货"],"answer":"B","explain":"主要的商品期货种类有：农产品期货（D选项不符合题意）、金属期货（C选项不符合题意）、能源化工期货（A选项不符合题意）。B选项符合题意，外汇期货属于金融期货的品种。故本题选B选项。"},{"id":"basics1-39","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"资金需求者与资金初始供应者之间不发生直接信贷关系，而是由金融中介机构起桥梁作用，二者只与金融机构发生债权债务关系。这反映了间接融资的（）特点。","options":["资金获得的间接性","融资的相对集中性","融资信誉的较大差异性","可逆性"],"answer":"A","explain":"间接融资的特点：资金获得的间接性（A选项正确），即资金需求者与资金初始供应者之间不发生直接信贷关系，而是由金融中介机构起桥梁作用，二者只与金融机构发生债权债务关系。故本题选A选项。【温馨提示】间接融资的特点：（1）资金获得的间接性，即资金需求者与资金初始供应者之间不发生直接信贷关系，而是由金融中介机构起桥梁作用，二者只与金融机构发生债权债务关系。（2）融资的相对集中性。间接融资通过金融机构（主要是商业银行）进行，但这种中介，在多数情况下（除委托贷款外）并不是对某一资金供应者与某一资金需求者之间一对一的对应性中介，而是一方面面对资金供应者群体，另一方面面对资金需求者群体的综合性中介。（3）融资信誉的差异性相对较小。间接融资相对集中于银行或非银行金融机构，由于国家对金融机构的管理一般都较为严格，银行自身的经营也多采取稳健方针，加上一些国家实行了存款保险制度，相对于直接融资来说，间接融资的信誉程度高，风险也相对较小，融资的稳定性较强。（4）全部具有可逆性（可返还性）。通过金融中介的融资均属借贷融资，到期必须归还并支付利息。（5）融资的主动权主要掌握在金融中介机构手中。由于间接融资的资金集中于商业银行等金融机构，资金贷给谁不贷给谁，并非由资金的初始供应者决定而是由商业银行等金融中介机构决定。"},{"id":"basics1-40","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"按发行流通性质划分，金融市场可分为（）。","options":["交易所市场","场外交易市场","发行市场","流通市场"],"answer":"CD","explain":"按发行流通性质分为一级市场和二级市场：（1）一级市场是新金融资产的发行市场（C选项符合题意），例如股票和债券的发行市场。（2）二级市场是已发行金融资产的流通市场（D选项符合题意），金融资产的持有者可以在这个市场中将持有的证券出售，以达到变现的目的。A、B选项不符合题意，按组织方式分为交易所市场和场外交易市场。故本题选CD选项。"},{"id":"basics1-41","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"按照市场功能不同，资本市场可分为（）。","options":["场外市场","发行市场","场内市场","交易市场"],"answer":"BD","explain":"A、C选项错误，按照资本市场的组织形式和交易活动是否集中统一，可以将资本市场划分为场内交易市场和场外交易市场。B、D选项正确，按照市场功能的不同，可以将资本市场划分为发行市场和交易市场。故本题选BD选项。【温馨提示】（1）按照交易产品品种的不同，可以将资本市场划分为股票市场、债券市场、衍生品证券市场和基金市场。（2）按照所服务和覆盖的企业所在地范围的不同，可以将资本市场划分为全球性市场、全国性市场、区域性市场等类型。（3）按照发行和募集方式的不同，可以将资本市场划分为公募市场和私募市场。"},{"id":"basics1-42","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"风险管理的流程包括（）。","options":["风险的识别","风险的衡量","风险的应对","风险的监测、预警与报告"],"answer":"ABCD","explain":"一般情况下，风险管理的流程主要包括：风险的识别（A选项正确）、风险的衡量（B选项正确）、风险的监测、预警与报告（D选项正确）以及风险的应对（C选项正确）。故本题选ABCD选项。"},{"id":"basics1-43","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"风险管理方法包括（）。","options":["风险控制","风险规避","风险分散","风险补偿"],"answer":"ABCD","explain":"金融机构面临风险时可以选择采用的应对方法，主要包括风险规避（B选项符合题意）、风险控制（A选项符合题意）、风险分散（C选项符合题意）、风险对冲、风险转移、风险补偿（D选项符合题意）与准备金。故本题选ABCD选项。"},{"id":"basics1-44","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"根据《证券法》，下列属于国务院证券监督管理机构有权采取的措施包括（）。","options":["查阅、复制与被调查事件有关的财产权登记、通讯记录等文件和资料","进入涉嫌违法行为发生场所调查取证","询问被调查事件当事人、涉嫌违法从业的所有人","对证券发行人、证券公司、证券服务机构、证券交易所、证券登记结算机构进行现场检查"],"answer":"ABCD","explain":"国务院证券监督管理机构根据《证券法》依法履行职责，有权采取下列措施：（1）对证券发行人、证券公司、证券服务机构、证券交易场所、证券登记结算机构进行现场检查（D选项正确）。（2）进入涉嫌违法行为发生场所调查取证（B选项正确）。（3）询问当事人和与被调查事件有关的单位和个人（C选项正确），要求其对与被调查事件有关的事项作出说明；或者要求其按照指定的方式报送与被调查事件有关的文件和资料。（4）查阅、复制与被调查事件有关的财产权登记、通讯记录等文件和资料（A选项正确）。故本题选ABCD选项。【温馨提示】国务院证券监督管理机构根据《证券法》依法履行职责，有权采取的措施还包括：（1）查阅、复制当事人和与被调查事件有关的单位和个人的证券交易记录、登记过户记录、财务会计资料及其他相关文件和资料；对可能被转移、隐匿或者毁损的文件和资料，可以予以封存、扣押。（2）查询当事人和与被调查事件有关的单位和个人的资金账户、证券账户、银行账户以及其他具有支付、托管、结算等功能的账户信息，可以对有关文件和资料进行复制。对有证据证明已经或者可能转移或者隐匿违法资金、证券等涉案财产或者隐匿、伪造、毁损重要证据的，经国务院证券监督管理机构主要负责人或者其授权的其他负责人批准，可以冻结或者查封，期限为6个月；因特殊原因需要延长的，每次延长期限不得超过 3个月，冻结、查封期限最长不得超过2年。（3）在调查操纵证券市场、内幕交易等重大证券违法行为时，经国务院证券监督管理机构主要负责人或者其授权的其他负责人批准，可以限制被调查事件当事人的证券买卖，但限制的期限不得超过3个月；案情复杂的，可以延长 3 个月。（4）通知出境入境管理机关依法阻止涉嫌违法人员、涉嫌违法单位的主管人员和其他直接责任人员出境。"},{"id":"basics1-45","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"根据《证券法》的规定，下列关于我国证券结算分级结算制度和结算参与人制度的说法，正确的有（）。","options":["证券公司是与证券登记结算机构进行证券和资金清算交收的主体，并承担相应的清算交收责任","证券登记结算机构根据清算交收结果为证券公司办理登记过户手续","在分级结算制度下，只有获得证券登记结算机构结算参与人资格的证券经营机构才能直接进入登记结算系统参与结算业务","通过对结算参与人实行准入制度，制订风险控制和财务指标要求，证券登记结算机构可以有效控制结算风险，维护结算系统安全"],"answer":"ACD","explain":"《证券法》明确规定，证券公司是与证券登记结算机构进行证券和资金清算交收的主体，并承担相应的清算交收责任（A选项正确）；证券登记结算机构根据清算交收结果为投资者办理登记过户手续（B选项错误）。在分级结算制度下，只有获得证券登记结算机构结算参与人资格的证券经营机构才能直接进入登记结算系统参与结算业务（C选项正确）。通过对结算参与人实行准入制度，制定风险控制和财务指标要求，证券登记结算机构可以有效控制结算风险，维护结算系统安全（D选项正确）。故本题选ACD选项。"},{"id":"basics1-46","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"根据科创板的定位，下列属于其服务范围的领域或行业有（）。","options":["新一代信息技术领域","生物医药领域","主要从事金融业务的行业","新能源领域"],"answer":"ABD","explain":"申报科创板发行上市的发行人，应当属于下列行业领域：一是新一代信息技术领域（A选项正确）；二是高端装备领域；三是新材料领域；四是新能源领域（D选项正确）；五是节能环保领域；六是生物医药领域（B选项正确）；七是符合科创板定位的其他领域。限制金融科技、模式创新企业在科创板上市，禁止房地产和主要从事金融、投资类业务的企业在科创板上市（C选项错误）。故本题选ABD选项。"},{"id":"basics1-47","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"根据中国证监会的规定进行注册备案的基金服务机构有（）。","options":["从事基金销售的机构","从事公开基金评价的服务机构","从事公开基金投资顾问业务的机构","从事基金销售支付的机构"],"answer":"ABCD","explain":"基金市场上还有许多面向基金提供各类服务的其他服务机构。这些机构主要包括基金销售机构（A选项正确）、基金销售支付机构（D选项正确）、基金份额登记机构、基金估值核算机构、基金投资顾问机构（C选项正确）、基金评价机构（B选项正确）、律师事务所、会计师事务所、信息技术系统服务机构等。从事基金服务业务的机构，应当按照国务院证券监督管理机构的规定进行注册或者备案。故本题选ABCD选项。"},{"id":"basics1-48","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"股票价格指数被视为股市行情的指示器和经济景气变化的晴雨表。下列属于股票价格指数主要功能的有（）。","options":["作为指数衍生产品和其他金融创新的基础","作为投资业绩评价的标尺，提供一个股市投资的基准回报","由于股票价格短期内受到市场投资者情绪的带动而发生剧烈波动，因此股票价格指数准确反映了市场参与投资者情绪的变动方向和变动程度","为投资者和分析家研究、判断股市动态提供信息，便于对股票市场大势走向作出分析"],"answer":"ABD","explain":"股票价格指数的功能有：（1）综合反映一定时期内某一证券市场上股票价格的变动方向和变动程度（C选项错误）。（2）为投资者和分析家研究、判断股市动态提供信息，便于对股票市场大势走向作出分析（D选项正确）。（3）作为投资业绩评价的标尺，提供一个股市投资的基准回报（B选项正确）。（4）作为指数衍生产品和其他金融创新的基础（A选项正确）。故本题选ABD选项。"},{"id":"basics1-49","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"股票价格指数的编制步骤包括（）。","options":["选择样本股","选定基期并以一定方法计算基期平均股价或市值","计算计算期平均股价或市值且不可作任何修正","指数化"],"answer":"ABD","explain":"股票价格指数的编制步骤：第一步，选择样本股（A选项正确）。第二步，选定某基期，并以一定方法计算基期平均股价或市值（B选项正确）。第三步，计算计算期平均股价或市值，并作必要的修正（C选项错误）。第四步，指数化（D选项正确）。故本题选ABD选项。"},{"id":"basics1-50","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"关于地方政府一般债券的说法，正确的有（）。","options":["一般债券采用记账式固定利率付息形式","实行自发自还","偿债资金为政府性基金","债券资金收入列入一般公共预算管理"],"answer":"ABD","explain":"一般债券采用记账式固定利率付息形式（A选项正确），地方政府一般债券实行自发自还（B选项正确），债券资金收支列入一般公共预算管理（D选项正确）。故本题选ABD选项。"},{"id":"basics1-51","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"关于中国证监会对基金监管的主要职责，下列说法正确的有（）。","options":["制定有关证券投资基金活动监督管理的规章、规则，并行使审批、核准或者注册权","指导和监督基金行业协会的活动","组织行业交流，推动行业创新","监督检查基金信息的披露情况"],"answer":"ABD","explain":"中国证监会基金监管主要职责包括：（1）制定有关证券投资基金活动监督管理的规章、规则，并行使审批、核准或者注册权（A选项正确）；（2）办理基金备案；（3）对基金管理人、基金托管人及其他从事证券投资基金活动的机构进行监督管理，对违法行为进行查处；（4）制定基金从业人员的资格标准和行为准则，并监督实施；（5）监督检查基金信息的披露情况（D选项正确）；（6）指导和监督中国证券投资基金业协会的活动（B选项正确）等。故本题选ABD选项。"},{"id":"basics1-52","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"货币政策的传导机制包括（）。","options":["利率传导机制","信用传导机制","资产价格传导机制","汇率传导机制"],"answer":"ABCD","explain":"货币政策传导机制是指中央银行以货币政策手段，使用货币政策工具，来调整和影响经济中的相关经济变量，并通过一定渠道实现既定的经济目标的过程与作用机理。货币传导机制的类型包括：利率传导机制（A选项正确）、信用传导机制（B选项正确）、资产价格传导机制（C选项正确）、汇率传导机制（D选项正确）。故本题选ABCD选项。"},{"id":"basics1-53","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"金融机构（不包括政策性银行）发行金融债券申报文件应包括（）。","options":["金融债券发行申请报告、募集说明书","发行人近5年经审计的财务报告及审计报告","发行公告或发行章程、承销协议","发行人关于本期债券偿债计划及保障措施的专项报告"],"answer":"ACD","explain":"金融机构（不包括政策性银行）发行金融债券应向中国人民银行报送下列文件：①金融债券发行申请报告（A选项正确）；②发行人公司章程或章程性文件规定的权力机构的书面同意文件；③监管机构同意金融债券发行的文件；④发行人近3年经审计的财务报告及审计报告（B选项错误）；⑤募集说明书（A选项正确）；⑥发行公告或发行章程（C选项正确）；⑦承销协议（C选项正确）；⑧发行人关于本期债券偿债计划及保障措施的专项报告（D选项正确）；⑨信用评级机构出具的金融债券信用评级报告及有关持续跟踪评级安排的说明；⑩发行人律师出具的法律意见书；中国人民银行要求的其他文件。采用担保方式发行金融债券的，还应提供担保协议及担保人资信情况说明。如有必要，中国人民银行可商请其监管机构出具相关监管意见。故本题选ACD选项。【温馨提示】政策性银行及开发性金融机构发行金融债券应向中国人民银行报送下列文件：金融债券发行申请报告；发行人近3年经审计的财务报告及审计报告；金融债券发行办法；承销协议；中国人民银行要求的其他文件。"},{"id":"basics1-54","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"目前我国国债发行方式有（）。","options":["招标方式","承销方式","行政摊派","定向招募方式"],"answer":"ABD","explain":"目前，我国国债发行方式包括招标方式（向国债一级承销商发行可上市国债）（A选项正确）、承销方式（向商业银行和财政部所属国债经营机构等销售不上市的凭证式储蓄国债）（B选项正确）、定向招募方式（向社会保障机构和保险公司定向出售国债）（D选项正确）。C选项错误，1991年之前我国普通国债主要采用行政摊派的发行方式。故本题选ABD选项。"},{"id":"basics1-55","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"契约型基金的当事人包括（）。","options":["基金管理人","基金投资人","基金董事会","基金托管人"],"answer":"ABD","explain":"契约型基金是依据基金合同设立的一类基金。在我国，契约型基金依据基金管理人、基金托管人之间所签署的基金合同设立，基金投资者购买基金份额后成为基金持有人，依法享受权利并承担义务。因此契约型基金的当事人包括基金管理人、托管人和投资人（A、B、D选项正确）。故本题选ABD选项。"},{"id":"basics1-56","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"上市公司再融资的方式有（）。","options":["首次公开发行股票","定向增发","向不特定的对象公开募集股份","向原股东配售股份"],"answer":"BCD","explain":"（1）上市公司首次融资的途径。根据《公司法》，上市公司是指其股票在证券交易所上市交易的股份有限公司。上市公司首次融资主要是指首次公开发行股票（IPO）（A选项错误）。（2）上市公司再融资的途径。上市公司再融资的方式有向原股东配售股份（D选项正确）、向不特定对象募集股份（C选项正确）、向特定对象发行股票（B选项正确）、发行可转换公司债券。故本题选BCD选项。"},{"id":"basics1-57","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"属于金融衍生工具的是（）。","options":["远期合同","期货合同","投资合同","互换和期权合同"],"answer":"ABD","explain":"A、B、D选项正确，远期合同、期货合同、互换和期权合同属于金融衍生工具。C选项错误，投资合同不属于金融衍生工具，因其价值不依赖基础资产派生，而是直接关联投资标的经营成果。故本题选ABD选项。【温馨提示】金融衍生工具又称金融衍生产品，是与基础金融产品相对应的一个概念，指建立在基础产品或基础变量之上，其价格取决于基础金融产品价格（或数值）变动的派生金融产品。"},{"id":"basics1-58","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"我国的证券登记结算制度主要包括（）。","options":["货银对付的交收制度","证券账户转借制度","分级结算制度和结算参与人制度","净额结算制度"],"answer":"ACD","explain":"我国证券登记结算制度主要包括：（1）证券实名制；（2）货银对付的交收制度（A选项正确）；（3）分级结算制度和结算参与人制度（C选项正确）；（4）净额结算制度（D选项正确）；（5）结算证券和资金的专用性制度。故本题选ACD选项。"},{"id":"basics1-59","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"我国开放式基金的赎回方式采用（）。","options":["份额赎回","金额赎回","\"已知价\"赎回","\"未知价\"赎回"],"answer":"AD","explain":"开放式基金申购、赎回的原则：（1）对固定净值型货币基金而言，基金份额价格固定为1元人民币，因此投资者在申购、赎回货币基金时，按固定价格进行申购、赎回。（2）对一般开放式基金（股票基金、债券基金、混合基金等）而言，在申购、赎回时则遵循\"未知价\"交易原则（D选项符合题意），投资者在申购、赎回一般开放式基金份额时并不能即时获知成交价格。（3）一般采取\"金额申购、份额赎回\"原则（A选项符合题意），即申购以金额申请，赎回以份额申请。故本题选AD选项。"},{"id":"basics1-60","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"下列各项中，属于委托指令内容的有（）。","options":["委托数量、价格","证券代码","证券账户号码","买卖方向"],"answer":"ABCD","explain":"在委托指令中，不管是采用填写委托单还是自助委托方式，都需要反映客户买卖证券的具体要求，这些要求主要体现在委托指令的内容中。委托指令应当包括下列内容：证券账户号码（C选项正确）、证券代码（B选项正确）、买卖方向（D选项正确）、委托数量、委托价格（A选项正确）、交易所及其会员要求的其他内容。故本题选ABCD选项。"},{"id":"basics1-61","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"下列关于保荐制度的说法，正确的有（）。","options":["保荐制度主要内容包括：建立保荐机构资格核准和保荐代表人的登记管理制度","保荐制度的重点是明确保荐机构和保荐代表人的责任，并建立责任追究机制","保荐制度是指有资格的证券公司推荐符合条件的公司公开发行股票和上市，对发行人的申请文件和信息披露资料进行审慎核查，督导发行人规范运作","保荐人的保荐责任期仅为发行上市全过程"],"answer":"ABC","explain":"A选项正确，保荐制度主要内容包括：建立保荐机构资格核准和保荐代表人的登记管理制度。B选项正确，保荐制度的重点是明确保荐机构和保荐代表人的责任，并建立责任追究机制。C选项正确，保荐制度是指有资格的证券公司推荐符合条件的公司公开发行股票和上市，对发行人的申请文件和信息披露资料进行审慎核查，督导发行人规范运作。D选项错误，保荐人的保荐责任期包括发行上市全过程以及上市后的一段时期。故本题选ABC选项。"},{"id":"basics1-62","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"下列关于非公开发行公司债券的说法，正确的有（）。","options":["非公开发行公司债券，募集资金应当用于约定的用途；改变资金用途，应当履行募集说明书约定的程序","非公开发行的公司债券应当向专业投资者发行，不得采用广告、公开劝诱和变相公开方式，每次发行对象不得超过200人","非公开发行公司债券任何时候都不能改变资金用途","非公开发行公司债券，不得进行转让"],"answer":"AB","explain":"A选项正确、C选项错误，非公开发行公司债券，募集资金应当用于约定的用途；改变资金用途，应当履行募集说明书约定的程序。B选项正确，非公开发行的公司债券应当向专业投资者发行，不得采用广告、公开劝诱和变相公开方式，每次发行对象不得超过200人。D选项错误，非公开发行公司债券，可以申请在证券交易场所、证券公司柜台转让，并仅限于专业投资者范围内转让。故本题选AB选项。"},{"id":"basics1-63","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"下列关于股票收益性的说法，正确的有（）。","options":["收益性是股票的基本特征之一","认购股票后，持有者即对发行公司享有经济权益，其实现形式是公司派发的股息、红利","资本利得是股票获取收益的来源之一","股东取得股份公司的收益仅取决于个人所持股票的多少"],"answer":"ABC","explain":"收益性是股票最基本的特征（A选项正确），它是指股票可以为持有人带来收益的特性。股票的收益来源可分成两类：一是来自股份公司。认购股票后，持有者即对发行公司享有经济权益，其实现形式是公司派发的股息、红利（B选项正确），数量多少取决于股份公司的经营状况和盈利水平（D选项错误）。二是来自股票流通。股票持有者可以持股票到依法设立的证券交易场所进行交易，当股票的市场价格高于买入价格时，卖出股票就可以赚取差价收益。这种差价收益被称为资本利得（C选项正确）。故本题选ABC选项。"},{"id":"basics1-64","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"下列关于国际资金流动的说法，正确的有（）。","options":["国际长期资金流动是指期限在三年以上的资金的跨国流动","最传统的国际资金流动方式就是贸易资金的流动","国际长期资金流动主要有国际直接投资、国际间接投资和国际信贷三种形式","国际短期资金流动包括套利性资金、保值性资金以及投机性资金等的跨国流动"],"answer":"BCD","explain":"A选项错误、C选项正确，国际长期资金流动，是指期限在 1年以上的资金的跨国流动，包括国际直接投资、国际间接投资和国际信贷三种形式。B选项正确，贸易资金的流动是最传统的国际资金流动方式，早期的国际资金流动多以这种方式出现。D选项正确，国际短期资金流动主要包括贸易资金的流动、套利性资金的流动、保值性资金的流动以及投机性资金的流动四种类型。故本题选BCD选项。"},{"id":"basics1-65","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"下列关于美国存托凭证（ADR）的说法，正确的有（）。","options":["存托凭证由J.P.摩根首创","上市交易的ADR不须经过SEC 注册","存托凭证能避开直接发行股票和债券的相关法律要求，上市手续简单，发行成本低","由于市场容量大，在美国发行ADR的外国公司能在短期内筹集到大量的外汇资金"],"answer":"ACD","explain":"A选项正确，存托凭证由J.P.摩根首创。B选项错误，上市交易的ADR须经美国证券交易委员会（SEC）注册，有助于保障投资者权益。C、D选项正确，对发行人而言，发行存托凭证能够带来下列好处：（1）市场容量大，筹资能力强。美国证券市场最突出的特点就是市场容量极大，这使在美国发行ADR的外国公司能在短期内筹集到大量的外汇资金。（2）避开直接发行股票与债券的法律要求，上市手续简单，发行成本低。故本题选ACD选项。"},{"id":"basics1-66","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"下列关于中国香港金融市场的说法，错误的有（）。","options":["2000年，香港联合交易所和香港期货交易所实行股份化，并与香港结算所合并于单一控股公司香港交易所旗下","2009年7月，中国香港政府推出政府债券计划的目的是筹集必要资金弥补公共服务支出缺口","中国香港自2003年开放人民币业务以来，逐步成为全球人民币离岸市场中心","在中国香港，基础货币的组成部分包括未偿还外汇基金票据和债券总额"],"answer":"AB","explain":"A选项错误，2000年，香港联合交易所和香港商品交易所实行股份化，并与香港结算所合并于单一控股公司香港交易所旗下，于6月在香港联合交易所上市。B选项错误，2009年 7月，中国香港特区政府推出政府债券计划，主要目的是提供无风险债券种类，促进中国香港债券市场发展。C选项正确，中国香港自2003年开放人民币业务以来，逐步成为全球人民币离岸市场中心。D选项正确，在中国香港，基础货币的组成部分包括：（1）已发行负债证明书（用作支持银行纸币）和由政府发行的纸币及硬币；（2）持牌银行在香港金融管理局的结算账户结余总额；（3）未偿还外汇基金票据和债券总额。故本题选AB选项。"},{"id":"basics1-67","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"下列可能导致股票供求变动的特殊原因包括（）。","options":["履行某种承诺（如期权到期行权）而买进股票","由于财产清算等原因股票持有人卖出股票","为了争夺或保持公司控制权而买入股票","股票持有人因流动性挤兑而卖出股票"],"answer":"ABCD","explain":"某些特殊原因可能导致股票的供求变化，比如为了夺取或保持公司控制权而买入股票（C选项正确），履行某种承诺（如期权到期行权）而买进股票（A选项正确）；同样，股票持有人也可能因为流动性挤压或者财产清算等原因而卖出股票（B、D选项正确）。故本题选ABCD选项。"},{"id":"basics1-68","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"下列属于基础设施公募REITs的要求的有（）。","options":["基金通过资产支持证券和项目公司等特殊目的载体取得基础设施项目完全所有权或经营权利","基金管理人主动运营管理基础设施项目，以获取基础设施项目租金、收费等稳定现金流为主要目的","80%以上基金资产投资于基础设施资产支持证券，并持有其全部份额","采取封闭式运作，收益分配比例不低于合并后基金年度可供分配金额的 60%"],"answer":"ABC","explain":"基础设施公募REITs要求有：（1）80%以上基金资产投资于基础设施资产支持证券，并持有其全部份额（C选项正确）；基金通过基础设施资产支持证券持有基础设施项目公司全部股权。（2）基金通过资产支持证券和项目公司等特殊目的载体取得基础设施项目完全所有权或经营权利（A选项正确）。（3）基金管理人主动运营管理基础设施项目，以获取基础设施项目租金、收费等稳定现金流为主要目的（B选项正确）。（4）采取封闭式运作，收益分配比例不低于合并后基金年度可供分配金额的 90%（D选项错误）。故本题选ABC选项。"},{"id":"basics1-69","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"下列属于金融期货交易制度的有（）。","options":["集中交易制度","标准化的期货合约和对冲机制","保证金制度","结算所和无负债结算制度"],"answer":"ABCD","explain":"金融期货的主要交易制度包括：（1）集中交易制度（A选项正确）；（2）标准化的期货合约和对冲机制（B选项正确）；（3）保证金制度（C选项正确）；（4）结算所和无负债结算制度（D选项正确）；（5）持仓限额制度；（6）大户报告制度；（7）每日价格波动限制；（8）强行平仓制度；（9）强制减仓制度。故本题选ABCD选项。"},{"id":"basics1-70","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"下列属于金融市场的有（）。","options":["房地产市场","货币市场","债券市场","股权投资市场"],"answer":"BCD","explain":"金融市场是创造和交易金融资产的市场，是以金融资产为交易对象而形成的供求关系和交易机制的总和。现代金融市场往往是无形的市场。A选项不符合题意，房地产市场不属于金融市场。B、C、D选项符合题意，货币市场、债券市场、股权投资市场属于金融市场。故本题选BCD选项。"},{"id":"basics1-71","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"现代信用风险分析的构成要素包括（）。","options":["违约概率","违约损失率","违约时的风险暴露","违约时间"],"answer":"ABC","explain":"现代信用风险概念已经从单纯的违约风险发展到包括信用等级变化的更加全面的信用风险，但在信用风险分析中，违约依然是最为重要的信用事件，对信用风险的描述和量化仍然是以违约为中心，主要包括违约概率（A选项正确）、违约损失率（B选项正确）和违约时的风险暴露（C选项正确）等。这些要素决定了信用产品的预期损失和非预期损失。故本题选ABC选项。"},{"id":"basics1-72","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"影响我国金融市场的主要因素有（）。","options":["经济因素","技术因素","心理因素","政策因素"],"answer":"ABCD","explain":"影响中国金融市场运行的因素来自诸多方面，可以将之大体归纳为政策因素（D选项正确）、经济因素（A选项正确）、法律因素、市场因素、技术因素（B选项正确）、心理因素（C 选项正确）以及其他因素七个方面。故本题选ABCD选项。"},{"id":"basics1-73","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"与个人投资者相比，机构投资者的特点包括（）。","options":["投资结构规范化","投资管理专业化","投资灵活性强","投资资金规模化"],"answer":"BD","explain":"机构投资者的特点有：（1）投资资金规模化（D选项正确）；（2）投资管理专业化（B选项正确）；（3）投资结构组合化；（4）投资行为规范化。故本题选BD选项。"},{"id":"basics1-74","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"债券报价的主要方式包括（）。","options":["公开报价","对话报价","净额报价","双边报价"],"answer":"ABD","explain":"债券买卖交易中有公开报价（A选项正确）、对话报价（B选项正确）、双边报价（D选项正确）和小额报价四种报价方式。故本题选ABD选项。"},{"id":"basics1-75","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"债券成交竞价原则的主要内容是（）。","options":["时间优先","价格优先","数量优先","客户委托优先"],"answer":"ABD","explain":"证券交易所内，债券成交就是要使买卖双方在价格和数量上达成一致。这一程序必须遵循特殊的原则，即竞价原则。这种竞价原则的主要内容是\"三先\"，即价格优先（B选项正确）、时间优先（A选项正确）、客户委托优先（D选项正确）。C选项错误，数量优先并非债券成交竞价原则，因为单纯依据交易数量决定成交优先级，可能会导致市场价格失真，无法真实反映债券的价值，也不利于市场的稳定和健康发展。故本题选ABD选项。"},{"id":"basics1-76","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"证券公司声誉风险管理应遵循以下（）原则。","options":["全程全员原则","预防第一原则","审慎管理原则","快速响应原则"],"answer":"ABCD","explain":"证券公司声誉风险管理应遵循以下原则：（1）全程全员原则（A选项正确）；（2）预防第一原则（B选项正确）；（3）审慎管理原则（C选项正确）；（4）快速响应原则（D选项正确）。故本题选ABCD选项。"},{"id":"basics1-77","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"证券公司压力测试可采用的方法有（）。","options":["历史情景分析法","历史情景和假设情景相结合的分析方法","假设情景分析法","敏感性分析法"],"answer":"ABCD","explain":"证券公司压力测试可采用敏感性分析和情景分析等方法（D选项正确）。证券公司在设置压力情景时，可采取历史情景法、假设情景法或者二者相结合的方法（A、B、C选项正确）。故本题选ABCD选项。"},{"id":"basics1-78","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"中央银行的三大职能包含（）。","options":["发行的银行","银行的银行","政府的银行","盈利性商业银行"],"answer":"ABC","explain":"A、B、C选项正确，一般来说，中央银行的主要职能可概括为\"发行的银行\"、\"银行的银行\"、\"政府的银行\"。故本题选ABC选项。"},{"id":"basics1-79","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"中证中小投资者服务中心的维权服务主要包括（）。","options":["支持诉讼","股东诉讼","管理和公布市场信息","证券特别代表人诉讼"],"answer":"ABD","explain":"维权服务主要包括证券特别代表人诉讼（D选项正确）、支持诉讼（A选项正确）、股东诉讼（B选项正确）。故本题选ABD选项。"},{"id":"basics1-80","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"判断","q":"按选择权的性质划分，金融期权可以分为股权类期权、利率期权、货币期权、金融期货期权、互换期权。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。按照选择权的性质划分，金融期权可以分为认购期权和认沽期权。按照金融期权基础资产性质的不同，金融期权可以分为股权类期权、利率期权、货币期权、金融期货期权、互换期权等。故本题表述错误。"},{"id":"basics1-81","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"判断","q":"存款利息是资产时间价值的一种体现。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。货币的时间价值是指处于社会生产中的货币随时间的推移而发生的增值。日常生活中的存款利息是货币时间价值的一种直观体现。故本题表述正确。"},{"id":"basics1-82","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"判断","q":"法定存款准备金率越低，银行吸收的存款用于贷款的数额就越少。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。法定准备金率越高（并非越低），则银行吸收的存款用于贷款的数额就越少，货币供应量也会越少；反之，则越多。故本题表述错误。"},{"id":"basics1-83","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"判断","q":"根据委托订单的数量，委托指令可分为整数委托、零数委托和批量委托。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。根据委托订单的数量，委托指令可分为整数委托和零数委托。故本题表述错误。"},{"id":"basics1-84","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"判断","q":"公募REITs与其他公募基金一样，能够申购赎回。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。基础设施基金采取封闭式运作，不开通申购赎回，只能在二级市场交易，存在流动性不足的风险。故本题表述错误。"},{"id":"basics1-85","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"判断","q":"公司（企业）发行长期公司（企业）债券所募集资金用于长期资本需求，发行短期债券所募资金用于弥补流动性资金短缺。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。发行股票和长期企业（公司）债券是企业（公司）筹措长期资本的主要途径，发行短期债券则是补充流动资金的重要手段。故本题表述正确。"},{"id":"basics1-86","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"判断","q":"公司支付清算费用，员工工资和社会保险费用，缴付所欠税款，清偿公司债务，如还有剩余资产，再按照比例分配给各股东。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。公司的剩余资产在分配给股东之前，一般应按下列顺序支付：支付清算费用，支付公司员工工资和劳动保险费用，缴付所欠税款，清偿公司债务；如还有剩余资产，再按照股东持股比例分配给各股东。故本题表述正确。"},{"id":"basics1-87","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"判断","q":"监管资本是按照监管当局的要求计算的资本，金融机构应满足监管的最低要求。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。监管资本是按照监管当局的要求计算的资本，金融机构应满足监管的最低要求。故本题表述正确。【温馨提示】净资本是指根据证券公司的业务范围和公司资产负债的流动性特点，在净资产的基础上对资产负债等项目和有关业务进行风险调整后得出的综合性风险控制指标。证券公司净资本由核心净资本和附属净资本构成。"},{"id":"basics1-88","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"判断","q":"金融风险内涵包括：任何金融产品是风险和收益的组合，风险是与收益相匹配的，投资是以风险换收益。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。金融风险内涵：（1）任何金融产品是风险和收益的组合；（2）风险是与收益相匹配的；（3）投资是以风险换收益。故本题表述正确。"},{"id":"basics1-89","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"判断","q":"金融期货交易和普通远期交易之间存在一定的区别和联系，其中，金融期货交易是标准化交易，远期交易的内容可协商确定，但是由于两者都实行保证金制度和每日结算制度，交易者均以交易所（或期货清算公司）为交易对手，基本不用担心交易违约风险。（）","options":["正确","错误"],"answer":"B","explain":"本题表述错误。作为一种标准化的远期交易，金融期货交易与普通远期交易之间也存在以下区别：（1）交易场所和交易组织形式不同金融期货必须在有组织的交易所进行集中交易；而远期交易在场外市场进行双边交易。（2）交易的监管程度不同。在世界各国，金融期货交易至少要受到一家以上的监管机构监管，交易品种、交易者行为均须符合监管要求；而远期交易则较少受到监管。（3）金融期货交易是标准化交易，远期交易的内容可协商确定。金融期货交易中，基础资产的质量、合约时间、合约规模、交割安排、交易时间、报价方式、价格波动限制、持仓限额、保证金水平等内容都由交易所明确规定，金融期货合约具有显著的标准化特征；而远期交易的具体内容可由交易双方协商确定，具有较大的灵活性。（4）保证金制度和每日结算制度导致违约风险不同金融期货交易实行保证金制度和每日结算制度，交易者均以交易所（或期货清算公司）为交易对手，基本不用担心交易违约；而远期交易通常不存在上述安排，存在一定的交易对手违约风险。"},{"id":"basics1-90","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"判断","q":"金融市场按照交易是即期还是未来交割，分为现货市场和衍生品市场。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。按交易是即期还是未来交割，可将金融市场分为现货市场和衍生品市场。故本题表述正确。"},{"id":"basics1-91","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"判断","q":"金融衍生工具极强的派生能力和高度的杠杆性使其发展速度十分惊人，根据国际清算银行的金融衍生产品统计报告，金融衍生工具以场外交易为主。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。金融衍生工具极强的派生能力和高度的杠杆性使其发展速度十分惊人，根据国际清算银行的金融衍生产品统计报告，金融衍生工具以场外交易为主。故本题表述正确。"},{"id":"basics1-92","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"判断","q":"科创板包含了高新技术产业和战略性新兴产业。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。科创板重点服务于高新技术产业和战略性新兴产业的企业。故本题表述正确。"},{"id":"basics1-93","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"判断","q":"可交换债券的股份来源是发行人持有的其他公司已发行在外的股份，而可转换债券的股份来源通常是发行人本身未来将发行的新股。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。可交换债券的股份来源是发行人持有的其他公司已发行在外的股份，而可转换债券的股份来源通常是发行人本身未来将发行的新股。故本题表述正确。"},{"id":"basics1-94","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"判断","q":"敏感性分析是一个动态的分析过程，它将风险因子的变化视为外生的，没有研究风险因子自身变化的概率分布，忽略了这些风险因子自身发生变化的可能性，而将分析集中于金融工具价值随给定风险因子变化而变化的程度。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。敏感性风险分析方法的特点在于将投资风险暴露与风险因子联系起来，关注的是投资价值的变化，而非市场风险因子的变化。因此，敏感性分析是一个静态的分析过程（并非动态），它将风险因子的变化视为外生的，没有研究风险因子自身变化的概率分布，忽略了这些风险因子自身发生变化的可能性，而将分析集中于金融工具价值随给定风险因子变化而变化的程度。故本题表述错误。"},{"id":"basics1-95","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"判断","q":"目前，我国的封闭式基金于每个交易日估值，不晚于下一交易日披露基金份额净值。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。我国的开放式基金于每个交易日估值，一般不迟于T+1交易日公告份额净值（对于不投资QDII的FOF，不迟于T+2 交易日公告；投资范围包括 QDII的FOF，不迟于 T+3交易日公告）。封闭式基金和定期开放式基金的封闭期每个交易日都进行估值，但每周披露一次基金份额净值。故本题表述错误。"},{"id":"basics1-96","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"判断","q":"目前，我国证券交易所一般采用两种竞价方式集合竞价方式和连续竞价方式。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。目前，我国证券交易所采用两种竞价方式：集合竞价方式和连续竞价方式。故本题表述正确。"},{"id":"basics1-97","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"判断","q":"内部控制是证券公司操作风险管理的主要手段。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。内部控制是证券公司降低操作风险的有效方法之一。故本题表述正确。"},{"id":"basics1-98","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"判断","q":"通常期限在1年以下（含 1年）的国债为附息国债；期限在 1年以上的为贴现国债。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。通常期限在1年以下（含 1年）的国债为贴现国债；期限在 1年以上的国债为附息国债。故本题表述错误。"},{"id":"basics1-99","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"判断","q":"养老目标基金是指以追求养老资产的长期稳健增值为目的，鼓励投资人长期持有，采用成熟的资产配置策略，合理控制投资组合波动风险的私募基金。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。养老目标基金是指以追求养老资产的长期稳健增值为目的，鼓励投资人长期持有，采用成熟的资产配置策略，合理控制投资组合波动风险的公开募集证券投资基金（并非私募基金）。故本题表述错误。"},{"id":"basics1-100","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"判断","q":"一般来讲，影响股票投资价值的外部因素主要包括宏观经济因素、行业因素及市场因素。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。影响股票投资价值的外部因素主要包括宏观经济因素、行业因素及市场因素。故本题表述正确。【温馨提示】影响股票投资价值的内部因素主要包括公司净资产、盈利水平、股利政策、股份分割、增资和减资以及并购重组等。"},{"id":"basics1-101","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"判断","q":"在我国设立证券公司，必须由国务院监督管理局核准。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。证券公司，是指依照《公司法》和《证券法》设立的经营证券业务的有限责任公司或股份有限公司。在我国，设立证券公司必须经国务院证券监督管理机构（并非国务院监督管理局）审查批准。故本题表述错误。"},{"id":"basics1-102","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"判断","q":"在证券交易所内，证券竞价原则的主要内容是\"三先\"，即价格优先、时间优先、机构优先。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。证券交易所内的证券竞价交易按\"价格优先、时间优先\"的原则撮合成交。（1）价格优先。成交时价格优先的原则为：较高价格买入申报优先于较低价格买入申报，较低价格卖出申报优先于较高价格卖出申报。（2）时间优先。成交时时间优先的原则为：买卖方向、价格相同的，先申报者优先于后申报者。先后顺序按证券交易所交易主机接受申报的时间确定。故本题表述错误。"},{"id":"basics1-103","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"判断","q":"债券的托管量等于债券的总量。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。债券托管量等于已经发行但尚未到期的债券总量。故本题表述错误。"},{"id":"basics1-104","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"判断","q":"正常情况下，利率债的信用风险很小。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。利率债，是指直接以政府信用为基础或是以政府提供偿债支持为基础而发行的债券。由于有政府信用背书，正常情况下利率债的信用风险很小。故本题表述正确。"},{"id":"basics1-105","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"判断","q":"证券存续期内，该证券的评级机构应至少每半年出具一次定期跟踪评级报告。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。对于存续期限超过1年的受评证券，证券评级机构应当在受评级证券存续期内每年（并非每半年）至少出具一次定期跟踪评级报告，且在受评级证券或其发行人年度报告披露后 3个月内披露。故本题表述错误。"},{"id":"basics1-106","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"判断","q":"证券投资咨询机构及其从业人员从事证券服务业务可与委托人约定分享证券投资收益或者分担证券投资损失。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。根据《证券法》，证券投资咨询机构及其从业人员从事证券服务业务不得有下列行为：（1）代理委托人从事证券投资。（2）与委托人约定分享证券投资收益或者分担证券投资损失。（3）买卖本证券投资咨询机构提供服务的证券。（4）法律、行政法规禁止的其他行为。有上述所列行为之一，给投资者造成损失的，应当依法承担赔偿责任。故本题表述错误。"},{"id":"basics1-107","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"判断","q":"直接融资和间接融资比例反映了一国金融体系配置的效率是否与实体经济相匹配。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。直接融资和间接融资的比例反映了一国金融体系配置的效率是否与实体经济相匹配。我国正处于转变经济发展方式、调整产业结构的经济转型期，在这个过程中提高直接融资比重，特别是发展多种股权融资方式能够弥补间接融资的不足，也有利于促进实体经济的健康稳定发展。故本题表述正确。"},{"id":"basics1-108","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"判断","q":"直接融资与间接融资的主要区别是资金供求双方是否直接产生债权债务关系。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。直接融资和间接融资的区别主要在于融资过程中资金的需求者与资金的供给者是否直接形成债权债务关系。故本题表述正确。"},{"id":"basics1-109","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"判断","q":"中国证券业协会采取会员制的组织形式，是证券业的自律组织，是社会团体法人，证券公司应当加入中国证券业协会。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。中国证券业协会是证券业的自律性组织，是社会团体法人。中国证券业协会采取会员制的组织形式，证券公司应当加入中国证券业协会。故本题表述正确。"},{"id":"basics1-110","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"案例","q":"【资料】2023年2 月1日，某票面利率 5%、面值100元、每年付息 1次的债券，T+0成交\n在净价101元。该只债券上次付息为2022 年12 月31日。 \n请根据上述背景信息回答以下问题。\n\n【问题】成交当天该只债券的应计利息（按实际天数/360）约为（）。","options":["0.43元","0.12元","0.56元","1.12元"],"answer":"A","explain":"该债券按实际天数计息，全年按360天计算，每年付息一次。上次付息日为 2022年12 月31日，当前成交日为2023年 2月 1日，需计算2022 年12 月31日-2023 年 2月 1日此段期间债券的应计利息。①累计天数（算头不算尾）=31天（1月）。②累计利息=100×5%×31/360=0.43（元）（A选项正确）。故本题选A选项。"},{"id":"basics1-111","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"案例","q":"【资料】2023年2 月1日，某票面利率 5%、面值100元、每年付息 1次的债券，T+0成交\n在净价101元。该只债券上次付息为2022 年12 月31日。 \n请根据上述背景信息回答以下问题。\n\n【问题】该只债券的实际支付价格为（）。","options":["101.43元","100.66元","101.12元","100.44元"],"answer":"A","explain":"该债券的实际支付价格为净价+应计利息=101+0.43=101.43元（A选项正确）。故本题选A选项。"},{"id":"basics1-112","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"案例","q":"【资料】2021年，中国期货市场成交75.14 亿手（单边，下同）和581.2万亿元。全球期\n货市场成交625.84亿手，中国期货市场成交量占全球期货市场总成交量的 12%。 \n请根据材料回答下列问题。\n\n【问题】下列不属于商品期货的是（）。","options":["能源化工期货","金属期货","农产品期货","金融期货"],"answer":"D","explain":"商品期货，是指标的物为实物商品的期货合约。商品期货历史悠久，种类繁多，主要包括农产品期货（C选项不符合题意）、金属期货（B 选项不符合题意）和能源化工期货（A选项不符合题意）等。D选项符合题意，与商品期货并列，金融期货是以金融工具（或金融变量）为基础工具的期货交易，主要包括货币期货、利率期货、股票指数期货和股票期货四种。故本题选D选项。"},{"id":"basics1-113","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"案例","q":"【资料】2021年，中国期货市场成交75.14 亿手（单边，下同）和581.2万亿元。全球期\n货市场成交625.84亿手，中国期货市场成交量占全球期货市场总成交量的 12%。 \n请根据材料回答下列问题。\n\n【问题】下列属于我国商品期货交易所的有（）。","options":["上海期货交易所","广州期货交易所","郑州商品交易所","大连商品交易所"],"answer":"ABCD","explain":"目前，我国共有上海期货交易所（A选项正确）、大连商品交易所（D选项正确）、郑州商品交易所（C选项正确）和2021 年4 月19日揭牌成立的广州期货交易所（B选项正确）四大商品期货交易所。故本题选ABCD选项。"},{"id":"basics1-114","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"案例","q":"【资料】075，起购金额1万元，交易日开放申购赎回、管理费率 1.5%（每年）、托管费率0.25%\n（每年）、最高认购费率1.2%（前端）、最高申购费率1.5%（前端）、最高赎回费率1.5%\n（前端）、业绩比较基准60%×中证1000指数收益率+40%×上证国债指数收益率。2020年债\n券基金、理财基金和货币基金收益一般不超过6%。 \n根据该案例，回答以下问题。\n\n【问题】成某的朋友2021年购买的基金最可能为（）。","options":["债券型基金","股票型基金","货币型基金","纯债型基金"],"answer":"B","explain":"由题干知，2021年债券基金、理财基金和货币基金收益一般不超过6%，而成某的朋友购买的基金获得了20%以上的收益，所以最有可能的是股票型基金（B选项正确）。故本题选B选项。"},{"id":"basics1-115","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"案例","q":"【资料】075，起购金额1万元，交易日开放申购赎回、管理费率 1.5%（每年）、托管费率0.25%\n（每年）、最高认购费率1.2%（前端）、最高申购费率1.5%（前端）、最高赎回费率1.5%\n（前端）、业绩比较基准60%×中证1000指数收益率+40%×上证国债指数收益率。2020年债\n券基金、理财基金和货币基金收益一般不超过6%。 \n根据该案例，回答以下问题。\n\n【问题】成某如果购买A基金，他需要一次性支付的费用有（）。","options":["认购费","托管费","申购费","管理费"],"answer":"C","explain":"A选项错误，认购指在基金设立募集期内，投资者申请购买基金份额的行为。通过材料中该基金净值为4.075（一般认购期基金净值为1元）且开放申购赎回判断，该基金合同已生效，已过认购期，此时申请购买基金为申购，故无认购费。C选项正确，投资者在办理开放式基金申购时，一般需要缴纳申购费，因此，申购费是需要在购买基金时一次性支付的费用。B、D选项错误，我国的基金管理费、基金托管费及基金销售服务费均是按照前一日基金资产净值的一定比例逐日计提，按月支付。故本题选C选项。"},{"id":"basics1-116","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"案例","q":"【资料】075，起购金额1万元，交易日开放申购赎回、管理费率 1.5%（每年）、托管费率0.25%\n（每年）、最高认购费率1.2%（前端）、最高申购费率1.5%（前端）、最高赎回费率1.5%\n（前端）、业绩比较基准60%×中证1000指数收益率+40%×上证国债指数收益率。2020年债\n券基金、理财基金和货币基金收益一般不超过6%。 \n根据该案例，回答以下问题。\n\n【问题】最可能对A基金收取托管费的机构有（）。","options":["证券交易所","基金销售机构","商业银行","基金公司"],"answer":"C","explain":"C选项正确，在我国，基金托管人只能由依法设立并取得基金托管资格的商业银行或其他金融机构承担。故本题选C选项。"},{"id":"basics1-117","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"案例","q":"【资料】假定商业银行法定存款准备金率为20%，超额存款准备金率为5%，并且实行客户\n一切款项均存入商业银行的非现金结算制度，客户李某将10，000元现金存入商业银行，一段\n时间以后，中央银行取消了超额存款准备金率和非现金结算制度，现金比率定为 5%，这时客\n户王某将30，000元现金存入商业银行。 \n不考虑其他相关影响因素，请根据上述背景信息回答以下问题。\n\n【问题】在中央银行货币政策调整前，李某的原始存款货币乘数为（）。","options":["20","4","6.67","5"],"answer":"B","explain":"完整的货币乘数公式为m=（c+1）/（c+r+e）。因为没有考虑到现金比率，c=0，因此m=1/（20%+5%）=4（B选项正确）。故本题选B选项。"},{"id":"basics1-118","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"案例","q":"【资料】假定商业银行法定存款准备金率为20%，超额存款准备金率为5%，并且实行客户\n一切款项均存入商业银行的非现金结算制度，客户李某将10，000元现金存入商业银行，一段\n时间以后，中央银行取消了超额存款准备金率和非现金结算制度，现金比率定为 5%，这时客\n户王某将30，000元现金存入商业银行。 \n不考虑其他相关影响因素，请根据上述背景信息回答以下问题。\n\n【问题】在中央银行货币政策调整后，王某的原始存款可以被商业银行创造出（）万元货币供给。","options":["12.6","12","20","15"],"answer":"A","explain":"①本题中，在中央银行货币政策调整后，取消了超额存款准备金率，因此 e=0。现金比率c=5%，法定存款准备金率r=20%，将数值代入公式得m=（5%+1）/（5%+20%+0）=4.2。②王某将30000元现金存入商业银行，因此他的原始存款为 3万元，则王某可以被商业银行创造出的货币为：原始存款×货币乘数=3万×4.2=12.6万元（A选项正确）。故本题选A选项。"},{"id":"basics1-119","subject":"basics","source":"2026.09 LC终极押题 · 押题卷一","type":"案例","q":"【资料】假定商业银行法定存款准备金率为20%，超额存款准备金率为5%，并且实行客户\n一切款项均存入商业银行的非现金结算制度，客户李某将10，000元现金存入商业银行，一段\n时间以后，中央银行取消了超额存款准备金率和非现金结算制度，现金比率定为 5%，这时客\n户王某将30，000元现金存入商业银行。 \n不考虑其他相关影响因素，请根据上述背景信息回答以下问题。\n\n【问题】如不考虑其他因素影响，关于中央银行调整货币政策的措施与效果，下列说法正确的有（）。","options":["取消非现金结算制度将使货币乘数增加","降低超额存款准备金率将使货币乘数增加","提高现金比率将使货币乘数减小","提高法定存款准备金率将使货币乘数减小"],"answer":"BCD","explain":"现实中，影响货币乘数的因素主要为法定存款准备金率、超额准备金率及提现率。这些因素和货币乘数为反向变动的关系，即提高这些比率将降低货币乘数，而降低这些比率将增加货币乘数（B、C、D选项正确）。取消非现金结算制度说明允许客户使用现金结算，则一部分存款以现金的形式被公众提取出来，并持续地保留在公众手中，那就意味着提现率（现金比率）的增加。提现率增加将使货币乘数减少（A选项错误）。故本题选BCD选项。"}]},{"id":"basics2","subject":"basics","name":"金融基础 · 押题卷二","stats":{"单选":31,"多选":51,"判断":30,"案例":0},"questions":[{"id":"basics2-0","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"单选","q":"\"金融加速器\"理论认为（）。","options":["金融市场只是被动地反映实体经济活动的运行状况","货币供应量的变化影响名义变量而不影响实际变量，货币经济只是覆盖实体经济上的一层面纱","金融市场上资金借贷双方之间的信息不对称导致了外部融资的代理成本等摩擦，这些摩擦及其随后产生的效应会放大对实体经济产出的动态影响","未来的不确定性是货币经济的主要特征，通过利率对投资的诱导等作用，货币能影响实体经济"],"answer":"C","explain":"C选项符合题意，\"金融加速器\"理论认为，金融市场上资金借贷双方之间的信息不对称导致了外部融资的代理成本等摩擦，这些摩擦会产生\"加速器\"效应并放大对实体经济产出的动态影响。故本题选C选项。"},{"id":"basics2-1","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"单选","q":"2018年11 月5日，国家主席习近平在首届中国国际进口博览会开幕式上宣布，将在上海证券交易所设立科创板并试点（），支持上海国际金融中心和科技创新中心建设。","options":["申报制","注册制","审批制","核准制"],"answer":"B","explain":"2018年11 月5日，国家主席习近平在首届中国国际进口博览会开幕式上宣布，将在上海证券交易所设立科创板并试点注册制（B选项正确）。故本题选B选项。【温馨提示】2023年2 月17日，中国证监会及交易所等发布全面实行股票发行注册制制度规则。"},{"id":"basics2-2","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"单选","q":"根据《上海证券交易所科创板企业发行上市申报及推荐暂行规定》，科创板重点服务的新能源领域不包括（）。","options":["大型火电","高效储能","先进核电","高效光电光热"],"answer":"A","explain":"新能源领域主要包括先进核电（C选项不符合题意）、大型风电、高效光电光热（D选项不符合题意）、高效储能（B选项不符合题意）及相关服务等。故本题选A选项。【温馨提示】科创板重点服务于高新技术产业和战略性新兴产业的企业。上海证券交易所在《上海证券交易所科创板企业发行上市申报及推荐暂行规定（2024年4月修订）》中指出，申报科创板发行上市的发行人，应当属于下列行业领域：一是新一代信息技术领域；二是高端装备领域；三是新材料领域；四是新能源领域；五是节能环保领域；六是生物医药领域；七是符合科创板定位的其他领域。"},{"id":"basics2-3","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"单选","q":"根据2020年 3月正式实施的《证券法》，从事（）服务业务，应当经国务院证券监督管理机构核准。","options":["资产评估","证券投资咨询","财务顾问","资信评级"],"answer":"B","explain":"《证券法》规定，从事证券投资咨询（B选项正确）服务业务，应当经国务院证券监督管理机构核准，从事其他证券服务业务，应当报国务院证券监督管理机构和国务院有关主管部门备案。故本题选B选项。"},{"id":"basics2-4","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"单选","q":"关于全球金融市场的说法，错误的是（）。","options":["伦敦外汇市场以非居民交易为主，反映出伦敦外汇市场的高度国际化","纽约联邦储备银行每日计算和发布成交额加权的有效联邦基金利率","2007年，美国证券交易商协会与纽约证券交易所监管委员会合并，成立金融业监管局，是证券业非自律性组织","目前，伦敦证券交易所集团业务涵盖伦敦证交所、意大利证交所、加拿大蒙特利尔证交所以及泛欧股票和衍生品平台Turquoise"],"answer":"C","explain":"2007年，美国证券交易商协会与纽约证券交易所监管委员会合并，成立金融业监管局，是证券业自律性组织（C选项错误），负责监管经纪商、交易商与投资大众之间的业务。故本题选C选项。"},{"id":"basics2-5","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"单选","q":"国际长期资金流动的方式不包括（）。","options":["国际直接投资","投机性资金的流动","国际间接投资","国际信贷"],"answer":"B","explain":"国际长期资金流动，是指期限在1年以上的资金的跨国流动，包括国际直接投资（A选项不符合题意）、国际间接投资（C选项不符合题意）和国际信贷（D选项不符合题意）三种形式。国际短期资金流动，是指期限为1年或 1年以下的资金的跨国流动。国际短期资金流动主要包括贸易资金的流动、套利性资金的流动、保值性资金的流动以及投机性资金的流动（B选项符合题意）四种类型。故本题选B选项。"},{"id":"basics2-6","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"单选","q":"机构投资者有助于实现社会保障体系与宏观经济的良性互动发展的基础是（）。","options":["将养老金投资于期货产品","基金分级制的养老制度","以企业年金为主的企业补充养老金在内的多层次养老保障体系的构建","现收现付的公共养老制度"],"answer":"C","explain":"机构投资者有助于实现社会保障体系与宏观经济的良性互动发展。对现收现付的公共养老制度进行改革，建立起以包括企业年金为主的企业补充养老金和个人自愿储蓄性养老金在内的多层次养老保障体系（C选项正确），是我国社会保障体系改革的方向。故本题选C选项。"},{"id":"basics2-7","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"单选","q":"基金管理人会针对不同的基金类型、不同的认购金额设置不同的（）。","options":["认购方式","认购费率","认购代理","认购要件"],"answer":"B","explain":"B选项正确，基金管理人会针对不同的基金类型、不同的认购金额设置不同的认购费率。故本题选B选项。【温馨提示】我国股票型基金的认购费率大多在1%-1.5%，债券型基金的认购费率通常在1%以下，货币市场基金一般不收取认购费。"},{"id":"basics2-8","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"单选","q":"将整个金融机构或资产组合置于某一特定压力情景之下，然后测试该金融机构或资产组合在这些关键市场变量突变压力下的表现状况，以考虑它们是否能经受得起这种市场的突变，是指（）。","options":["压力测试","压力情景","敏感性分析","情景分析"],"answer":"A","explain":"压力测试（A选项正确）是指将整个金融机构或资产组合置于某一特定压力情景之下，然后测试该金融机构或资产组合在这些关键市场变量突变压力下的表现状况，以考虑它们是否能经受得起这种市场的突变。故本题选A选项。"},{"id":"basics2-9","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"单选","q":"交易者买入看涨期权，是因为其预期基础金融工具的价格在合约期限内将会（）。","options":["上涨","下跌","不变","难以判断"],"answer":"A","explain":"认购期权也称为看涨期权，指期权的买方具有在约定期限内（或合约到期日）按行权价格（也称为敲定价格或执行价格）向期权的卖方买入一定数量标的资产的权利。交易者之所以买入认购期权，是因为他预期基础金融工具的价格在合约期限内将会上涨（A选项正确）。故本题选A选项。"},{"id":"basics2-10","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"单选","q":"开放式基金申购、赎回的原则是（）。","options":["份额申购、金额赎回","份额申购、份额赎回","金额申购、金额赎回","金额申购、份额赎回"],"answer":"D","explain":"D选项正确，开放式基金的申购、赎回一般采取\"金额申购、份额赎回\"原则，即申购以金额申请，赎回以份额申请。这是适应未知价下进行申购、赎回最方便、安全的方式。货币基金也遵循同样的原则。故本题选D选项。"},{"id":"basics2-11","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"单选","q":"李某、王某研究全球金融市场与金融体系，他们认为，全球金融体系主要指金融资本在国际的存在形式和金融资本流动形式的总和、英国、美国和中国香港金融市场发达，其中，伦敦拥有全球最大的外汇市场，美国金融业居全球霸主地位，中国香港在联结中国内地与国际金融市场方面起着重要作用。下列由李某给出的伦敦外汇市场的特点，错误的是（）。","options":["以居民非批发性交易为主","以外币交易为主","以非居民交易为主","以外汇衍生品交易为主"],"answer":"A","explain":"伦敦外汇市场有以下几个特点：（1）以外币交易为主（B选项正确）。（2）以非居民交易为主（C选项正确）。（3）以金融机构批发性交易为主（A选项错误）。（4）以外汇衍生品交易为主（D选项正确）。（5）交易时段桥接美洲和亚太市场。故本题选A选项。"},{"id":"basics2-12","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"单选","q":"00元，则其基金认购份额为（）份。","options":["78964.35","98864.23","85664.57","67864.98"],"answer":"B","explain":"根据规定，基金认购费用将统一按净认购金额为基础收取，计算过程如下：（1）净认购金额=认购金额/（1+认购费率）=100000/（1+1.2%）=98814.23元。（2）认购份额=（净认购金额＋认购利息）/基金份额初始面值=（98814.23＋50）/1=98864.23份（B选项正确）。故本题选B选项。"},{"id":"basics2-13","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"单选","q":"区域性股权市场是为其所在（）级行政区域内中小微企业证券非公开发行、转让及相关活动提供设施与服务的场所。","options":["国家","县","省","市"],"answer":"C","explain":"C选项正确，区域性股权市场是为其所在省级行政区域内中小微企业证券非公开发行、转让及相关活动提供设施与服务的场所。故本题选C选项。"},{"id":"basics2-14","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"单选","q":"属于我国证券市场监管体系和自律管理体系组成的部分机构是（）。","options":["中国证券登记结算有限公司","分支证监局","中国银行保险业协会","证券投资者保护基金"],"answer":"D","explain":"我国证券市场经过20多年的发展，逐步形成了以国务院证券监督管理机构、国务院证券监督管理机构的派出机构、证券交易所、国务院批准的其他全国性证券交易场所、行业协会和证券投资者保护基金（D选项正确）为一体的监管体系和自律管理体系。故本题选D选项。"},{"id":"basics2-15","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"单选","q":"属于远期合约的衍生工具是（）。","options":["远期股票期权","远期利率协议","远期股票指数期货","远期货币期货"],"answer":"B","explain":"金融衍生工具包括远期、期货、期权和互换。根据基础资产划分，常见的金融远期合约包括四个大类：股权类资产的远期合约、债权类资产的远期合约、远期利率协议（B选项正确）、远期汇率协议。故本题选B选项。"},{"id":"basics2-16","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"单选","q":"投资者保护机构可以作为诉讼代表人，按照（）的原则，依法为受害投资者提起民事损害赔偿诉讼。","options":["默示退出、明示加入","默示退出、默示加入","明示退出、默示加入","明示退出、明示加入"],"answer":"C","explain":"C选项正确，规定投资者保护机构可以作为诉讼代表人，按照\"明示退出、默示加入\"的原则，依法为受害投资者提起民事损害赔偿诉讼。故本题选C选项。"},{"id":"basics2-17","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"单选","q":"投资者在开放式基金合同生效后，申请购买基金份额的行为通常被称为基金的（）。","options":["买入","申购","认购","交易"],"answer":"B","explain":"投资者在开放式基金合同生效后，申请购买基金份额的行为通常称为基金的申购（B选项正确）。故本题选B选项。"},{"id":"basics2-18","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"单选","q":"下列各项中，属于国际金融监管机构的是（）。","options":["世界银行","世界贸易组织","国际货币基金组织","国际证监会组织"],"answer":"D","explain":"国际金融监管体系是全球金融体系的重要组成部分，包括巴塞尔银行监管委员会、国际证监会组织（D选项正确）、国际保险监督官协会等。故本题选D选项。"},{"id":"basics2-19","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"单选","q":"下列关于非公开募集证券投资基金基本规范的说法，错误的是（）。","options":["担任非公开募集基金的基金管理人，应当按照规定向中国证券投资基金业协会履行登记手续","在我国，单只非公开募集证券投资基金合格投资者累计不得超过 200人","除基金合同另有约定外，非公开募集基金应当由基金托管人托管","私募基金不可采用公司型组织形式"],"answer":"D","explain":"在我国，单只非公开募集证券投资基金（私募基金）合格投资者累计不得超过 200人（B选项正确）。担任非公开募集基金的基金管理人，应当依法向国务院证券监督管理机构委托的机构履行登记手续，报送基本情况（A选项正确）。除基金合同另有约定外，非公开募集基金应当由基金托管人托管（C选项正确）。私募基金可采用公司型、合伙型、契约型三种组织形式（D选项错误）。故本题选D选项。"},{"id":"basics2-20","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"单选","q":"下列关于股利政策的说法，错误的是（）。","options":["股利政策是公司资本管理事项中经常要涉及的一个与股票相关的概念","股利政策体现了公司的发展战略和经营思路","稳定可预测的股利政策是股份公司稳健经营的重要指标","股利政策与股东利益最大化不相关"],"answer":"D","explain":"A选项正确，公司的股利政策直接影响股票投资价值。股利政策是公司资本管理事项中经常要涉及的一个与股票相关的概念。B、C选项正确，D选项错误，股利政策体现了公司的发展战略和经营思路，稳定可预测的股利政策有利于股东利益最大化，是股份公司稳健经营的重要指标。故本题选D选项。"},{"id":"basics2-21","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"单选","q":"下列关于股票合并的说法，错误的是（）。","options":["股票合并会影响每位股东所持股东权益占公司全部股东权益的比重","股票合并是将若干股票合并为1股","股票合并又称并股","股票合并常见于低价股"],"answer":"A","explain":"股票合并又被称为并股（C选项正确），是将若干股股票合并为1股（B选项正确）。从理论上说，不论分割还是合并，将增加或减少股份总数和股东持有股票的数量，但并不改变公司的实收资本和每位股东所持股东权益占公司全部股东权益的比重（A选项错误）。股票合并常见于低价股（D选项正确）。故本题选A选项。"},{"id":"basics2-22","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"单选","q":"下列关于股票价格指数的说法，错误的是（）。","options":["股票价格指数一般由一些有影响力的机构编制，并定期及时发布","股票价格指数是衡量整个市场价格水平的一个总的尺度标准，能够观察股票市场的总体变化情况","股票价格指数是观测经济形势和周期状况的参考指标，被视为经济景气变化的晴雨表","股票价格指数是用以反映整个市场上各种股票市场价格的总体水平及其变动情况的指标，因此股票价格指数上涨则意味着市场所有股票价格上涨"],"answer":"D","explain":"A选项正确，股票价格指数一般由一些有影响的机构编制，并定期及时公布。B选项正确，股票价格指数是用以反映整个市场上各种股票市场价格的总体水平及其变动情况的指标。在股票市场上，成百上千种股票同时交易，股票价格的涨跌各不相同，因此需要有一个总的尺度标准即股票价格指数来衡量整个市场的价格水平，观察股票市场的变化情况。C选项正确，股票价格指数是反映股票市场行情变动的重要指标，也是观测经济形势和周期状况的参考指标，被视为股市行情的指示器和经济景气变化的晴雨表。D选项错误，股票价格指数上涨并不意味着市场所有股票价格上涨。故本题选D选项。"},{"id":"basics2-23","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"单选","q":"下列关于会计师事务所从事相关业务的做法，错误的是（）。","options":["为乙公司到全国股转系统公司挂牌出具财务报表审计报告，按照从事证券服务业务相关规定向中国证监会和国务院有关主管部门备案","为丙上市公司的控股子公司（资产总额为丙上市公司最近一期经审计合并财务报表对应项目金额的10%）出具内部控制审计报告，未按照从事证券服务业务相关规定向中国证监会和国务院有关主管部门备案","为丁证券公司资产管理产品出具验资报告，未按照从事证券服务业务相关规定向中国证监会和国务院有关主管部门备案","为甲公司股票的发行、上市出具财务报表审计报告，按照从事证券服务业务相关规定向中国证监会和国务院有关主管部门备案"],"answer":"C","explain":"会计师事务所从事下列证券服务业务，应当按照规定向中国证监会和国务院有关主管部门备案：（1）为证券的发行、上市、挂牌、交易等证券业务活动制作、出具财务报表审计报告、内部控制审计报告、内部控制鉴证报告、验资报告、盈利预测审核报告，以及中国证监会和国务院有关主管部门规定的其他文件（A、D选项正确）。（2）为证券公司及其资产管理产品制作、出具财务报表审计报告、内部控制审计报告、内部控制鉴证报告、验资报告、盈利预测审核报告，以及中国证监会和国务院有关主管部门规定的其他文件（C选项错误）。会计师事务所参与上述第（1）项相关主体重要组成部分或者其控制的主体的审计，其审计对象的资产总额、营业收入中的一项达到上述第（1）项相关主体最近一期经审计合并财务报表对应项目金额15%的（B选项正确，未达15%故无需备案），视同从事证券服务业务。故本题选C选项。"},{"id":"basics2-24","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"单选","q":"下列关于基金资产估值需考虑的估值频率、估值方法的一致性及公开性等因素的说法，错误的是（）。","options":["封闭式基金每周估值一次","我国的开放式基金于每个交易日估值，一般不迟于T+1交易日公告份额净值","基金的估值方法需要在法定募集文件中公开披露","基金一般都按照固定的时间间隔对基金资产进行估值"],"answer":"A","explain":"A选项错误，封闭式基金和定期开放式基金的封闭期每个交易日都进行估值，但每周披露一次基金份额净值。B选项正确，我国的开放式基金于每个交易日估值，一般不迟于T+1交易日公告份额净值（对于不投资QDII的FOF，不迟于 T+2交易日公告；投资范围包括 QDII的FOF，不迟于 T+3交易日公告）。C选项正确，估值方法的公开性，是指基金采用的估值方法需要在法定募集文件中公开披露。若基金变更了估值方法，必须及时进行披露。D选项正确，基金一般都按照固定的时间间隔对基金资产进行估值，通常相关法规会规定一个最小的估值频率。故本题选A选项。"},{"id":"basics2-25","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"单选","q":"下列关于债券评级的说法，错误的是（）。","options":["信用等级评审会议的参会评审委员不得少于5人","评级项目组至少由两名评级分析人员组成","委托人同时委托多家证券评级机构对同一评级对象进行评级，受委托的证券评级机构应当同时对外公布评级结果","评级机构受理复评申请后应当从尽职调查开始重新执行评级程序"],"answer":"D","explain":"A选项正确，信用等级评审会议由信用评审委员会主任或其书面委托的其他委员主持，参会评审委员不得少于5人。B选项正确，证券评级机构应当聘用具有评级相关知识或经验的信用评级分析人员，并根据评级项目特点组成项目组。项目组实行组长负责制，至少由两名信用评级分析人员组成。C选项正确，委托人同时委托多家证券评级机构对同一评级对象进行评级，或委托人对评级结果有异议另行委托其他证券评级机构的，受委托的证券评级机构应当同时对外公布评级结果。D选项错误，证券评级机构受理复评申请后，项目组根据评级对象提供的补充资料修改评级报告，并将修改后的评级报告、建议信用等级、补充资料等提交信用评审委员会，由信用评审委员会确定复评结果。故本题选D选项。"},{"id":"basics2-26","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"单选","q":"下列关于证券公司次级债的发行条件的说法，错误的是（）。","options":["次级债应以现金或中国证监会认可的其他形式借入或融入","证券公司次级债对发行主体财务状况没有要求","长期次级债计入净资本的数额不得超过净资本（不含长期次级债累计计入净资本的数额）的50%","借入或募集资金有合理用途"],"answer":"B","explain":"证券公司借入或发行次级债应符合以下条件：（1）借入或募集资金有合理用途（D选项正确）；（2）次级债应以现金或中国证监会认可的其他形式借入或融入（A选项正确）；（3）借入或发行次级债数额应符合相关规定：①长期次级债计入净资本的数额不得超过净资本（不含长期次级债累计计入净资本的数额）的50%（C选项正确）；②净资本与负债的比例、净资产与负债的比例等各项风险控制指标不触及预警标准（B选项错误）。（4）募集说明书内容或次级债务合同条款符合证券公司监管规定。故本题选B选项。"},{"id":"basics2-27","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"单选","q":"下列业务中，不属于财产保险公司业务的是（）。","options":["责任保险","海洋开发保险","信用保证保险","变额年金"],"answer":"D","explain":"（1）财产保险公司的基础类业务包括以下五项：①机动车保险，包括机动车交通事故责任强制保险和机动车商业保险；②企业/家庭财产保险及工程保险（特殊风险保险除外）；③责任保险（A选项不符合题意）；④船舶/货运保险；⑤短期健康/意外伤害保险。（2）财产保险公司扩展类业务包括以下四项：①农业保险；②特殊风险保险，包括航空航天保险、海洋开发保险（B选项不符合题意）、石油天然气保险、核保险；③信用保证保险（C选项不符合题意）；④投资型保险。D选项符合题意，属于人身保险公司的业务类型。故本题选D选项。【温馨提示】人身保险公司扩展类业务包括以下两项：①投资连结型保险；②变额年金。"},{"id":"basics2-28","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"单选","q":"以下不属于基金的当事人（）。","options":["基金管理人","基金份额持有人","基金托管人","基金销售机构"],"answer":"D","explain":"我国证券投资基金依据基金合同设立，基金份额持有人（B选项不符合题意）、基金管理人（A选项不符合题意）与基金托管人（C选项不符合题意）是基金合同的当事人，简称基金当事人。D选项符合题意，基金销售机构属于基金服务机构，不属于基金的当事人。故本题选D选项。"},{"id":"basics2-29","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"单选","q":"以下不属于我国国际债券主要品种的是（）。","options":["国家债券","金融债券","公司债券","次级债券"],"answer":"D","explain":"对外发行债券是我国吸引国外资金的一个重要渠道，我国发行国际债券始于 20世纪80 年代初期。当时，在改革开放政策的指导下，为利用国外资金，加快我国的建设步伐，我国开始利用国际债券市场筹集资金，主要的债券品种有：政府债券（A选项不符合题意）、金融债券（B选项不符合题意）和公司债券（C选项不符合题意）。故本题选D选项。"},{"id":"basics2-30","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"银行间债券市场中长期债券信用评级等级划分为（）。","options":["四等九级","三等六级","三等九级","四等六级"],"answer":"C","explain":"（1）银行间债券市场中长期债券信用评级。该评级等级划分为三等九级（C选项正确），符号表示为：AAA、AA、A、BBB、BB、B、CCC、CC、C。（2）银行间债券市场短期债券信用评级。该评级等级划分为四等六级，符号表示为：A-1、A-"},{"id":"basics2-31","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"影响股票投资价值的外部因素是（）。","options":["盈利水平","股份分割","市场因素","并购重组"],"answer":"C","explain":"C选项正确，影响股票价值的外部因素有：宏观经济因素、行业因素、市场因素。A、B、D选项错误，影响股票投资价值的内部因素主要包括公司净资产、盈利水平、股利政策、股份分割、增资和减资以及并购重组等。故本题选C选项。"},{"id":"basics2-32","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"影响金融市场长期走势的最主要因素是（）。","options":["宏观经济运行","宏观经济政策","投资者心理因素","国际经济环境"],"answer":"A","explain":"影响中国金融市场运行的因素来自诸多方面，可以将之大体归纳为政策因素、经济因素、法律因素、市场因素、技术因素、心理因素以及其他因素七个方面。宏观经济因素是影响金融市场长期走势的最重要因素（A选项正确），其他因素可以暂时改变金融市场的中期和短期走势，但改变不了金融市场的长期走势。故本题选A选项。"},{"id":"basics2-33","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"在全球金融体系中不属于存款吸收机构的是（）。","options":["商业银行","抵押贷款银行","证券交易所","储蓄银行"],"answer":"C","explain":"存款吸收机构，是指通过自己的账户，以中介的方式将资金从贷款人转向借款人的单位。存款吸收机构包括商业银行（A选项不符合题意）和其他存款吸收机构。商业银行通常吸收存款，在支付系统中处于核心地位。其他存款吸收机构包括储蓄银行（D选项不符合题意）、开发银行、信用合作社、投资银行、抵押贷款银行（B选项不符合题意）以及建房互助协会、吸收存款的小额贷款机构。故本题选C选项。"},{"id":"basics2-34","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"在我国，设立证券公司必须经过（）审查批准。","options":["人民银行","国务院证券监督管理机构","财政部","证券业协会"],"answer":"B","explain":"证券公司，是指依照《公司法》和《证券法》设立的经营证券业务的有限责任公司或股份有限公司。在我国，设立证券公司必须经国务院证券监督管理机构审查批准（B选项正确）。故本题选B选项。"},{"id":"basics2-35","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"证券投资基金是通过国内公开发售（）募集资金。","options":["理财产品","有价证券","企业债券","基金份额"],"answer":"D","explain":"证券投资基金，是指通过公开发售基金份额（D选项正确）等筹集资金，由基金管理人管理，基金托管人托管，为基金份额持有人的利益，以资产组合方式进行证券投资活动的基金。故本题选D选项。"},{"id":"basics2-36","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"只能用于基金、国债及其他债券的认购及交易的账户是（）。","options":["债券账户","基金账户","资金账户","股票账户"],"answer":"B","explain":"投资者买卖交易所上市的封闭式基金必须开立深、沪证券账户或深、沪基金账户及资金账户。基金账户（B选项正确）只能用于基金、国债及其他债券的认购及交易。故本题选B选项。"},{"id":"basics2-37","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"中国证券业协会的性质是（）。","options":["监管组织","管理机构","自律性组织","审批机构"],"answer":"C","explain":"中国证券业协会正式成立于1991年 8月28 日，是依据《证券法》和《社会团体登记管理条例》的有关规定设立的证券业自律性组织（C选项符合题意），是非营利性社会团体法人。故本题选C选项。"},{"id":"basics2-38","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"中央银行是发行的银行主要体现在（）。","options":["是全国唯一有权发行货币的机构","代理国库收支","代理国家债券的发行","对政府提供信贷"],"answer":"A","explain":"A选项正确，\"发行的银行\"是指中央银行垄断货币发行权，是全国唯一有权发行货币的机构。B、C、D选项错误，属于\"政府的银行\"职能。故本题选A选项。【温馨提示】\"政府的银行\"是指中央银行代表国家制定和执行货币政策，处理对外金融关系，为国家提供各种金融服务。作为\"政府的银行\"，其具体职能包括：第一，代理国库收支；第二，代理国家债券的发行；第三，对政府提供信贷；第四，代表政府管理金融活动，制定、发布并监督执行有关金融监管和业务的命令及规章，负责金融业的统计、调查、分析和预测；第五，持有、管理、经营国家外汇储备和黄金储备；第六，代表政府参加国际金融组织活动，进行国际金融合作。"},{"id":"basics2-39","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"中证指数有限公司编制沪深300指数，采用的方法是（）。","options":["派许加权法","算术平均法","几何平均法","B-S模型法"],"answer":"A","explain":"沪深300指数以2004 年12 月31 日为基日，基点为 1000点。沪深300 指数采用派许加权综合价格指数公式（A选项正确）进行计算。故本题选A选项。"},{"id":"basics2-40","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"2018年4 月28日，中国证监会正式发布《外商投资证券公司管理办法》，办法修订内容主要涉及（）。","options":["逐步放开合资证券公司业务范围","完善境外股东条件","明确外资持有上市和非上市两类证券公司股权的比例不同","允许外资控股合资证券公司"],"answer":"ABD","explain":"2018年4 月28日，中国证监会正式发布《外商投资证券公司管理办法》，办法修订内容主要涉及五个方面：（1）允许外资控股合资证券公司（D选项正确）。（2）逐步放开合资证券公司业务范围（A选项正确）。（3）统一外资持有上市和非上市两类证券公司股权的比例（C选项错误）。（4）完善境外股东条件（B选项正确）。（5）明确境内股东的实际控制人身份变更导致内资证券公司性质变更相关政策。故本题选ABD选项。"},{"id":"basics2-41","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"道·琼斯股价平均数主要包括（）。","options":["道·琼斯公用事业股价平均数","道·琼斯工业股价平均数","道·琼斯能源业股价平均数","道·琼斯运输业股价平均数"],"answer":"ABD","explain":"道·琼斯股价平均指数包括5组指标：（1）道·琼斯工业股价平均数（B选项正确）；（2）道·琼斯运输业股价平均数（D选项正确）；（3）道·琼斯公用事业股价平均数（A选项正确）；（4）道·琼斯股价综合平均数；（5）道·琼斯工业平均收益加权指数。故本题选ABD选项。"},{"id":"basics2-42","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"根据《企业债券管理条例》，下列关于企业债券发行的条款设计要求的说法，正确的有（）。","options":["企业发行企业债券的总面额不得大于该企业的自有资产净值的80%","没有对企业债券的期限作出明确的规定，实务操作中一般为1年以上","企业债券的发行期限一般为3～10年，以 5 年为主","发行企业债券，担保并非强制性要求"],"answer":"BD","explain":"A选项错误，企业发行企业债券的总面额不得大于该企业的自有资产净值。B选项正确，《企业债券管理条例》等没有对企业债券的期限作出明确的规定，只是说约定在一定期限内还本付息，实务操作中一般为1年以上。C选项错误，企业债券的发行期限一般为3～20 年，以7年为主；公司债券的发行期限一般为3～10年，以5年为主。D选项正确，企业可发行无担保信用债券、资产抵押债券、第三方担保债券。可见，发行企业债券，担保并非强制要求。故本题选BD选项。"},{"id":"basics2-43","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"根据国债的偿还期限，可以把国债分为（）。","options":["赤字国债","长期国债","中期国债","短期国债"],"answer":"BCD","explain":"按资金用途分类，国债可以分为赤字国债（A选项错误）、建设国债、战争国债和特种国债。按偿还期限分类，国债的偿还期限是国债的存续时间，以此为标准，习惯上把国债分为短期国债（D选项正确）、中期国债（C选项正确）和长期国债（B选项正确）。故本题选BCD选项。"},{"id":"basics2-44","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"根据科创板定位，保荐机构优先推荐的科技创新企业所属的领域包括（）。","options":["高端装备领域","新一代信息技术领域","现代服务领域","新材料领域"],"answer":"ABD","explain":"《上海证券交易所科创板企业发行上市申报及推荐暂行规定》规定，申报科创板发行上市的发行人，应当属于下列行业领域：（1）新一代信息技术领域（B选项正确）；（2）高端装备领域（A选项正确）；（3）新材料领域（D选项正确）；（4）新能源领域；（5）节能环保领域；（6）生物医药领域；（7）符合科创板定位的其他领域。故本题选ABD选项。"},{"id":"basics2-45","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"根据债券券面的形态不同，可以分为（）。","options":["实物式债券","凭证式债券","记账式债券","电子式债券"],"answer":"ABC","explain":"债券有不同的形式，根据债券券面形态可以分为实物债券（A选项正确）、凭证式债券（B 选项正确）和记账式债券（C选项正确）。故本题选ABC选项。"},{"id":"basics2-46","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"股份公司解散或破产进行清算时，下列关于对公司剩余资产分配的顺序的说法，正确的有（）。","options":["优先股票股东在普通股票股东之前","优先股票股东在债权人之后","优先股票股东在债权人之前","优先股票股东在普通股票股东之后"],"answer":"AB","explain":"优先股既像债券，又像股票，其\"优先\"主要体现在：（1）通常具有固定的股息（类似债券），并须在派发普通股股息之前派发；（2）在破产清算时，优先股股东对公司剩余财产的权利先于普通股股东（A选项正确），但在债权人之后（B选项正确）。故本题选AB选项。"},{"id":"basics2-47","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"关于金融市场的经济内涵，下列说法错误的有（）。","options":["金融市场是以货币为交易对象而形成的供求关系和交易机制的总和","金融市场是创造和交易金融资产的市场","金融市场属于要素市场的一种","金融市场的参与者主要在有形的固定场所进行金融资产交易"],"answer":"AD","explain":"与产品市场不同，金融市场是要素市场的一种（C选项正确）。金融市场是创造和交易金融资产的市场（B选项正确），是以金融资产为交易对象而形成的供求关系和交易机制的总和（A选项错误）。金融市场参与者不仅在有形的固定场所进行金融资产交易，还通过各种线上手段进行联系，形成庞大的无形金融市场网络。现代金融市场往往是无形的市场（D选项错误）。故本题选AD选项。"},{"id":"basics2-48","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"国务院再次出台的资本市场指导性文件新\"国九条\"中主要内容包括下列的（）。","options":["加大退市监管力度，进一步严格强制退市标准","加强证券基金机构监管，完善对衍生品、融资融券等重点业务的监管制度","大力推动中长期资金入市，持续壮大长期投资力量","鼓励更多的量化投资者进入证券机构进行交易"],"answer":"ABC","explain":"新\"国九条\"主要内容及配套制度有：（1）总体要求。（2）严把发行上市准入关。（3）严格上市公司持续监管。（4）加大退市监管力度：深化退市制度改革，加快形成应退尽退、及时出清的常态化退市格局。进一步严格强制退市标准（A选项符合题意）。（5）加强证券基金机构监管，推动行业回归本源、做优做强：完善对衍生品、融资融券等重点业务的监管制度（B选项符合题意）。（6）加强交易监管，增强资本市场内在稳定性。（7）大力推动中长期资金入市，持续壮大长期投资力量（C选项符合题意）。（8）进一步全面深化改革开放，更好地服务高质量发展。（9）推动形成促进资本市场高质量发展的合力。故本题选ABC选项。"},{"id":"basics2-49","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"基础设施公募REⅠTs的申请文件包括（）。","options":["资产支持证券材料","基金管理材料","基金合同草案","招募说明书"],"answer":"ABCD","explain":"申请文件应当包括以下内容：（1）基金管理材料（B选项正确）：包括投资管理、运营制度、部门设置及同类业务管理情况等；（2）资产支持证券材料（A选项正确）：如专项计划说明书、法律意见书、备案材料等；（3）协议文件：基金合同草案（C选项正确）、托管协议、招募说明书（D选项正确）及与参与机构签订的协议；（4）补充材料：如基础设施项目财务报告、现金流测算报告、评估报告等。故本题选ABCD选项。"},{"id":"basics2-50","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"基金管理人运作基金财产进行证券投资，不得出现的情形包括（）。","options":["基金中基金持有其他单只基金，其市值超过基金资产净值的20%","基金财产参与股票发行申购，单只基金所申报的金额超过该基金的总资产","基金财产参与股票发行申购，单只基金所申报的股票数量超过拟发行股票公司本次发行股票的总量","一只基金持有一家公司发行的证券，其市值为该基金资产净值的 5%"],"answer":"ABC","explain":"基金管理人运用基金财产进行证券投资的禁止性情形主要有以下几种：（1）一只基金持有一家公司发行的证券，其市值超过基金资产净值的 10%（D选项不符合题意）；（2）同一基金管理人管理的全部基金持有一家公司发行的证券，其市值超过该证券的 10%；（3）基金财产参与股票发行申购，单只基金所申报的金额超过该基金的总资产（B选项符合题意），单只基金所申报的股票数量超过拟发行股票公司本次发行股票的总量（C选项符合题意）；（4）一只基金持有其他基金（不含货币市场基金），其市值超过基金资产净值的 10%，但基金中基金除外；（5）基金中基金持有其他单只基金，其市值超过基金资产净值的20%（A选项符合题意），或者投资于其他基金中基金；（6）每只开放式公募产品的总资产超过该产品净资产的140%，每只封闭式公募产品总资产超过该产品净资产的200%；（7）违反基金合同关于投资范围、投资策略和投资比例等约定；（8）中国证监会规定禁止的其他情形。故本题选ABC选项。"},{"id":"basics2-51","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"基金交易费是指基金在进行证券买卖交易时所发生的相关交易费用，主要包括（）。","options":["印花税","开户费","证管费","佣金"],"answer":"ACD","explain":"我国基金的交易费主要包括印花税（A选项正确）、佣金（D选项正确）、过户费、经手费、证管费（C选项正确）。故本题选ACD选项。"},{"id":"basics2-52","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"基金投资收益具体包括（）。","options":["ETF替代损益","衍生工具收益","股利收益","手续费返还"],"answer":"BC","explain":"（1）投资收益是指基金经营活动中因买卖股票、债券、资产支持证券、基金等实现的差价收益，具体可分为股票投资收益、债券投资收益、资产支持证券投资收益、基金投资收益、衍生工具收益（B选项正确）、股利收益（C选项正确）等。（2）其他收入是指除上述收入以外的其他各项收入，包括赎回费扣除基本手续费后的余额、手续费返还（D选项错误）、ETF替代损益（A 选项错误），以及基金管理人等机构为弥补基金财产损失而支付给基金的赔偿款项等。故本题选BC选项。【温馨提示】（1）基金收入主要包括利息收入、投资收益以及其他收入。（2）利息收入是指基金经营活动中因债券投资、资产支持证券投资、银行存款、结算备付金、存出保证金、按买入返售协议融出资金等而实现的利息收入。具体包括债券利息收入、资产支持证券利息收入、存款利息收入、买入返售金融资产收入等。"},{"id":"basics2-53","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"金融市场的功能包括（）。","options":["资金融通","价格发现","提供流动性","风险管理"],"answer":"ABCD","explain":"金融市场的功能：（1）资金融通（A选项正确）；（2）价格发现（B选项正确）；（3）提供流动性（C选项正确）；（4）风险管理（D选项正确）；（5）降低搜寻成本和信息成本。故本题选ABCD选项。"},{"id":"basics2-54","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"私募基金募集应当履行的程序，主要包括（）等。","options":["特定对象确定","投资者适当性匹配","合格投资者确认","投资冷静期"],"answer":"ABCD","explain":"私募基金募集应当履行下列程序：（1）特定对象确定（A选项正确）；（2）投资者适当性匹配（B选项正确）；（3）基金风险揭示；（4）合格投资者确认（C选项正确）；（5）投资冷静期（D选项正确）；（6）回访确认。故本题选ABCD选项。"},{"id":"basics2-55","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"下列关于地方政府债券概念的说法，错误的有（）。","options":["仅向银行、证券公司等金融机构发行筹集资金","是一种债务凭证","根据本地区经济发展和资金需求状况发行","筹集资金不可用于地方兴建大型项目"],"answer":"AD","explain":"地方政府债券是地方政府根据本地区经济发展和资金需求状况，以承担还本付息责任为前提，向社会筹集资金的债务凭证（A选项错误，B、C选项正确）。筹集的资金一般用于弥补地方财政资金的不足，或者地方兴建大型项目（D选项错误）。故本题选AD选项。"},{"id":"basics2-56","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"下列关于风险偏好和风险容忍度的说法，正确的有（）。","options":["风险容忍度是风险偏好的具体体现，是对风险偏好的进一步量化和细化","风险容忍度表现为公司在不同业务板块和不同控制维度上的总体边界","风险偏好是公司决策层综合考虑多种风险因素后作出的一种更高层次的承诺","风险偏好的设定通常从战略角度出发，采取\"自上而下\"的设定方法"],"answer":"ABCD","explain":"A选项正确，风险容忍度是风险偏好的具体体现，是对风险偏好的进一步量化和细化。B选项正确，风险容忍度表现为公司在不同业务板块和不同控制维度上的总体边界。C选项正确，风险偏好是公司决策层综合考虑多种风险因素后作出的一种更高层次的承诺。D选项正确，风险偏好的设定通常从战略角度出发，采取\"自上而下\"的设定方法。故本题选ABCD选项。"},{"id":"basics2-57","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"下列关于国债的承购包销发行方式的说法，正确的有（）。","options":["承购包销团负责在市场上转售","任何未能售出的余额均由承销者包销","按一定条件向财政部承购包销国债","大宗机构投资者组成承购包销团"],"answer":"ABCD","explain":"承购包销发行方式，指大宗机构投资者组成承购包销团（D选项正确），按一定条件向财政部承购包销国债（C选项正确），并由其负责在市场上转售（A选项正确），未能售出的余额均由承销者自行包购（B选项正确）。故本题选ABCD选项。"},{"id":"basics2-58","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"下列关于沪港通的说法，正确的有（）。","options":["沪股通是指投资者委托内地证券公司，向香港联合交易所进行申报，买卖沪港通规定范围内的香港联合交易所上市的股票","沪股通是指投资者委托香港经纪商，向上海证券交易所进行申报，买卖沪港通规定范围内的上海证券交易所上市的股票","沪港通下的港股通，是指投资者委托香港经纪商，向上海证券交易所进行申报，买卖沪港通规定范围内的上海证券交易所上市的股票","沪港通下的港股通，是指投资者委托内地证券公司，向香港联合交易所进行申报，买卖沪港通规定范围内的香港联合交易所上市的股票"],"answer":"BD","explain":"A选项错误、B选项正确，沪股通，是指投资者委托香港联合交易所参与者（即香港经纪商），经由香港联合交易所在上海设立的证券交易服务公司，向上海证券交易所进行申报，买卖沪港通规定范围内的上海证券交易所上市的股票。C选项错误、D选项正确，沪港通下的港股通，是指投资者委托上海证券交易所会员（即内地证券公司），经由上海证券交易所在香港设立的证券交易服务公司，向香港联合交易所进行申报，买卖沪港通规定范围内的香港联合交易所上市的股票。故本题选BD选项。"},{"id":"basics2-59","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"下列关于基金信息披露的说法，正确的有（）。","options":["基金的信息披露不具有强制性","基金的信息披露必须保证所披露信息的真实性、准确性和完整性","基金的信息披露制度有利于防止利益冲突和利益输送","与市场上其他理财产品相比，基金的一个突出特点就是透明度较高"],"answer":"BCD","explain":"基金的信息披露是指基金信息披露义务人按照法律、行政法规和中国证监会的规定披露基金信息，并保证所披露信息的真实性、准确性和完整性的活动（B选项正确）。在我国，基金的信息披露具有强制性（A选项错误），《证券投资基金法》《公开募集证券投资基金信息披露管理办法》及一系列配套法规对基金信息披露的原则、内容、禁止行为等各方面作出了明确、严格的规定。因此，与市场上其他理财产品相比，基金的一个突出特点就是透明度较高（D选项正确）。基金披露的各种公开信息是了解、识别基金的重要信息来源渠道。强制性的基金信息披露制度，有利于培育和完善市场运行机制，有利于防止利益冲突与利益输送（C选项正确），增强市场参与各方对市场的理解和信心。故本题选BCD选项。"},{"id":"basics2-60","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"下列关于美国金融市场的说法，正确的有（）。","options":["根据国债的特点，美国国债有通货膨胀保值债券、浮动利率国库票据等分类","目前的纽约证券交易所交易制度模式主要包括三个特征，即专家制度、场内经纪商制度和补充流动性供商制度","1997年纳斯达克市场将电子通信引入自身的报价和交易系统中，并启用美国证券交易委员会的《交易指令处理规则》","有效联邦基金利率由联储理事会公开市场委员会负责计算和发布"],"answer":"AC","explain":"A选项正确，根据国债的特点，美国国债有通货膨胀保值债券、浮动利率国库票据等分类。B选项错误，纽约证券交易所交易制度模式主要包括三个特征，即指定做市商制度、场内经纪商制度和补充流动性提供商制度。C选项正确，1997年纳斯达克市场将电子通信引入自身的报价和交易系统中，并启用美国证券交易委员会《交易指令处理规则》。D选项错误，为保证联邦基金利率正确反映银行间市场的供求状况，美联储根据国际证监会组织（IOSCO）关于金融基准指标计算和发布的指导原则，具体由最贴近市场的纽约联邦储备银行（并非联储理事会）负责根据联邦基金市场每日的交易情况，每日计算和发布成交额加权的有效联邦基金利率，并根据联邦公开市场委员会（FOMC）的议息会议决定，保证该利率在规定的范围内波动。故本题选AC选项。"},{"id":"basics2-61","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"下列关于证券公司压力测试的说法，正确的有（）。","options":["证券公司压力测试采用以定量分析为主的风险分析方法","压力情景包括证券公司内外部经营环境发生极端变化或出现突发事件、开展重大业务以及进行利润分配等情形","证券公司在设置压力情景时，可采取历史情景法、假设情景法或者二者相结合的方法","假设情景法是指基于经验判断或数量模型模拟未来可预见的极端不利情况"],"answer":"ABCD","explain":"A选项正确，对于证券公司来说，压力测试具体是指采用以定量分析为主的风险分析方法，测算压力情景下净资本和流动性等风险控制指标、财务指标、证券公司内部风险限额及业务指标的变化情况，评估风险承受能力，并采取必要应对措施的过程。B选项正确，压力情景包括证券公司内外部经营环境发生极端变化或出现突发事件、开展重大业务以及进行利润分配等情形。C选项正确，证券公司在设置压力情景时，可采取历史情景法、假设情景法或者二者相结合的方法。D选项正确，历史情景法是指模拟历史上重大风险事件或重大压力情景；假设情景法是指基于经验判断或数量模型模拟未来可预见的极端不利情况。故本题选ABCD选项。"},{"id":"basics2-62","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"下列关于直接融资和间接融资的说法，正确的有（）。","options":["提高直接融资比重，有利于分散过度集中于银行的金融风险","发展多种股权融资方式有利于提高实体经济的健康稳定发展","相对于直接融资来说，间接融资的信誉程度低，风险也相对较大","直接融资通过市场主体充分博弈直接进行交易，有利于合理引导资源配置"],"answer":"ABD","explain":"直接融资对金融市场的影响包括：（1）直接融资和间接融资的比例反映了一国金融体系风险的分布情况。提高直接融资比重，平衡金融体系结构，可以分散过度集中于银行的金融风险（A选项正确），有利于金融和经济的平稳运行。（2）直接融资和间接融资比例反映了一国金融体系配置的效率是否与实体经济相匹配。我国正处于转变经济发展方式、调整产业结构的经济转型期，在这个过程中提高直接融资比重，特别是发展多种股权融资方式能够弥补间接融资的不足，也有利于促进实体经济的健康稳定发展（B选项正确）。（3）通过市场主体充分博弈直接进行交易，更有利于合理引导资源配置（D选项正确），发挥市场筛选作用。C选项错误，相对于直接融资来说，间接融资的信誉程度高，风险也相对较小，融资的稳定性较强。故本题选ABD选项。"},{"id":"basics2-63","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"下列属于股票相对估值法的有（）。","options":["自由现金流折现模型","市净率倍数法","市销率倍数法","市盈率倍数法"],"answer":"BCD","explain":"B、C、D选项正确，属于股票相对估值法。A选项错误，属于股票绝对估值法。故本题选BCD选项。"},{"id":"basics2-64","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"下列属于金融市场的有（）。","options":["劳动力市场","外汇市场","证券市场","房地产市场"],"answer":"BC","explain":"根据不同的分类标准，可以将金融市场分成不同的子市场。按金融资产的种类分为证券市场（C选项正确）和非证券金融市场。（1）证券市场是指以股票、债券、证券投资基金等有价证券为对象的发行和交易关系的总和，主要包括股票市场、债券市场、证券投资基金市场、证券衍生品市场等。（2）非证券金融市场，是指以有价证券以外的金融资产为对象的发行和交易关系的总和，包括股权投资市场、信托市场、融资租赁市场、外汇市场（B选项正确）、黄金市场、保险市场、银行理财产品市场、长期贷款市场等。A、D选项错误，不属于金融市场。故本题选BC选项。"},{"id":"basics2-65","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"下列属于一般性货币政策工具的有（）。","options":["存款准备金制度","再贴现政策","公开市场业务","常备借贷便利（SLF）"],"answer":"ABC","explain":"一般性货币政策工具是指中央银行普遍或常规运用的货币政策工具，其实施对象是整体经济和金融活动，主要包括存款准备金制度（A选项正确）、再贴现政策（B选项正确）和公开市场业务（C选项正确）三大工具。故本题选ABC选项。"},{"id":"basics2-66","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"下列属于优先股的特点的是（）。","options":["收益相对固定","先于普通股获得股息","清偿顺序先于普通股，而次于债权人","权利范围小"],"answer":"ABCD","explain":"优先股的特征：（1）优先股收益相对固定（A选项符合题意）。（2）优先股可以先于普通股获得股息（B选项符合题意）。（3）优先股的清偿顺序先于普通股，而次于债权人（C选项符合题意）。（4）优先股的权利范围小（D选项符合题意）。故本题选ABCD选项。"},{"id":"basics2-67","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"下列有关股票特征的说法，正确的有（）。","options":["股票的风险性和收益性是并存的","股份公司派发的股息红利数量，主要取决于公司的盈利情况","股票的风险性和收益性是彼此独立的","股份公司派发的股息红利数量，主要取决于公司的股息红利分配方案"],"answer":"AB","explain":"A选项正确、C选项错误，股票的风险性和收益性是并存的。价格波动的不确定性越大，投资收益的不确定性越大，投资风险也越大。股票风险的内涵是股票投资收益的不确定性，或者说实际收益与预期收益之间的偏离。B选项正确、D选项错误，股份公司派发的股息、红利，数量多少取决于股份公司的经营状况和盈利水平。故本题选AB选项。"},{"id":"basics2-68","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"以下属于场内市场的是（）。","options":["主板市场","创业板市场","私募基金市场","全国中小企业股份转让系统"],"answer":"ABD","explain":"主板市场（A选项正确）、科创板市场、创业板市场（B选项正确）、北京证券交易所和全国中小企业股份转让系统（D选项正确）属于场内市场，区域股权交易市场、券商柜台市场、机构间私募产品报价与服务系统和私募基金市场（C选项错误）属于场外市场。故本题选ABD选项。"},{"id":"basics2-69","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"以下属于股利分配相关日期的是（）。","options":["除息除权日","股权登记日","股利宣告日","股利派发日"],"answer":"ABCD","explain":"股利分配4个相关日期：（1）股利宣告日（C选项正确），即公司董事会将分红派息的消息公布于众的时间。（2）股权登记日（B选项正确），即统计和确认参加本期股利分配的股东的日期，在此日期持有公司股票的股东方能享受股利发放。（3）除息除权日（A选项正确），通常为股权登记日之后的1个工作日，本日之后（含本日）买入的股票不再享有本期股利。（4）股利派发日（D选项正确），即股利正式发放给股东的日期。根据证券存管和资金划转的效率不同，通常会在几个工作日之内到达股东账户。故本题选ABCD选项。"},{"id":"basics2-70","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"以下属于银行附属金融机构的有（）。","options":["财务公司","金融租赁公司","汽车金融公司","消费金融公司"],"answer":"BCD","explain":"银行附属机构包括：金融租赁公司（B选项正确）、消费金融公司（D选项正确）、汽车金融公司（C选项正确）、直销银行。故本题选BCD选项。"},{"id":"basics2-71","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"在证券公司柜台市场，证券公司可以为客户提供的私募产品服务有（）。","options":["清算交割","风险监控","公募基金买卖","估值核算"],"answer":"ABD","explain":"证券公司可以接受委托，为客户依法持有或者管理的在其柜台市场发行、销售与转让的私募产品提供保管、清算交割（A选项正确）、估值核算（D选项正确）、投资监督、风险监控（B选项正确）、出具托管报告等服务。故本题选ABD选项。"},{"id":"basics2-72","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"证券公司自营业务投资范围包括（）。","options":["计划在区域股权市场挂牌的私募债券","政府债券","央行票据","短期融资券"],"answer":"BCD","explain":"证券自营业务，是指证券公司以自己的名义，以自有资金或者依法筹集的资金，为本公司买卖在境内证券交易所上市交易的证券，在境内银行间市场交易的政府债券（B选项正确）、国际开发机构人民币债券、央行票据（C选项正确）、金融债券、短期融资券（D选项正确）、公司债券、中期票据和企业债券，以及经中国证监会批准或者备案发行并在境内金融机构柜台交易的证券，以获取盈利的行为。故本题选BCD选项。"},{"id":"basics2-73","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"证券金融公司根据市场状况和风险控制的需要，确定和调整转融通的（）。","options":["佣金","费率","数量占比","保证金的比例"],"answer":"BD","explain":"证券金融公司应当按照国家宏观政策，根据市场状况和风险控制需要，确定和调整转融通费率（B选项正确）和保证金的比例（D选项正确）。故本题选BD选项。"},{"id":"basics2-74","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"证券金融公司开展转融通业务，应当以自己的名义，在证券登记结算机构分别开立（）账户。","options":["融券专用证券账户","融资专用资金账户","转融通担保资金账户","转融通资金交收账户"],"answer":"CD","explain":"证券金融公司开展转融通业务，应当以自己的名义，在证券登记结算机构分别开立转融通担保资金账户（C选项正确）和转融通资金交收账户（D选项正确）。故本题选CD选项。"},{"id":"basics2-75","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"证券投资基金作为一种金融产品，与股票相比较，不同点主要表现为（）。","options":["股票投资风险通常大于基金投资风险","股票价格的波动要小于基金净值的波动","股票是间接投资工具，基金是直接投资工具","股票反映的是一种所有权关系，基金反映的则是一种信托关系"],"answer":"AD","explain":"A选项正确，股票投资风险通常大于基金投资风险。B选项错误，股票价格的波动要大于基金净值的波动。C选项错误，股票是直接投资工具，基金是间接投资工具。D选项正确，股票反映的是所有权关系，而基金反映的则是信托关系。故本题选AD选项。"},{"id":"basics2-76","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"政府债券的功能包括（）。","options":["调节居民收入分配","国家实施宏观经济政策、进行宏观调控的工具","弥补财政赤字","为政府筹集资金、扩大公共开支"],"answer":"BCD","explain":"从功能上看，政府债券最初仅是政府弥补赤字的手段（C选项正确），但在现代商品经济条件下，政府债券已成为政府筹集资金、扩大公共开支的重要手段（D选项正确），并且随着金融市场的发展，逐渐具备了金融商品和信用工具的职能，成为国家实施宏观经济政策、进行宏观调控的工具（B选项正确）。故本题选BCD选项。"},{"id":"basics2-77","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"资本的功能主要体现在（）。","options":["资本显示金融机构的实力和信誉，向债权人和投资者树立信心","限制业务过度扩张和承担风险，资本是金融机构承担风险的底线和边界","为金融机构提供融资，资本是金融机构发放贷款和投资的资金来源之一","可以抵御风险损失，保证公司正常运营，为避免破产提供缓冲余地"],"answer":"ABCD","explain":"资本的功能主要体现在：（1）为金融机构提供融资，资本是金融机构发放贷款和投资的资金来源之一（C选项正确）；（2）资本可以抵御风险损失，保证公司正常运营，为避免破产提供缓冲余地（D选项正确）；（3）资本显示金融机构的实力和信誉，使债权人和投资者树立信心（A选项正确）；（4）限制业务过度扩张和承担风险，资本是与风险相联系的资产，是金融机构承担风险的底线和边界（B选项正确）；（5）维持金融体系的稳定，监管当局通过规定法定资本比率来约束和控制金融机构过度业务扩张和风险承担，进而维护金融体系的稳定。故本题选ABCD选项。"},{"id":"basics2-78","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"资产证券化是以（）为支持，发行可交易证券的一种融资形式。","options":["特定现金流","特定股票组合","特定资产组合","特定基金组合"],"answer":"AC","explain":"资产证券化是以特定资产组合或特定现金流为支持（A、C选项正确），发行可交易证券的一种融资形式。传统的证券发行是以企业为基础，而资产证券化是以特定的资产池为基础发行证券。故本题选AC选项。"},{"id":"basics2-79","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"做市商交易制度的特点有（）。","options":["做市商的收入来源是买卖证券的差价","证券成交价格的形成由做市商决定","投资者之间可以直接成交","投资者买卖证券都以做市商为对手"],"answer":"ABD","explain":"做市商的收入来源是买卖证券的差价（A选项正确）。报价驱动的特点有：第一，证券成交价格的形成由做市商决定（B选项正确）；第二，投资者买卖证券都以做市商为对手，与其他投资者不发生直接关系（D选项正确、C 选项错误）。故本题选ABD选项。"},{"id":"basics2-80","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"判断","q":"ⅠPO是首次公开发行股票的简称。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。上市公司首次融资主要是指首次公开发行股票（简称IPO），是指拟上市公司首次面向不特定的社会公众投资者公开发行股票募集资金并上市的行为。"},{"id":"basics2-81","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"判断","q":"按收益保障性分类可将结构化金融衍生产品分为股权联结型产品、利率联结型产品、汇率联结型产品和商品联结型产品等种类。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。按联结的基础产品分类（并非按收益保障性分类），结构化金融衍生产品可分为股权联结型产品（其收益与单只股票、股票组合或股票价格指数相联系）、利率联结型产品、汇率联结型产品、商品联结型产品等种类。"},{"id":"basics2-82","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"判断","q":"场外交易包括做市商交易和竞价交易。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。近年来，随着计算机和网络通信等电子技术的应用，场外交易市场和交易所市场在交易方式上日益趋同，场外交易市场也具备了计算机自动撮合的条件。目前的场外交易市场早已不再单纯地采用集中报价、分散成交的做市商模式，而是掺杂自动竞价撮合，形成混合交易模式。"},{"id":"basics2-83","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"判断","q":"场外期权交易不只是机构投资者参与。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。场外期权交易仅限专业机构投资者参与，对于一般法人和机构投资者，其交易对手仅限符合一定条件的机构投资者，比如经验丰富的投资银行、商业银行等专业金融机构，期权合约的内容、交易方式等均由经验丰富的交易对手设计。"},{"id":"basics2-84","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"判断","q":"风险覆盖率和资本杠杆率是重要的证券公司净资本监管工具，二者相辅相成、相互配合，促使证券公司在资产规模和风险水平方面寻求平衡，在业务发展和风险管理方面寻求有机统一，既要避免无节制地扩张业务，又要防止为追求利润过度发展高风险业务。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。风险覆盖率和资本杠杆率是重要的证券公司净资本监管工具，二者相辅相成。基于风险资本准备的风险覆盖率能防范证券公司背离审慎经营原则、过度积聚高风险资产。基于表内外资产总额的资本杠杆率可以反映总资产规模带来的风险，避免粗放式经营下规模过度扩张。两个指标相互配合，促使证券公司在资产规模和风险水平方面寻求平衡，在业务发展和风险管理方面寻求有机的统一，既要避免无节制地扩张业务，又要防止为追求利润过度发展高风险业务。"},{"id":"basics2-85","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"判断","q":"风险容忍度更接近于业务单元与实际风险特征联系紧密，通常采用\"自下而上\"和\"自上而下\"相结合的方式设定。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。风险偏好的设定通常从战略角度出发，采取\"自上而下\"的设定方法；而风险容忍度更接近于业务单元，与实际风险特征联系紧密，通常采用\"自下而上\"和\"自上而下\"相结合的方式设定。"},{"id":"basics2-86","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"判断","q":"附息债券与累息债券的区别在于支付利息的频率不同。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。附息债券的合约中明确规定，在债券存续期内，对持有人定期支付利息（通常每半年或每年支付一次）。息票累积债券（即累息债券）与附息债券相似，也规定了票面利率，但是债券持有人必须在债券到期时一次性获得本息，存续期间没有利息支付。因此付息债券和累息债券的区别在于支付利息的频率不同。附息债券定期支付利息，累息债券到期一次支付利息。"},{"id":"basics2-87","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"判断","q":"根据《证券公司监督管理条例》，证券公司从事证券经纪业务，可以委托证券公司以外的金融机构作为证券经纪人，代理其进行客户招揽、客户服务等活动。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。根据《证券公司监督管理条例》，证券公司从事证券经纪业务，可以委托证券公司以外的人员作为证券经纪人（委托自然人而非机构），代理其进行客户招揽、客户服务。"},{"id":"basics2-88","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"判断","q":"根据金融资产确认和计量的会计准则，一旦被确认为衍生产品或可分离的嵌入式衍生产品，相关机构应把这一部分资产归入交易性资产类别，按照公允价格计价。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。根据金融资产确认和计量的会计准则，一旦被确认为衍生产品或可分离的嵌入式衍生产品，相关机构就要把这一部分资产归入交易性资产类别，按照公允价格计价。"},{"id":"basics2-89","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"判断","q":"股票和债券都是直接投资的金融工具，筹集的资金主要投向实业。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。股票和债券是直接投资工具，筹集的资金主要投向实业；而基金是间接投资工具，筹集的资金主要投向有价证券等金融工具。"},{"id":"basics2-90","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"判断","q":"货币供应量增加，实际利率下降，投资增加，总产出增加。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。货币供应量↑→市场货币供给过剩，资金价格（实际利率）↓→企业融资成本降低，投资意愿上升，投资I↑→总产出↑。"},{"id":"basics2-91","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"判断","q":"金融市场只能通过政府干预性的价格决定利率，将货币资金配置到生产效率最高的经济主体或部门，使这些部门能够获得更多的生产要素，从而提高全社会的产出，使资源的利用效率得到提高。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。金融市场通过竞争性的价格决定利率，将货币资金配置到生产效率最高的经济主体或部门，使这些部门能够获得更多生产要素（土地、资本、技术、劳动力），从而提高了全社会的产出，使资源的利用效率得到提高。"},{"id":"basics2-92","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"判断","q":"金融债券一般不记名、不挂失，但可以抵押和转让。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。金融债券作为债券的一种特殊类型，它具有的特点之一是金融债券一般不记名、不挂失，但可以抵押和转让。"},{"id":"basics2-93","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"判断","q":"可转换债券的回购是指当公司股票价格在一段时间内连续高于转换价格达到一定幅度时，可转换公司债券持有人按事先约定的价格将所持可转换债券卖给发行人的行为。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。可转换公司债券的赎回条件一般是当公司股票价格在一段时间内连续高于转换价格达到一定幅度时，公司可按照事先约定的赎回价格买回发行在外尚未转股的可转换债券。可转换公司债券的回售是指公司股票在一段时间内连续低于转换价格达到某一幅度时，可转换债券持有人按事先约定的价格将所持可转换债券卖给发行人的行为。"},{"id":"basics2-94","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"判断","q":"目前，在我国基金投资活动中，基金买卖股票按照0.1%的税率征收交易印花税，即对印花税实行双向征收。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。基金卖出股票按照0.05%（并非0.1%）的税率征收交易印花税，买入交易不征收印花税，即对印花税实行单向征收。"},{"id":"basics2-95","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"判断","q":"募集证券投资基金有一定人数和募集基金限额要求。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。封闭式基金需满足募集的基金份额总额达到核准规模的80%以上，并且基金份额持有人人数达到200人以上；开放式基金需满足募集份额总额不少于 2亿份，基金募集金额不少于 2亿元人民币，基金份额持有人的人数不少于200人。"},{"id":"basics2-96","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"判断","q":"企业市场化并购重组，促进产业整合，是解决产能过剩问题的重要手段。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。大力推进企业市场化并购重组，促进产业整合，是解决产能过剩问题的重要手段。"},{"id":"basics2-97","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"判断","q":"首次公开发行证券，持有一定数量的非限售股份或国债的投资者才能参与网上申购。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。首次公开发行证券，网上投资者应当持有一定数量非限售股份或存托凭证（并非\"国债\"），并自主表达申购意向，不得概括委托证券公司进行证券申购。采用其他方式进行网上申购和配售的，应当符合中国证监会的有关规定。"},{"id":"basics2-98","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"判断","q":"特殊目的机构（SPV）是以资产证券化为目的而特别组建的独立法律主体，其负债主要是发行的资产支持债券，资产则是向发起人购买的基础资产，SPV是介于发起人和投资者之间的中介机构，是资产支持证券的真正发行人。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。特殊目的机构（SPV）是以资产证券化为目的而特别组建的独立法律主体，其负债主要是发行的资产支持债券，资产则是向发起人购买的基础资产。SPV是介于发起人和投资者之间的中介机构，是资产支持证券的真正发行人。"},{"id":"basics2-99","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"判断","q":"投资者申请开立A股账户时，开户代理机构应当为其同时开立沪市及深市 A股账户，投资者确有需要开立单边A股账户的除外。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。中国证券登记结算有限责任公司依投资者申请为其开立一码通账户及相应的子账户。投资者申请开立A股账户时，开户代理机构应当为其同时开立沪市及深市 A股账户，投资者确有需要开立单边A股账户的除外。"},{"id":"basics2-100","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"判断","q":"投资者应当以书面形式承诺其符合合格投资者标准，投资者的评估结果有效期最长不得超过5年。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。在向投资者推介私募基金之前，募集机构应当采取问卷调查等方式履行特定对象确定程序，对投资者的风险识别能力和风险承担能力进行评估。投资者应当以书面形式承诺其符合合格投资者标准。投资者的评估结果有效期最长不得超过 3年（并非5年）。"},{"id":"basics2-101","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"判断","q":"委托指令应当包括下列内容：证券账户号码、证券代码、买卖方向、委托数量、委托价格、交易所及其会员要求的其他内容。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。委托指令应当包括下列内容：证券账户号码、证券代码、买卖方向、委托数量、委托价格、交易所及其会员要求的其他内容。"},{"id":"basics2-102","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"判断","q":"在信用风险分析中，违约依然是最为重要的信用事件，对信用风险的描述和量化仍然以违约为中心，主要包括违约概率、违约损失率和违约时的风险暴露等。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。信用风险的构成要素分析以违约为中心。尽管现代信用风险概念已经从单纯的违约风险发展到包括信用等级变化的更加全面的信用风险，但在信用风险分析中，违约依然是最为重要的信用事件，对信用风险的描述和量化仍然是以违约为中心，主要包括违约概率、违约损失率和违约时的风险暴露等。"},{"id":"basics2-103","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"判断","q":"在中央银行的职能中，\"政府的银行\"的职能主要是指垄断发行货币、调节货币供应量。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。\"发行的银行\"是指中央银行垄断货币发行权，是全国唯一有权发行货币的机构。货币发行权经国家以法律形式授予，中央银行还对调节货币供应量、保证货币流通的正常与稳定负有责任。\"政府的银行\"是指中央银行代表国家制定和执行货币政策，处理对外金融关系，为国家提供各种金融服务。"},{"id":"basics2-104","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"判断","q":"债券的特征包括偿还性，波动性和收益性。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。债券的特征：偿还性、流动性、安全性、收益性（不包括\"波动性\"）。"},{"id":"basics2-105","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"判断","q":"证券服务机构是指会计师事务所、律师事务所以及从事证券投资咨询、资产评估、资信评级、财务顾问、信息技术系统服务的证券服务机构。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。证券服务机构，是指依法设立的从事证券服务业务的法人机构，包括会计师事务所、律师事务所以及从事证券投资咨询、资产评估、资信评级、财务顾问、信息技术系统服务的证券服务机构。"},{"id":"basics2-106","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"判断","q":"证券公司进行压力测试应遵循全面性、实践性、审慎性和前瞻性原则。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。证券公司在进行压力测试，应当遵循以下原则：（1）全面性原则：证券公司压力测试应当全面覆盖公司各个业务领域、所有子公司以及比照子公司管理的各类孙公司（统称\"子公司\"）的各类风险，并充分考虑各类风险间的相关性。（2）实践性原则：证券公司开展压力测试的流程与方法应当具备针对性和可操作性，与经营管理实践紧密结合，压力测试结果应当在风险管理和经营决策中得到有效应用。（3）审慎性原则：证券公司开展压力测试所选用的风险因素、数量模型、情景假设应当审慎合理，符合行业和公司实际，以利于科学分析各类风险的特征及其对各项业务的影响。（4）前瞻性原则：证券公司开展压力测试应当综合考虑宏观经济运行周期、行业发展变化趋势以及公司发展战略规划，合理预见各种可能出现的极端不利情况和风险。"},{"id":"basics2-107","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"判断","q":"证券经纪商要根据证券交易所的交易规则，对客户的证件和委托单在合法性和真实性方面进行审查。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。证券经纪商要根据证券交易所的交易规则，对客户的证件和委托单在合法性和同一性（并非真实性）方面进行审查。"},{"id":"basics2-108","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"判断","q":"政府债券最初仅是政府弥补财政赤字的手段，但在现代商品经济条件下，政府债券已经成为政府筹集资金、扩大公共开支的重要手段，也是进行宏观调控的工具。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。政府债券的性质：（1）从形式上看，政府债券是一种有价证券，具有债券的一般性质。政府债券本身有面额，投资者投资于政府债券可以取得利息，因此政府债券具备了债券的一般特征。（2）从功能上看，政府债券最初仅是政府弥补赤字的手段，但在现代商品经济条件下，政府债券已成为政府筹集资金、扩大公共开支的重要手段，并且随着金融市场的发展，逐渐具备了金融商品和信用工具的职能，成为国家实施宏观经济政策、进行宏观调控的工具。"},{"id":"basics2-109","subject":"basics","source":"2026.09 LC终极押题 · 押题卷二","type":"判断","q":"中长期银行贷款市场属于资本市场。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。资本市场，是指所交易金融资产到期期限在1 年以上或者没有到期期限的金融市场，如股票市场、中长期国债市场、中长期银行贷款市场等。"}]},{"id":"advisor1","subject":"advisor","name":"证券投顾 · 押题卷一","stats":{"单选":40,"多选":40,"判断":20,"案例":20},"questions":[{"id":"advisor1-0","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"单选","q":"（），即由于基础资产市场价格的不利变动或者急剧波动而产生的风险暴露。","options":["风险敞口","下行风险","单向敞口","双向敞口"],"answer":"A","explain":"A 选项正确，在对冲交易中，风险敞口通常是指市场风险敞口，即由于基础资产市场价格的不利变动或者急剧波动而产生的风险暴露。故本题选A选项。【温馨提示】（1）行风险是指低于设定阈值的收益率相对于该阈值的标准差，该阈值通常是指投资者愿意接受的最低收益率。（2）单向敞口指仅暴露在单一方向的价格变动风险中（比如只担心汇率升值或只担心利率下跌）。（3）双向敞口指同时暴露在价格涨跌两个方向的风险中，比如既可能因汇率涨受损，也可能因汇率跌受损。"},{"id":"advisor1-1","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"单选","q":"（）是对剩余流动性的弹性。","options":["估值杠杆","利润杠杆","运营杠杆","财务杠杆"],"answer":"A","explain":"在不同行业轮动介入时点的选择上，存在三种杠杆：①财务杠杆，对利率的弹性（D选项错误）；②运营杠杆，对经济的弹性（C选项错误）；③估值杠杆，对剩余流动性的弹性（A选项正确）。B选项错误，通常指企业利润对收入或成本的敏感度，与剩余流动性无直接关联。故本题选A选项。"},{"id":"advisor1-2","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"单选","q":"（）是利用统计、数值模拟和其他定量模型进行证券市场相关研究的方法。","options":["量化分析法","技术分析法","基本分析法","统计分析法"],"answer":"A","explain":"A 选项正确，量化分析法是利用统计、数值模拟和其他定量模型进行证券市场相关研究的一种方法，具有使用大量模型、数据的显著特点，广泛应用于解决证券估值、组合构造与优化、策略制定、绩效评估、风险计量与风险管理等投资相关问题，是继传统的基本面分析和技术分析之后发展起来的一种重要的证券投资分析方法。B 选项错误，技术分析是以证券市场过去和现在的市场行为作为分析对象，应用数学方法探索出一些典型变化规律，并据此预测证券市场未来变化趋势的技术方法。C 选项错误，基本分析法是指根据经济学、金融学、财务管理学及投资学等基本原理，对决定证券价值及价格的基本要素进行分析，从而评估证券的投资价值，判断证券的合理价位，提出相应投资建议的一种分析方法。D 选项错误，统计分析法泛指一般统计方法（如回归分析、相关性分析），虽涉及数据建模，但未特指证券市场的复杂数值模拟和定量策略。故本题选A选项。"},{"id":"advisor1-3","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"单选","q":"常见的市场风险计量指标包括（）指标和总量类指标。","options":["趋势性","敏感性","结构性","业务性"],"answer":"B","explain":"B选项符合题意，常见的市场风险计量指标包括敏感性指标和总量类指标。故本题选B选项。"},{"id":"advisor1-4","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"单选","q":"从家庭生命周期不同阶段的保险安排来看，成熟期家庭的理财重点是（）。","options":["寿险保额","养老保险或递延年金","长期看护险","教育年金"],"answer":"B","explain":"从家庭生命周期不同阶段的保险安排来看，成熟期家庭的理。故本题选B选项。"},{"id":"advisor1-5","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"单选","q":"从经济学角度讲，\"套利\"可以理解为（）。","options":["人们利用不同证券或组合的期望收益率不同，通过调整不同证券或组合的构成比例而实现有风险收益的行为","人们利用不同证券或组合的期望收益率不同，通过调整不同证券或组合的构成比例而实现无风险收益的行为","人们利用同一资产在不同市场间定价不一致，通过资金的转移而实现有风险收益的行为","人们利用同一资产在不同市场间定价不一致，通过资金的转移而实现无风险收益的行为"],"answer":"D","explain":"D 选项正确，从经济学的角度讲，套利是指利用同一资产在不同市场间定价的不一致，通过资金的转移而实现无风险收益的行为。故本题选D选项。"},{"id":"advisor1-6","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"单选","q":"风险资产的预期报酬率与其所承担的系统风险 β 系数之间呈线性关系，充分体现了风险与收益相匹配的原则的方程式是（）。","options":["证券市场线方程","证券特征线方程","资本市场线方程","马柯威茨方程"],"answer":"A","explain":"A选项正确，证券市场线很清晰地反映了风险资产的预期报酬率与其所承担的系统风险β系数之间呈线性关系，充分体现了风险与收益相匹配的原则。B 选项错误，指单个资产超额收益与市场超额收益的回归方程，它不是用来给出预期收益与 β的关系，而是描述实际收益的生成过程。C选项错误，描述有效投资组合的预期收益率与总风险（标准差）的关系，不是与β的线性关系。D 选项错误，指马柯威茨投资组合理论，涉及均值-方差模型，并非直接给出预期收益率与 β的线性方程。故本题选A选项。"},{"id":"advisor1-7","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"单选","q":"个人在社会群体压力下，放弃自己的意见，采取与大多数人一致的行为现象称为（）。","options":["反应不足","羊群行为","控制力幻觉","过度反应"],"answer":"B","explain":"B 选项正确，\"羊群效应\"也称\"从众效应\"，是指个人的观念或行为由于真实的或想象的群体的影响或压力，而向与多数人相一致的方向变化的现象。故本题选B选项。"},{"id":"advisor1-8","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"单选","q":"根据移动平均法，如果某只股票价格超过平均价的某一百分比时，应该（）。","options":["买入","卖出","清仓","满仓"],"answer":"A","explain":"A 选项正确，移动平均法的实质是简单过滤器规则的一种变形。它是以一段时期内的股票价格移动平均值为参考基础，根据股票价格与该平均价之间的差额，在价格超过平均价的某一百分比时买入该股票，在股票价格低于平均价的一定百分比时卖出该股票。故本题选A选项。"},{"id":"advisor1-9","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"单选","q":"关于适当性匹配说法正确的是（）。","options":["特定的投资者购买恰当的产品","适合的投资者购买低风险的产品","适合的投资者购买恰当的产品","特定的投资者购买低风险的产品"],"answer":"C","explain":"C 选项正确，适当性匹配是证券公司、证券投资咨询机构开展投资顾问业务需要履行的职责。该职责旨在确保证券经营机构向适当的投资者提供适当的金融产品或服务，确保投资者具备必要的专业知识、经验和风险承受能力，并了解与其投资目标相关的各类风险。故本题选C选项。"},{"id":"advisor1-10","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"单选","q":"关于套利，下列说法正确的是（）。","options":["当投资者不需要任何投资就可以获得低风险收益时，他们就是在套利","套利机会的存在意味着市场处于不均衡状态","套利只存在单一资产上","套利机会可以长久地存在下去"],"answer":"B","explain":"B 选项正确，套利是指不需要追加投资就可获得收益的买卖行为。从经济学的角度讲，套利是指利用同一资产在不同市场间定价的不一致，通过资金的转移而实现无风险收益的行为。随着套利的进行，差价会慢慢变小直至消失。A选项错误，不是低风险收益，而是无风险收益。C选项错误，套利不一定只存在单一资产上，也可以构建套利组合。D选项错误，套利机会不会长久的存在下去。故本题选B选项。"},{"id":"advisor1-11","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"单选","q":"关于头肩顶形态中的颈线，以下说法不正确的是（）。","options":["头肩顶形态中，它是支撑线，起支撑作用","突破颈线一定需要大成交量配合","当颈线被突破，反转确认以后，大势将下跌","如果股价最后在颈线水平回升，而且回升的幅度高于头部，或者股价跌破颈线后又回升到颈线上方，这可能是一个失败的头肩顶，宜作进一步观察"],"answer":"B","explain":"B选项错误，突破颈线不一定需要大成交量配合，但日后继续下跌时成交量会放大。故本题选B选项。"},{"id":"advisor1-12","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"单选","q":"国际资本流动造成外汇市场和汇率的波动。国际资本流入将导致（）。","options":["对本币的兑换需求下降，本币贬值","对本币的兑换需求下降，本币升值","对本币的兑换需求上升，本币贬值","对本币的兑换需求上升，本币升值"],"answer":"D","explain":"D 选项正确，国际资本流入外币必须兑成本币才能使用，所以会导致对本币的兑换需求上升，本币升值。故本题选D选项。"},{"id":"advisor1-13","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"单选","q":"基金投资顾问机构开展管理型基金投资顾问业务的，应当（）披露委托资产参考市值，基金投资顾问机构应当建立复核机制，确保市值信息的真实完整。","options":["每日","每周","每月","每季"],"answer":"A","explain":"A 选项正确，基金投资顾问机构开展管理型基金投资顾问业务的，应当每日披露委托资产参考市值，基金投资顾问机构应当建立复核机制，确保市值信息的真实、完整。故本题选A选项。"},{"id":"advisor1-14","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"单选","q":"基金投资管理过程中，投资决策委员会负责决定的内容包括（）。","options":["投资原则","投资指令","投资策略","投资权限"],"answer":"C","explain":"C选项正确，根据《管理规定》的要求，下列事项应当经投资决策委员会审议决策：（1）生成基金组合策略；（2）调整基金组合策略的风险等级、目标资产配置比例、目标风险收益等重要属性；（3）决策基金出、入基金备选库；（4）调整基金组合策略具体基金品种、数量；（5）授权策略经理调整基金组合策略具体基金品种、数量；（6）确定基金组合策略说明书内容；（7）其他基金投资顾问业务投资决策的重大事项。故本题选C选项。"},{"id":"advisor1-15","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"单选","q":"技术分析理论不包括（）。","options":["切线理论","资本资产定价理论","波浪理论","循环周期理论"],"answer":"B","explain":"技术分析的主要理论：道氏理论、K 线理论、切线理论（A 选项不符合题意）、形态理论、波浪理论（C选项不符合题意）、量价关系理论、循环周期理论（D选项不符合题意）。B选项符合题意，技术分析理论不包括资本资产定价理论。故本题选B选项。"},{"id":"advisor1-16","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"单选","q":"家庭状况会影响个人投资者的投资需求，家庭状况不包括（）。","options":["子女的数量与年龄","需赡养老人的数量和健康状况","个人投资者的工作稳定性","婚姻状况"],"answer":"C","explain":"A、B、D 选项不符合题意，个人投资者的家庭状况（比如婚姻状况、子女数量和年龄、需赡养老人数量和健康状况）对其投资需求会产生较大的影响。故本题选C选项。"},{"id":"advisor1-17","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"单选","q":"某 5 年期债券，面值为 100 元，票面利率为 10%，单利计息，市场利率为 10%，到期一次还本付息，则该债券的麦考利久期为（）年。","options":["3","3.5","4","5"],"answer":"D","explain":"该债券为到期一次还本付息结构（仅期末产生单笔现金流），且市场利率与票面利率相同，此类债券的麦考利久期恒等于其到期期限，即其麦考利久期为5年。故本题选D选项。"},{"id":"advisor1-18","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"单选","q":"某公司的可转换债券，面值为 1000 元，转换价格为 25 元，当前的市场价格为 1150 元，其标的股票当前的市场价格为27元，该债券的转换价值为（）。","options":["1150元","1080元","926元","1000元"],"answer":"B","explain":"B选项正确，该可转换债券的转换比率=可转换面值／转换价格=1000/25=40；转换价值=股票价格×转换比率=27×40=1080（元）。故本题选B选项。"},{"id":"advisor1-19","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"单选","q":"某投资者用952元购买了一张面值为1000元的债券，息票利率10%，每年付息一次，距到期日还有3年，试计算其到期收益率（）。","options":["15%","14%","12%","8%"],"answer":"C","explain":"设到期收益率为 x，则有：952=100／（1+x）+100／（1+x）2+1100／（1+x）3，解得：x=12％（C选项正确）。故本题选C选项。"},{"id":"advisor1-20","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"单选","q":"普通投资者应在（）不享有特别保护。","options":["信息告知","风险警示","投资收益","适当性匹配"],"answer":"C","explain":"专业投资者之外的投资者为普通投资者，普通投资者在信息告知（A 选项不符合题意）、风险警示（B选项不符合题意）、适当性匹配（D 选项不符合题意）等方面享有特别保护。C选项符合题意，普通投资者应在投资收益不享有特别保护。故本题选C选项。"},{"id":"advisor1-21","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"单选","q":"市场预期理论认为利率期限结构完全取决于对未来即期利率的市场预期，局限在于不能解释收益率曲线通常是（）。","options":["向下倾斜的","水平的","向上倾斜的","拱形的"],"answer":"C","explain":"C选项正确，市场预期理论不可以解释收益率曲线是通常向上倾斜的。A、B、D 选项错误，可以解释：不同期限的债券倾向于同向运动的原因；短期利率较低时，收益率曲线倾向于向上倾斜，而短期利率较高时，收益率曲线向下倾斜的原因。故本题选C选项。"},{"id":"advisor1-22","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"单选","q":"收益率曲线的类型不包括（）。","options":["正向的利率曲线","反向的利率曲线","平直的利率曲线","垂直的利率曲线"],"answer":"D","explain":"收益率曲线是描绘债券即期利率与期限关系的曲线。从形状上来看，收益率曲线主要包括四种类型：①正向的利率曲线（A选项不符合题意）；②反向的利率曲线（B选项不符合题意）；③一条平直的利率曲线（C选项不符合题意）；④拱形利率曲线。故本题选D选项。【温馨提示】收益率曲线是描绘债券即期利率与期限关系的曲线。从形状上来看，收益率曲线主要包括四种类型：①正向的利率曲线，一条向上倾斜的利率曲线，表示期限越长的债券利率越高。②反向的利率曲线，一条向下倾斜的利率曲线，表示期限越长的债券利率越低。③一条平直的利率曲线，表示不同期限的债券利率相等，这通常是正利率曲线与反利率曲线转化过程中出现的暂时现象。④拱形利率曲线，表示期限相对较短的债券，利率与期限呈正向关系；期限相对较长的债券，利率与期限呈反向关系。"},{"id":"advisor1-23","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"单选","q":"套利定价理论的创始人是（）。","options":["威廉夏普","史蒂芬·罗斯","莫辛","马科维茨"],"answer":"B","explain":"B 选项正确，1976 年，美国学者斯蒂芬 D 罗斯在《经济理论杂志》上发表了经典论文\"资本资产定价的套利理论\"，提出了一种新的资产定价模型，此即套利定价理论（APT）。故本题选B选项。"},{"id":"advisor1-24","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"单选","q":"通常，对于（）型投资者而言，倾向于在保证本金的基础上维持资金增值，进而选择低风险投资产品。","options":["成长","保守","稳健","激进"],"answer":"B","explain":"B 选项正确，保守型客户通常为步入退休阶段的老年人群、低收入家庭、家庭负担较重、性格保守的投资者，在选择一项产品或投资工具时，首先考虑是否能够保本，然后才考虑追求收益。保守型客户适合投资于风险极低的投资工具，如国债、货币市场基金、债券基金等。A 选择错误，成长型客户可以选择适合长期持有、收益较高、风险较低的投资工具，如开放式股票基金、大型蓝筹股票等。C选项错误，稳健型客户适合投资低风险的投资工具，如银行理财产品等。D 选项错误，激进型投资者追求高收益且能接受高风险（如杠杆产品、股票），与\"低风险\"直接矛盾，排除。故本题选B选项。"},{"id":"advisor1-25","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"单选","q":"投资顾问业务的私人银行的起源是（）。","options":["英国伦敦","瑞士日内瓦","德国慕尼黑","荷兰阿姆斯特丹"],"answer":"B","explain":"B选项正确，第一阶段是萌芽期，在16世纪的瑞士日内瓦，第一批从事投资顾问业务的私人银行家出现，主要服务于达官贵族的财富管理需要，提供财务咨询、投资规划等全方位、定制化的服务。故本题选B选项。"},{"id":"advisor1-26","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"单选","q":"为推进利率市场化改革，提高金融机构自主定价能力健全货币政策传导机制，培育货币市场基准利率，（）于2007年开始试运行上海银行间同业拆借利率。","options":["中国人民银行","中国证监会","财政部","中国银监会"],"answer":"A","explain":"为推进利率市场化改革，提高金融机构自主定价能力，健全货币政策传导机制，培育货币市场基准利率，中国人民银行于2007开始试运行上海银行间同业拆借利率。故本题选A选项。"},{"id":"advisor1-27","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"单选","q":"下列对个人资产负债表的理解错误的一项是（）。","options":["资产负债表的记账法遵循会计恒等式\"资产=负债+净资产\"","资产负债表可以反映客户的动态财务特征","客户的资产负债表是记录和分析客户资产和负债状况的重要工具","编制资产负债表时，首要考虑确定报表时点，即月末、季末或年末"],"answer":"B","explain":"B 选项错误，资产负债表又称财务状况表，是反映某一时点财务状况的会计报表。资产负债表利用会计平衡原则，即净资产=资产-负债，将\"资产、负债、净资产\"科目，以特定日期的静态（并非动态）情况为基准，编制成一张报表。故本题选B选项。"},{"id":"advisor1-28","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"单选","q":"下列关于客户投资目标分类的说法中，错误的是（）。","options":["按照时间的长短可以分为短期目标、中期目标和长期目标","休假、购置新车等属于短期目标","短期、中期、长期目标之间的界限是绝对分明的","退休保障安排、遗产安排等属于长期目标"],"answer":"C","explain":"A选项正确，按照时间的长短可以将证券投资目标分为短期目标、中期目标和长期目标。C 选项错误，短期目标、中期目标和长期目标之间的界限并不是绝对的，相同的投资目标对于不同的客户其分类可能不同，需要根据客户的实际情况来界定和划分。B 选项正确，短期目标通常是指在未来一到两年内需要实现的目标。这些目标可能包括紧急的资金需求、短期项目的资金支持、应急备用金、支付特定费用或旅行计划等。在短期目标中，保持资金的流动性和安全性往往是关键考虑因素。中期目标是指在未来三到五年内需要实现的目标。这些目标可能包括购买房产、子女的教育金、中期旅行计划、创业或扩大业务的启动资金等。在中期目标中，除了保持一定的流动性外，投资回报和资本增值也是重要的考虑因素。D 选项正确，长期目标通常是指在未来 5 年以上的时间跨度内需要实现的目标。这些目标可能包括养老金储备、财富增长和资产传承等。在长期目标中，资本增值、复利效应和风险管理是重要的考虑因素。故本题选C选项。"},{"id":"advisor1-29","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"单选","q":"下列关于生命周期理论的表述，不正确的是（）。","options":["个人在不同阶段的消费水平应相对平滑，而不要出现大幅波动","个人是在相当长的时间内计划他的消费和储蓄行为的","个人希望在整个生命周期实现消费和储蓄的最佳配置","个人在决定目前消费和储蓄时，其主要考虑的因素是未来收入、可预期的支出以及工作时间、退休时间等，而无须关注即期收入"],"answer":"D","explain":"生命周期理论是由美国经济学家 F.莫迪利安尼、R.布伦博格与 A.安多共同创建的，该理论创造性地将个人储蓄、消费行为和终身收入联系起来，明确人的消费和储蓄决策应充分考虑自己的现实财富、未来预期收入、未来预期支出等诸多因素，在长期内做好消费和储蓄规划（B 选项正确），避免在一生之中的消费水平出现较大的波动（A 选项正确），以获得人生效用的最大化。该理论从个人的生命周期消费计划出发，最终创建了消费与储蓄的宏观经济理论（C 选项正确），也称消费与储蓄的生命周期假说。D 选项错误，个人在决定目前消费和储蓄时，不光要考虑未来收入、可预期的支出以及工作时间、退休时间等，还需要关注即期收入。故本题选D选项。"},{"id":"advisor1-30","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"单选","q":"下列关于债务规划的说法中错误的是（）。","options":["偿还高利率信用贷款时，采取本金摊还款法可以更快地还清本金","通常应优先偿还临近到期的借款","债务整合规划是在降低总负担的前提下，把不同贷款机构的贷款整合在一家","转贷规划是以高利率负债置换低利率负债"],"answer":"D","explain":"债务规划通常应优先偿还临近到期的借款（B 选项正确），偿还高利率信用贷款时，采取本金平均摊还法可以更快地还清本金（A 选项正确），债务整合规划是在降低总负担的前提下，把不同贷款机构的贷款整合在一家（C选项正确）。D选项错误，转贷规划的目的是以低利率负债置换高利率负债，降低利息支出。故本题选D选项。"},{"id":"advisor1-31","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"单选","q":"下列信息中属于客户的定量信息的是（）。","options":["健康状况","收入与支出","金钱观","风险特征"],"answer":"B","explain":"B 选项正确，定量信息包括客户的年龄、收入水平、资产负债状况、投资组合、投资经验、风险承受能力等信息。故本题选B选项。"},{"id":"advisor1-32","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"单选","q":"向客户提供证券投资顾问服务的人员应当符合相关从业条件，并在（）注册登记为证券投资顾问。","options":["证券公司","中国证监会","国务院证券监督管理机构","中国证券业协会"],"answer":"D","explain":"A选项错误，证券公司是业务开展主体，但注册登记职能由行业协会承担。B选项错误，证监会负责监督管理，不直接负责从业人员注册。C选项错误，国务院证券监督管理机构与证监会职能重叠，法规中未赋予其注册职责。D 选项正确，向客户提供证券投资顾问服务的人员应当符合相关从业条件，并在中国证券业协会注册登记为证券投资顾问。故本题选D选项。"},{"id":"advisor1-33","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"单选","q":"已知无风险回报率为6%，市场要求的回报率为12%，某公司股票的β为1.5，如果去年公司每股股息2.5，股息增长率持续保持在5%，则该公司的股票估值为（）元。","options":["3.75","7.25","26.25","13.25"],"answer":"C","explain":"根据资本资产定价模型：E（Ri）=Rf+βi×[E（RM）-Rf]。其中，E（Ri）为资产 i 的预期收益率，E（RM）为市场组合的预期收益率，Rf 为无风险收益率，βi为资产i 的β系数。将题干给的数据代入公式：计算必要收益率为E（Ri）=6%+1.5（12%-6%）=15%；根据题意，股息增长率持续保持为5%，是股息增长模型中的不变增长模型V=D1/（k-g），V是股票的内在价值；D1 是下一期股利，D0 计算，D0×（1+g）；k 是必要收益率；g 是股利增长率。代入公式为V=2.5×（1+5%）÷（15%-5%）=26.25元（C选项正确）。故本题选C选项。"},{"id":"advisor1-34","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"单选","q":"用来反映证券组合期望收益水平和总风险水平之间均衡关系的方程式是（）。","options":["证券市场线方程","证券特征线方程","资本市场线方程","套利定价方程"],"answer":"C","explain":"A项错误，证券市场线方程反映任意证券或组合的期望收益率和风险之间的关系。B项错误，证券特征线方程用于描述一种证券实际收益率的方程。C 项正确，资本市场线方程对有效组合的期望收益率和风险之间的关系提供了十分完整的阐述。D 项错误，套利定价方程反映证券组合期望收益水平和多个因素风险水平之间均衡关系的方程。故本题选C选项。"},{"id":"advisor1-35","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"单选","q":"预计某公司的股息每股每年约增长5%，如果上年的股息是每股8元，市场资本化率为每年10%利用股息贴现模型（DDM），当前公司的股价为（）元。","options":["168","56","16","84"],"answer":"A","explain":"由不变增长模型V=D0（1+g）／（r-g）。可得：如果股息每股每年增长 5％，则当前公司的股价 =8×（1+5％）／（10％-5％）=168（元）（A选项正确）。故本题选A选项。"},{"id":"advisor1-36","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"单选","q":"在凯恩斯学派的货币政策传导理论中，其传导机制的核心是（）。","options":["基础货币","货币乘数","利率","货币供应量"],"answer":"C","explain":"C 选项正确，凯恩斯学派的货币政策传导机制是：通过货币供给的增减影响利率，利率的变化则通过资本边际效益影响投资，而投资的增减进而影响总支出和总收入。这一传导机制的主要环节是利率。故本题选C选项。"},{"id":"advisor1-37","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"单选","q":"证券公司、证券投资咨询机构应当向客户提供风险揭示书，并由客户签收确认。风险揭示书内容与格式要求由（）制定。","options":["本公司","中国证监会","中国证券业协会","交易所"],"answer":"C","explain":"C 选项正确，风险揭示书内容与格式要求由中国证券业协会制定，应以书面或者电子文件形式，由投资者签收确认，并由证券投资咨询机构归入证券投资顾问业务档案保存。故本题选C选项。"},{"id":"advisor1-38","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"单选","q":"证券投资顾问依据本公司或者其他证券公司证券投资咨询机构的证券研究报告作出投资建议的，应当向客户说明（）。","options":["证券投资顾问本人关于证券研究报告的观点","证券研究报告的发布人、发布日期","除作为依据之外的第三方证券研究报告的观点","与该证券研究报告冲突的其他证券研究报告的观点"],"answer":"B","explain":"证券投资顾问依据本公司或者其他机构的证券研究报告作出投资建议的，应当向投资者说明证券研究报告的发布人、发布日期（B选项正确）。故本题选B选项。"},{"id":"advisor1-39","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"单选","q":"证券投资咨询机构中向客户提供证券投资顾问服务的人员应符合相关从业条件，并在协会登记为（）","options":["证券投资顾问","证券分析师","客户经理","证券经纪人"],"answer":"A","explain":"A 选项正确，证券投资咨询机构中向客户提供证券投资顾问服务的人员应符合相关从业条件，并在协会登记为证券投资顾问。故本题选A选项。"},{"id":"advisor1-40","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"艾略特波浪理论的基本思想包括（）。","options":["斐波那奇数列是波浪理论的数学基础","艾略特的波浪理论以周期为基础","艾略特最初提出波浪理论是受股价上涨下跌现象不断重复的启发","艾略特的波浪理论与道氏理论密切相关"],"answer":"ABCD","explain":"A 选项正确，艾略特波浪理论中所用到的数字 2、3、5、8、13、21、34......都来自斐波那奇数列，这个数列是数学上很著名的数列，它有很多特殊的性质，是波浪理论的数学基础。B 选项正确，艾略特的波浪理论以周期为基础，将大的运动周期分成时间长短不同的各种周期，并指出在一个大周期之中可能存在一些小周期，而小的周期又可以再细分成更小的周期。C 选项正确，艾略特最初提出波浪理论是受到股价上涨下跌现象不断重复的启发，力图找出其上升和下降的规律。D 选项正确，与波浪理论密切相关的理论除经济周期以外，还有道氏理论和斐波那奇数列，艾略特波浪理论中的大部分理论是与道氏理论相吻合的。故本题选ABCD选项。"},{"id":"advisor1-41","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"编制个人现金流量表要符合的原则有（）","options":["真实可靠原则","反映充分原则","本币反映原则","明晰性原则"],"answer":"ABCD","explain":"编制个人现金流量表要符合的原则有：真实可靠原则（A 选项正确）、反映充分原则（B 选项正确）、明晰性原则（D 选项正确）、及时性原则、本币反映原则（C 选项正确）、充分揭示原则。故本题选ABCD选项。"},{"id":"advisor1-42","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"财政政策对证券市场的影响有（）。","options":["减少税收，降低税率，扩大减免税范围，会推动证券市场价格上涨","扩大财政支出，加大财政赤字，会推动证券市场价格上涨","减少国债发行（或回购部分短期国债），会推动证券市场上扬","增加财政补贴会推动证券市场总体水平趋于上涨"],"answer":"ABCD","explain":"实施积极财政政策对证券市场的影响如下：（1）减少税收，降低税率，扩大减免税范围，会推动证券市场价格上涨（A选项正确）。（2）扩大财政支出，加大财政赤字，会推动证券市场价格上涨（B选项正确）。（3）减少国债发行（或回购部分短期国债），会推动证券市场上扬（C选项正确）。（4）增加财政补贴会推动证券市场总体水平趋于上涨（D选项正确）。故本题选ABCD选项。"},{"id":"advisor1-43","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"反映公司投资收益的指标有（）。","options":["资本化率","每股收益","市盈率","存货周转率"],"answer":"BC","explain":"反映公司投资收益指标的主要有每股收益（B 选项正确）、市盈率（C 选项正确）、股利支付率、每股净资产等。A 选项错误，资本化率主要用于不动产评估，是净营运收入与资产价值的比率，反映不动产投资的收益率，并不是反映公司投资收益的指标。D 选项错误，存货周转率是公司一定时期内营业成本与平均存货余额的比率，即存货的周转次数，是衡量和评价公司购入存货、投入生产、销售收回等各环节管理状况的综合性指标，用于反映存货的流动性及存货占用资金的合理性，而不是反映公司投资收益。故本题选BC选项。"},{"id":"advisor1-44","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"根据《证券投资顾问业务暂行规定》，证券公司、证券投资咨询机构从事证券投资顾问业务，应当保证证券投资顾问（）与服务方式、业务规模相适应。","options":["人员数量","业务能力","合规管理","风险控制"],"answer":"ABCD","explain":"证券投资咨询机构应当建立健全证券投资顾问业务管理制度、合规管理和风险控制机制，覆盖业务推广、协议签订、服务提供、客户回访、投诉处理等业务环节；应当保证证券投资顾问人员数量（A 选项正确）、业务能力（B 选项正确）、合规管理（C 选项正确）和风险控制（D 选项正确）与服务方式、业务规模相适应。故本题选ABCD选项。"},{"id":"advisor1-45","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"根据《证券投资顾问业务暂行规定》，证券投资顾问向客户提供投资建议，应当具有合理的依据。投资建议的依据包括（）。","options":["证券研究报告","基于证券研究报告形成的投资意见","基于理论模型形成的投资意见","基于分析方法形成的投资分析意见"],"answer":"ABCD","explain":"投资建议的依据包括证券研究报告（A 选项正确）或者基于证券研究报告（B 选项正确）、理论模型（C选项正确）以及分析方法形成的投资分析意见（D选项正确）等。故本题选ABCD选项。"},{"id":"advisor1-46","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"根据《证券投资顾问业务暂行规定》的要求，证券公司、证券投资咨询机构应当对证券投资顾问（）等环节实行留痕管理。","options":["服务提供","客户回访和投诉处理","业务推广","协议签订"],"answer":"ABCD","explain":"证券公司、证券投资咨询机构应当对证券投资顾问业务推广（C 选项正确）、协议签订（D 选项正确）、服务提供（A 选项正确）、投资者回访、投诉处理（B 选项正确）等环节实行留痕管理。向投资者提供投资建议的时间、内容、方式和依据等信息，应当以书面或者电子文件形式予以记录留存。故本题选ABCD选项。"},{"id":"advisor1-47","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"根据对客户收入预测的方法，可以把客户收入分为（）。","options":["一般性收入","常规性收入","永久性收入","临时性收入"],"answer":"BD","explain":"B、D 选项正确，在预测客户的未来收入时，可以将收入分为常规性收入和临时性收入两类。故本题选BD选项。【温馨提示】在预测客户的未来收入时，可以将收入分为：（1）常规性收入也称为经常性收入、持久性收入，是可以预料的能够长期获得的基础性收入，一般是在上一年收入的基础上作出合理的预期，如工资、奖金和津贴、股票分红和债券投资收益、银行存款利息和租金收入等。（2）临时性收入也称暂时性收入、非常规收入，是由于某种偶然的机会或特殊事件导致的收入。"},{"id":"advisor1-48","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"根据美林时钟理论，关于不同经济周期的收益率的大小，下列说法正确的有（）。","options":["衰退期：债券>现金>股票>大宗商品","复苏期：股票>债券>现金>大宗商品","过热期：股票>大宗商品>现金/债券","滞胀期：现金>大宗商品/债券>股票"],"answer":"ABD","explain":"美林时钟不同经济阶段对应大类资产表现：故本题选ABD选项。"},{"id":"advisor1-49","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"根据资本资产定价模型在资源配置方面的应用，下列正确的有（）。","options":["牛市到来时，应选择那些低β系数的证券或组合","牛市到来时，应选择那些高β系数的证券或组合","熊市到来之际，应选择那些低β系数的证券或组合","熊市到来之际，应选择那些高β系数的证券或组合"],"answer":"BC","explain":"一般而言，当市场处于牛市时，在估值优势相差不大的情况下，投资者会选择 β 系数较大的股票，以期获得较高的收益（A选项错误、B 选项正确）；反之，当市场处于熊市时，投资者会选择β系数较小的股票，以减少股票下跌的损失（C选项正确、D选项错误）。故本题选BC选项。"},{"id":"advisor1-50","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"关于对客户未来支出的预测，下列说法正确的是（）","options":["通货膨胀因素是支出预期的考虑因素之一","生活质量是支出预期的考虑因素之一","为了顾及客户未来支出，首先要考虑客户基本生活的支出","客户未来支出还包括临时性支出"],"answer":"ABC","explain":"D选项错误，估计客户的未来支出，需要了解两种不同状态下的客户支出。一是满足客户基本生活的支出。基本生活并非指仅实现基本生活状态的生活水平，而是指在保证客户正常生活水平不变的情况下，考虑了通货膨胀后的支出数额预测（C选项正确）。二是客户期望实现的支出水平。很多客户在维持现有消费水平的基础上，都期望能够进一步提高生活质量。因此，应根据客户的要求制定出客户期望实现的支出水平（B选项正确）。无论是预测客户基本生活必需的支出，还是其期望达到的消费水平支出，都要考虑客户所在地区的通货膨胀水平，这一数据可以从有关部门公布的经济统计数据中获得（A选项正确）。故本题选ABC选项。"},{"id":"advisor1-51","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"关于紧急预备金的储存方式，下列说法正确的有（）。","options":["以存款作为储备金可能无法达到长期投资的平均报酬率","以贷款额度作为预备金，需要考虑支付的利息","紧急预备金通常包括两种方式","存贷款利率的差距越大，越需要利用贷款额度作为预备金"],"answer":"ABC","explain":"紧急预备金可以用两种方式来储备（C选项正确）：一是持有期限短、流动性强、容易变现、价值变动风险很小的金融工具，包括活期存款、短期定期存款、货币市场基金等；二是未使用的贷款融资额度和信用卡额度。需注意的是，以存款作为储备保持了资金的流动性，但由于现金类资产的收益率普遍较低，投资者可能无法达到长期投资的平均报酬率（A选项正确）。而以贷款额度作为预备，一旦动用就要支付相对较高的利息（B 选项正确），如果只是紧急情况下的临时支用，借款时间通常较短，虽然利率较高，但实际使用时间不长，财务负担也不会很大，最好的方式是将二者搭配使用（D选项错误）。故本题选ABC选项。"},{"id":"advisor1-52","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"关于自下而上的分析方法，下列说法正确的有（）。","options":["自下而上的分析法注重对股票趋势的把握","根据投资目标，通过一系列的公司财务指标等选出投资个股的选择","自下而上的分析法更注重个股的选择，忽略市场的短期波动","巴菲特是采用\"自下而上\"分析法的典范"],"answer":"BCD","explain":"A 选项错误，自下而上分析法更侧重于关注个股的具体情况和公司的经营状况，而不过分关注市场整体的走势和趋势。B、C 选项正确，自下而上分析法则是以个股为切入点，通过财务指标分析寻找具有潜力的公司进行投资，并且在该板块或行业中筛选出其他的投资机会。这种投资方式强调分析公司的基本面，例如公司的经营模式、管理团队、市场竞争力等，以求寻找出具有投资价值的个股。D 选项正确，巴菲特是典型的价值投资者，注重分析公司内在价值，而不是首先预测宏观经济走势，他用的就是自下而上的选股方法。故本题选BCD选项。"},{"id":"advisor1-53","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"计量违约损失率应当采取审慎的态度，估计经济衰退时期违约债项的损失严重程度，主要方法包括（）。","options":["市场价值法","专家判断法","信用评分模型","回收现金流法"],"answer":"AD","explain":"计量违约损失率应当采取审慎的态度，估计经济衰退时期违约债项的损失严重程度，主要方法包括市场价值法（A选项符合题意）和回收现金流法（D选项符合题意）。B、C 选项不符合题意，专家判断法与信用评分模型是客户评级中的一种而不属于债项评级。故本题选AD选项。"},{"id":"advisor1-54","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"假设市场中存在 A、B 两种无风险债券，均每年支付一次，利息相关信息如下，则下列说法中正确的有（）。","options":["市场1年期即期利率为8.25%","市场2年期即期利率为7.08%","市场1年期即期利率为8.05%","市场2年期即期利率为6.97%"],"answer":"AB","explain":"1年期A债券（每年付息 1次，1年期）。现金流：1年末收到 面值+利息 = 1000 + 1000×5% = 1050。价格970 = 未来现金流1050 ÷ （1 + r1）；r1=8.25%（A选项正确）。B 债券每年付息：1000×6%=60。第 1 年末现金流 60，用 1 年期即期利率r1=8.25%折现；第 2 年末现金流60+1000=1060，用 2 年期即期利率r2折现；债券现价 980 美元，估值公式：980=60/（1+r1）+1060/（1+r2）2，可算出 r2=7.08%（B 选项正确）。故本题选AB选项。"},{"id":"advisor1-55","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"结合美国、日本两国业务实践，投资顾问业务模式分为（）。","options":["咨询型模式","全权委托型模式","管理型模式","分析型模式"],"answer":"AB","explain":"结合美国、日本两国业务实践，投资顾问业务模式分为两种，一种是咨询型模式（ A 选项正确），另一种是全权委托型模式（B选项正确）。故本题选AB选项。"},{"id":"advisor1-56","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"了解客户的渠道有（）。","options":["家访","面谈","风险测评","调查问卷"],"answer":"BCD","explain":"基金投资顾问机构应当全面了解客户的个人情况、财务状况、投资经验、投资目标、投资期限、风险承受能力和偏好等方面的信息。可以通过面谈（B 选项正确）、调查问卷（D 选项正确）、风险测评（C选项正确）等方式来获取上述信息。故本题选BCD选项。"},{"id":"advisor1-57","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"某公司某年末净赚利润为 150 万元，营业收入为 3000 万元，资产总额为 2000 万元，股东权益为1000万元，则下列财务指标正确的是（）。","options":["营业利润率为5%","总资产周转率为1.5","权益乘数为2","净资产收益率为15%"],"answer":"ABCD","explain":"A选项正确，营业利润率=净利润／营业收入=150/3000=5%。B选项正确，总资产周转率=营业收入／总资产=3000/2000=1.5。C选项正确，权益乘数=总资产／股东权益=2000/1000=2。D 选项正确，净资产收益率 =净利润／净资产 =营业利润率 ×总资产周转率 ×权益乘数=5%×1.5×2=15%。故本题选ABCD选项。"},{"id":"advisor1-58","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"某投资者于年初将1500元现金按5%的年利率投资 5年，那么该投资者（）。","options":["按单利计算的第五年年末的终值为1785元","按单利计算的第五年年末的终值为1875元","按复利计算的第二年年末的终值为1653.75 元","按复利计算的第二年年末的终值为1914.42 元"],"answer":"BC","explain":"B选项正确，A选项错误，单利计算的第五年年末的终值FV=PV×（1+r×t）=1500×（1+5%×5）=1875（元）。C 选项正确，D 选项错误，复利计算的第二年年末的终值 FV=PV×（1+r）t=1500×（1+5%）2=1653.75（元）。故本题选BC选项。"},{"id":"advisor1-59","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"通过对资本资产定价模型中投资组合的 β 系数进行管理，可以衍生出一系列量化投资策略。以下属于这类量化策略的有（）。","options":["Smartβ策略---调整资产组合的β系数，来实现一定的组合风险收益特征","纯α策略---通过多空对冲，使整个组合的β系数始终趋近于0，赚取选股带来的主动收益","高频宏观因子策略---利用对利率、经济增长、通胀等因子的观察和跟踪，通过回归等数理统计手段构建有效投资组合","纯β策略---被动投资，跟踪某一股票指数，获得市场收益"],"answer":"ABD","explain":"A 选项正确，Smartβ 策略：运用 CAPM 的基本原理去调整资产组合的 β 系数，来实现想要实现的收益和抗风险能力。B 选项正确，纯 Alpha 策略：用于描述一个投资策略打败市场的能力。在允许做空的情况下，就可以构建一个多空对冲组合，一方面买入看好的股票，另一方面做空其他股票、指数或股指期货，通过量化模型来动态调整多空头寸的相对比例，使整个组合的及系数始终趋近于 0，这样便能很大程度上剔除系统性风险，只赚取选股带来的主动收益α。C选项错误，高频宏观因子策略更多属于因子投资或多因子模型，虽然可能涉及β的管理，但其核心是捕捉宏观经济因子的风险溢价，而不是直接调整组合的 β 系数。例如，利率因子可能影响资产定价，但策略重点在因子暴露而非β调整。D选项正确，纯Beta策略：一些被动投资的产品，衡量其业绩的标准不是收益的高低，而是相较于业绩基准的跟踪误差。最大程度减小跟踪误差的方法，是构建与指数完全相同的股票组合，即买入指数全部成分股，并且各股票的权重也与指数一致，但这种方法的弊端是交易成本太高，且某些股票可能无法买到所需的数量。故本题选ABD选项。"},{"id":"advisor1-60","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"投资组合管理及资产配置步骤包括（）。","options":["明确投资组合管理的收益目标","形成资本市场预期","构建具体的投资组合","评价投资组合的业绩"],"answer":"ABCD","explain":"管理型投资顾问业务的投资组合管理及资产配置步骤包括：①明确投资组合管理的收益目标（A选项符合题意）；②根据投资目标制定相应的组合管理政策；③形成资本市场预期（B选项符合题意）；④建立战略性资产配置方案；⑤构建具体的投资组合（C选项符合题意）；⑥对投资组合进行修正；⑦评价投资组合的业绩（D选项符合题意）。故本题选ABCD选项。"},{"id":"advisor1-61","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"下列不属于客户的定量信息是（）。","options":["收入和支出","家庭状况","职业信息","投资偏好"],"answer":"BCD","explain":"定量信息主要是客户的财务数据和可度量的量化指标，可以直接进行计算和分析，包括客户的年龄、收入水平（A 选项不符合题意）、资产负债状况、投资组合、投资风险承受能力等信息。定性信息则更多关注客户的意愿、偏好和目标，包括姓名、性别、家庭状况（B 项选项符合题意）、职业（C 项选项符合题意）、个人兴趣爱好、投资偏好（D 项选项符合题意）等，通过与客户的交流和调查等方式获取。两者结合，可以全面了解客户真实的财务状况、投资需求、风险承受能力和投资目标。故本题选BCD选项。"},{"id":"advisor1-62","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"下列关于违约风险暴露的说法中，正确的有（）。","options":["若客户尚未违约，违约风险暴露的表外项目为已提取金额 +信用转换系数×已承诺未提取金额","若客户已违约，则违约风险暴露为其违约时的债务账面价值","是债务人违约时预期表内项目和表外项目的风险暴露总额","若客户尚未违约，违约风险暴露的表内项目为债务账面价值"],"answer":"ABCD","explain":"（1）违约风险暴露是指债务人违约时预期表内项目和表外项目的风险暴露总额（ C 选项正确），包括已使用的授信余额、应收未收利息、未使用授信额度的预期提取数量以及可能发生的相关费用等。（2）如果客户已经违约，则违约风险暴露为其违约时的债务账面价值（ B 选项正确）；如果客户尚未违约，则违约风险暴露对于表内项目为债务账面价值（D选项正确）。（3）对于表外项目为：已提取金额+信用转换系数×已承诺未提取金额（A选项正确）。故本题选ABCD选项。"},{"id":"advisor1-63","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"下列关于无差异曲线特点的说法中，正确的有（）。","options":["无差异曲线是由左至右向上弯曲的曲线","每个投资者的无差异曲线形成连续密布整个平面又互不相交的曲线簇","不同无差异曲线上的组合给投资者带来的满意程度相同","无差异曲线的位置越高，其上的组合给投资者带来的满意程度就越高"],"answer":"ABD","explain":"不同投资者由于具有不同的风险偏好，其无差异曲线形状也不尽相同，但是无差异曲线普遍满足以下特点：（1）无差异曲线是由左至右向上弯曲的曲线（A选项正确）。（2）每个投资者的无差异曲线形成连续密布整个平面又互不相交的曲线簇（B选项正确）。（3）同一条无差异曲线上的组合给投资者带来的满意程度相同；不同无差异曲线上的组合给投资者带来的满意程度不同（C选项错误）。（4）无差异曲线的位置越高，其上的组合给投资者带来的满意程度就越高（D选项正确）。（5）无差异曲线向上弯曲的程度大小反映投资者承受风险的能力强弱，无差异曲线向上弯曲的程度大，投资者承受风险的能力越弱。故本题选ABD选项。"},{"id":"advisor1-64","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"下列关于现值的说法中，错误的有（）。","options":["当给定终值时，贴现率越高，现值越低","当给定利率及终值时，取得终值的时间越长，该终值的现值就越高","在其他条件相同的情况下，按单利计息的现值要低于用复利计息的现值","利率为正时，现值大于终值"],"answer":"BCD","explain":"B 选项错误，根据复利现值公式可知，当给定利率及终值时，取得终值的时间越长，该终值的现值就越低。C 选项错误，单利现值公式为在其他条件相同的情况下、按单利计息的现值要高于用复利计息的现值。D选项错误，利率为正时，现值小于终值。故本题选BCD选项。"},{"id":"advisor1-65","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"下列属于客户现金流量表支出项目的有（）。","options":["房地产贷款月供支出","学费、培训费","医疗费用","信用卡透支"],"answer":"ABC","explain":"客户现金流量表支出项目主要包括房地产相关的贷款支出（ A 选项符合题意）、教育支出（B选项符合题意）、日常生活开支、休闲娱乐、商业保险支出、医疗费用支出（C 选项符合题意）等。D 选项不符合题意，信用卡透支的本金部分属于筹资活动负债，其利息可能计入财务费用，但透支行为本身不直接列为支出项目。现金流量表中通常仅记录实际偿还的本金和利息，而非透支额度。故本题选ABC选项。"},{"id":"advisor1-66","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"下列说法中，属于资本资产定价模型假设条件的有（）。","options":["投资者厌恶风险","证券收益由历史收益和标准差刻画","证券无限可分","税收和交易费用均忽略不计"],"answer":"ACD","explain":"资本资产定价模型是建立在若干假设条件基础上的。这些假设条件可以概括为如下三项假设：①所有投资者都具有风险厌恶的特征，即面临其他条件相同的两种组合时，他们将选择具有较低风险也即标准差较小的组合（A选项符合题意）。②所有资产都是无限可分的，即资产的任何一部分都是可以单独买卖的（C选项符合题意）。③资本市场不存在摩擦，没有税负，没有交易成本（D 选项符合题意）。因此，该假设意味着，在分析问题的过程中，不考虑交易成本和对红利、股息及资本利得的征税，信息在市场中自由流动，任何证券的交易单位都是无限可分的，市场只有一个无风险借贷利率，在借贷和卖空上没有限制。B 选项不符合题意，CAPM 假设证券收益服从正态分布，由期望收益和标准差（而非历史收益）刻画。故本题选ACD选项。"},{"id":"advisor1-67","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"下列因素中，能增加企业变现能力的因素有（）。","options":["准备很快变现的长期资产","可动用的银行贷款指标","偿债能力的声誉","未作记录的或有负债"],"answer":"ABC","explain":"以下几种因素会增强公司的短期偿债能力：（1）可动用的银行贷款额度（B选项正确）；（2）准备短期内变现的长期资产（A选项正确）；（3）偿债的声誉（C选项正确）。D选项错误，或有负债和担保责任引起的负债会减弱公司的短期偿债能力。故本题选ABC选项。"},{"id":"advisor1-68","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"一般而言，风险偏好型客户会倾向于选择（）。","options":["垃圾债券","股指期货","投资于新兴产业的股票型基金","货币型基金"],"answer":"ABC","explain":"风险偏好型的客户对于风险的态度非常积极，在最大化收益的同时追求最大的风险，在预期收益相同的情况下，愿意选择风险更高的产品来为其带来更高的效用。A、B、C 选项正确，垃圾债券、股指期货和投资于新兴产业的股票型基金属于高风险投资工具。D 选项错误，货币型基金属于低风险、低收益、高流动性的产品，主要投资于短期货币工具，不符合风险偏好型客户的需求。故本题选ABC选项。"},{"id":"advisor1-69","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"影响证券市场供给的制度因素主要有（）。","options":["发行上市制度","市场设立制度","股权流通制度","红利分配制度"],"answer":"ABC","explain":"影响证券市场供给的制度因素主要有发行上市制度（A 选项正确）、市场设立制度（B 选项正确）、股权流通制度（C选项正确）三大因素。D 选项错误，红利分配属于公司治理与投资者回报机制，影响资金留存与再投资，但属于需求侧调节工具（如高分红吸引长期资金），不直接决定市场供给量。故本题选ABC选项。"},{"id":"advisor1-70","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"在房地产市场发展过热的形势下，一方面居民大量提取存款买房，另一方面房地产开发商和个人向银行借款。如果房地产市场突然萎缩，出现大量个人住房贷款无法偿还、房地产开发商由于资金链断裂而倒闭的情形。监测信用风险指标的计算方法正确的有（）。","options":["不良贷款率=（次级类贷款+可疑类贷款）/各项贷款×100%","预期损失率=预期损失/资产风险暴露×100%","关联授信比例=全部关联方授信额度/资本净额×100%","逾期贷款率=逾期贷款余额/贷款总余额×100%"],"answer":"BCD","explain":"A选项错误，不良贷款率=（次级类贷款+可疑类贷款+损失类贷款）/各项贷款×100%。B选项正确，预期损失率=预期损失/资产风险暴露×100%。C选项正确，关联授信比例=全部关联方授信额度/资本净额×100%。D选项正确，逾期贷款率=逾期贷款余额／贷款总余额×100％。故本题选BCD选项。"},{"id":"advisor1-71","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"在风险管理过程中，由于利率汇率等市场价格因素的频繁波动，一般（）具有实质性意义。","options":["名义价值","市场价值","公允价值","价值重估"],"answer":"BC","explain":"公允价值、名义价值、市场价值和市值重估是对资产的四类价值计量指标。A 选项错误，在市场风险管理过程中，由于利率、汇率等市场价格因素的频繁变动，名义价值一般不具有实质性意义。B、C 选项正确，在市场风险计量与监测的过程中，更具有实质意义的是市场价值和公允价值。D选项错误，它是\"过程/行为\"，不是\"价值指标\"本身。故本题选BC选项。"},{"id":"advisor1-72","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"在现金、消费和债务管理中，家庭紧急预备金的储存形式包括（）","options":["短期定期存款","活期存款","货币市场基金","利用贷款额度"],"answer":"ABCD","explain":"紧急预备金可以用两种方式来储备：一是持有期限短、流动性强、容易变现、价值变动风险很小的金融工具，包括活期存款（B 选项符合题意）、短期定期存款（A选项符合题意）、货币市场基金（C选项符合题意）等；二是未使用的贷款融资额度和信用卡额度（D选项符合题意）。故本题选ABCD选项。"},{"id":"advisor1-73","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"证券公司、证券投资咨询机构提供证券投资顾问服务，应当与客户签订证券投资顾问服务协议，协议内容应包括（）。","options":["服务内容和方式","争议或纠纷解决方式","终止或解除协议的条件和方式","收费标准和支付方式"],"answer":"ABCD","explain":"证券公司、证券投资咨询机构提供证券投资顾问服务，应当与投资者签订证券投资顾问服务协议，并对协议实行编号管理。协议应当包括下列内容：（1）当事人的权利义务；（2）证券投资顾问服务的内容和方式（A选项符合题意）；（3）证券投资顾问的职责和禁止行为；（4）收费标准和支付方式（D选项符合题意）；（5）争议或者纠纷解决方式（B选项符合题意）；（6）终止或者解除协议的条件和方式（C选项符合题意）。故本题选ABCD选项。"},{"id":"advisor1-74","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"证券公司、证券投资咨询机构通过（）等公众媒体对证券投资顾问业务进行广告宣传，应当遵守《广告法》和证券信息传播的有关规定。","options":["广播","电视","网络","报刊"],"answer":"ABCD","explain":"通过广播（A 选项正确）、电视（B 选项正确）、网络（C 选项正确）、报刊（D 选项正确）等公众媒体对证券投资顾问业务进行广告宣传，应当遵守《广告法》和证券信息传播的有关规定。广告宣传内容不得存在虚假、不实、误导性信息以及其他违法违规情形。故本题选ABCD选项。"},{"id":"advisor1-75","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"证券公司、证券投资咨询机构应当按照（）的原则，与客户协商并书面约定收取证券投资顾问服务费用的安排。","options":["公平","公正","合理","自愿"],"answer":"ACD","explain":"A、C、D 选项正确，证券公司、证券投资咨询机构应当按照公平、合理、自愿的原则，与投资者协商并书面约定收取证券投资顾问服务费用的安排，可以按照服务期限、投资者资产规模收取服务费用，也可以采用差别佣金等其他方式收取服务费用。故本题选ACD选项。"},{"id":"advisor1-76","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"证券投资顾问向客户提供投资建议，应当具有合理的依据。投资建议的依据包括（）撰写的证券研究报告。","options":["本公司证券分析师","其他公司证券分析师","投资顾问本人","投资顾问小组"],"answer":"AB","explain":"A、B 选项正确，证券投资顾问基于特定客户的立场，遵循忠实客户利益原则，向客户提供适当的证券投资建议；证券分析师基于独立、客观的立场，对证券及证券相关产品的价值进行研究分析，撰写发布研究报告。故本题选AB选项。"},{"id":"advisor1-77","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"证券组合管理过程中，进行证券投资分析的主要目的有（）。","options":["确定具体证券的投资额度","确定投资目标","明确这些证券的价格形成机制和影响证券价格波动的诸因素及其作用机制","发现那些价格偏离价值的证券"],"answer":"CD","explain":"A选项错误，是\"构建证券投资组合\"的内容。B选项错误，是\"确定证券投资政策\"的内容。C、D 选项正确，进行证券投资分析的一个目的是明确这些证券的价格形成机制和影响证券价格波动的诸多因素及其作用机制，另一个目的是发现那些价格偏离价值的证券。故本题选CD选项。"},{"id":"advisor1-78","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"中期移动平均线包括（）。","options":["10日线","30日线","60日线","250日线"],"answer":"BC","explain":"①通常以5日、10日线观察证券市场的短期走势，称为短期移动平均线（A选项错误）；②以30日（B选项正确）、60 日（C选项正确）线观察中期走势，称为中期移动平均线；③以13周、26周研判长期趋势，称为长期移动平均线。D选项错误，250日线通常称为年线，属于长期移动平均线。故本题选BC选项。"},{"id":"advisor1-79","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"多选","q":"资本资产定价模型是投资组合管理的基础，在投资组合管理中的应用非常广泛，包括（）。","options":["资产估值","量化投资","资源配置","预测股票市场的变动趋势"],"answer":"ABC","explain":"A、B、C 选项符合题意，资本资产定价模型是投资组合管理的基础，在投资组合管理中的应用非常广泛，主要介绍在资产估值、资产配置、量化投资三个方面的应用。故本题选ABC选项。"},{"id":"advisor1-80","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"判断","q":"本币汇率下降必然导致股价下跌。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。当汇率下降时，本币升值，国外对本币的需求增大以及流出增加，对国内的进口增加，这就使国内需求减少，使国内供给增加，但对股价影响并不确定。故本题表述错误。"},{"id":"advisor1-81","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"判断","q":"当久期缺口为负值时，如果市场利率下降，则流动性会随之减弱。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。当久期缺口为负值时，如果市场利率下降，流动性随之减弱；如果市场利率上升，流动性随之增强。故本题表述正确。"},{"id":"advisor1-82","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"判断","q":"对保险产品的分类有助于投资者研究分析保险产品的风险收益特征，为资产配置奠定基础。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。对保险产品的分类有助于投资者研究分析保险产品的风险收益特征，为资产配置奠定基础。故本题表述正确。"},{"id":"advisor1-83","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"判断","q":"分红寿险、万能寿险在为投资人提供一定保障同时兼具储蓄、投资功能。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。万能寿险，是指产品运作机制完全透明、可灵活缴纳保费、可随时调整保险保障水平且将保障和投资功能融为一体的人寿保险。分红寿险，是一种长期储蓄型寿险，既可以保障被保险人的生命安全，又可以为被保险人提供长期的储蓄和投资收益。分红寿险的特点是保险公司会将保费中的一部分用于投资，获得的投资收益会按照一定比例分配给被保险人，这就是所谓的\"分红\"。万能寿险、分红寿险有确定的利益保证，适合有稳健理财需求的人。故本题表述正确。"},{"id":"advisor1-84","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"判断","q":"基金评价人员可以同时在两个以上的基金评价机构执业。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。基金评价人员只有被一家基金评价机构聘用后，方可从事基金评价业务，且基金评价人员不得同时（并非可以同时）在两家以上的基金评价机构执业。故本题表述错误。"},{"id":"advisor1-85","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"判断","q":"盲目乐观的客户会认为能够在比实际更低的波动性下获得更高的收益。因此，在资产配置过程中，如果客户预期管理不好，将严重影响投资顾问业务开展。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。盲目乐观的客户倾向于低估风险（波动性）并高估收益，这与\"高风险高收益\"的基本原则相悖。若未及时纠正，这种预期可能导致客户对投资结果不满。客户预期管理是指在为客户制订和执行资产配置方案时，通过有效的沟通和行动使客户对资产配置的目标、过程、风险、收益等有一个合理和清晰的认知，从而提高客户的满意度和信任度。管理客户预期可以减少客户投诉、纠纷等，也可以增加客户的忠诚度、口碑。管理客户预期的方法包括：①设定适当的客户期望值，不夸大或虚假宣传资产配置的能力或效果，客观评价各类资产的风险收益特征；②谨慎对待客户的不合理要求，避免客户对资产配置过程、结果形成过高要求；③重视配置过程中与客户的沟通，对客户提出的问题或建议给予及时和真实的反馈，减少信息不对称和理解误差。故本题表述正确。"},{"id":"advisor1-86","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"判断","q":"如今多因素模型被广泛应用在证券组合中普通股之间的分配上，而均值一方差模型则被广泛应用在不同类型证券之间的投资分配上。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。当今，均值一方差模型被广泛应用于不同类型证券之间的投资分配上，如对债券、股票、不动产等大类资产进行配置，而多因素模型则被广泛应用在证券组合中普通股之间的投资分配上。故本题表述正确。"},{"id":"advisor1-87","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"判断","q":"授信业务中抵（质）押品主要包括金融质押品、应收账款、房地产以及其他抵 /质押品。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。授信业务中经常使用的抵/质押品主要包括金融质押品、应收账款、房地产以及其他抵/质押品。故本题表述正确。"},{"id":"advisor1-88","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"判断","q":"随着复利次数的增加，同一个名义年利率求出的有效年利率会不断增加，且速度越来越快。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。随着复利次数的增加，有效年利率也会不断增加，但增加的速度越来越慢（并非越来越快），当复利期间无限小时，相当于连续复利。故本题表述错误。"},{"id":"advisor1-89","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"判断","q":"套利定价模型表明市场均衡状态下套利组合中各种证券的权数之和等于 1。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。在套利定价理论中，套利机会被套利组合所描述。所谓套利组合，是指满足下述三个条件的证券组合：（1）该组合中各种证券的投资比例满足 w1+w2+...+wN=0（并非等于 1），即该组合不需要投资者任何的额外资金；（2）该组合因素灵敏度系数为零；（3）该组合具有正的期望收益率。故本题表述错误。"},{"id":"advisor1-90","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"判断","q":"投资者适当性制度核心目的在于\"将适当的产品或服务销售或提供给适当的投资者\"。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。证券经营机构适当性管理要求：证券经营机构应当在销售产品或者提供服务的过程中，勤勉尽责，审慎履职，全面了解投资者情况，深入调查分析产品或者服务信息，科学有效评估风险，基于投资者的不同风险承受能力以及产品或者服务的不同风险等级等因素，提出明确的适当性匹配意见，将适当的产品或者服务提供给适合的投资者，并对违法违规行为承担法律责任。故本题表述正确。"},{"id":"advisor1-91","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"判断","q":"退休后从保险公司领取的养老金和按月领取的奖励均可视为一种年金。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。年金是指一组在某个特定时段内金额相等、方向相同、时间间隔相同、不间断的现金流。按月领取的奖励不一定是相等金额，奖金可能有多有少，不满足年金的概念。故本题表述错误。"},{"id":"advisor1-92","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"判断","q":"已获利息倍数可以用于测量债权人投入资本的风险和收益状况。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。已获利息倍数是指经营业务收益与利息支出的比例，用以衡量企业偿还借款利息的能力和债权人投资资本的风险。从债权人的立场出发，可以通过计算已获利息倍数来测试债权人投入资本的风险，但是不能测量投入资本的收益状况。故本题表述错误。"},{"id":"advisor1-93","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"判断","q":"因金融产品设计、运营和委托人提供的信息不真实、不准确、不完整而产生的责任由证券公司承担。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。证券公司应当向客户说明，因金融产品设计、运营和委托人提供的信息不真实、不准确、不完整而产生的责任由委托人承担，证券公司不承担任何担保责任。故本题表述错误。"},{"id":"advisor1-94","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"判断","q":"在利率互换时通常无须交换本金，而是定期交换利息差额。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。在利率互换中通常无须交换本金，只需定期交换利息差额。故本题表述正确。"},{"id":"advisor1-95","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"判断","q":"在期货合约签订后，期货价格可能高于、等于或低于相应的现货金融工具价格。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。在期货合约签订后，期货价格可能高于、等于或低于相应的现货金融工具价格。故本题表述正确。"},{"id":"advisor1-96","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"判断","q":"证券投资顾问当年注册资格后还需要再教育学时间培训。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。证券投资咨询机构应当要求其从业人员在每个培训周期内完成一定时间的业务培训，建议不少于 15 学时。从业人员自首次执业登记日的下一年起，每个自然年为一个培训周期。证券投资顾问在注册的当年是不需要参加后续职业培训的。故本题表述错误。"},{"id":"advisor1-97","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"判断","q":"证券投资顾问服务费用可以以个人账户收取（）。","options":["正确","错误"],"answer":"B","explain":"本题说法错误。证券投资顾问服务费用应当以公司（并非个人）账户收取。故本题表述错误。"},{"id":"advisor1-98","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"判断","q":"证券投资顾问业务，是证券投资咨询业务的一种基本形式，指证券公司、证券投资咨询机构接受客户委托，按照约定，向客户提供涉及证券及证券相关产品的投资建议服务，辅助客户作出投资决策，并直接或者间接获取经济利益的经营活动。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。证券投资顾问业务是证券投资咨询业务的一种基本形式，指证券投资咨询机构接受客户委托，按照约定，向客户提供涉及证券及证券相关产品的投资建议服务，辅助客户作出投资决策，并直接或者间接获取经济利益的经营活动。投资建议服务内容包括投资品种的选择、投资组合以及投资理财规划建议等。故本题表述正确。"},{"id":"advisor1-99","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"判断","q":"证券投资者是证券市场资金的供给者，也是证券市场的供给主体。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。证券市场的供给主体是上市公司（企业）、政府与政府机构以及金融机构（并非证券投资者）。故本题表述错误。"},{"id":"advisor1-100","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"案例","q":"【资料】某证券公司深入研究基金产品及其类型，自营投资了股票型基金和债券型基金，\n基金A和基金 B为股票型基金，基金 C为债券型基金。持仓信息如下： \n请根据上述背景信息回答以下问题。\n\n【问题】关于基金的类型，下列说法正确的是（）。","options":["指数基金通过指数增强策略，以期获得高于标的指数回报水平的投资业绩","成长型基金主要投资于可带来现金收入的有价证券，以获取当期的最大收入为目的","公司型基金是依据基金合同设立的","基金资产80%以上投资于股票的为股票基金"],"answer":"AD","explain":"B 选项错误，收入型基金主要投资于可带来现金收入的有价证券，以获取当期的最大收入为目的，成长型基金追求的是基金资产的长期增值，为了达到这一目标，基金管理人通常将基金资产投资于信誉度较高、有长期成长前景或长期盈余的所谓成长公司的股票；C选项错误，公司型基金依据公司章程成立。故本题选AD选项。"},{"id":"advisor1-101","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"案例","q":"【资料】某证券公司深入研究基金产品及其类型，自营投资了股票型基金和债券型基金，\n基金A和基金 B为股票型基金，基金 C为债券型基金。持仓信息如下： \n请根据上述背景信息回答以下问题。\n\n【问题】关于股票基金的分析，下列说法正确的有（）。","options":["基金B的净值增长率为-20%","基金A的净值增长率为30%","基金B的净值增长率为0%","基金A的净值增长率为20%"],"answer":"BC","explain":"基金净值增长率=[期末份额净值-（期初份额净值-分红）]/期初份额净值。①基金A的净值增长率=[1.2-（1-0.1）]/1=30%；②基金B的净值增长率=[0.8-（1-0.2）]/1=0。故本题选BC选项。"},{"id":"advisor1-102","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"案例","q":"【资料】某证券公司深入研究基金产品及其类型，自营投资了股票型基金和债券型基金，\n基金A和基金 B为股票型基金，基金 C为债券型基金。持仓信息如下： \n请根据上述背景信息回答以下问题。\n\n【问题】关于债券型基金，下列说法错误的是（）。","options":["债券型基金常常被投资者认为是收益、风险适中的投资工具","债券型基金根据投资范围的不同，可分为纯债型基金、混合债券型基金、债券指数型基金","债券型基金以追求长期资本增值为目标","债券型基金的波动通常小于股票型基金"],"answer":"C","explain":"C 选项错误，股票型基金（并非债券型基金）以追求长期资本增值为目标，比较适合长期投资。故本题选C选项。"},{"id":"advisor1-103","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"案例","q":"【资料】6元/股。 \n请根据上述背景信息回答以下问题。\n\n【问题】影响期权价格（期权费）的因素包括（）。","options":["协定价格与市场价格","标的物价格的波动性","利率","剩余期限"],"answer":"ABCD","explain":"总体来看期权价格的影响因素包括标的价格（A 选项正确）、行权价格、剩余期限（D 选项正确）、无风险利率（C 选项正确）、分红率（或其他标的资产收益）、波动率（B 选项正确）等。故本题选ABCD选项。"},{"id":"advisor1-104","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"案例","q":"【资料】6元/股。 \n请根据上述背景信息回答以下问题。\n\n【问题】根据以上情况，下列说法正确的是（）。","options":["海某所做的交易属于看跌期权，期权费为3000元","海某所做的交易属于卖出期权，期权费为300元","海某所做的交易属于买进期权，期权费为3000元","海某所做的交易属于卖出期权，期权费为8000元"],"answer":"A","explain":"该投资者预期股票价格将会下跌，所做交易为看跌期权，期权费为5000×0.6=3000元（A选项正确）。故本题选A选项。"},{"id":"advisor1-105","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"案例","q":"【资料】6元/股。 \n请根据上述背景信息回答以下问题。\n\n【问题】如果一个月后，甲股票价格降至每股 8 元，海某认为时机已到，于是以现货方式买进 5000 股甲股票，然后按原定合约行使期权卖给王某甲股票5000股。该笔交易海某获利（）元。","options":["2500","5000","7000","10000"],"answer":"C","explain":"根据题意，海某获利=（10-8）×5000－5000×0.6=7000元（C选项正确）。故本题选C选项。"},{"id":"advisor1-106","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"案例","q":"【资料】某证券投资组合的实际平均收益率为 15%，期间市场组合的期望收益率为 8%，无\n风险收益率为3.5%，投资组合的系统性风险为12%。 \n请根据上述背景信息回答以下问题。\n\n【问题】该证券投资组合的詹森（Jensen）指数为（）。","options":["4.04%","11.50%","6.50%","10.96%"],"answer":"D","explain":"资本资产定价模型的公式：E（Ri）=Rf+βi×[E（RM）-Rf]=3.5%+12%×（8%-3.5%）=4.04%；詹森α=15%-4.04%=10.96%（D选项正确）。故本题选D选项。"},{"id":"advisor1-107","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"案例","q":"【资料】某证券投资组合的实际平均收益率为 15%，期间市场组合的期望收益率为 8%，无\n风险收益率为3.5%，投资组合的系统性风险为12%。 \n请根据上述背景信息回答以下问题。\n\n【问题】该投资组合的特雷诺（Treynor）指数为（）。","options":["0.96","1.05","0.58","1.25"],"answer":"A","explain":"A选项正确，特雷诺比率=Tp=（Rp-Rf）/βp=（15%-3.5%）/12%=0.96。故本题选A选项。"},{"id":"advisor1-108","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"案例","q":"【资料】某证券投资组合的实际平均收益率为 15%，期间市场组合的期望收益率为 8%，无\n风险收益率为3.5%，投资组合的系统性风险为12%。 \n请根据上述背景信息回答以下问题。\n\n【问题】下列关于詹森指数、特雷诺指数和夏普指数的说法，正确的有（）。","options":["三种指数均是风险调整后收益率的业绩评估指标","三种指数均以资本市场线为基础","三种指数可能会因理论假设方面的局限性导致评价结果失真","夏普指数越低越好"],"answer":"AC","explain":"A选项正确，三种指数均是风险调整后收益率的业绩评估指标。B选项错误，三种指数均以资本资产定价模型为基础，此为证券市场线，而非资本市场线。C 选项正确，因为以资本资产定价模型为基础，模型本身存在假设，故可能会导致评价结果失真。D 选项错误，夏普比率代表单位总风险下的超额收益，一般来讲是越高越好（并非越低越好）。故本题选AC选项。"},{"id":"advisor1-109","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"案例","q":"【资料】证券投资咨询机构甲和乙根据某投资者的收益要求、风险偏好等特征，分别推荐\n了 A 股票投资组合和 B 股票投资组合。B 股票投资组合采用指数型消极投资策略，跟踪某个指\n数。该指数共有100支成分股，前10支成分股市值在指数中合计权重为50%，股票C在指数中\n权重为10%。 \n请根据上述背景信息回答问题。\n\n【问题】可以衡量投资组合收益率的波动程度及损失风险的指标是（）。","options":["最大回撤","持有到期收益率","投资组合规模","货币加强收益率"],"answer":"A","explain":"风险类指标衡量了投资组合收益率的波动程度及损失风险，一般来讲，实际收益率相对于期望收益率的偏离程度越大，投资者承担的风险也就越大，其风险的大小可由波动率或者向下波动的程度来衡量。常用的指标包括标准差、最大回撤（A选项正确）、下行风险等。故本题选A选项。"},{"id":"advisor1-110","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"案例","q":"【资料】证券投资咨询机构甲和乙根据某投资者的收益要求、风险偏好等特征，分别推荐\n了 A 股票投资组合和 B 股票投资组合。B 股票投资组合采用指数型消极投资策略，跟踪某个指\n数。该指数共有100支成分股，前10支成分股市值在指数中合计权重为50%，股票C在指数中\n权重为10%。 \n请根据上述背景信息回答问题。\n\n【问题】若A股票投资组合采用了量化中性策略，下列说法错误的有（）。","options":["量化中性策略与市场相关性低","量化中性策略获取相对收益","量化中性策略是指利用统计学、时间序列或机器学习等技术发现市场上的同类金融产品之间的定价误差，进而构建投资组合","量化中性策略属于积极型股票投资策略"],"answer":"BC","explain":"量化选股，即借助统计学和数学的方法，对包括宏观经济、上市公司财务指标等基本面因子，以及股票量价、投资者情绪、分析师预期等市场面因子的海量数据进行全面的分析，从中发现可用于推测未来股价走势的指标，从而构建数量化选股策略模型，实现交易执行的程序化（ C选项错误，D选项正确）。其优势在于优质的量化中性产品在不同的牛熊环境中均能获得稳健的正收益（A 选项正确，侧面反映与市场相关性低），主要原因包括以下两点：①量化中性策略追求绝对收益（B 选项错误），在持有一组量化选股的股票多头时，通过对冲工具对冲掉市场风险，赚取选股组合带来的收益；②量化中性策略可利用自身的技术优势捕捉市场套利，从而获得收益。故本题选BC选项。"},{"id":"advisor1-111","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"案例","q":"【资料】证券投资咨询机构甲和乙根据某投资者的收益要求、风险偏好等特征，分别推荐\n了 A 股票投资组合和 B 股票投资组合。B 股票投资组合采用指数型消极投资策略，跟踪某个指\n数。该指数共有100支成分股，前10支成分股市值在指数中合计权重为50%，股票C在指数中\n权重为10%。 \n请根据上述背景信息回答问题。\n\n【问题】若 B 股票投资组合是通过市值法，选取前 10 支成分股构建的，则股票 C 在 B 股票投资组合中的权重为（）。","options":["20%","5%","10%","50%"],"answer":"A","explain":"B 股票投资组合采用市值法选取前 10 支成分股，其权重需根据在原指数中的相对占比重新分配。由于股票 C 在指数中的总权重为 10%，而前 10 支成分股合计占指数的 50%，因此股票 C 在前 10 支中的市值占比为 10%÷50%=20%。B 组合仅包含这 10 支股票，故股票 C 在其组合中的权重即为 20%。此计算逻辑体现了市值法的核心原则——按成分股在原始指数中的市值比例调整持仓权重。故选项A正确。故本题选A选项。"},{"id":"advisor1-112","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"案例","q":"【资料】我国某企业计划发行 10 亿元面额为 100 元、期限为 5 年的债券，该债券的票面利\n息为每年10元，于每年年末支付，5年末返本，当年通货膨胀率为 3%。 \n请根据材料回答下列问题。\n\n【问题】该债券的名义收益率是（）。","options":["7%","10%","12%","15%"],"answer":"B","explain":"B 选项正确，名义收益率又称票面收益率，是债券票面收益与债券面值之比。该债券的名义收益率=10/100=10%。故本题选B选项。"},{"id":"advisor1-113","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"案例","q":"【资料】我国某企业计划发行 10 亿元面额为 100 元、期限为 5 年的债券，该债券的票面利\n息为每年10元，于每年年末支付，5年末返本，当年通货膨胀率为 3%。 \n请根据材料回答下列问题。\n\n【问题】如果该债券市场价格为90元，则该债券的当期收益率为（）。","options":["4%","8%","11.1%","13.5%"],"answer":"C","explain":"当期收益率是指债券的年利息收入与买入债券的实际价格的比率。当期收益率=10/90≈11.1%（C选项正确）。故本题选C选项。"},{"id":"advisor1-114","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"案例","q":"【资料】我国某企业计划发行 10 亿元面额为 100 元、期限为 5 年的债券，该债券的票面利\n息为每年10元，于每年年末支付，5年末返本，当年通货膨胀率为 3%。 \n请根据材料回答下列问题。\n\n【问题】如果发行时当期收益率为10%，则该债券的发行价格应当是（）元。","options":["80","100","110","125"],"answer":"B","explain":"B 选项正确，当期收益率是指债券的年利息收入与买入债券的实际价格的比率。市场价格 =年收入利息/当期收益率=10/10%=100（元）。故本题选B选项。"},{"id":"advisor1-115","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"案例","q":"【资料】基金投资顾问业务，全称是 “公开募集证券投资基金投资顾问”，指试点机构可\n以接受客户委托，按照协议约定向客户提供基金投资组合策略建议。根据与客户协议约定的投\n资组合策略，试点机构可以在客户授权的范围内，代客户作出具体基金投资品种、数量和买卖\n时机的决策，并代客户执行基金产品申购、赎回、转换等交易申请，开展管理型基金投资顾问\n服务。 \n请根据上述背景信息回答以下问题。\n\n【问题】基金销售机构申请试点机构提供基金投顾服务，非货币基金保有量不低于（）亿元。","options":["10","50","100","200"],"answer":"C","explain":"具备下列条件的机构，经中国证监会备案，可以从事基金投资顾问业务：①具有资产管理、基金销售等业务资格；②有一定的市场竞争力和客户基础。证券公司、基金管理公司或其销售子公司申请的，应具有较强的合规风控及投资者服务能力；基金销售机构申请的，非货币基金保有量不低于 100 亿元（C选项正确）；③合规记录良好；④具有高质量的基金产品研究团队，与业务开展相匹配的投资顾问人员，以及与其拟从事业务相适应的信息技术能力；⑤业务方案完备，业务制度健全，能够确保客户利益优先原则，有效防范利益冲突和防控各类风险；⑥支持业务开展的其他必要条件。符合前款第②至③项条件且客户数量达到 1 亿人的机构，可设立子公司开展基金投资顾问业务试点，该子公司应当符合第③至⑥项的条件。故本题选C选项。"},{"id":"advisor1-116","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"案例","q":"【资料】基金投资顾问业务，全称是 “公开募集证券投资基金投资顾问”，指试点机构可\n以接受客户委托，按照协议约定向客户提供基金投资组合策略建议。根据与客户协议约定的投\n资组合策略，试点机构可以在客户授权的范围内，代客户作出具体基金投资品种、数量和买卖\n时机的决策，并代客户执行基金产品申购、赎回、转换等交易申请，开展管理型基金投资顾问\n服务。 \n请根据上述背景信息回答以下问题。\n\n【问题】基金投资顾问机构与普通投资者签订的服务协议应当包括（）。","options":["当事人的权利义务","履行持续注意义务的具体方式","费用收取的项目、标准，以及支付方式","服务终止的情形、程序"],"answer":"ABCD","explain":"与普通投资者签订的服务协议应当至少包括下列内容：①当事人的权利义务（A选项符合题意）；②基金投资顾问机构及其人员的职责和禁止行为；③基金投资顾问服务内容和方式，包括资金规划、资产配置等投资规划方案，以及不同投资目标、投资期限对应的基金组合策略；④履行持续注意义务的具体方式（B选项符合题意）；⑤信息披露的内容和方式；⑥费用收取的项目、标准，以及支付方式等（C选项符合题意）；⑦服务终止的情形、程序等（D选项符合题意）；⑧可能影响基金投资顾问业务开展和客户权益的其他事项。故本题选ABCD选项。"},{"id":"advisor1-117","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"案例","q":"【资料】基金投资顾问业务，全称是 “公开募集证券投资基金投资顾问”，指试点机构可\n以接受客户委托，按照协议约定向客户提供基金投资组合策略建议。根据与客户协议约定的投\n资组合策略，试点机构可以在客户授权的范围内，代客户作出具体基金投资品种、数量和买卖\n时机的决策，并代客户执行基金产品申购、赎回、转换等交易申请，开展管理型基金投资顾问\n服务。 \n请根据上述背景信息回答以下问题。\n\n【问题】基金投资顾问业务回访包括（）。","options":["老客户回访","客户满意度回访","客户持续管理回访","专项回访"],"answer":"BCD","explain":"基金投资顾问业务回访包括新开业务客户回访、客户满意度回访（B 选项符合题意）、客户持续管理回访（C选项符合题意）、专项回访（D选项符合题意）等。故本题选BCD选项。"},{"id":"advisor1-118","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"案例","q":"【资料】基金投资顾问业务，全称是 “公开募集证券投资基金投资顾问”，指试点机构可\n以接受客户委托，按照协议约定向客户提供基金投资组合策略建议。根据与客户协议约定的投\n资组合策略，试点机构可以在客户授权的范围内，代客户作出具体基金投资品种、数量和买卖\n时机的决策，并代客户执行基金产品申购、赎回、转换等交易申请，开展管理型基金投资顾问\n服务。 \n请根据上述背景信息回答以下问题。\n\n【问题】基金投资顾问机构与客户约定由第三方机构对授权账户进行监督的，该第三方机构应当具有基金（）业务资格。","options":["咨询","宣传","托管","销售"],"answer":"C","explain":"C 选项正确，基金投资顾问机构与客户约定由第三方机构对授权账户进行监督的，该第三方机构应当具有基金托管业务资格。故本题选C选项。"},{"id":"advisor1-119","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷一","type":"案例","q":"【资料】基金投资顾问业务，全称是 “公开募集证券投资基金投资顾问”，指试点机构可\n以接受客户委托，按照协议约定向客户提供基金投资组合策略建议。根据与客户协议约定的投\n资组合策略，试点机构可以在客户授权的范围内，代客户作出具体基金投资品种、数量和买卖\n时机的决策，并代客户执行基金产品申购、赎回、转换等交易申请，开展管理型基金投资顾问\n服务。 \n请根据上述背景信息回答以下问题。\n\n【问题】基金投资顾问机构开展管理型基金投资顾问业务的，应当（）披露委托资产参考市值。","options":["每日","每周","每月","每季"],"answer":"A","explain":"A 选项正确，基金投资顾问机构开展管理型基金投资顾问业务的，应当每日披露委托资产参考市值，基金投资顾问机构应当建立复核机制，确保市值信息的真实、完整。故本题选A选项。"}]},{"id":"advisor2","subject":"advisor","name":"证券投顾 · 押题卷二","stats":{"单选":40,"多选":40,"判断":20,"案例":20},"questions":[{"id":"advisor2-0","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"单选","q":"\"飓风起于青萍之末\"，可以类指（）的证券分析方法。","options":["仔细观察","自上而下","宏观经济分析","自下而上"],"answer":"D","explain":"D 选项正确，题中\"飓风起于青萍之末\"即指自下而上分析法，自下而上分析法则是以个股为切入点，通过财务指标分析寻找具有潜力的公司进行投资，并且在该板块或行业中筛选出其他的投资机会。这种方式下，更侧重于关注个股的具体情况和公司的经营状况，而不过分关注市场整体的走势和趋势。故本题选D选项。"},{"id":"advisor2-1","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"单选","q":"A方案在三年中每年年初付款100元，B方案在三年中每年年末付款100元，若利率为10%，则二者在第三年年末时的终值相差（）元。","options":["33.1","31.3","133.1","13.31"],"answer":"A","explain":"A方案在第三年年末的终值为：100×[（1+10%）+（1+10%）2+（1+10%）3]=364.1（元）；B方案在第三年年末的终值为：100×[（1+10%）2+（1+10%）+1]=331（元）。二者的终值相差为：364.1-331=33.1（元）（A选项正确）。故本题选A选项。"},{"id":"advisor2-2","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"单选","q":"财务报表分析的原则主要有两个：一是坚持全面原则，二是坚持（）原则。","options":["考虑个性","均衡性","非流动性","流动性"],"answer":"A","explain":"财务报表分析的原则包括：①坚持全面原则；②坚持考虑个性原则（A选项正确）。故本题选A选项。"},{"id":"advisor2-3","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"单选","q":"从家庭生命周期的角度分析，家庭收入以理财收入及转移性收入为主的阶段一般称为家庭（）。","options":["衰老期","成熟期","成长期","形成期"],"answer":"A","explain":"A 选项正确，衰老期是指夫妻双方退休到一方过世的阶段。在这一阶段，家庭收入以理财收入和转移性收入为主；医疗费用支出增加，其他费用支出减少；支出大于收入，储蓄逐步减少。B 选项错误，成熟期起点是子女独立，终点是夫妻退休。这一阶段家庭收入达到顶峰，支出则逐渐减少，财富积累加快，养老金的筹措是该阶段的主要目标。C 选项错误，成长期起点是子女出生，终点是子女独立。这一阶段家庭支出固定，教育负担增加，保险需求大，需要偿还购房贷款，压力相对较大。D 选项错误，形成期起点是结婚，终点是子女出生。这一阶段家庭收入呈上升趋势，具有一定风险承受能力，同时购房贷款需求较高，消费支出增多。故本题选A选项。"},{"id":"advisor2-4","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"单选","q":"存款准备金利率是（）对金融机构存在央行的准备金支付的利率，分为法定准备金利率和超额准备金利率。","options":["中国证监会","中国人民银行","财政部","中国银监会"],"answer":"B","explain":"B 选项正确，存款准备金利率是央行对金融机构存在央行的准备金支付的利率，分为法定准备金利率和超额准备金利率。故本题选B选项。"},{"id":"advisor2-5","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"单选","q":"弹性价格货币分析法模型是由货币需求函数、货币市场均衡条件及（）三者导出。","options":["非套补利率平价","套补的利率平价","国际收支学说","购买力平价理论"],"answer":"D","explain":"D 选项正确，弹性价格货币分析法模型是由货币需求函数、货币市场均衡条件及购买力平价理论三者导出。它表明，本国与外国之间国民收入水平、利率水平及货币供给水平通过对各自物价水平的影响而决定了汇率水平。故本题选D选项。"},{"id":"advisor2-6","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"单选","q":"当没有投资主张时，看着别人投资什么自己也跟着投资属于（）。","options":["羊群效应","处置效应","损失厌恶","锚定效应"],"answer":"A","explain":"A 选项正确，行为金融学中，羊群效应常常用来描述金融市场中投资者盲目从众的行为心理现象，羊群效应所带来的繁荣背后往往是巨大的市场经济泡沫。B选项错误，处置效应指投资者倾向于过早卖出盈利资产，而长期持有亏损资产的心理偏差。C 选项错误，损失厌恶描述的是投资者是按投资收益的多少来衡量机会，而不是按照获得投资收益的可能性大小。D 选项错误，锚定效应指投资者过度依赖初始信息（如股票的历史价格、发行价等）作为决策基准，忽视当前市场信息的变化。故本题选A选项。"},{"id":"advisor2-7","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"单选","q":"当中央银行（）时，商业银行可运用的资金减少，贷款能力下降，货币乘数变小，市场货币流通量便会相应减少。","options":["提高法定存款准备金率","提高再贴现率","提高存款准备金率","提高存款率"],"answer":"A","explain":"A 选项正确，当中央银行提高法定存款准备金率时，商业银行可运用的资金减少，贷款能力下降，货币乘数变小，市场货币流通量便会相应减少。故本题选A选项。"},{"id":"advisor2-8","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"单选","q":"个人生命周期中探索期的主要理财活动是（）。","options":["偿还房贷、筹教育金","量入为出、存自备款","求学深造、提高收入","收入增加、筹退休金"],"answer":"C","explain":"A选项错误，稳定期的投资理财活动为偿还房贷、筹教育金。B选项错误，量入为出、存自备款主要对应建立期。C选项正确，探索期的投资理财活动为求学深造、提高收入。D选项错误，维持期的投资理财活动为收入增加、筹退休金。故本题选C选项。"},{"id":"advisor2-9","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"单选","q":"根据《证券期货投资者适当性管理办法》，证券经营机构应当（）开展一次适当性自查，形成自查报告。","options":["每月","每半年","每年","每2年"],"answer":"B","explain":"B选项正确，证券经营机构应当每半年开展一次适当性自查，形成自查报告。发现违反《证券期货投资者适当性管理办法》规定的情况，应当及时处理并主动报告住所地中国证监会派出机构。故本题选B选项。"},{"id":"advisor2-10","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"单选","q":"根据资本资产定价模型（CAPM），当我们在衡量某证券的收益率时，其风险溢价收益应为（）。","options":["无风险利率和贝塔（β）的乘积","贝塔（β）和市场预期收益率的乘积","无风险利率和市场风险溢价之和","贝塔（β）和市场风险溢价的乘积"],"answer":"D","explain":"资本资产定价模型认为，对于任一资产 i 而言，其期望收益率可以用公式表示： E（Ri）=Rf+βi×[E（Rm）-Rf]。其中E（Ri）为资产i的预期收益率；Rf为无风险收益率；E（Rm）为市场组合的预期收益率；[E（Rm）-Rf]为市场组合的风险溢价；βi为某一资产与市场组合的风险溢价相关系数。D选项正确，风险溢价收益=βi×[E（Rm）-Rf]。故本题选D选项。"},{"id":"advisor2-11","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"单选","q":"假定汪先生当前投资某项目，期限为 3 年，第一年年初投资 100000 元，第二年年初又追加投资50000元，年收益率为10%，那么他在 3年内每年末至少收回（）元才是盈利的。","options":["33339","43333","58489","44386"],"answer":"C","explain":"（1）已知第一年现值 PV=100000，利率 r=10%，期数 n=3，根据复利终值计算公式：FV=PV×（1+r）n=100000×（1+10%）3=133100（元）。（2）已知第二年现值 PV=50000，利率 r=10%，期数 n=2，根据复利终值计算公式：FV=PV×（1+r）n=50000×（1+10%）2=60500（元）。（3）该投资的终值为：133100+60500=193600（元）。（4）已知该投资的终值 FV=193600，利率 r=10%，期数 n=3，根据期末年金终值计算公式：FV=A/r×[（1+r）N-1]=A/10%×[（1+10%）3-1]=193600（元），则 A=58489（元）（C 选项正确）。故本题选C选项。"},{"id":"advisor2-12","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"单选","q":"久期缺口是资产加权平均久期减去负债加权平均久期与（）的乘积。","options":["收益率","资产负债率","现金率","市场利率"],"answer":"B","explain":"B 选项正确，久期分析法通常采用的指标为资产负债久期缺口，即资产加权平均久期减去负债加权平均久期与资产负债率的乘积。故本题选B选项。"},{"id":"advisor2-13","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"单选","q":"就单根K线而言，反映多方占据绝对优势的 K线形状是（）。","options":["带有较长上影线的阳线","大阴线实体","大阳线实体","大十字星"],"answer":"C","explain":"A 选项错误，带有较长上影线的阳线，证明多方曾试图向上发起进攻，但失败，落回来了，力量不强；B选项错误，大阴线实体，表明空方已取得优势地位，是一种跌势的信号；C 选项正确，大阳线实体，是大幅低开高收的阳线，实体很长以至于可以忽略上下影线的存在，这意味着多方已经取得决定性的胜利；D 选项错误，大十字星，有很长的上下影线，表明多空双方争斗激烈，最后回到原处，后市往往有变化。故本题选C选项。"},{"id":"advisor2-14","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"单选","q":"考察和分析企业的（），主要从管理层风险，行业风险，生产与经营风险，宏观经济，社会及自然环境等方面进行分析和判断。","options":["基本信息","财务状况","经营状况","非财务因素"],"answer":"D","explain":"D 选项正确，非财务分析是对法人客户管理层领导能力、生产经营能力、内部控制及风险管理能力，以及所处的宏观、区域、行业、社会等经营环境进行全面综合分析的过程，与财务分析互相补充、互相印证。故本题选D选项。"},{"id":"advisor2-15","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"单选","q":"了解客户信息是投资顾问提供专业化服务的基础内容和必要工作步骤，下列不属于客户的非财务信息是（）。","options":["收入和支出","家庭状况","职业信息","投资偏好"],"answer":"A","explain":"A 选项符合题意，收入和支出属于财务信息。财务信息是指客户的财务收支和资产负债情况，包括收入、支出、资产、负债、投资、储蓄和消费、社会保障、风险管理等信息。B、C、D 选项不符合题意，非财务信息指客户的基本信息、职业、兴趣爱好等信息，具体包括个人信息、家庭状况、职业信息、教育背景、投资偏好和目标、生活兴趣与习惯等。故本题选A选项。"},{"id":"advisor2-16","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"单选","q":"利率下降，则债券的贴现率（），债券价格（）。","options":["上升，下降","下降，下降","上升，上升","下降，上升"],"answer":"D","explain":"D 选项正确，利率和债券价格之间呈现反向变动关系，即利率上升，债券价格下降；利率下降，债券价格上升。故本题选D选项。"},{"id":"advisor2-17","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"单选","q":"某公司上一年度每股收益为1元，公司未来每年每股收益以5%的速度增长，公司未来每年的所有利润都分配给股东。如果该公司股票今年年初的市场价格为 35 元，并且必要收益率为10%，据此下列说法错误的是（）。","options":["该公司股票今年年初的内在价值约等于39 元","该公司股票的内部收益率为8%","该公司股票今年年初市场价格被高估","持有该公司股票的投资者应当在今年年初卖出该公司股票"],"answer":"A","explain":"该公司股票今年年初的内在价值=1×（1+5%）/（10%-5%）=21（元）（A选项错误）。设该公司股票的内部收益率为r，则35=1×（1+5%）/（r-5%），解得：r=8%（B选项正确），因此该公司股票价格被高估（C 选项正确），投资者应当在今年年初卖出该公司股票（D 选项正确）。故本题选A选项。"},{"id":"advisor2-18","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"单选","q":"某客户准备对原油进行对冲交易，现货价格为40美元/桶，1个月后的期货价格为45美元/桶，则零时刻的基差是（）美元。","options":["-8","-5","-3","3"],"answer":"B","explain":"基差是现货价格与期货价格之间的差异，即基差=现货价格-期货价格。本题中的基差=40-45=-5（美元）（B选项正确）。故本题选B选项。"},{"id":"advisor2-19","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"单选","q":"某零息债券在到期日的价值1000元，偿还期为10年，该债券的到期收益率为5%，则其久期为（）年。","options":["9","8","10","7"],"answer":"C","explain":"C 选项正确，麦考利久期是指按照现值计算，投资者能够收回投资债券本金的时间（用年表示），也就是债券期限的加权平均数，其权数是每年的债券利息或本金的现值占当前市价的比重。零息债券的久期等于其到期时间。本题的偿还期为10年，因此其久期也为10 年。故本题选C选项。"},{"id":"advisor2-20","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"单选","q":"目前不存在完全垄断的市场，我国接近完全垄断的行业有（）。","options":["自来水","纺织","石油","钢铁"],"answer":"A","explain":"A 选项正确，在当前的现实生活中没有真正的完全垄断型市场，每个行业都或多或少地存在竞争。公用事业（如发电厂、煤气公司、自来水公司和邮电通信等）和某些资本、技术高度密集型或稀有金属矿藏的开采等行业属于接近完全垄断的市场类型。B 选项错误，该市场结构中，造成垄断现象的原因是产品差别，造成竞争现象的原因是产品同种，即具有可替代性。在国民经济各行业中，制成品（如纺织、服装等轻工业产品）的市场类型一般属于垄断竞争。C、D 选项错误，资本密集型、技术密集型产业，如钢铁、汽车等重工业以及少数储量集中的矿产品如石油等的市场多属寡头垄断类型。故本题选A选项。"},{"id":"advisor2-21","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"单选","q":"特雷诺比率以（）作为风险的度量。","options":["单位系统性风险","非系统性风险","系统性风险","资本性风险"],"answer":"A","explain":"A 选项正确，特雷诺比率以单位系统性风险作为风险的度量，表示投资组合承担每单位系统性风险对应的超额收益。故本题选A选项。"},{"id":"advisor2-22","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"单选","q":"通常来说，指数化投资策略是（）的代表。","options":["战术性投资策略","战略性投资策略","被动型投资策略","主动型投资策略"],"answer":"C","explain":"C 选项正确，根据证券组合管理者对市场有效性的不同看法，其采取的投资策略、管理方法也不尽相同，可以分为三种方式：积极型投资策略、消极型投资策略和半积极型投资策略，其中，积极型又称主动型、消极型又称被动型。通常将指数化投资策略视为消极投资策略的代表，但由此发展而来的各种指数增强型或指数优化型策略已经带有了积极投资的成分，也称之为半积极型投资策略。故本题选C选项。"},{"id":"advisor2-23","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"单选","q":"王某有 1 万元现金，5 万元定期基金，20 万元的房产，每月的生活费为 0.5 万元，还需要偿还房贷0.5万元，那么他的失业保障月数为（）个月。","options":["6","8","28","3"],"answer":"A","explain":"A 选项正确，失业保障月数=存款、可变现资产或净资产/月固定支出=（1+5）/（0.5+0.5）=6。故本题选A选项。"},{"id":"advisor2-24","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"单选","q":"下列对证券投资顾问人员注册登记管理的说法中，错误的是（）。","options":["证券投资顾问不得同时注册为证券分析师","证券投资顾问可以同时注册为证券分析师，但应分开管理以防止可能的利益冲突","向客户提供证券投资顾问服务的人员，应当符合相关从业条件","向客户提供证券投资顾问服务的人员应在中国证券业协会注册登记为证券投资顾问"],"answer":"B","explain":"B 选项错误，向客户提供证券投资顾问服务的人员，应当符合相关从业条件，并在中国证券业协会注册登记为证券投资顾问。证券投资顾问不得同时注册为证券分析师。故本题选B选项。"},{"id":"advisor2-25","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"单选","q":"下列各项中，（）在每个层次中再度按照权重选取前几位的股票构建模拟组合。","options":["分类法","最优法","分层法","完全法"],"answer":"C","explain":"C 选项正确，分层法将投资组合按照某种标准分成若干层次，每个层次代表不同的市场细分领域或不同的投资因素，然后在每个层次中再度按照权重选取前几位的股票构建模拟组合。故本题选C选项。"},{"id":"advisor2-26","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"单选","q":"下列关于基金投资顾问业务的说法中，错误的是（）。","options":["试点机构应当通过风险揭示书等向客户充分揭示相关风险","以预收方式收取的基金投资顾问服务费在确认为投资顾问收入前，可以用于人员激励","试点机构应当制定统一的基金投资组合策略说明书","合规、风控部门每季度应当对基金投资组合策略及实施有效性进行核查评估"],"answer":"B","explain":"B 选项错误，以预收方式收取的基金投资顾问服务费在确认为投资顾问收入前，不得用于人员激励。故本题选B选项。"},{"id":"advisor2-27","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"单选","q":"下列属于绝对估值法是（）。","options":["市盈率","市净率","现金流折现法","企业价值/息税前利润"],"answer":"C","explain":"C 选项符合题意，常用的现金流贴现模型包括红利贴现模型、自由现金流贴现模型、股东现金流贴现模型、经济利润贴现模型等，各种基于现金流贴现的方法均属绝对估值法。A、B、D 选项不符合题意，常见的市盈率、市净率、市销率、企业价值倍数、市值回报增长比等均属相对估值方法。故本题选C选项。"},{"id":"advisor2-28","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"单选","q":"下列行业属于防守型行业的是（）。","options":["TMT行业","食品类","消耗品","商业"],"answer":"B","explain":"B 选项正确，防守型行业的产品往往是生活必需品或是必要的公共服务，公众对其产品有相对稳定的需求。例如，食品业和公用事业就属于典型的防守型行业。A选项错误，TMT（科技、媒体、通信）属于典型的增长型行业。C 选项错误，\"消耗品\"概念较宽泛，若指耐用品（如家电、汽车），则属于周期型行业；若指日用品（如纸巾、清洁剂），可能接近防守型。但题目未明确细分，且选项中\"食品类\"更直接对应防守型行业定义。D 选项错误，商业涵盖零售、服务业等，其需求受经济周期影响较大（如奢侈品消费在经济衰退期下降），整体属于周期型或混合型行业。故本题选B选项。"},{"id":"advisor2-29","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"单选","q":"下列因素中不会影响银行等金融机构资产负债期限结构的是（）。","options":["金融机构新增营业网点数量","股票市场投资收益率上涨5%","客户新增贷款或融资需求","央行宣布上调利率0.25%"],"answer":"A","explain":"资产负债期限结构是指在未来特定的时段内，到期资产（现金流入）与到期负债（现金流出）的构成状况。A选项符合题意，不会影响到到期资产、到期负债问题。B、C、D选项不符合题意，都会影响到期资产（贷款到期）、到期负债（存款到期）。故本题选A选项。"},{"id":"advisor2-30","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"单选","q":"一般而言，风险厌恶型客户的投资需求多倾向于（）。","options":["股票型基金","股票","混合型基金","固定收益类基金"],"answer":"D","explain":"D 选项符合题意，风险厌恶型投资者厌恶风险，对待风险态度消极，不愿为增加收益而承担风险，非常注重投资的资金安全，极力回避风险。适合这类投资者的投资工具包括安全性较高的定期存款、大额存单、国债以及保险等。题中给出的四个选项中，按照风险程度从高到低依次排列为：股票 >股票型基金>混合型基金>固定收益类基金。固定收益基金在四个选项中风险最小，能提供给投资人稳定的收益，同时又有部分保本功能。对于只想获取稳定的经常性收益，却又能承担一定风险的投资人，可考虑此类型基金。故本题选D选项。"},{"id":"advisor2-31","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"单选","q":"以下不属于证券公司、证券投资咨询机构向客户提供证券投资顾问服务应当告知客户的基本信息的是（）。","options":["投资决策由客户作出，投资风险由客户承担","证券投资顾问服务的内容和方式","证券投资顾问的姓名","与投资人约定分享投资收益"],"answer":"D","explain":"证券公司、证券投资咨询机构向客户提供证券投资顾问服务，应当告知客户下列基本信息：①公司名称、地址、联系方式、投诉电话、证券投资咨询业务资格等；②证券投资顾问的姓名及其登记编码（C选项不符合题意）；③证券投资顾问服务的内容和方式（B选项不符合题意）；④投资决策由客户作出，投资风险由客户承担（A选项不符合题意）；⑤证券投资顾问不得代客户作出投资决策。D 选项符合题意，与投资人约定分享投资收益不属于证券公司、证券投资咨询机构向客户提供证券投资顾问服务应当告知客户的基本信息。故本题选D选项。"},{"id":"advisor2-32","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"单选","q":"影响资产配置的主要因素（）。","options":["投资期限","流动性要求","生命周期","资产规模"],"answer":"C","explain":"一般情况下，对于个人投资者而言，生命周期（C选项正确）是影响资产配置的最主要因素。故本题选C选项。"},{"id":"advisor2-33","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"单选","q":"与老年父母同住或者夫妻两人同住的情形，出现在（）。","options":["成长期","成熟期","稳定期","衰老期"],"answer":"B","explain":"B 选项正确，家庭成熟期的居住状况为与老年父母同住或夫妻两人居住。此阶段，可积累的资产达到巅峰，要逐步降低投资风险。A 选项错误，家庭成长期起点是子女出生，终点是子女独立。该阶段建议依旧保持资产流动性，并适当增加固定收益类资产的比例，如债券基金、浮动收益类理财产品。C 选项错误，稳定期为个人生涯角度的划分，这一阶段在职业上已经进入稳定发展期，收入逐步提高，财富积累较多，工作、收入、家庭相对稳定，面临着未来的子女教育、父母赡养、养老退休三大人生重任，这时的投资理财任务是要尽可能多地储备资产、积累财富。这一时期要做好投资规划与家庭现金流规划，以防范疾病、意外、失业等风险。D 选项错误，衰老期起点是夫妻退休，终点是夫妻一方身故。此阶段家庭工作收入大幅降低，以投资理财收入为主，领用养老金，医疗、休闲支出增加。养老和资产传承是该阶段的核心目标。因此，该阶段建议进一步提升资产的安全性，将 80%以上资产投资于储蓄及固定收益类理财产品。故本题选B选项。"},{"id":"advisor2-34","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"单选","q":"在（），创业公司的研究和开发费用较高，销售收入较低。","options":["幼稚期","成长期","成熟期","衰退期"],"answer":"A","explain":"A 选项正确，在初创期（幼稚期），创业公司的研究和开发费用较高，而大众对其产品尚缺乏全面了解，致使产品市场需求狭小，销售收入较低，因此这些创业公司财务上可能不但没有盈利，反而出现较大亏损。故本题选A选项。"},{"id":"advisor2-35","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"单选","q":"在半强式有效市场中，下列说法中，错误的是（）。","options":["基本面分析无效","反映了公开信息","技术分析无效","反映了内幕信息"],"answer":"D","explain":"A、B、C 选项正确，D 选项错误，在半强式有效市场中，资产价格已经反映了与资产价格相关的所有公开信息（包括历史成交的量价信息、其他全部公开的历史信息、全部现时公开信息），不包括内幕信息。故本题选D选项。"},{"id":"advisor2-36","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"单选","q":"在收集客户信息的过程中，属于定性信息的是（）。","options":["资产负债状况","投资组合","投资偏好","投资经验"],"answer":"C","explain":"客户信息可以分为定量信息和定性信息：（1）定性信息则更多关注客户的意愿、偏好和目标，包括姓名、性别、家庭状况、职业、个人兴趣爱好、投资偏好（C选项符合题意）等，通过与客户的交流和调查等方式获取；（2）定量信息主要是客户的财务数据和可度量的量化指标，可以直接进行计算和分析，包括客户的年龄、收入水平、资产负债状况（ A 选项不符合题意）、投资组合（ B 选项不符合题意）、投资经验（D选项不符合题意）、风险承受能力等信息。故本题选C选项。"},{"id":"advisor2-37","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"单选","q":"证券A的贝塔系数是1.2，证券 B的贝塔系数是 0.8，下列正确的是（）","options":["证券A的非系统风险最大","证券B的非系统风险最大","证券A的系统风险最大","证券B的系统风险最大"],"answer":"C","explain":"β 系数是衡量证券承担系统风险水平的指数，可以用来衡量承担系统风险（A、B 选项错误）的大小。如果某资产的 β>1，说明该资产相比于整个市场波动性更大。相反，如果资产的 β<1，说明该资产相比于市场波动性更小（C选项正确、D选项错误）。故本题选C选项。"},{"id":"advisor2-38","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"单选","q":"证券市场技术分析是以一定的假设条件为前提的，这些假设不包括（）。","options":["市场行为涵盖一切信息","证券价格沿趋势移动","历史会重演","指标须可靠"],"answer":"D","explain":"证券市场技术分析是以一定的假设条件为前提的，这些假设是：（1）市场行为涵盖一切信息（是进行技术分析的基础）（A选项不符合题意）；（2）证券价格沿趋势移动（进行技术分析最根本、最核心的条件）（B选项不符合题意）；（3）历史会重演（从人的心理因素方面考虑的）（C选项不符合题意）。D选项符合题意，指标须可靠不是证券市场技术分析的前提假设条件。故本题选D选项。"},{"id":"advisor2-39","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"单选","q":"证券投资顾问可以通过广播、电视、网络、报刊等公众媒体，客观、专业、审慎地对（）发表评论意见。","options":["特定的分级基金","特定的指数期货合约","某上市公司","宏观经济、行业状况、证券市场变动情况"],"answer":"D","explain":"D 选项正确，证券公司、证券投资咨询机构可组织安排证券投资顾问人员，按照证券信息传播的有关规定，通过广播、电视、网络、报刊等公众媒体，客观、专业、审慎地对宏观经济、行业状况、证券市场变动情况发表评论意见，为公众投资者提供证券咨询服务，传播证券知识，揭示投资风险，引导理性投资。故本题选D选项。"},{"id":"advisor2-40","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"ETF的特点包括（）。","options":["被动操作的指数基金","独特的实物申购、赎回机制","主动操作的指数基金","实行一级市场与二级市场并存的交易制度"],"answer":"ABD","explain":"ETF 的特点有：（1）被动操作的指数基金；（2）独特的实物申购、赎回机制；（3）实行一级市场与二级市场并存的交易制度。故本题选ABD选项。"},{"id":"advisor2-41","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"按投资风格划分，股票投资策略可分为（）。","options":["价值型投资策略","成长性投资策略","平衡型投资策略","另类型投资策略"],"answer":"ABC","explain":"按照投资风格划分，可分为价值型投资策略（A 选项正确）、成长型投资策略（B 选项正确）和平衡型投资策略（C选项正确）。故本题选ABC选项。"},{"id":"advisor2-42","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"反转突破的几种形态中，未来走势向下的可能性较大的有（）。","options":["头肩顶形态","头肩底形态","双重顶形态","圆弧顶形态"],"answer":"ACD","explain":"A 选项正确，是一个可靠的沽出时机，当价格有效跌破连接左右肩低点的颈线时，形态确认，标志着上涨趋势终结，下跌趋势启动。C 选项正确，双重顶因形态酷似\"M\"字得名，是常见的顶部反转形态。其形成过程为：价格两次冲击相近高点（颈线为两次回调低点连线），第二次冲高时成交量萎缩（显示多头动力不足），随后跌破颈线，确认下跌趋势。D 选项正确，圆弧顶是渐变的顶部反转形态，价格呈弧形缓慢上升后反转，反映多空力量的缓慢转换。其形成过程中，成交量逐渐萎缩（多头热情消退），当价格跌破圆弧的切线支撑时，下跌行情加速。B 选项错误，头肩底是头肩顶的倒转形态，是一个可靠的买进时机，未来走势向上的可能性较大。故本题选ACD选项。"},{"id":"advisor2-43","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"个人投资者的特点包括（）。","options":["投资的专业性强","资金规模有限","专业知识相对匮乏","投资行为具有随意性、分散性和短期性"],"answer":"BCD","explain":"个人投资者的特点：①资金规模有限（主要来源于自有资金）（B选项符合题意）；②专业知识相对匮乏（C选项符合题意）；③投资行为具有随意性、分散性和短期性（D选项符合题意）；④投资的灵活性强（较机构投资者有更多的短期投资获利机会）。A选项不符合题意，投资的专业性强属于机构投资者的特点。故本题选BCD选项。"},{"id":"advisor2-44","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"根据可贷资金理论，以下说法正确是（）。","options":["储蓄S（i），与利率正相关","货币供给增加额ΔMs（i）货币供给变动是由央行决定的","货币供给变动与利率正相关","利率与货币反窖藏正相关"],"answer":"ABCD","explain":"可贷资金的供给认为：①储蓄S（i），与利率正相关，是可贷资金供给的主要来源（A选项正确）。②货币供给增加额 ΔMs（i）货币供给变动是由央行决定的，但考虑到利率与超额准备金的反向关系，即利率上升时超额准备金率下降，货币供给将增加，因此认为货币供给变动与利率正相关（B、C选项正确）。③货币的反窖藏 DH（i），即人们将窖藏的货币用于购买债券或放贷，利率越高，对债券的需求以及将货币用于放贷的动力越强，因此货币的反窖藏越多，即利率与货币反窖藏正相关（ D选项正确）。故本题选ABCD选项。"},{"id":"advisor2-45","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"根据有效市场理论，下列说法正确的是（）。","options":["在有效率的市场中，投资者所获得的收益只能是与其承担的风险相匹配的那部分正常收益，而不会有高出风险补偿的超额收益","只要证券价格充分反映了全部有价值的信息，市场价格代表着证券的真实价值，这样的市场就称为有效市场","在有效率的市场中，不存在非正常报酬","在有效率的市场中，一组特定的信息能够在股票市场上随即被投资者知晓"],"answer":"ABCD","explain":"A、C、D 选项正确，有效市场假说理论认为，在一个充满信息交流和信息竞争的社会里，一组特定的信息能够在股票市场上随即被投资者知晓。随后，股票市场的竞争将会驱使股票价格充分且及时地反映该组信息，从而使得投资者根据该组信息所进行的交易不存在非正常报酬，而只能赚取风险调整的平均市场报酬率。B 选项正确，只要证券的市场价格充分及时地反映了全部有价值的信息、市场价格代表着证券的真实价值，这样的市场就称为有效市场。故本题选ABCD选项。"},{"id":"advisor2-46","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"构建基金组合的步骤有（）。","options":["风险承受能力评估","确定投资目标","确定配置方案","定量评价"],"answer":"ABC","explain":"构建基金组合的步骤有：①风险承受能力评估（A选项正确）；②确定投资目标（B选项正确）；③确定配置方案（C选项正确）。D 选项错误，后续绩效评估环节的方法，不属于前期构建步骤，更多属于组合管理阶段的 \"监控与评估\"环节。故本题选ABC选项。"},{"id":"advisor2-47","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"关于RSⅠ的应用法则，下列说法正确的是（）","options":["将100分成五个区域，根据RSI 的取值落入的区域进行操作","股票越活跃，RSI所能达到的高度越高","RSI的取值范围介于050之间","当短期RSI>长期RSI时，属多头市场"],"answer":"BD","explain":"A 选项错误，根据 RSI 取值的大小判断行情。将 100 分成四个（并非五个）区域，根据 RSI 的取值落入的区域进行操作。C选项错误，RSI的取值范围介于0100（并非 050）之间。故本题选BD选项。"},{"id":"advisor2-48","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"关于客户的证券投资需求与理财需求间的关系，下列说法正确的有（）。","options":["证券投资是客户个人理财需求的一个重要组成部分","收入越高的客户越热衷于以证券投资需求为其主要理财方式","券商可以给客户设计出风险偏低的证券投资组合","对于偏好银行理财产品的客户，股票投资是属于偏激进型"],"answer":"ACD","explain":"B 选项错误，客户选择何种理财方式为主要方式，并非仅由收入高低决定，还受风险偏好、投资期限、理财目标、年龄阶段、专业知识储备等多重因素影响。故本题选ACD选项。"},{"id":"advisor2-49","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"关于外币汇率上升、本币贬值对证券市场影响，下列说法正确的有（）。","options":["导致资本流出本国，证券市场需求减少市场价格下跌","本币表示的进口商品价格提高，带动国内物价水平上涨，引起通货膨胀","出口型企业的股票价格上涨","政府可能动用外汇储备，抛售外汇减少本币供应量，证券市场价格下跌"],"answer":"ABCD","explain":"A 选项正确，同时，汇率上升，本币贬值，将导致资本流出本国，资本的流失将使得本国证券市场需求减少，从而市场价格下跌。B 选项正确，汇率上升时，本币表示的进口商品价格提高，进而带动国内物价水平上涨，引起通货膨胀。C 选项正确，以外币为基准，汇率上升，本币贬值，本国产品竞争力强，出口型企业将增加收益，因而企业的股票和债券价格将上涨；相反，依赖于进口的企业成本增加，利润受损，股票和债券的价格将下跌。D 选项正确，为维持汇率稳定，政府可能动用外汇储备，抛售外汇，从而减少本币的供应量，使得证券市场价格下跌，直到汇率回落恢复均衡，反面效应可能使证券价格回升。故本题选ABCD选项。"},{"id":"advisor2-50","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"管理型投资顾问业务的投资组合管理及资产配置步骤包括（）。","options":["明确投资组合管理的目标","制定投资组合管理政策","建立战略性资产配置","对证券投资组合进行修正"],"answer":"ABCD","explain":"管理型投资顾问业务的投资组合管理及资产配置步骤，包括：明确投资组合管理的收益目标（A 选项正确），根据投资目标制定相应的组合管理政策（B 选项正确），形成资本市场预期，建立战略性资产配置方案（C 选项正确），构建具体的投资组合，对投资组合进行修正（D 选项正确），评价投资组合的业绩。故本题选ABCD选项。"},{"id":"advisor2-51","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"划分产品或者服务风险等级时应综合考虑的因素有（）。","options":["流动性","杠杆情况","募集方式","投资单位产品或者相关服务的最高金额"],"answer":"ABC","explain":"划分产品或者服务风险等级时应当综合考虑以下因素：①流动性（A选项正确）；②到期时限；③杠杆情况（B选项正确）；④结构复杂性；⑤投资单位产品或者相关服务的最低金额（D选项错误，并非最高）；⑥投资方向和投资范围；⑦募集方式（C选项正确）；⑧发行人等相关主体的信用状况；⑨同类产品或者服务过往业绩；⑩其他因素。故本题选ABC选项。"},{"id":"advisor2-52","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"技术分析方法包括（）方法。","options":["价格类","形态类","指标类","K线类"],"answer":"BCD","explain":"一般来说，可以将技术分析方法分为常用的五类，即 K 线类（D 选项符合题意）、切线类、形态类（B选项符合题意）、波浪类、指标类（C选项符合题意）。故本题选BCD选项。"},{"id":"advisor2-53","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"家庭紧急预备金的储存形式包括（）。","options":["短期定期存款","活期存款","货币市场基金","未使用的贷款融资额度"],"answer":"ABCD","explain":"紧急预备金可以用两种方式来储备：一是持有期限短、流动性强、容易变现、价值变动风险很小的金融工具，包括活期存款（B 选项符合题意）、短期定期存款（A选项符合题意）、货币市场基金（C选项符合题意）等；二是未使用的贷款融资额度（D选项符合题意）和信用卡额度。故本题选ABCD选项。"},{"id":"advisor2-54","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"敏感性分析是指在保持其他条件不变的前提下，研究单个市场风险要素，包括（）的微小变化可能会对金融工具或资产组合的收益或经济价值产生的影响。","options":["股票价格","商品价格","利率","汇率"],"answer":"ABCD","explain":"A、B、C、D 选项符合题意，敏感性分析是指在保持其他条件不变的前提下，研究单个市场风险要素（利率、汇率、股票价格和商品价格）的微小变化可能会对金融工具或资产组合的收益或经济价值产生的影响。故本题选ABCD选项。"},{"id":"advisor2-55","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"某投资者于年初将10万元本金按年利率8%进行投资，那么，该项投资（）。","options":["按单利计算，在投资第二年年末的终值为11.4万元","按单利计算，在投资第三年年末的终值为12.4万元","按复利计算，在投资第二年年末的终值为11.664万元","按复利计算，在投资第三年年末的终值为15.3896万元"],"answer":"BC","explain":"A选项错误，按单利计算，在投资第二年年末的终值为10×（1+8%×2）=11.6（万元）。B选项正确，按单利计算，在投资第三年年末的终值为10×（1+8%×3）=12.4（万元）。C选项正确，按复利计算，在投资第二年年末的终值为10×（1+8%）2=11.664（万元）。D选项错误，按复利计算，在投资第三年年末的终值为10×（1+8%）3=12.59712（万元）。故本题选BC选项。"},{"id":"advisor2-56","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"评价组合管理的业绩需考虑的主要因素包括（）。","options":["组合收益的高低","组合承担的风险","组合的规模","组合管理者的收入"],"answer":"AB","explain":"A、B 选项符合题意，证券投资组合的业绩评价既要考虑组合收益的高低，也要考虑组合所承担风险的大小。故本题选AB选项。"},{"id":"advisor2-57","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"投资顾问在对客户正常情况下的收入进行预测时，主要预测（）。","options":["常规性收入","收入最低情况下的收入","临时性收入","上一年的实际收入"],"answer":"AC","explain":"客户正常情况下的收入，主要是根据以往收入和宏观经济情况下的合理预期。在预测客户未来收入时，可以将收入分为常规性收入（A选项正确）和临时性收入（C选项正确）两类。故本题选AC选项。"},{"id":"advisor2-58","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"我国目前拥有的信用风险缓释工具包括（）。","options":["信用风险缓释合约","信用风险缓释凭证","信用违约互换","信用联结票据"],"answer":"ABCD","explain":"A、B、C、D选项符合题意，目前我国共有4种银行间市场信用风险缓释工具，分别是信用风险缓释合约、信用风险缓释凭证、信用违约互换、信用联结票据。故本题选ABCD选项。"},{"id":"advisor2-59","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"下列对主观CTA策略的表述，说法正确的有（）。","options":["主观CTA策略是指投资决策方式为主观研究、主观决策和主观交易的策略","主观CTA策略对期货合约的历史交易数据进行统计","主观CTA策略的研究重点是期货合约的标的物价格的走势和变化","主观CTA策略考量的是投资经理对基本面或产业链的研究能力"],"answer":"ACD","explain":"A选项正确，主观CTA策略是指投资决策方式为主观研究、主观决策和主观交易的策略。C、D选项正确，主观CTA策略的研究重点是期货合约的标的物价格的走势和变化，考量的是投资经理对基本面或产业链的研究能力。B 选项错误，量化 CTA 策略是指通过对期货合约的历史交易数据进行统计来寻求合约价格变化规律，并通过数量模型给出的信号进行交易的策略。故本题选ACD选项。"},{"id":"advisor2-60","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"下列各类公司或行业，不适宜采用市盈率进行估值的有（）。","options":["成熟行业","亏损公司","周期性公司","服务行业"],"answer":"BC","explain":"市盈率估值方法一般适用于周期性较弱企业，如一般制造业、服务业，不适用于亏损公司（ B选项正确）、周期性公司（C选项正确）。A选项错误，成熟行业不适宜采用市盈率相对盈利增长比率进行估值。D选项错误，服务行业不适宜采用市净率进行估值。故本题选BC选项。"},{"id":"advisor2-61","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"下列各项中，（）属于货币时间价值的影响因素。","options":["通货膨胀率","单利","复利","时间"],"answer":"ABCD","explain":"计算货币时间价值的基本参数有以下4个，也是影响货币时间价值的主要因素：（1）现值：指货币现在的价值。（2）终值：指货币在未来某个时间点上的价值，通常用 FV 表示。资金的时间价值一般按照复利方式计算。复利（C 选项符合题意）是指不仅本金要计利息，利息也要计利息，也就是通常所说的\"利滚利\"。如果一定金额的本金按照单利（B 选项符合题意）计算若干期后的本利和，则称为单利终值；如果一定金额的本金按照复利计算若干期后的本利和，则称为复利终值。（3）时间（D选项符合题意）：是货币价值的参照系数。（4）利率：是影响货币时间价值波动的要素，在现值计算中利率也被称为贴现率。A 选项教材未直接提及，但通货膨胀率实际影响货币的购买力，从而间接影响利率（如名义利率需补偿通胀），因此，A选项符合题意，通货膨胀是隐含的影响因素。故本题选ABCD选项。"},{"id":"advisor2-62","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"下列各项中，可以证实市场不是半强式有效市场的有（）。","options":["股票分割消息宣布后不产生利得","内幕知情人可以从内幕交易中获利","投资者在盈余宣布很长时间后才能做出交易反应","基于公司规模及股票账面价值与市场的比率的投资策略可以从中获利"],"answer":"CD","explain":"在半强式有效市场上，证券的价格反映了包括历史信息在内的所有公开发表的信息，即公开可得信息，在市场中，基本分析和技术分析失效。A选项错误，基本分析失效；B选项错误，只能证实市场不是强式有效；C、D选项错误，基本分析有效。故本题选CD选项。"},{"id":"advisor2-63","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"下列关于ρAB的说法正确的是（）。","options":["当ρAB=1时，弯曲程度最大，呈直线","当ρAB=1时，弯曲程度最小，呈直线","当ρAB=1时，弯曲程度最小，呈折线","当ρAB=-1时，弯曲程度最大，呈折线"],"answer":"BD","explain":"相关系数决定结合线在A与 B点之间的弯曲程度，随着 ρAB的增大，弯曲程度将降低。当ρAB=1时，弯曲程度最小，呈直线（A选项错误、B选项正确）；当ρAB=-1时，弯曲程度最大，呈折线（C选项错误、D选项正确）；不相关是一种中间状态，比正完全相关弯曲程度大，比负完全相关弯曲程度小。故本题选BD选项。"},{"id":"advisor2-64","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"下列关于从事证券投资顾问业务违反相关法律法规的后果说法错误的是（）。","options":["由中国证监会及其派出机构给予处罚","涉嫌犯罪的，由司法机关依法量刑","情节严重的，由司法机关依照法律、行政法规和有关规定作出行政处罚","中国证监会及其派出机构采取的处罚措施中不包括暂停新增客户"],"answer":"CD","explain":"证券公司、证券投资咨询机构及其人员从事证券投资顾问业务，违反法律、行政法规和《证券投资顾问业务暂行规定》的，中国证监会及其派出机构可以采取责令改正、监管谈话、出具警示函、责令增加内部合规检查次数并提交合规检查报告、责令清理违规业务、责令暂停新增客户（D选项错误）、责令处分有关人员等监管措施；情节严重的，中国证监会依照法律、行政法规和有关规定作出行政处罚（C 选项错误，应该是中国证监会，而不是司法机关）；涉嫌犯罪的，依法移送司法机关。故本题选CD选项。"},{"id":"advisor2-65","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"下列关于缺口分析法的说法中，正确的有（）。","options":["只要不存在流动性缺口，就不存在流动性风险","流动性缺口就是融资性缺口","缺口分析法是针对未来特定时段，计算到期资产和到期负债之间的差额","通过判断流动性缺口，可以判断金融机构不同时段内流动性是否充足"],"answer":"CD","explain":"缺口分析法针对未来特定时段，计算到期资产（现金流入）和到期负债（现金流出）之间的差额（C 选项正确），即流动性缺口，以判断金融机构在不同时段内的流动性是否充足（D 选项正确）。A选项错误，流动性缺口仅为衡量风险的指标之一，即使缺口为零，仍可能存在风险。B 选项错误，流动性缺关注资产与负债的期限匹配，衡量短期偿债能力，融资性缺口通常指融资需求与稳定资金来源的差额，属于更广义的流动性管理概念。故本题选CD选项。"},{"id":"advisor2-66","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"下列关于证券市场的说法中，错误的有（）。","options":["证券市场供给的主体是投资银行，其数量是证券市场供给的主要影响因素","宏观经济环境的变化对证券市场供给影响不大","上市公司的质量状况会影响公司的再融资，从而影响股票的供给","股权分置改革对证券市场供给影响不大"],"answer":"ABD","explain":"A 选项错误，证券市场的供给主体是上市公司（企业）、政府与政府机构以及金融机构。上市公司的质量和数量会影响证券市场的供给，其中，质量是最根本的因素。B 选项错误，如果宏观经济运行良好，投资扩张的企业增多，融资的需求增加，这时将有更多的企业申请公开发行股票；同时，投资者良好的预期会促使其积极参与认购，上市公司数量也随之增加。C 选项正确，上市公司的质量影响证券市场的前景、投资者的收益及投资热情、大盘指数及个股价格变动，这些因素将直接或间接影响证券市场的供给。上市公司的质量和业绩情况也会影响公司本身的再筹资，从而影响股票的供给。因此上市公司质量与经济效益是影响证券市场供给的最根本因素。D选项错误，股权分置改革对证券市场供给影响很大。故本题选ABD选项。"},{"id":"advisor2-67","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"下列说法正确的有（）","options":["套利定价理论和马柯威茨理论一样都属于多因素模型","套利定价理论有三个基本假设","套利定价理论认为，只有投资者的套利行为不断进行直至套利机会出现，市场才能形成证券的均衡价格","套利定价理论认为，只有投资者的套利行为不断进行直至套利机会消失，市场才能形成证券的均衡价格"],"answer":"BD","explain":"A选项错误，套利定价理论（APT）是典型的多因素模型。B 选项正确，与资本资产定价模型（CAPM）相比，建立套利定价理论的假设条件较少，可概括为三个基本假设。C 选项错误、D 选项正确，套利组合理论认为，当市场上存在套利机会时，投资者会不断进行套利交易，从而不断推动证券的价格向套利机会消失的方向变动，直到套利机会消失为止，此时证券的价格即为均衡价格，市场也就进入均衡状态。故本题选BD选项。"},{"id":"advisor2-68","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"下列行业中，美林投资时钟模型的指导意义相对较强的有（）。","options":["可选消费","石油和天然气","电信","公共事业"],"answer":"AB","explain":"美林投资时钟的核心是基于经济周期和通胀水平的双维度变化，分析行业盈利和估值的轮动规律，其指导意义的强弱，核心取决于行业的周期性特征：①顺周期（尤其是强周期）行业与经济、通胀周期关联度高，盈利和股价轮动显著，指导意义强；②防御性行业需求刚性、盈利稳定，周期波动小，指导意义弱。A 选项符合题意，可选消费的需求高度依赖居民收入水平和消费意愿，属于典型的顺周期行业。其盈利和股价随经济周期的轮动特征突出，完美契合美林时钟的周期分析框架。B 选项符合题意，油气行业是强顺周期和通胀敏感型行业，盈利和价格同时受经济供需、通胀水平双重驱动。其波动与美林时钟的\"经济+通胀\"双维度分析高度匹配，是时钟模型中大宗商品类资产的核心代表。C 选项不符合题意，电信服务是居民和企业的基础刚需，无论经济周期如何波动，需求都相对稳定，企业盈利的周期性波动极小。D 选项不符合题意，公共事业是生活必需品，需求具有极强的刚性，盈利受经济周期、通胀水平的影响几乎可以忽略。故本题选AB选项。"},{"id":"advisor2-69","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"下列应列入个人现金流量表的是（）。","options":["利息收入","股票","头发护理费用","汽车及住房"],"answer":"AC","explain":"现金流量表是一定时期内的现金收入与支出的变化情况表，其表内项目如下图所示:B 选项不符合题意，股票是个人持有的金融资产，属于存量指标，仅代表某一时点的资产价值，不会直接产生现金收付。只有买卖股票时产生的现金收支才需要列入，股票本身这个资产项目不列入现金流量表。D 选项不符合题意，汽车和住房属于固定资产，是某一时点的资产存量。只有购买汽车 /住房时的现金支出、出售时的现金流入需要列入，汽车及住房本身不列入现金流量表。故本题选AC选项。"},{"id":"advisor2-70","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"有效市场的支持者极力主张（）。","options":["价值投资","投资于指数基金","被动性的投资策略","主动性的投资策略"],"answer":"BC","explain":"信奉市场有效性的投资者认为：在任何时候，市场价格都是公司真实价值的最优估计，任何试图通过挖掘市场无效部分而获利的行为是得不偿失的。因此这些投资者会主张被动型投资策略（C选项正确），投资于指数基金（B选项正确）。故本题选BC选项。"},{"id":"advisor2-71","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"与股票基金相比，债券基金的特点有（）。","options":["适合追求稳定收入的投资者","不受经济环境变化的影响","收益、风险适中","波动相对较小"],"answer":"ACD","explain":"债券基金的波动性通常要小于股票基金（D 选项正确），因此常常被投资者认为是收益、风险适中的投资工具（C 选项正确），对追求稳定收入的投资者具有较强的吸引力（A 选项正确）。故本题选ACD选项。"},{"id":"advisor2-72","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"预计某公司今年年末每股收益为 2 元，每股股息支付率为 90%，并且该公司以后每年每股股利将以5%的速度增长。如果某投资者希望内部收益率不低于10%，那么，（）。","options":["他在今年年初购买该公司股票的价格应小于18元","他在今年年初购买该公司股票的价格应大于38元","他在今年年初购买该公司股票的价格应不超过36元","该公司今年年末每股股利为1.8元"],"answer":"CD","explain":"今年年末的每股股利=2×90%=1.8（元）（D选项正确）；投资者希望内部收益率不低于 10%，则其在今年年初购买股票的价格应该不超过：1.8/（10%-5%）=36（元）（A、B选项错误，C选项正确）。故本题选CD选项。"},{"id":"advisor2-73","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"张某今年 56 岁，目前没有家庭债务负担，且其儿子已经工作并结婚。下述关于理财规划的表述，适合张某的是（）。","options":["以保守稳健型投资为主，配以适当比例的进取型投资","以活期、定期储蓄为主","以中高风险的组合投资为主要财务投资手段","多配置基金、债券、储蓄、固定收益理财产品"],"answer":"AD","explain":"根据题干，张某今年 56 岁，目前没有家庭债务负担，且其儿子已经工作并结婚，是属于个人生命周期的高峰期。A、D 选项正确，个人的主要投资理财任务是保障资产的稳健增值，降低投资风险，资产配置上以稳健型投资为主，配以适当比例的进取型投资，主要配置债券、银行存款、固定收益理财产品等，辅以适当比例的基金，主要配置债券、银行存款、固定收益理财产品等，辅以适当比例的基金，以相对稳健的方式使资产得以保值增值。B选项错误，以活期、定期为主一般属于退休期的理财特点；C选项错误，以中高风险组合为主要财务投资手段的属于稳定期的投资特征。故本题选AD选项。"},{"id":"advisor2-74","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"证券公司、证券投资咨询机构及其人员从事证券投资顾问业务，违反法律、行政法规和相关规定的，中国证监会及其派出机构可以采取监管措施，下列属于相关监管措施的有（）。","options":["监管谈话","出具警示函","处以罚款","责令处分有关人员"],"answer":"ABD","explain":"证券公司、证券投资咨询机构及其人员从事证券投资顾问业务，违反法律、行政法规和《证券投资顾问业务暂行规定》的，中国证监会及其派出机构可以采取责令改正、监管谈话（A 选项正确）、出具警示函（B 选项正确）、责令增加内部合规检查次数并提交合规检查报告、责令清理违规业务、责令暂停新增客户、责令处分有关人员（D 选项正确）等监管措施；情节严重的，中国证监会依照法律、行政法规和有关规定作出行政处罚；涉嫌犯罪的，依法移送司法机关。C选项错误，\"处以罚款\"属于行政处罚。故本题选ABD选项。"},{"id":"advisor2-75","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"证券公司、证券投资咨询机构可以组织证券投资顾问，通过广播电视、网络、报刊等公众媒体，客观、专业、审慎地（）。","options":["对宏观经济、行业状况发表评论意见","对证券市场变动情况发表评论意见","提供买入、卖出或持有具体证券的投资建议","提供股票组合的买入卖出建议"],"answer":"AB","explain":"A、B 选项正确，证券投资咨询机构可组织安排证券投资顾问人员，按照证券信息传播的有关规定，通过广播、电视、网络、报刊等公众媒体，客观、专业、审慎地对宏观经济、行业状况、证券市场变动情况发表评论意见，为公众投资者提供证券咨询服务，传播证券知识，揭示投资风险，引导理性投资。C、D选项错误，属于禁止性行为。故本题选AB选项。"},{"id":"advisor2-76","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"证券经营机构向投资者销售产品或提供服务时，应当了解投资者的下列（）信息。","options":["财务状况","投资经验","投资目标","诚信记录"],"answer":"ABCD","explain":"证券经营机构向投资者销售产品或者提供服务时，应当了解投资者的下列信息：（1）自然人的姓名、住址、职业、年龄、联系方式，法人或者其他组织的名称、注册地址、办公地址、性质、资质及经营范围等基本信息；（2）收入来源和数额、资产、债务等财务状况（A选项正确）；（3）投资相关的学习、工作经历及投资经验（B选项正确）；（4）投资期限、品种、期望收益等投资目标（C选项正确）；（5）风险偏好及可承受的损失；（6）诚信记录（D选项正确）；（7）实际控制投资者的自然人和交易的实际受益人；（8）法律法规、自律规则规定的投资者准入要求相关信息；（9）其他必要信息。故本题选ABCD选项。"},{"id":"advisor2-77","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"证券投资咨询业务的基本形式包括（）。","options":["证券投资顾问","委托理财","发布证券研究报告","销售基金"],"answer":"AC","explain":"2010年10月12日，为进一步规范投资咨询业务，中国证监会同时颁布了《发布证券研究报告暂行规定》和《证券投资顾问业务暂行规定》，明确了证券投资顾问（A 选项符合题意）和发布证券研究报告（C选项符合题意）业务是证券投资咨询业务的两类基本形式。B 选项不符合题意，委托理财属于资产管理业务（如券商资管、基金专户），需取得相应牌照，与咨询业务的\"建议辅助\"性质不同，故排除。D 选项不符合题意，基金销售属于证券经纪或财富管理业务，需基金销售资格，与咨询业务无直接关联，故排除。故本题选AC选项。"},{"id":"advisor2-78","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"证券相对估值的常用指标包括（）。","options":["市盈率","权益现金流","经济增加值与利息折旧摊销前收入比","资本现金流"],"answer":"AC","explain":"相对估值通常需要运用证券的市场价格与某个财务指标之间存在的比例关系对证券进行估值。如常见的市盈率（A 选项正确）、市净率、市销率、经济增加值与利息折旧摊销前收入比（ C选项正确）等均属相对估值方法。故本题选AC选项。"},{"id":"advisor2-79","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"多选","q":"资本资产定价模型的假设条件包括（）。","options":["证券的收益率具有确定性","资本市场没有摩擦","投资者都依据组合的期望收益率和方差选择证券组合","投资者对证券的收益和风险及证券间的关联性具有完全相同的预期"],"answer":"BCD","explain":"资本资产定价模型的假设条件可概括为3项：①投资者都依据期望收益率评价证券组合的收益水平，依据方差（或标准差）评价证券组合的风险水平，并按照投资者共同偏好规则选择最优证券组合（C选项符合题意）。②投资者对证券的收益、风险及证券间的关联性具有完全相同的预期（D选项符合题意）。③资本市场没有摩擦（B选项符合题意）。故本题选BCD选项。"},{"id":"advisor2-80","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"判断","q":"\"倒微笑曲线周期\"是基金定投最不适合的市场条件，投资者需要在可能出现的 \"倒微笑曲线周期\"及时止盈。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。适合基金定投的市场走势：\"先下跌后回升\"是最适合基金定投的；\"震荡向上\"仍然能保持盈利，但较期初一次性投资盈利较少；在\"震荡向下\"的市场条件下，基金定投能够有效地降低持仓成本；\"先升后回落\"即\"倒微笑曲线周期\"是基金定投最不适合的市场条件，投资者需要在可能出现的\"倒微笑曲线周期\"及时止盈。"},{"id":"advisor2-81","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"判断","q":"从价值链的角度来看，对不同国家和地区间产业竞争力的比较，需要建立在最终产品或服务的比较上，特别是需要就产业价值链条上的某几个价值环节的经济效益进行比较。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。企业是集管理、设计、采购、生产、销售、交货一系列创造价值活动组成的链条式集合体，企业的竞争优势来源于自身与对手在价值链上的差异。从价值链的角度来看，对不同国家或地区间产业竞争力的比较，并不一定需要建立在最终产品或服务的比较上，只需要就产业价值链条上的某几个价值环节的经济效益进行比较或对其中间产品或半成品进行比较。"},{"id":"advisor2-82","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"判断","q":"道氏理论认为，最重要的价格是收盘价。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。道氏理论认为收盘价是最重要的价格，并利用收盘价计算平均价格指数。"},{"id":"advisor2-83","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"判断","q":"短期债券一般不付息，而是到期一次性还本。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。短期债券一般不付息，而是到期一次性还本，因此要折价交易。"},{"id":"advisor2-84","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"判断","q":"风险认知度反映的是客户主观上对风险的基本态度，也是一种不确定性在客户心理上产生的影响。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。风险偏好反映的是客户主观上对风险的基本态度，也是一种不确定性在客户心理上产生的影响。风险认知度反映的是客户对风险的主观评价。"},{"id":"advisor2-85","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"判断","q":"风险转移可分为保险转移和非保险转移。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。风险转移是指通过支付保费、购买衍生工具（如互换）或结构化产品等方式，将自身的风险转移给保险公司、衍生品交易对手等第三方。风险转移可分为保险转移和非保险转移。"},{"id":"advisor2-86","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"判断","q":"管理型基金投资顾问服务的单个客户持有单只基金的市值，不得高于该客户委托资产市值的10%，货币市场基金、指数基金不受此限。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。管理型基金投资顾问服务的单一客户持有单只基金的市值不得高于该客户委托资产市值的 20%（并非 10%），货币市场基金、宽基指数及宽基指数增强基金、养老目标基金、基金中基金产品及中国证监会认可的其他品种除外。"},{"id":"advisor2-87","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"判断","q":"基金投资顾问业务试点机构应当在负责投资业务的部门层面建立专门的投资决策委员会负责审议投资组合策略的产生和调整，并评估形成投资组合策略的风险特征。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。投资决策委员会是公司层面建立的，不是在负责投资业务的部门层面建立。"},{"id":"advisor2-88","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"判断","q":"考察公司短期偿债能力的关键是考察公司的资金周转能力。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。变现能力是公司产生现金的能力，它取决于可以在近期转变为现金的流动资产的多少，是考察公司短期偿债能力的关键（并非资金周转能力）。"},{"id":"advisor2-89","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"判断","q":"利率与债券的价格呈正相关关系。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。利率对债券价格影响最为直接，主要由于利率是债券未来现金流的折现率，债券的本金和利息现金流的现值随利率变化而变化。因此，债券的价格与利率呈反向关系（并非正相关关系），即利率上升，债券价格下降；利率下降，债券价格上升。"},{"id":"advisor2-90","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"判断","q":"两个风险证券的相关系数越小，它们构造组合形成的可行域弯曲度越小。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。相关系数的取值范围是[-1，1]，相关系数越小，可行域的弯曲程度越大（可行域的弯曲程度并非越小）。"},{"id":"advisor2-91","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"判断","q":"三角形态是属于持续整理形态的一类形态，三角形主要分为对称三角形、上升三角形和下降三角形。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。持续整理形态主要包括三角形、矩形、旗形和楔形。三角形整理形态主要分为对称三角形、上升三角形和下降三角形。"},{"id":"advisor2-92","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"判断","q":"稳健型投资者既不厌恶风险也不追求风险，对任何投资都比较理性，往往会仔细分析不同的投资市场、工具与产品，从中寻找风险适中、收益适中的产品、获得社会平均水平的收益，同时承受社会平均风险。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。平衡型投资者既不厌恶风险也不追求风险，对任何投资都比较理性，往往会仔细分析不同的投资市场、工具与产品，从中寻找风险适中、收益适中的产品、获得社会平均水平的收益，同时承受社会平均风险。稳健型投资者追求投资安全和适度增值，风险承受能力有限。"},{"id":"advisor2-93","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"判断","q":"信用风险缓释是指通过控制措施降低风险的损失频率或影响程度，在银行业中，信用风险缓释通过抵质押品、净额结算等工具转移信用风险。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。信用风险缓释是指运用合格的抵质押品、净额结算、保证和信用衍生工具等方式转移或降低信用风险，体现为违约概率、违约损失率或违约风险暴露的下降。"},{"id":"advisor2-94","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"判断","q":"一般来说，买卖价差越大，流动性风险越高；成交量越大，流动性越好，流动性风险就越低。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。买卖价差是指买入和卖出一项金融工具的价格之差。买卖价差越小，代表该资产流动性越好，所面临的流动性风险越小。成交量：反映市场的交易活跃程度。成交量越大，说明市场参与者越多，资产能以合理价格快速成交的能力越强，流动性越好，反之则流动性风险越低。"},{"id":"advisor2-95","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"判断","q":"证券公司、证券投资咨询机构应当按照公平、合理、自愿的原则，与客户协商并书面约定收取证券投资顾问服务费用的安排，可以按照服务期限、客户资产规模收取服务费用，不可以采用差别佣金等其他方式收取服务费用。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。证券公司、证券投资咨询机构应当按照公平、合理、自愿的原则，与投资者协商并书面约定收取证券投资顾问服务费用的安排，可以按照服务期限、投资者资产规模收取服务费用，也可以（并非不可以）采用差别佣金等其他方式收取服务费用。"},{"id":"advisor2-96","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"判断","q":"证券经营机构对销售的产品划分风险等级时需要考虑产品的到期期限。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。经营机构应当了解所销售产品或者所提供服务的信息，根据风险特征和程度，对销售产品或者提供的服务划分风险等级。划分产品或者服务风险等级时应综合考虑如下因素：流动性、到期期限、杠杆情况、结构复杂性、投资单位产品或者相关服务的最低金额、投资方向和投资范围、募集方式、发行人等相关主体的信用状况、同类产品或者服务过往业绩等。"},{"id":"advisor2-97","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"判断","q":"证券经营机构可以将产品或服务风险等级由低至高至少划分为五级。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。证券经营机构可以将产品或服务风险等级由低至高至少划分为五级，分别为：R1、R2、R3、R4、R5。"},{"id":"advisor2-98","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"判断","q":"资本资产定价模型在分析问题的过程中，不考虑交易成本对红利、股息以及资本利得的征税，但限制借贷和卖空。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。资本资产定价模型建立在多种假设基础之上。假设条件包括：（1）资本市场不存在摩擦，没有税负，没有交易成本。（2）存在无风险利率，且所有投资者都能以这一利率水平不受限制地贷出（即投资）或借入资金。也可概括为以下三项假设：假设 1：投资者都依据期望收益率评价证券组合的收益水平，依据方差（或标准差）评价证券组合的风险水平，并按照投资者共同偏好规则选择最优证券组合。假设2：投资者对证券的收益、风险及证券间的关联性具有完全相同的预期。假设3：资本市场没有摩擦。CAPM的核心假设是无摩擦市场+无限制借贷/卖空，题目后半句表述错误。"},{"id":"advisor2-99","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"判断","q":"资产配置可以分为战略配置和战术配置两个层次。战略资产配置重在长期回报，不考虑资产的短期波动，其投资期限可以长达 5 年以上。战术资产配置更多关注市场的短期波动，通过择时调节大类资产之间的分配比例，战术资产配置的模型主要有均值方差模型等。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。均值-方差模型属于战略资产配置模型（并非战术资产配置）。"},{"id":"advisor2-100","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"案例","q":"【资料】假设证券市场只有证券A和证券B，证券A和证券B的期望收益率分别为6%和12%，\nβ系数分别为0.6 和1.2，无风险借贷利率为 3%。 \n根据上述材料，回答下列各小题。\n\n【问题】根据资本资产定价模型，（）。","options":["这个证券市场不处于均衡状态","这个证券市场处于均衡状态","证券A的单位系统风险补偿为0.05","证券B的单位系统风险补偿为0.075"],"answer":"ACD","explain":"[根据资本资产定价模型的公式：E（Ri）=Rf+βi×[E（RM）-Rf]]。证券A的单位系统风险补偿为（6%-3%）/0.6=0.05（C选项正确）；证券B的单位系统风险补偿为（12%-3%）/1.2=0.075（D选项正确）。当市场均衡时，单位系统风险补偿应该相同（A选项正确、B选项错误）。故本题选ACD选项。"},{"id":"advisor2-101","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"案例","q":"【资料】假设证券市场只有证券A和证券B，证券A和证券B的期望收益率分别为6%和12%，\nβ系数分别为0.6 和1.2，无风险借贷利率为 3%。 \n根据上述材料，回答下列各小题。\n\n【问题】一般而言，资本资产定价模型的应用领域包括（）。","options":["投资决策","证券投资预算","公司理财","预测股票市场的变动趋势"],"answer":"AC","explain":"资本资产定价模型是由美国学者威廉·夏普、林特尔、特雷诺和莫辛等人于 1964 年在证券投资组合理论基础上发展起来的，主要研究证券市场中资产的预期收益率与预期风险之间的关系，以及均衡价格是如何形成的，是现代金融市场价格理论的支柱，广泛应用于投资决策（A 选项正确）和公司理财（C选项正确）领域。B、D选项错误，不属于CAPM的应用领域。故本题选AC选项。"},{"id":"advisor2-102","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"案例","q":"【资料】某期国债距到期日还有3年，面值100元，票面利率年息3.75%，每年付息一次，\n下次付息日在1年以后。1年期、2年期、3年期贴现率分别为 3%、4%、5.5%。 \n请根据上述背景信息回答以下问题。\n\n【问题】该债券的理论价格为（）元。","options":["96.67","95.46","95.74","96.57"],"answer":"B","explain":"P=3.75/（1+3%）+3.75/（1+4%）2+103.75/（1+5.5%）3≈95.46（元）（B选项正确）。故本题选B选项。"},{"id":"advisor2-103","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"案例","q":"【资料】某期国债距到期日还有3年，面值100元，票面利率年息3.75%，每年付息一次，\n下次付息日在1年以后。1年期、2年期、3年期贴现率分别为 3%、4%、5.5%。 \n请根据上述背景信息回答以下问题。\n\n【问题】下列属于债券估值模型的是（）。","options":["零息债券定价","附息债券定价","累息债券定价","资产报酬率"],"answer":"ABC","explain":"债券估值模型包括：零息债券定价（A 选项正确）、附息债券定价（B 选项正确）、累息债券定价（C选项正确）。故本题选ABC选项。"},{"id":"advisor2-104","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"案例","q":"【资料】某公司为扩大业务范围，在上海证券交易所通过发行债券的方式筹集资金，共发\n行面值为100元、票据利率为5%、到期期限为3年的债券10亿元，每年11月20日支付利息，\n到期还本付息，假定未来3年市场利率一直保持为 5%。 \n请根据上述背景信息回答以下问题。\n\n【问题】该债券的投资者每张债券第一年后收到的第一笔利息的现值为（）元。","options":["4.5","4.55","4.76","5.05"],"answer":"C","explain":"债券持有一年获得的利息=100×5%=5（元），PV=5/（1+5%）=4.76（元）（C选项正确）。故本题选C选项。"},{"id":"advisor2-105","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"案例","q":"【资料】某公司为扩大业务范围，在上海证券交易所通过发行债券的方式筹集资金，共发\n行面值为100元、票据利率为5%、到期期限为3年的债券10亿元，每年11月20日支付利息，\n到期还本付息，假定未来3年市场利率一直保持为 5%。 \n请根据上述背景信息回答以下问题。\n\n【问题】该债券的发行价格应为（）元。","options":["86.38","90.7","95.23","100.00"],"answer":"D","explain":"D 选项正确，市场利率等于债券收益率时，债券的市场价格（购买价）等于债券面值，即债券为平价发行。故本题选D选项。"},{"id":"advisor2-106","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"案例","q":"【资料】某公司为扩大业务范围，在上海证券交易所通过发行债券的方式筹集资金，共发\n行面值为100元、票据利率为5%、到期期限为3年的债券10亿元，每年11月20日支付利息，\n到期还本付息，假定未来3年市场利率一直保持为 5%。 \n请根据上述背景信息回答以下问题。\n\n【问题】该债券的投资者以发行价格买入该债券，持有至到期的收益率为（）。","options":["7.00%","4.55%","5.00%","5.23%"],"answer":"C","explain":"C 选项正确，市场利率（或债券预期收益率）等于债券收益率（息票利率）时，债券的市场价格（购买价）等于债券面值，即债券为平价发行，也称等价发行。根据题干所说\"以发行价格买入该债券\"，说明该债券的市场价格（购买价）等于债券面值，即平价发行，所以其获得的收益率应等于其息票利率，即5%。故本题选C选项。"},{"id":"advisor2-107","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"案例","q":"【资料】某投资者计划通过跟踪指数的方式参与股票投资，并购买了一只指数基金，该基\n金采用完全复制的方式对指数进行跟踪。 \n请根据上述背景信息回答以下问题。\n\n【问题】该投资者采用的投资策略是（）。","options":["主动投资策略","自上而下策略","被动投资策略","自下而上策略"],"answer":"C","explain":"C 选项正确，该投资是用跟踪指数的方式参与股票投资，属于指数化投资策略，指数化投资策略是被动投资策略。A、B、D选项错误，自上而下和自下而上策略是主动投资的分析方法。故本题选C选项。"},{"id":"advisor2-108","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"案例","q":"【资料】某投资者计划通过跟踪指数的方式参与股票投资，并购买了一只指数基金，该基\n金采用完全复制的方式对指数进行跟踪。 \n请根据上述背景信息回答以下问题。\n\n【问题】下列变化会增加该投资者购买的指数基金相对于基准指数的跟踪误差的有（）。","options":["指数成分股的交易流动性下降","基金管理人下调基金管理费","基金管理人增加投资组合中的现金比例","国家下调证券交易印花税"],"answer":"AC","explain":"跟踪误差主要来源于指数策略与挂钩指数本身的差别，以及交易成本和管理费用。A 选项正确，流动性下降会导致基金买卖成分股时的交易成本增加（如冲击成本、买卖价差扩大），从而增大跟踪误差。C 选项正确，指数基金的目标是满仓复制指数，持有现金相当于未完全投资，会增大跟踪误差。B、D选项错误，降低基金运作成本使得基金能更高效地复制指数，从而减小跟踪误差。故本题选AC选项。"},{"id":"advisor2-109","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"案例","q":"【资料】某投资者计划通过跟踪指数的方式参与股票投资，并购买了一只指数基金，该基\n金采用完全复制的方式对指数进行跟踪。 \n请根据上述背景信息回答以下问题。\n\n【问题】该投资者眼中的股票市场有可能是（）。","options":["半弱式有效市场","半强式有效市场","弱式有效市场","强式有效市场"],"answer":"BCD","explain":"消极型投资策略的假设前提是投资者认为证券市场是有效的，证券价格充分反映可获得的信息，因此被动接受市场变化更有可能获取市场收益，而且能够避免过多的交易成本和误判市场走势造成的损失。材料中，该投资者使用指数化投资策略，说明他认为市场是有效市场，而根据市场对信息反应的强弱，将有效市场分为三种形式，即强式有效市场（B 选项正确）、半强式有效市场（B 选项正确）和弱式有效市场（C选项正确）。故本题选BCD选项。"},{"id":"advisor2-110","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"案例","q":"【资料】某公司的企业公司上年度自由现金流为 5000000 元，预计今年自由现金流增长率\n为5%，公司的负债比率（负债/总资产）为20%，股票投资者必要收益率为16%，负债的税前成\n本为8%，税率为25%，公司负债市场价值11200000元，公司现有2000000股普通股发行在外。 \n请根据上述背景信息回答以下问题。\n\n【问题】根据企业自由现金流贴现模型，采用的贴现率为（）。","options":["必要回报率","最低回报率","加权平均资本成本","算术平均资本成本"],"answer":"C","explain":"C选项正确，企业自由现金流贴现模型采用企业加权平均资本成本（WACC）为贴现率。A 选项错误，必要回报率通常指股东要求的最低回报率（如股权成本 KE），但 FCFF 模型需覆盖所有资本提供者（包括债权人），因此仅用股权成本不全面。B 选项错误，最低回报率一般指企业对投资项目的最低收益要求，属于项目层面指标，与企业整体估值的贴现率无直接关联。D 选项错误，算术平均资本成本未考虑不同资本来源的权重（如债务与股权比例），无法准确反映企业真实资本成本，实践中极少采用。故本题选C选项。"},{"id":"advisor2-111","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"案例","q":"【资料】某公司的企业公司上年度自由现金流为 5000000 元，预计今年自由现金流增长率\n为5%，公司的负债比率（负债/总资产）为20%，股票投资者必要收益率为16%，负债的税前成\n本为8%，税率为25%，公司负债市场价值11200000元，公司现有2000000股普通股发行在外。 \n请根据上述背景信息回答以下问题。\n\n【问题】上述材料的贴现率为（）。","options":["12%","13%","14%","15%"],"answer":"C","explain":"C 选项正确，WACC=E/（E+D）×KE+D/（E+D）×KD×（1-T）=0.8×16%+0.2×8%×（1-25%）=12.8%+1.2%=14%。故本题选C选项。"},{"id":"advisor2-112","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"案例","q":"【资料】某公司的企业公司上年度自由现金流为 5000000 元，预计今年自由现金流增长率\n为5%，公司的负债比率（负债/总资产）为20%，股票投资者必要收益率为16%，负债的税前成\n本为8%，税率为25%，公司负债市场价值11200000元，公司现有2000000股普通股发行在外。 \n请根据上述背景信息回答以下问题。\n\n【问题】股票的内在价值为（）元/股。","options":["21.57","22.57","23.57","24.57"],"answer":"C","explain":"①公司价值VA=FCFF1/（WACC-gFCFF）=5250000/（14%-5%）≈58333333（元）。②计算股权价值。考虑到公司负债价值 VD=11200000（元）；则公司股权价值 VE=VA-VD=58333333-11200000=47133333（元）。③ 计算股票内在价值。因为发行在外股票数量为 2000000 股 ， 每 股 内 在 价 值47133333/2000000≈23.57（元）（C选项正确）。故本题选C选项。"},{"id":"advisor2-113","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"案例","q":"【资料】某投资机构需要为其市值 1000 万人民币的 A 股投资组合做对冲，该投资组合业绩\n对标沪深 300，当时的沪深 300 期货（IF）价格为 4000 点（每点 300 元），该投资组合的 β\n值为1.2。 \n请根据上述背景信息回答以下问题。\n\n【问题】该投资机构需要卖出的指数期货合约数量为（）。","options":["11张","8张","10张","9张"],"answer":"C","explain":"沪深300期货价格4000 点，每点300 元，则买一张需要 120万元。买卖期货合约的数量=β×现货总价值/（期货指数点×每点乘数）=1.2×1000 万/120=10 张（C选项正确）。故本题选C选项。"},{"id":"advisor2-114","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"案例","q":"【资料】某投资机构需要为其市值 1000 万人民币的 A 股投资组合做对冲，该投资组合业绩\n对标沪深 300，当时的沪深 300 期货（IF）价格为 4000 点（每点 300 元），该投资组合的 β\n值为1.2。 \n请根据上述背景信息回答以下问题。\n\n【问题】1 个月后，该投资组合上涨了 10%，沪深 300 指数期货的价格上涨到了 4340 点，忽略手续费和冲击成本，则该投资机构的盈亏状况为（）。","options":["盈利8万元","亏损2万元","亏损8万元","盈利2万元"],"answer":"B","explain":"投资组合涨了10%，所以投资组合盈利1000x10%=100 万元；但是，股指期货价格上涨到了 4340 点，由于卖出了 10 张，每张亏损 4340-4000=340 点，股指期货部分亏损=10×300×340=102万元。故总体盈亏状况为100-102=-2万元，亏损 2 万元（B选项正确）。故本题选B选项。"},{"id":"advisor2-115","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"案例","q":"【资料】某投资机构需要为其市值 1000 万人民币的 A 股投资组合做对冲，该投资组合业绩\n对标沪深 300，当时的沪深 300 期货（IF）价格为 4000 点（每点 300 元），该投资组合的 β\n值为1.2。 \n请根据上述背景信息回答以下问题。\n\n【问题】该投资机构要保证利用股指期货进行套期保值成功，必须遵循的原则有（）。","options":["买卖方向对应的原则","品种相同原则","数量相等原则","月份相同或相近原则"],"answer":"ACD","explain":"进行套期保值操作时，有四个基本原则需要遵循，以确保有效的风险管理和套期保值策略的实施：买卖方向对应的原则（A 选项正确）、品种相同或相近原则（B 选项错误，品种不一定要相同也可以相近）、数量相等原则（C选项正确）、月份相同或相近原则（D选项正确）。故本题选ACD选项。"},{"id":"advisor2-116","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"案例","q":"【资料】小王和小吴同在一家企业工作。小王今年 35 岁，有很强的财富规划欲望，属于典\n型的风险爱好者，对于理财他追求高收益高回报，也敢于承担风险。小吴今年 33 岁，属于典\n型的风险厌恶者，对于理财，他追求稳妥、固定的收益回报，秉承安全第一的原则。两人最近\n都有打算要投资基金产品。 \n请根据上述背景信息回答以下问题。\n\n【问题】从投资目标来看，小王应该会考虑投资（）产品。","options":["成长型基金","收入型基金","股票基金","私募基金"],"answer":"A","explain":"A 选项正确，成长型基金是基金中最常见的一种，它追求的是基金资产的长期增值。为了达到这一目标，基金管理人通常将基金资产投资于信誉度较高、有长期成长前景的成长型公司股票。此类基金的特征符合小王的投资性格和投资目标。故本题选A选项。"},{"id":"advisor2-117","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"案例","q":"【资料】小王和小吴同在一家企业工作。小王今年 35 岁，有很强的财富规划欲望，属于典\n型的风险爱好者，对于理财他追求高收益高回报，也敢于承担风险。小吴今年 33 岁，属于典\n型的风险厌恶者，对于理财，他追求稳妥、固定的收益回报，秉承安全第一的原则。两人最近\n都有打算要投资基金产品。 \n请根据上述背景信息回答以下问题。\n\n【问题】从投资目标来看，小吴应该会考虑投资（）产品。","options":["增长型基金","收入型基金","股票基金","私募基金"],"answer":"B","explain":"B 选项正确，收入型基金主要投资于可带来现金收入的有价证券，以获取当期的最大收入为目的。收入型基金资产成长的潜力较小，损失本金的风险也相对较低。此类基金的特征符合小吴的投资性格和投资目标。A、C、D选项错误，三者均属于高风险产品。故本题选B选项。"},{"id":"advisor2-118","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"案例","q":"【资料】小王和小吴同在一家企业工作。小王今年 35 岁，有很强的财富规划欲望，属于典\n型的风险爱好者，对于理财他追求高收益高回报，也敢于承担风险。小吴今年 33 岁，属于典\n型的风险厌恶者，对于理财，他追求稳妥、固定的收益回报，秉承安全第一的原则。两人最近\n都有打算要投资基金产品。 \n请根据上述背景信息回答以下问题。\n\n【问题】股票基金以追求长期的资本增值为目标，比较适合长期投资。小王也看重了股票基金的这一特性，欲考虑投资股票基金。若小王真的投资股票基金，则他将面临（）。","options":["系统性风险","经营风险","管理运作风险","通货膨胀风险"],"answer":"ABC","explain":"股票基金所面临的投资风险主要包括系统性风险（A 选项正确）、经营风险（B 选项正确）以及管理运作风险（C选项正确）。故本题选ABC选项。"},{"id":"advisor2-119","subject":"advisor","source":"2026.09 LC终极押题 · 押题卷二","type":"案例","q":"【资料】小王和小吴同在一家企业工作。小王今年 35 岁，有很强的财富规划欲望，属于典\n型的风险爱好者，对于理财他追求高收益高回报，也敢于承担风险。小吴今年 33 岁，属于典\n型的风险厌恶者，对于理财，他追求稳妥、固定的收益回报，秉承安全第一的原则。两人最近\n都有打算要投资基金产品。 \n请根据上述背景信息回答以下问题。\n\n【问题】根据投资对象的不同，小吴应该考虑投资的基金产品是（）。","options":["股票基金","债券基金","货币市场基金","混合基金"],"answer":"C","explain":"A 选项不符合题意，股票基金是指以股票为主要投资对象的基金。股票基金在各类基金中历史最为悠久，也是各国（地区）广泛采用的一种基金类型。B 选项不符合题意，债券基金是指以债券为主要投资对象的基金。根据中国证监会《基金管理办法》对基金类别的分类标准，基金资产80%以上投资于债券的为债券基金。C 选项符合题意，货币市场基金是以货币市场工具为投资对象的基金。与其他类型基金相比，货币市场基金具有风险低、流动性好的特点，是厌恶风险、对资产流动性和安全性要求较高的投资者进行短期投资和现金管理的理想工具。D 选项不符合题意，混合基金是同时以股票、债券等为投资对象的基金，以期通过在不同资产类别上的投资实现收益与风险之间的平衡。故本题选C选项。"}]}];
